              className="group overflow-hidden rounded-2xl border border-border bg-background transition-all hover:border-brand hover:shadow-lg"
              initial={
                shouldReduceMotion
                  ? { opacity: 1 }
                  : { opacity: 0, y: INITIAL_Y_OFFSET }
              }
              key={faq.question}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      delay: index * STAGGER_DELAY,
                      duration: ANIMATION_DURATION,
                    }
              }
              viewport={{ once: true }}
              whileInView={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }
              }
            >
              <motion.button
                className="flex w-full cursor-pointer items-center justify-between p-6 text-left transition-colors hover:bg-background/50"
                onClick={() => toggleAccordion(index)}
                type="button"
                whileHover={shouldReduceMotion ? {} : { scale: HOVER_SCALE }}
                whileTap={shouldReduceMotion ? {} : { scale: TAP_SCALE }}
              >
                <h3 className="pr-4 font-semibold text-foreground text-lg">
                  {faq.question}
                </h3>
                <motion.div
                  animate={
                    shouldReduceMotion
                      ? {
                          rotate:
                            openIndex === index
                              ? ROTATION_OPEN
                              : ROTATION_CLOSED,
                        }
                      : {
                          rotate:
                            openIndex === index
                              ? ROTATION_OPEN
                              : ROTATION_CLOSED,
                        }
                  }
                  className="flex-shrink-0"
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { duration: ANIMATION_DURATION, ease: "easeInOut" }
                  }
                >
                  <svg
                    aria-hidden="true"
                    className="h-5 w-5 text-foreground/60"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      d="M19 9l-7 7-7-7"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                    />
                  </svg>
                </motion.div>
              </motion.button>

              <AnimatePresence>
                {openIndex === index && (
                  <motion.div
                    animate={{ height: "auto", opacity: 1 }}
                    className="overflow-hidden"
                    exit={
                      shouldReduceMotion
                        ? { opacity: 0, transition: { duration: 0 } }
                        : { height: 0, opacity: 0 }
                    }
                    initial={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { height: 0, opacity: 0 }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : { duration: ANIMATION_DURATION, ease: "easeInOut" }
                    }
                  >
                    <motion.div
                      animate={{ y: 0 }}
                      className="px-6 pb-6"
                      exit={
                        shouldReduceMotion
                          ? { transition: { duration: 0 } }
                          : { y: INITIAL_CONTENT_Y }
                      }
                      initial={
                        shouldReduceMotion ? { y: 0 } : { y: INITIAL_CONTENT_Y }
                      }
                      transition={
                        shouldReduceMotion
                          ? { duration: 0 }
                          : {
                              delay: CONTENT_DELAY,
                              duration: ANIMATION_DURATION,
                            }
                      }
                    >
                      <p className="text-foreground/70 leading-relaxed">
                        {faq.answer}
                      </p>
                    </motion.div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          ))}
