              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, y: -30 }
              }
              initial={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 30 }
              }
              key={index}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : { duration: 0.5, type: "spring" as const }
              }
            >
