  M: ["#...#", "##.##", "#.#.#", "#.#.#", "#...#", "#...#", "#...#"],
  N: ["#...#", "##..#", "#.#.#", "#.#.#", "#..##", "#...#", "#...#"],
  O: [".###.", "#...#", "#...#", "#...#", "#...#", "#...#", ".###."],
  P: ["####.", "#...#", "#...#", "####.", "#....", "#....", "#...."],
  Q: [".###.", "#...#", "#...#", "#...#", "#.#.#", "#..#.", ".##.#"],
  R: ["####.", "#...#", "#...#", "####.", "#.#..", "#..#.", "#...#"],
  S: [".####", "#....", "#....", ".###.", "....#", "....#", "####."],
  T: ["#####", "..#..", "..#..", "..#..", "..#..", "..#..", "..#.."],
  U: ["#...#", "#...#", "#...#", "#...#", "#...#", "#...#", ".###."],
  V: ["#...#", "#...#", "#...#", "#...#", "#...#", ".#.#.", "..#.."],
  W: ["#...#", "#...#", "#...#", "#.#.#", "#.#.#", "#.#.#", ".#.#."],
  X: ["#...#", "#...#", ".#.#.", "..#..", ".#.#.", "#...#", "#...#"],
  Y: ["#...#", "#...#", ".#.#.", "..#..", "..#..", "..#..", "..#.."],
  Z: ["#####", "....#", "...#.", "..#..", ".#...", "#....", "#####"],
};

/** Glyph grid dimensions. */
const FONT_COLUMNS = 5;
const FONT_ROWS = 7;
/** Blank columns inserted between characters when building a text grid. */
const CHARACTER_SPACING_COLUMNS = 1;
const CHARACTER_UNIT_WIDTH = FONT_COLUMNS + CHARACTER_SPACING_COLUMNS;

const BLANK_CELL_CHARACTERS = new Set([".", " "]);

/**
 * Row strings accept "." or " " for an unlit cell, "#" for palette index 1, and
 * a digit for any other palette index, so sprites can be multi-colour.
 */
const characterToCellValue = (character: string): number => {
  if (BLANK_CELL_CHARACTERS.has(character)) {
    return 0;
  }
  const parsed = Number.parseInt(character, 10);
  return Number.isNaN(parsed) ? 1 : parsed;
};

const rowsToGrid = (rows: string[]): number[][] =>
  rows.map((row) => Array.from(row, characterToCellValue));

/** Numeric 5x7 pixel font map (0 = blank, 1 = lit), keyed by uppercase character. */
export const PIXEL_FONT_5X7: Record<string, number[][]> = Object.fromEntries(
  Object.entries(FONT_GLYPH_ROWS).map(([character, rows]) => [
    character,
    rowsToGrid(rows),
  ])
);

/**
 * Ready-made sprites so the `sprite` path is usable without hand-authoring a
 * grid. `alien` and `alienAlt` are the two frames of a space-invader style
 * marcher: alternate them on a timer to animate it.
 */
export const ARCADE_SPRITES: Record<string, number[][]> = {
  alien: rowsToGrid([
    "..#.....#..",
    "...#...#...",
    "..#######..",
    ".##.###.##.",
    "###########",
    "#.#######.#",
    "#.#.....#.#",
    "...##.##...",
  ]),
  alienAlt: rowsToGrid([
    "..#.....#..",
    "#..#...#..#",
    "#.#######.#",
    "###.###.###",
    "###########",
    ".#########.",
    "..#.....#..",
    ".##.....##.",
  ]),
  arrow: rowsToGrid([
    "....#....",
    "....##...",
    "....###..",
    "########.",
    "#########",
    "########.",
    "....###..",
    "....##...",
    "....#....",
  ]),
  heart: rowsToGrid([
    ".###.###.",
    "#22######",
    "#2#######",
    "#########",
    ".#######.",
    "..#####..",
    "...###...",
    "....#....",
  ]),
};

const BLANK_GLYPH_GRID = rowsToGrid(
  Array.from({ length: FONT_ROWS }, () => ".".repeat(FONT_COLUMNS))
);

const getGlyphGrid = (character: string): number[][] =>
  PIXEL_FONT_5X7[character.toUpperCase()] ?? BLANK_GLYPH_GRID;

const buildTextGrid = (text: string): number[][] => {
  const characters = text.length > 0 ? Array.from(text) : [" "];
  const rows: number[][] = Array.from(
    { length: FONT_ROWS },
    () => [] as number[]
  );

  for (const [index, character] of characters.entries()) {
    const glyph = getGlyphGrid(character);
    for (let rowIndex = 0; rowIndex < FONT_ROWS; rowIndex++) {
      rows[rowIndex].push(...glyph[rowIndex]);
      if (index < characters.length - 1) {
        rows[rowIndex].push(0);
      }
    }
  }

  return rows;
};

const resolveGrid = (sprite?: number[][], text?: string): number[][] => {
  if (sprite && sprite.length > 0) {
    return sprite;
  }
  if (typeof text === "string") {
    return buildTextGrid(text);
  }
  return BLANK_GLYPH_GRID;
};

/**
 * `fillStyle` cannot resolve CSS custom properties, so `var(--token)` palette
 * entries are read off the live element before the first paint.
 */
const CSS_VARIABLE_PATTERN = /^var\(\s*(--[\w-]+)\s*(?:,\s*([\s\S]+))?\)$/;
const FALLBACK_COLOR = "#ffffff";

const resolveColor = (element: HTMLElement, color: string): string => {
  const match = CSS_VARIABLE_PATTERN.exec(color.trim());
  if (!match) {
    return color;
  }
  const computed = getComputedStyle(element).getPropertyValue(match[1]).trim();
  if (computed) {
    return computed;
  }
  return match[2] ? resolveColor(element, match[2].trim()) : FALLBACK_COLOR;
};

/**
 * Palettes arrive as arrays, which are a fresh reference on every render when
 * written inline. Serialising them gives the render effect a stable dependency.
 * The separator is a unit separator rather than a space, because a modern colour
 * such as `oklch(0.72 0.2 145)` contains spaces of its own.
 */
const PALETTE_SEPARATOR = "\u001f";

type FrameState = {
  done: boolean;
  /** Column range currently landing with a type-reveal flash. */
  flashEnd: number;
  flashStart: number;
  offsetColumns: number;
  revealedColumns: number;
  visible: boolean;
};

type PaintOptions = {
  bloomAlpha: number;
  columnsInView: number;
  frame: FrameState;
  grid: number[][];
  height: number;
  matrixColor: string;
  palette: string[];
  /** Column span after which the grid repeats, for a seamless marquee. */
  period: number;
  pixelSize: number;
  stride: number;
  width: number;
};

const isSameFrame = (a: FrameState, b: FrameState): boolean =>
  a.visible === b.visible &&
  a.revealedColumns === b.revealedColumns &&
  a.offsetColumns === b.offsetColumns &&
  a.flashStart === b.flashStart &&
  a.flashEnd === b.flashEnd;

const FLASH_COLOR = "#ffffff";
const BLOOM_BLUR_PX = 5;
const MATRIX_ALPHA = 0.07;

/** Crisp, opaque pixels: one fillRect per lit cell. */
const paintLitPixels = (
  ctx: CanvasRenderingContext2D,
  options: PaintOptions
): void => {
  const { frame, period, pixelSize, stride, width } = options;
  const repeats = period > 0 ? [0, period] : [0];

  for (const [rowIndex, row] of options.grid.entries()) {
    const y = rowIndex * stride;
    for (const [columnIndex, value] of row.entries()) {
      if (!value || columnIndex >= frame.revealedColumns) {
        continue;
      }
      const isFlashing =
        columnIndex >= frame.flashStart && columnIndex < frame.flashEnd;
      const color = isFlashing
        ? FLASH_COLOR
        : (options.palette[value] ?? options.palette.at(-1));
      if (!color || color === "transparent") {
        continue;
      }
      ctx.fillStyle = color;
      for (const repeat of repeats) {
        const x = (columnIndex + repeat - frame.offsetColumns) * stride;
        if (x + pixelSize < 0 || x > width) {
          continue;
        }
        ctx.fillRect(x, y, pixelSize, pixelSize);
      }
    }
  }
};

/**
 * Phosphor bleed. One blurred self-composite in `lighter` mode costs a single
 * draw call, where a per-pixel `shadowBlur` would cost one blur per lit cell.
 */
const paintBloom = (
  ctx: CanvasRenderingContext2D,
  canvas: HTMLCanvasElement,
  options: PaintOptions
): void => {
  if (options.bloomAlpha <= 0) {
    return;
  }
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = options.bloomAlpha;
  ctx.filter = `blur(${BLOOM_BLUR_PX}px)`;
  ctx.drawImage(canvas, 0, 0, options.width, options.height);
  ctx.restore();
};

/**
 * The unlit dot matrix behind the message. Drawn last with `destination-over`
 * so it never dulls a lit pixel, and phase-locked to the marquee offset so the
 * dots and the message always sit on the same sub-cell grid.
 */
const paintDotMatrix = (
  ctx: CanvasRenderingContext2D,
  options: PaintOptions
): void => {
  const { columnsInView, frame, pixelSize, stride } = options;
  const phase = frame.offsetColumns - Math.floor(frame.offsetColumns);
  ctx.save();
  ctx.globalCompositeOperation = "destination-over";
  ctx.globalAlpha = MATRIX_ALPHA;
  ctx.fillStyle = options.matrixColor;
  for (let rowIndex = 0; rowIndex < options.grid.length; rowIndex++) {
    const y = rowIndex * stride;
    for (let column = 0; column <= columnsInView; column++) {
      ctx.fillRect((column - phase) * stride, y, pixelSize, pixelSize);
    }
  }
  ctx.restore();
};

const paintFrame = (
  ctx: CanvasRenderingContext2D,
  canvas: HTMLCanvasElement,
  options: PaintOptions
): void => {
  ctx.clearRect(0, 0, options.width, options.height);
  if (options.frame.visible) {
    paintLitPixels(ctx, options);
    paintBloom(ctx, canvas, options);
  }
  paintDotMatrix(ctx, options);
};

export type ArcadePixelAnimate = "none" | "type" | "wipe" | "blink" | "marquee";

export interface ArcadePixelProps {
  /** Reveal animation played on mount. `marquee` scrolls the message forever. */
  animate?: ArcadePixelAnimate;
  className?: string;
  /** Fixed display width in pixel cells. Defaults to the content width. */
  columns?: number;
  /** Curved vignette, chromatic fringing and a faint flicker over the canvas. */
  crt?: boolean;
  /** Gap, in CSS pixels, between pixel cells. */
  gap?: number;
  /** Phosphor bloom bleeding out of lit pixels. A number sets its intensity (0-1). */
  glow?: boolean | number;
  /** Whether the reveal animation repeats indefinitely. */
  loop?: boolean;
  /** Colors indexed by sprite/font value. Index 0 is treated as background. */
  palette?: string[];
  /** Size, in CSS pixels, of a single pixel cell. */
  pixelSize?: number;
  /** Overlays a CRT-style scanline pattern. */
  scanlines?: boolean;
  /** Animation speed multiplier. Higher plays faster. */
  speed?: number;
  /** 2D array of palette indices. Takes precedence over `text` when both are set. */
  sprite?: number[][];
  /** Text rendered through the built-in 5x7 pixel font. Ignored if `sprite` is set. */
  text?: string;
}

const DEFAULT_PIXEL_SIZE = 8;
const DEFAULT_GAP = 1;
const DEFAULT_PALETTE: string[] = ["transparent", "var(--color-brand)"];
const DEFAULT_SPEED = 1;
const MAX_DEVICE_PIXEL_RATIO = 2;
const TYPE_DURATION_MS = 1400;
const WIPE_DURATION_MS = 900;
const BLINK_INTERVAL_MS = 450;
const BLINK_SETTLE_CYCLES = 3;
const TYPE_FLASH_MS = 110;
const MARQUEE_COLUMNS_PER_SECOND = 16;
const MARQUEE_TAIL_COLUMNS = 8;
const DEFAULT_GLOW_INTENSITY = 0.65;
const MS_PER_SECOND = 1000;

/** Linear, expressed as a cubic-bezier so no string easing reaches Motion. */
const LINEAR_EASE: [number, number, number, number] = [0, 0, 1, 1];
const SCANLINE_PERIOD_PX = 3;
const SCANLINE_DRIFT_PX = SCANLINE_PERIOD_PX * 2;
const SCANLINE_DRIFT_SECONDS = 5;
const ROLL_BAND_SECONDS = 9;
const FLICKER_SECONDS = 2.4;

const SCANLINE_BACKGROUND = `repeating-linear-gradient(to bottom, rgba(0,0,0,0.44) 0px, rgba(0,0,0,0.44) 1px, rgba(0,0,0,0) 1px, rgba(0,0,0,0) ${SCANLINE_PERIOD_PX}px)`;
const ROLL_BAND_BACKGROUND =
  "linear-gradient(to bottom, rgba(255,255,255,0) 0%, rgba(255,255,255,0.05) 50%, rgba(255,255,255,0) 100%)";
const ABERRATION_BACKGROUND =
  "linear-gradient(90deg, rgba(255,0,72,0.18) 0%, rgba(255,0,72,0) 13%, rgba(0,190,255,0) 87%, rgba(0,190,255,0.18) 100%)";
const VIGNETTE_BACKGROUND =
  "radial-gradient(125% 125% at 50% 50%, rgba(0,0,0,0) 40%, rgba(0,0,0,0.32) 74%, rgba(0,0,0,0.82) 100%)";

type ArcadeCrtOverlayProps = {
  crt: boolean;
  scanlines: boolean;
  shouldReduceMotion: boolean;
};

/**
 * Every CRT artefact is a CSS layer stacked over the canvas, so none of it costs
 * per-frame canvas work.
 */
const ArcadeCrtOverlay = ({
  crt,
  scanlines,
  shouldReduceMotion,
}: ArcadeCrtOverlayProps) => (
  <>
    {scanlines ? (
      <motion.div
        animate={
          shouldReduceMotion
            ? undefined
            : {
                transform: [
                  "translateY(0px)",
                  `translateY(-${SCANLINE_DRIFT_PX}px)`,
                ],
              }
        }
        className="absolute inset-x-0 top-0 h-[200%]"
        style={{ backgroundImage: SCANLINE_BACKGROUND }}
        transition={{
          duration: SCANLINE_DRIFT_SECONDS,
          ease: LINEAR_EASE,
          repeat: Number.POSITIVE_INFINITY,
        }}
      />
    ) : null}
    {crt ? (
      <>
        {shouldReduceMotion ? null : (
          <motion.div
            animate={{ transform: ["translateY(-140%)", "translateY(240%)"] }}
            className="absolute inset-x-0 top-0 h-1/3"
            style={{ backgroundImage: ROLL_BAND_BACKGROUND }}
            transition={{
              duration: ROLL_BAND_SECONDS,
              ease: LINEAR_EASE,
              repeat: Number.POSITIVE_INFINITY,
            }}
          />
        )}
        <div
          className="absolute inset-0"
          style={{
            backgroundImage: ABERRATION_BACKGROUND,
            mixBlendMode: "screen",
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            backgroundImage: VIGNETTE_BACKGROUND,
            boxShadow: "inset 0 0 24px rgba(0,0,0,0.65)",
          }}
        />
        {shouldReduceMotion ? null : (
          <motion.div
            animate={{ opacity: [0.055, 0.015, 0.045, 0.01, 0.06] }}
            className="absolute inset-0 bg-white"
            transition={{
              duration: FLICKER_SECONDS,
              ease: LINEAR_EASE,
              repeat: Number.POSITIVE_INFINITY,
              repeatType: "mirror",
            }}
          />
        )}
      </>
    ) : null}
  </>
);

const ArcadePixel = ({
  sprite,
  text,
  palette = DEFAULT_PALETTE,
  columns,
  pixelSize = DEFAULT_PIXEL_SIZE,
  gap = DEFAULT_GAP,
  scanlines = false,
  crt = false,
  glow = false,
  animate = "none",
  speed = DEFAULT_SPEED,
  loop = false,
  className,
}: ArcadePixelProps) => {
  const shouldReduceMotion = Boolean(useReducedMotion());
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const grid = useMemo(() => resolveGrid(sprite, text), [sprite, text]);
  const paletteKey = palette.join(PALETTE_SEPARATOR);
  const stablePalette = useMemo(
    () => paletteKey.split(PALETTE_SEPARATOR),
    [paletteKey]
  );

  const totalRows = grid.length;
  const totalColumns = grid[0]?.length ?? 0;
  const columnsInView = Math.max(1, columns ?? totalColumns);
  const stride = pixelSize + gap;
  const cssWidth = columnsInView * stride - gap;
  const cssHeight = totalRows * stride - gap;

  const { numUnits, unitWidth } = useMemo(() => {
    if (!sprite && typeof text === "string") {
      return {
        numUnits: Math.max(1, Array.from(text).length),
        unitWidth: CHARACTER_UNIT_WIDTH,
      };
    }
    return { numUnits: Math.max(1, totalColumns), unitWidth: 1 };
  }, [sprite, text, totalColumns]);

  const accessibleLabel =
    typeof text === "string" && text.trim().length > 0 ? text : "pixel art";

  const glowIntensity =
    typeof glow === "number" ? glow : (glow && DEFAULT_GLOW_INTENSITY) || 0;

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!(container && canvas && ctx)) {
      return;
    }

    const safeSpeed = speed > 0 ? speed : DEFAULT_SPEED;
    const isStatic = shouldReduceMotion || animate === "none";
    const resolvedPalette = stablePalette.map((color) =>
      color === "transparent" ? color : resolveColor(container, color)
    );
    const matrixColor =
      resolvedPalette.find((color) => color !== "transparent") ??
      FALLBACK_COLOR;
    const period =
      animate === "marquee" ? totalColumns + MARQUEE_TAIL_COLUMNS : 0;

    const staticFrame: FrameState = {
      done: true,
      flashEnd: -1,
      flashStart: -1,
      offsetColumns: 0,
      revealedColumns: totalColumns,
      visible: true,
    };

    let rafId: number | null = null;
    let isFinished = isStatic;
    let isOffscreen = false;
    let isHidden = document.hidden;
    let isPaused = false;
    let elapsedMs = 0;
    let lastTimestamp: number | null = null;
    let lastFrame: FrameState = staticFrame;
    let currentCssWidth = cssWidth;
    let currentCssHeight = cssHeight;
    let landedUnits = 0;
    let flashStartedAtMs = Number.NEGATIVE_INFINITY;

    const setBackingStoreSize = () => {
      const rect = container.getBoundingClientRect();
      currentCssWidth = rect.width;
      currentCssHeight = rect.height;
      const devicePixelRatio = Math.min(
        window.devicePixelRatio || 1,
        MAX_DEVICE_PIXEL_RATIO
      );
      const width = Math.max(1, Math.round(rect.width * devicePixelRatio));
      const height = Math.max(1, Math.round(rect.height * devicePixelRatio));
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
    };

    const render = (frame: FrameState) => {
      lastFrame = frame;
      paintFrame(ctx, canvas, {
        bloomAlpha: glowIntensity,
        columnsInView,
        frame,
        grid,
        height: currentCssHeight,
        matrixColor,
        palette: resolvedPalette,
        period,
        pixelSize,
        stride,
        width: currentCssWidth,
      });
    };

    const computeTypeFrame = (): FrameState => {
      const progress = Math.min(elapsedMs / (TYPE_DURATION_MS / safeSpeed), 1);
      const units = Math.floor(progress * numUnits);
      if (units !== landedUnits) {
        landedUnits = units;
        flashStartedAtMs = elapsedMs;
      }
      const isFlashing = elapsedMs - flashStartedAtMs < TYPE_FLASH_MS;
      return {
        done: progress >= 1,
        flashEnd: isFlashing ? units * unitWidth : -1,
        flashStart: isFlashing ? (units - 1) * unitWidth : -1,
        offsetColumns: 0,
        revealedColumns: Math.min(totalColumns, units * unitWidth),
        visible: true,
      };
    };

    const computeWipeFrame = (): FrameState => {
      const progress = Math.min(elapsedMs / (WIPE_DURATION_MS / safeSpeed), 1);
      return {
        ...staticFrame,
        done: progress >= 1,
        revealedColumns: Math.floor(progress * totalColumns),
      };
    };

    const computeBlinkFrame = (): FrameState => {
      const phase = Math.floor(elapsedMs / (BLINK_INTERVAL_MS / safeSpeed));
      const settled = !loop && phase >= BLINK_SETTLE_CYCLES * 2;
      return {
        ...staticFrame,
        done: settled,
        visible: settled || phase % 2 === 0,
      };
    };

    const computeMarqueeFrame = (): FrameState => {
      const columnsPerMs =
        (MARQUEE_COLUMNS_PER_SECOND * safeSpeed) / MS_PER_SECOND;
      return {
        ...staticFrame,
        done: false,
        offsetColumns: (elapsedMs * columnsPerMs) % Math.max(1, period),
      };
    };

    const computeFrame = (): FrameState => {
      if (animate === "type") {
        return computeTypeFrame();
      }
      if (animate === "wipe") {
        return computeWipeFrame();
      }
      if (animate === "blink") {
        return computeBlinkFrame();
      }
      if (animate === "marquee") {
        return computeMarqueeFrame();
      }
      return staticFrame;
    };

    const step = (timestamp: number) => {
      rafId = null;
      if (isPaused || isFinished) {
        return;
      }
      if (lastTimestamp !== null) {
        elapsedMs += timestamp - lastTimestamp;
      }
      lastTimestamp = timestamp;

      const frame = computeFrame();
      // A blinking display only changes twice a second, so repainting it every
      // rAF tick would be pure waste.
      if (!isSameFrame(frame, lastFrame)) {
        render(frame);
      }

      if (frame.done) {
        if (loop) {
          elapsedMs = 0;
          landedUnits = 0;
          flashStartedAtMs = Number.NEGATIVE_INFINITY;
        } else {
          render(staticFrame);
          isFinished = true;
          return;
        }
      }
      rafId = requestAnimationFrame(step);
    };

    const schedule = () => {
      if (isPaused || isFinished || rafId !== null) {
        return;
      }
      rafId = requestAnimationFrame(step);
    };

    const updatePauseState = () => {
      const shouldPause = isOffscreen || isHidden;
      if (shouldPause === isPaused) {
        return;
      }
      isPaused = shouldPause;
      if (isPaused) {
        if (rafId !== null) {
          cancelAnimationFrame(rafId);
          rafId = null;
        }
        lastTimestamp = null;
      } else {
        schedule();
      }
    };

    setBackingStoreSize();
    if (isFinished) {
      render(staticFrame);
    } else {
      render({ ...staticFrame, revealedColumns: 0 });
      schedule();
    }

    const resizeObserver = new ResizeObserver(() => {
      setBackingStoreSize();
      render(lastFrame);
    });
    resizeObserver.observe(container);

    const intersectionObserver = new IntersectionObserver((entries) => {
      const [entry] = entries;
      if (!entry) {
        return;
      }
      isOffscreen = !entry.isIntersecting;
      updatePauseState();
    });
    intersectionObserver.observe(container);

    const handleVisibilityChange = () => {
      isHidden = document.hidden;
      updatePauseState();
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      if (rafId !== null) {
        cancelAnimationFrame(rafId);
      }
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [
    grid,
    stablePalette,
    pixelSize,
    stride,
    columnsInView,
    glowIntensity,
    animate,
    speed,
    loop,
    shouldReduceMotion,
    totalColumns,
    numUnits,
    unitWidth,
    cssWidth,
    cssHeight,
  ]);

  return (
    <div
      className={cn("relative inline-block overflow-hidden", className)}
      ref={containerRef}
      style={{ height: cssHeight, width: cssWidth }}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 select-none"
      >
        <canvas className="block h-full w-full" ref={canvasRef} />
        <ArcadeCrtOverlay
          crt={crt}
          scanlines={scanlines}
          shouldReduceMotion={shouldReduceMotion}
        />
      </div>
      <span className="sr-only">{accessibleLabel}</span>
    </div>
  );
};

export default ArcadePixel;

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export type AsciiColorMode = "mono" | "source";

export interface AsciiRenderSource {
  /** URL of the image or video to sample. Must allow cross-origin reads. */
  src: string;
  /** Kind of media behind `src`. */
  type: "image" | "video";
}

export interface AsciiRenderProps {
  /** Description of the media. Exposed to assistive technology. */
  alt: string;
  /** Character ramp ordered dense to sparse. */
  charset?: string;
  /** Extra classes for the wrapper. */
  className?: string;
  /** `mono` paints one theme colour, `source` tints the glyphs with the frame. */
  color?: AsciiColorMode;
  /** Number of character columns sampled across the frame. */
  columns?: number;
  /** Glyph size in pixels. */
  fontSize?: number;
  /** Frames per second for video sources. */
  fps?: number;
  /** Flip the luminance-to-character mapping. */
  invert?: boolean;
  /** Hold the current frame without tearing down the renderer. */
  paused?: boolean;
  /** Media descriptor. */
  source: AsciiRenderSource;
}

type RenderStatus = "fallback" | "loading" | "ready";

const DEFAULT_CHARSET = "@%#*+=-:. ";
const DEFAULT_COLUMNS = 80;
const DEFAULT_FONT_SIZE = 10;
const DEFAULT_FPS = 24;
const MIN_COLUMNS = 8;
const MAX_COLUMNS = 240;
const MIN_FPS = 1;
const MAX_FPS = 60;
const CHAR_ASPECT = 0.5;
const CHANNELS = 4;
const MAX_CHANNEL = 255;
const LUMA_R = 0.2126;
const LUMA_G = 0.7152;
const LUMA_B = 0.0722;
const MS_PER_SECOND = 1000;
const NEWLINE = "\n";
const VISIBILITY_MARGIN = "0px 0px 10% 0px";

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(max, value));

const buildAscii = (
  data: Uint8ClampedArray,
  columns: number,
  rows: number,
  charset: string,
  invert: boolean
) => {
  const lastIndex = charset.length - 1;
  const glyphs: string[] = [];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < columns; x++) {
      const offset = (y * columns + x) * CHANNELS;
      const luminance =
        (data[offset] * LUMA_R +
          data[offset + 1] * LUMA_G +
          data[offset + 2] * LUMA_B) /
        MAX_CHANNEL;
      const level = invert ? 1 - luminance : luminance;
      glyphs.push(charset[clamp(Math.round(level * lastIndex), 0, lastIndex)]);
    }
    glyphs.push(NEWLINE);
  }
  return glyphs.join("");
};

const AsciiRender = ({
  alt,
  charset = DEFAULT_CHARSET,
  className,
  color = "mono",
  columns = DEFAULT_COLUMNS,
  fontSize = DEFAULT_FONT_SIZE,
  fps = DEFAULT_FPS,
  invert = false,
  paused = false,
  source,
}: AsciiRenderProps) => {
  const shouldReduceMotion = useReducedMotion();
  const containerRef = useRef<HTMLDivElement>(null);
  const preRef = useRef<HTMLPreElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [status, setStatus] = useState<RenderStatus>("loading");
  const [isVisible, setIsVisible] = useState(true);

  const { src: sourceSrc, type: sourceType } = source;
  const safeCharset = charset.length > 1 ? charset : DEFAULT_CHARSET;
  const safeColumns = clamp(Math.round(columns), MIN_COLUMNS, MAX_COLUMNS);
  const safeFps = clamp(Math.round(fps), MIN_FPS, MAX_FPS);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof IntersectionObserver === "undefined") {
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          setIsVisible(entry.isIntersecting);
        }
      },
      { rootMargin: VISIBILITY_MARGIN }
    );
    observer.observe(container);
    return () => {
      observer.disconnect();
    };
  }, []);

  useEffect(() => {
    const pre = preRef.current;
    const media = sourceType === "video" ? videoRef.current : imageRef.current;
    if (!(pre && media && sourceSrc)) {
      return;
    }

    const grid = document.createElement("canvas");
    const context = grid.getContext("2d", { willReadFrequently: true });
    if (!context) {
      setStatus("fallback");
      return;
    }

    const video = sourceType === "video" ? (media as HTMLVideoElement) : null;
    const image = sourceType === "image" ? (media as HTMLImageElement) : null;
    let frame = 0;
    let lastDrawnAt = 0;
    let isCancelled = false;

    const naturalSize = () => {
      if (video) {
        return { height: video.videoHeight, width: video.videoWidth };
      }
      return {
        height: image?.naturalHeight ?? 0,
        width: image?.naturalWidth ?? 0,
      };
    };

    const drawFrame = () => {
      const { height: mediaHeight, width: mediaWidth } = naturalSize();
      if (mediaWidth === 0 || mediaHeight === 0) {
        return false;
      }
      const rows = Math.max(
        1,
        Math.round((safeColumns * mediaHeight * CHAR_ASPECT) / mediaWidth)
      );
      grid.width = safeColumns;
      grid.height = rows;
      context.clearRect(0, 0, safeColumns, rows);
      context.drawImage(media, 0, 0, safeColumns, rows);

      const { data } = context.getImageData(0, 0, safeColumns, rows);
      pre.textContent = buildAscii(
        data,
        safeColumns,
        rows,
        safeCharset,
        invert
      );
      pre.style.backgroundImage =
        color === "source" ? `url(${grid.toDataURL()})` : "";
      return true;
    };

    const safeDraw = () => {
      try {
        return drawFrame();
      } catch {
        setStatus("fallback");
        return false;
      }
    };

    const tick = (time: number) => {
      if (isCancelled) {
        return;
      }
      const interval = MS_PER_SECOND / safeFps;
      if (time - lastDrawnAt >= interval) {
        lastDrawnAt = time;
        if (!safeDraw()) {
          return;
        }
      }
      frame = requestAnimationFrame(tick);
    };

    const start = () => {
      if (isCancelled) {
        return;
      }
      if (!safeDraw()) {
        return;
      }
      setStatus("ready");
      const isStatic = !video || shouldReduceMotion || paused || !isVisible;
      if (isStatic) {
        video?.pause();
        return;
      }
      const playback = video.play();
      playback?.catch(() => {
        setStatus("fallback");
      });
      frame = requestAnimationFrame(tick);
    };

    const handleError = () => {
      if (!isCancelled) {
        setStatus("fallback");
      }
    };

    if (video) {
      if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) {
        start();
      } else {
        video.addEventListener("loadeddata", start, { once: true });
      }
      video.addEventListener("error", handleError);
    } else if (image) {
      if (image.complete) {
        start();
      } else {
        image.addEventListener("load", start, { once: true });
      }
      image.addEventListener("error", handleError);
    }

    return () => {
      isCancelled = true;
      cancelAnimationFrame(frame);
      video?.removeEventListener("loadeddata", start);
      video?.removeEventListener("error", handleError);
      video?.pause();
      image?.removeEventListener("load", start);
      image?.removeEventListener("error", handleError);
      grid.width = 0;
      grid.height = 0;
    };
  }, [
    color,
    invert,
    isVisible,
    paused,
    safeCharset,
    safeColumns,
    safeFps,
    shouldReduceMotion,
    sourceSrc,
    sourceType,
  ]);

  const isFallback = status === "fallback";
  const mediaClassName = cn(
    "h-full w-full object-contain",
    isFallback ? "relative" : "pointer-events-none absolute inset-0 opacity-0"
  );

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-xl bg-background",
        className
      )}
      ref={containerRef}
    >
      {sourceType === "video" ? (
        <video
          aria-hidden="true"
          className={mediaClassName}
          crossOrigin="anonymous"
          loop
          muted
          playsInline
          preload="auto"
          ref={videoRef}
          src={sourceSrc}
          tabIndex={-1}
        />
      ) : (
        <img
          alt=""
          aria-hidden="true"
          className={mediaClassName}
          crossOrigin="anonymous"
          ref={imageRef}
          src={sourceSrc}
        />
      )}

      <pre
        aria-hidden="true"
        className={cn(
          "m-0 select-none whitespace-pre font-mono",
          color === "mono" ? "text-foreground" : "text-transparent",
          isFallback ? "hidden" : "block"
        )}
        ref={preRef}
        style={{
          backgroundClip: color === "source" ? "text" : undefined,
          backgroundSize: "100% 100%",
          fontSize,
          imageRendering: "pixelated",
          lineHeight: 1,
          WebkitBackgroundClip: color === "source" ? "text" : undefined,
        }}
      />

      <span className="sr-only">{alt}</span>
    </div>
  );
};

export default AsciiRender;

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

export type AuroraDirection = "up" | "down";

export interface AuroraCurtainProps {
  /** Number of aurora ribbons rendered behind the content. Clamped to 1-8. */
  bands?: number;
  /** Softness of every ribbon edge, from 0 (crisp) to 1 (very diffuse). */
  blur?: number;
  /** Foreground content, always painted above the decorative curtain. */
  children?: ReactNode;
  /** Extra classes for the positioned wrapper element. */
  className?: string;
  /**
   * Ribbon colours. Accepts any CSS colour, a `var(--token)` expression, or a
   * bare custom property name such as `--color-brand`.
   */
  colors?: string[];
  /** Direction the light flows towards. */
  direction?: AuroraDirection;
  /** Overall brightness multiplier, from 0 to 1. */
  intensity?: number;
  /**
   * Film-grain strength from `0` (clean) to `1` (heavily filmic). The grain is
   * re-seeded every frame and covers the whole surface, not only the ribbons,
   * so it reads as moving film stock rather than dust on the glass.
   * `true` is accepted as a shorthand for `0.6`, `false` for `0`.
   */
  noise?: number | boolean;
  /** Freezes the animation on the current frame. */
  paused?: boolean;
  /** Drift speed multiplier. 1 is the calibrated default. */
  speed?: number;
}

type Rgb = [number, number, number];

interface AuroraSettings {
  bands: number;
  blur: number;
  colors: Rgb[];
  direction: number;
  grain: number;
  intensity: number;
  speed: number;
}

interface AuroraController {
  destroy: () => void;
  render: () => void;
  resize: () => void;
  setRunning: (running: boolean) => void;
  setSettings: (settings: AuroraSettings) => void;
}

const MAX_DPR = 2;
const MAX_COLORS = 6;
const MAX_BANDS = 8;
const MIN_BANDS = 1;
const MS_PER_SECOND = 1000;
const GRAIN_SHORTHAND = 0.6;
const GRAIN_SEED_CYCLE = 977;
const RGB_MAX = 255;
const DEFAULT_BANDS = 4;
const DEFAULT_SPEED = 1;
const DEFAULT_BLUR = 0.5;
const DEFAULT_INTENSITY = 1;

/**
 * Theme tokens first; the literal after the comma is the same colour written
 * out for consumers who install the component without SmoothUI's theme. Every
 * literal here is authored in oklch so the three ribbons sit at one perceptual
 * lightness with each hue taking a comparable share of its own chroma ceiling.
 */
const DEFAULT_COLORS = [
  "var(--color-green, oklch(0.78 0.16 148))",
  "var(--color-blue, oklch(0.79 0.11 196))",
  "var(--color-brand, oklch(0.70 0.17 318))",
];

/**
 * sRGB conversions of the three oklch literals above, used only when the
 * document cannot be probed for computed colours.
 * oklch(0.78 0.16 148) · oklch(0.79 0.11 196) · oklch(0.70 0.17 318)
 */
const FALLBACK_COLORS: Rgb[] = [
  [0.399, 0.826, 0.48],
  [0.323, 0.817, 0.822],
  [0.79, 0.471, 0.886],
];

const VERTEX_SHADER = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

const FRAGMENT_SHADER = `#version 300 es
precision highp float;

out vec4 fragColor;

uniform vec2 uRes;
uniform float uTime;
uniform float uBands;
uniform float uSpeed;
uniform float uBlur;
uniform float uIntensity;
uniform float uDirection;
uniform float uGrain;
uniform float uSeed;
uniform float uPixel;
uniform int uColorCount;
uniform vec3 uColors[6];

const int MAX_BANDS = 8;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Grain hash: the per-frame seed is folded in so the pattern is reborn every
// frame instead of sitting on the screen like dust on the glass.
float grainHash(vec2 p, float seed) {
  return fract(sin(dot(p, vec2(12.9898, 78.233)) + seed * 1.6180339) * 43758.5453123);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Two-octave detail, normalised to 0..1. Used where a second octave changes
// the silhouette; anything that only needs a slow scalar uses sines instead,
// because every octave is four more transcendentals per fragment.
float fbm2(vec2 p) {
  float value = vnoise(p) * 0.5 + vnoise(p * 2.07 + 9.31) * 0.25;
  return value * 1.3333333;
}

// Three-octave meander for the ribbon path, normalised to 0..1.
float fbm3(vec2 p) {
  float value = 0.0;
  float amplitude = 0.5;
  for (int i = 0; i < 3; i++) {
    value += amplitude * vnoise(p);
    p = p * 2.03 + 7.13;
    amplitude *= 0.5;
  }
  return value * 1.1428571;
}

vec3 bandColor(int index) {
  int count = max(uColorCount, 1);
  int slot = index - (index / count) * count;
  return uColors[slot];
}

void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float flow = mix(1.0, -1.0, uDirection);
  float y = mix(uv.y, 1.0 - uv.y, uDirection);

  // Vertical falloff: dense near the base, dissolving towards the far edge
  // the way a real aurora thins out as it climbs.
  float rise = smoothstep(-0.10, 0.26, y);
  float fade = 1.0 - smoothstep(0.16, 1.08, y);
  float envelope = rise * fade * fade;

  vec3 accum = vec3(0.0);
  float alpha = 0.0;
  float bandCount = clamp(uBands, 1.0, float(MAX_BANDS));
  float spacing = 0.92 / bandCount;
  float t = uTime * uSpeed;

  for (int i = 0; i < MAX_BANDS; i++) {
    if (float(i) >= bandCount) {
      break;
    }
    float fi = float(i);
    float seed = fi * 13.37;

    // Path: a three-octave meander, a faster single-octave wobble and a slow
    // sine fold, all evaluated per height, so each ribbon folds along its own
    // length instead of sliding across as a rigid bar.
    float driftA = fbm3(vec2(y * 1.35 + seed, t * 0.16 + seed)) - 0.5;
    float driftB = vnoise(vec2(y * 3.40 - seed, t * 0.27 + seed * 0.5)) - 0.5;
    float fold = sin(y * 4.1 + t * 0.42 * flow + seed) * 0.045;
    float center = 0.04 + spacing * (fi + 0.5) + driftA * 0.52 + driftB * 0.18 + fold;

    // Width and softness vary ALONG the ribbon, pinching towards both ends.
    float widthNoise = fbm2(vec2(y * 2.7 + seed * 2.0, t * 0.22 + seed));
    float pinch = smoothstep(0.0, 0.22, y) * (1.0 - smoothstep(0.55, 1.08, y));
    float width = (0.010 + uBlur * 0.052)
      * mix(0.30, 1.85, widthNoise)
      * (0.45 + 0.75 * pinch);
    width = max(width, 0.0025);

    // A bright narrow core wrapped in a much wider halo that falls off at the
    // edges, rather than one flat gaussian per ribbon.
    float dx = (uv.x - center) / width;
    float d2 = dx * dx;
    float core = exp(-d2 * 2.60);
    float halo = exp(-d2 * 0.22);
    float ribbon = core * 1.30 + halo * 0.34;

    // Fine vertical striations scrolling along the flow direction, and a slow
    // brightness swell. The swell is two sines, not another noise octave.
    float rays = 0.45 + 0.85 * fbm2(vec2(uv.x * 13.0 + seed, y * 1.7 - flow * t * 0.55));
    float breathe = 0.78 + 0.22 * sin(t * 0.31 + seed) * cos(t * 0.17 + seed * 0.7);

    float weight = ribbon * envelope * rays * breathe * 0.46;
    vec3 hot = mix(bandColor(i), vec3(1.0), clamp(core * 0.42, 0.0, 0.45));
    accum += hot * weight;
    alpha += weight;
  }

  // Ground haze so the ribbons sit inside atmosphere rather than on nothing.
  float haze = envelope * (1.0 - smoothstep(0.0, 0.58, y)) * 0.10;
  accum += bandColor(0) * haze;
  alpha += haze;

  alpha = clamp(alpha * uIntensity, 0.0, 1.0);
  accum = max(accum * uIntensity, vec3(0.0));

  if (uGrain > 0.0) {
    // One grain cell per CSS pixel. Two hashes averaged give a triangular
    // distribution, which reads far more photographic than a flat one, and
    // costs two extra sines rather than a whole extra noise octave.
    vec2 cell = floor(gl_FragCoord.xy / max(uPixel, 1.0));
    float g = grainHash(cell, uSeed) + grainHash(cell + vec2(41.7, 17.3), uSeed + 7.31) - 1.0;
    float amp = uGrain * 0.42;

    // Modulate the light where there is light...
    accum *= 1.0 + g * amp * 1.10;

    // ...then lay a symmetric veil over the WHOLE surface. Positive grain adds
    // light; negative grain adds coverage with no colour, which darkens the
    // backdrop through the premultiplied blend. Without the second half the
    // grain would only ever brighten, and empty areas would stay glassy.
    float bright = max(g, 0.0) * amp * 0.48;
    float dark = max(-g, 0.0) * amp * 0.34;
    accum += vec3(bright);
    alpha = clamp(alpha + bright + dark, 0.0, 1.0);
  }

  fragColor = vec4(max(accum, vec3(0.0)), alpha);
}`;

const QUAD = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(max, value));

const toCssColor = (input: string) =>
  input.trim().startsWith("--") ? `var(${input.trim()})` : input.trim();

const resolveGrain = (noise: number | boolean) => {
  if (typeof noise === "boolean") {
    return noise ? GRAIN_SHORTHAND : 0;
  }
  return clamp(noise, 0, 1);
};

const resolveCssColors = (inputs: string[], host: HTMLElement): Rgb[] => {
  const probe = document.createElement("span");
  probe.style.display = "none";
  host.append(probe);

  const canvas = document.createElement("canvas");
  canvas.width = 1;
  canvas.height = 1;
  const context = canvas.getContext("2d", { willReadFrequently: true });

  const resolved = inputs.map((input, index) => {
    const fallback = FALLBACK_COLORS[index % FALLBACK_COLORS.length];
    if (!context) {
      return fallback;
    }
    probe.style.color = "";
    probe.style.color = toCssColor(input);
    const computed = window.getComputedStyle(probe).color;
    if (!computed) {
      return fallback;
    }
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = "#000000";
    context.fillStyle = computed;
    context.fillRect(0, 0, 1, 1);
    const { data } = context.getImageData(0, 0, 1, 1);
    return [data[0] / RGB_MAX, data[1] / RGB_MAX, data[2] / RGB_MAX] as Rgb;
  });

  probe.remove();
  return resolved;
};

const compileShader = (
  gl: WebGL2RenderingContext,
  type: number,
  source: string
) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

const createAuroraController = (
  canvas: HTMLCanvasElement
): AuroraController | null => {
  const gl = canvas.getContext("webgl2", {
    alpha: true,
    antialias: false,
    premultipliedAlpha: true,
  });
  if (!gl) {
    return null;
  }

  const vertex = compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragment = compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  const program = gl.createProgram();
  if (!(vertex && fragment && program)) {
    return null;
  }

  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }

  // biome-ignore lint/correctness/useHookAtTopLevel: WebGL2RenderingContext.useProgram is not a React hook.
  gl.useProgram(program);

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, QUAD, gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, "aPosition");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

  const uRes = gl.getUniformLocation(program, "uRes");
  const uTime = gl.getUniformLocation(program, "uTime");
  const uBands = gl.getUniformLocation(program, "uBands");
  const uSpeed = gl.getUniformLocation(program, "uSpeed");
  const uBlur = gl.getUniformLocation(program, "uBlur");
  const uIntensity = gl.getUniformLocation(program, "uIntensity");
  const uDirection = gl.getUniformLocation(program, "uDirection");
  const uGrain = gl.getUniformLocation(program, "uGrain");
  const uSeed = gl.getUniformLocation(program, "uSeed");
  const uPixel = gl.getUniformLocation(program, "uPixel");
  const uColorCount = gl.getUniformLocation(program, "uColorCount");
  const uColors = gl.getUniformLocation(program, "uColors");

  const palette = new Float32Array(MAX_COLORS * 3);
  const startedAt = performance.now();
  let settings: AuroraSettings = {
    bands: DEFAULT_BANDS,
    blur: DEFAULT_BLUR,
    colors: FALLBACK_COLORS,
    direction: 0,
    grain: 0,
    intensity: DEFAULT_INTENSITY,
    speed: DEFAULT_SPEED,
  };
  let colorCount = FALLBACK_COLORS.length;
  let pixelRatio = 1;
  let grainSeed = 0;
  let frame = 0;
  let running = false;
  let destroyed = false;

  const applyPalette = () => {
    colorCount = clamp(settings.colors.length, 1, MAX_COLORS);
    for (let i = 0; i < colorCount; i++) {
      const rgb = settings.colors[i] ?? FALLBACK_COLORS[0];
      palette[i * 3] = rgb[0];
      palette[i * 3 + 1] = rgb[1];
      palette[i * 3 + 2] = rgb[2];
    }
  };
  applyPalette();

  const resize = () => {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    pixelRatio = dpr;
    const width = Math.max(1, Math.round(rect.width * dpr));
    const height = Math.max(1, Math.round(rect.height * dpr));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
      gl.viewport(0, 0, width, height);
    }
  };

  const draw = () => {
    if (destroyed) {
      return;
    }
    // A frame counter, not Math.random: deterministic, and it re-seeds the
    // grain hash so the pattern never freezes on screen.
    grainSeed = (grainSeed + 1) % GRAIN_SEED_CYCLE;
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(uRes, canvas.width, canvas.height);
    gl.uniform1f(uTime, (performance.now() - startedAt) / MS_PER_SECOND);
    gl.uniform1f(uBands, settings.bands);
    gl.uniform1f(uSpeed, settings.speed);
    gl.uniform1f(uBlur, settings.blur);
    gl.uniform1f(uIntensity, settings.intensity);
    gl.uniform1f(uDirection, settings.direction);
    gl.uniform1f(uGrain, settings.grain);
    gl.uniform1f(uSeed, grainSeed);
    gl.uniform1f(uPixel, pixelRatio);
    gl.uniform1i(uColorCount, colorCount);
    gl.uniform3fv(uColors, palette);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  };

  const tick = () => {
    if (destroyed || !running) {
      return;
    }
    draw();
    frame = requestAnimationFrame(tick);
  };

  resize();

  return {
    destroy: () => {
      destroyed = true;
      running = false;
      cancelAnimationFrame(frame);
      if (buffer) {
        gl.deleteBuffer(buffer);
      }
      gl.deleteProgram(program);
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    },
    render: () => {
      resize();
      draw();
    },
    resize: () => {
      resize();
      if (!running) {
        draw();
      }
    },
    setRunning: (next: boolean) => {
      if (destroyed || running === next) {
        return;
      }
      running = next;
      if (next) {
        frame = requestAnimationFrame(tick);
      } else {
        cancelAnimationFrame(frame);
      }
    },
    setSettings: (next: AuroraSettings) => {
      settings = next;
      applyPalette();
    },
  };
};

const AuroraCurtain = ({
  bands = DEFAULT_BANDS,
  blur = DEFAULT_BLUR,
  children,
  className,
  colors = DEFAULT_COLORS,
  direction = "up",
  intensity = DEFAULT_INTENSITY,
  noise = 0,
  paused = false,
  speed = DEFAULT_SPEED,
}: AuroraCurtainProps) => {
  const shouldReduceMotion = useReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controllerRef = useRef<AuroraController | null>(null);
  const [isSupported, setIsSupported] = useState(true);
  const [isActive, setIsActive] = useState(false);
  const [resolvedColors, setResolvedColors] = useState<Rgb[]>(FALLBACK_COLORS);

  const colorKey = colors.join("|");
  const grain = resolveGrain(noise);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) {
      return;
    }
    setResolvedColors(resolveCssColors(colorKey.split("|"), host));
  }, [colorKey]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const controller = createAuroraController(canvas);
    controllerRef.current = controller;
    setIsSupported(controller !== null);
    if (!controller) {
      return;
    }

    const observer = new ResizeObserver(() => controller.resize());
    observer.observe(canvas);

    return () => {
      observer.disconnect();
      controller.destroy();
      controllerRef.current = null;
    };
  }, []);

  useEffect(() => {
    const host = hostRef.current;
    if (!(host && isSupported)) {
      return;
    }

    let isOnScreen = true;
    const sync = () => {
      setIsActive(isOnScreen && document.visibilityState === "visible");
    };

    const observer = new IntersectionObserver((entries) => {
      isOnScreen = entries.some((entry) => entry.isIntersecting);
      sync();
    });
    observer.observe(host);
    document.addEventListener("visibilitychange", sync);
    sync();

    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", sync);
    };
  }, [isSupported]);

  useEffect(() => {
    const controller = controllerRef.current;
    if (!controller) {
      return;
    }
    controller.setSettings({
      bands: clamp(Math.round(bands), MIN_BANDS, MAX_BANDS),
      blur: clamp(blur, 0, 1),
      colors: resolvedColors,
      direction: direction === "down" ? 1 : 0,
      grain,
      intensity: clamp(intensity, 0, 1),
      speed: Math.max(speed, 0),
    });
    controller.render();
  }, [bands, blur, direction, grain, intensity, resolvedColors, speed]);

  useEffect(() => {
    const controller = controllerRef.current;
    if (!controller) {
      return;
    }
    const shouldRun = isActive && !paused && !shouldReduceMotion;
    controller.setRunning(shouldRun);
    if (!shouldRun) {
      controller.render();
    }
  }, [isActive, paused, shouldReduceMotion]);

  const fallbackBackground = colors
    .map((color, index) => {
      const x = 14 + index * (72 / Math.max(colors.length, 1));
      const y = direction === "up" ? 108 : -8;
      return `radial-gradient(58% 96% at ${x}% ${y}%, ${toCssColor(color)} 0%, transparent 68%)`;
    })
    .join(", ");

  return (
    <div
      className={cn("relative isolate overflow-hidden", className)}
      ref={hostRef}
    >
      {isSupported ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        >
          <canvas className="h-full w-full" ref={canvasRef} />
        </div>
      ) : (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 opacity-70 blur-2xl"
          style={{ backgroundImage: fallbackBackground }}
        />
      )}
      <div className="relative z-10">{children}</div>
    </div>
  );
};

export default AuroraCurtain;

