/** A single breadcrumb item definition. */
export type BreadcrumbItemProps = {
  /** Display label for the breadcrumb item. */
  label: ReactNode;
  /** URL the breadcrumb links to. Omit for the current (last) page. */
  href?: string;
};

export type BreadcrumbProps = {
  /** Ordered list of breadcrumb items. The last item is treated as the current page. */
  items: BreadcrumbItemProps[];
  /** Custom separator element. Defaults to a chevron icon. */
  separator?: ReactNode;
  /** Additional CSS classes for the nav element. */
  className?: string;
};

const staggerDelay = 0.04;

export default function Breadcrumb({
  items,
  separator,
  className,
}: BreadcrumbProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <nav aria-label="Breadcrumb" className={cn("inline-flex", className)}>
      <ol className="flex flex-wrap items-center gap-1.5 text-muted-foreground text-sm sm:gap-2.5">
        {items.map((item, index) => {
          const isLast = index === items.length - 1;

          return (
            <motion.li
              animate={{ opacity: 1, transform: "translateX(0px)" }}
              className="inline-flex items-center gap-1.5"
              initial={
                shouldReduceMotion
                  ? { opacity: 1 }
                  : { opacity: 0, transform: "translateX(-4px)" }
              }
              key={
                typeof item.label === "string"
                  ? item.label
                  : `breadcrumb-${String(index)}`
              }
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      ...SPRING_DEFAULT,
                      delay: index * staggerDelay,
                    }
              }
            >
              {index > 0 && (
                <span
                  aria-hidden="true"
                  className="mr-1.5 [&>svg]:size-3.5"
                  role="presentation"
                >
                  {separator ?? <ChevronRight className="size-3.5" />}
                </span>
              )}
              {isLast ? (
                <span
                  aria-current="page"
                  className="font-normal text-foreground"
                >
                  {item.label}
                </span>
              ) : (
                <a
                  className="transition-colors hover:text-foreground"
                  href={item.href ?? "#"}
                >
                  {item.label}
                </a>
              )}
            </motion.li>
          );
        })}
      </ol>
    </nav>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

const STORAGE_KEY = "smoothui:breakpoint-indicator:visible";
const DEFAULT_HOTKEY = "b";
const DEFAULT_POSITION: BreakpointIndicatorPosition = "bottom-left";
const BASE_BREAKPOINT_NAME = "base";
const RULER_MIN_PERCENT = 0;
const RULER_MAX_PERCENT = 100;

const DEFAULT_BREAKPOINTS: Breakpoint[] = [
  { min: 640, name: "sm" },
  { min: 768, name: "md" },
  { min: 1024, name: "lg" },
  { min: 1280, name: "xl" },
  { min: 1536, name: "2xl" },
];

export interface Breakpoint {
  min: number;
  name: string;
}

export type BreakpointIndicatorPosition =
  | "bottom-left"
  | "bottom-right"
  | "top-left"
  | "top-right";

export interface BreakpointIndicatorProps {
  breakpoints?: Breakpoint[];
  className?: string;
  enabled?: boolean;
  fixed?: boolean;
  hotkey?: string;
  position?: BreakpointIndicatorPosition;
  showRuler?: boolean;
  showSize?: boolean;
}

const POSITION_CLASSES: Record<BreakpointIndicatorPosition, string> = {
  "bottom-left": "bottom-3 left-3",
  "bottom-right": "bottom-3 right-3",
  "top-left": "top-3 left-3",
  "top-right": "top-3 right-3",
};

const readStoredVisibility = (): boolean => {
  if (typeof window === "undefined") {
    return true;
  }

  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    return stored === null ? true : stored === "true";
  } catch {
    return true;
  }
};

const getActiveBreakpoint = (
  breakpoints: Breakpoint[],
  width: number
): { active: Breakpoint; next: Breakpoint | null } => {
  const sorted = [...breakpoints].sort((a, b) => a.min - b.min);
  let active: Breakpoint = { min: 0, name: BASE_BREAKPOINT_NAME };
  let next: Breakpoint | null = sorted[0] ?? null;

  for (let index = 0; index < sorted.length; index += 1) {
    const candidate = sorted[index];
    if (width >= candidate.min) {
      active = candidate;
      next = sorted[index + 1] ?? null;
    }
  }

  return { active, next };
};

const clampPercent = (value: number): number =>
  Math.min(RULER_MAX_PERCENT, Math.max(RULER_MIN_PERCENT, value));

export default function BreakpointIndicator({
  breakpoints = DEFAULT_BREAKPOINTS,
  className,
  enabled = process.env.NODE_ENV !== "production",
  fixed = true,
  hotkey = DEFAULT_HOTKEY,
  position = DEFAULT_POSITION,
  showRuler = false,
  showSize = true,
}: BreakpointIndicatorProps) {
  const shouldReduceMotion = useReducedMotion();
  const [width, setWidth] = useState(0);
  const [height, setHeight] = useState(0);
  const [visible, setVisible] = useState<boolean>(readStoredVisibility);

  useEffect(() => {
    if (!enabled || typeof document === "undefined") {
      return;
    }

    let frame = 0;
    const measure = () => {
      frame = 0;
      setWidth(document.documentElement.clientWidth);
      setHeight(document.documentElement.clientHeight);
    };

    const observer = new ResizeObserver(() => {
      if (frame) {
        return;
      }
      frame = window.requestAnimationFrame(measure);
    });

    observer.observe(document.documentElement);
    measure();

    return () => {
      observer.disconnect();
      if (frame) {
        window.cancelAnimationFrame(frame);
      }
    };
  }, [enabled]);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    const normalizedHotkey = hotkey.toLowerCase();
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        (event.metaKey || event.ctrlKey) &&
        event.key.toLowerCase() === normalizedHotkey
      ) {
        event.preventDefault();
        setVisible((prev) => !prev);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [enabled, hotkey]);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    try {
      window.localStorage.setItem(STORAGE_KEY, String(visible));
    } catch {
      // localStorage unavailable (private mode, blocked storage, etc.)
    }
  }, [enabled, visible]);

  if (!(enabled && visible)) {
    return null;
  }

  const { active, next } = getActiveBreakpoint(breakpoints, width);
  const rulerPercent = next
    ? clampPercent(((width - active.min) / (next.min - active.min)) * 100)
    : RULER_MAX_PERCENT;
  const remainingPx = next ? Math.max(0, next.min - width) : 0;

  return (
    <div
      aria-label={`Current breakpoint ${active.name}, viewport ${width} by ${height} pixels`}
      aria-live="polite"
      className={cn(
        "z-50 flex items-center gap-2 rounded-full border border-foreground/10 bg-background/95 px-3 py-1.5 font-mono text-foreground text-xs shadow-lg backdrop-blur",
        fixed ? "fixed" : "absolute",
        POSITION_CLASSES[position],
        className
      )}
      role="status"
    >
      <div className="relative h-4 overflow-hidden">
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            animate={
              shouldReduceMotion ? { opacity: 1, y: 0 } : { opacity: 1, y: 0 }
            }
            className="inline-block font-semibold uppercase tracking-wide"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { opacity: 0, y: -8 }
            }
            initial={
              shouldReduceMotion ? { opacity: 1, y: 0 } : { opacity: 0, y: 8 }
            }
            key={active.name}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { bounce: 0.1, duration: 0.25, type: "spring" }
            }
          >
            {active.name}
          </motion.span>
        </AnimatePresence>
      </div>

      {showSize ? (
        <span className="text-foreground/60">
          {width}×{height}
        </span>
      ) : null}

      {showRuler ? (
        <div aria-hidden="true" className="flex items-center gap-1.5">
          <div className="h-1 w-16 overflow-hidden rounded-full bg-foreground/10">
            <div
              className="h-full bg-foreground/60"
              style={{ width: `${rulerPercent}%` }}
            />
          </div>
          {next ? (
            <span className="text-foreground/40">{remainingPx}px</span>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { Check, Copy, LoaderCircle } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

export interface ButtonCopyProps {
  className?: string;
  disabled?: boolean;
  duration?: number;
  idleIcon?: ReactNode;
  loadingDuration?: number;
  loadingIcon?: ReactNode;
  onCopy?: () => Promise<void> | void;
  successIcon?: ReactNode;
}

const defaultIcons = {
  idle: <Copy size={16} />,
  loading: (
    <LoaderCircle
      className="animate-spin motion-reduce:animate-none"
      size={16}
    />
  ),
  success: <Check size={16} />,
};

export default function ButtonCopy({
  onCopy,
  idleIcon = defaultIcons.idle,
  loadingIcon = defaultIcons.loading,
  successIcon = defaultIcons.success,
  className = "",
  duration = 2000,
  loadingDuration = 1000,
  disabled = false,
}: ButtonCopyProps) {
  const [buttonState, setButtonState] = useState<
    "idle" | "loading" | "success" | "error"
  >("idle");
  const shouldReduceMotion = useReducedMotion();

  const requestId = useRef(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(
    () => () => {
      requestId.current += 1;
      for (const timer of timers.current) {
        clearTimeout(timer);
      }
    },
    []
  );

  const handleClick = useCallback(async () => {
    const request = ++requestId.current;
    setButtonState("loading");
    try {
      await onCopy?.();
    } catch {
      if (request === requestId.current) {
        setButtonState("error");
      }
      return;
    }
    if (request !== requestId.current) {
      return;
    }
    timers.current = [
      setTimeout(() => setButtonState("success"), loadingDuration),
      setTimeout(() => setButtonState("idle"), loadingDuration + duration),
    ];
  }, [onCopy, loadingDuration, duration]);

  const icons = {
    error: idleIcon,
    idle: idleIcon,
    loading: loadingIcon,
    success: successIcon,
  };

  const ariaLabels = {
    error: "Copy failed. Try again",
    idle: "Copy",
    loading: "Copying...",
    success: "Copied",
  };

  return (
    <div className="flex justify-center">
      <button
        aria-label={ariaLabels[buttonState]}
        aria-live="polite"
        className={`relative min-h-[44px] w-auto min-w-[44px] cursor-pointer overflow-hidden rounded-full border bg-background p-3 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:opacity-50 ${className}`}
        disabled={
          buttonState === "loading" || buttonState === "success" || disabled
        }
        onClick={handleClick}
        type="button"
      >
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            animate={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(0px)", opacity: 1, y: 0 }
            }
            className="flex w-full items-center justify-center"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { filter: "blur(10px)", opacity: 0, y: 25 }
            }
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(10px)", opacity: 0, y: -25 }
            }
            key={buttonState}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { bounce: 0, duration: 0.25, type: "spring" as const }
            }
          >
            {icons[buttonState]}
          </motion.span>
        </AnimatePresence>
      </button>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  animate,
  motion,
  type PanInfo,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react";
import {
  type KeyboardEvent,
  type ReactNode,
  type Ref,
  useCallback,
  useEffect,
  useImperativeHandle,
  useState,
} from "react";

const DEFAULT_THRESHOLD = 110; // px of horizontal drag needed to commit
const DEFAULT_ROTATION_FACTOR = 18; // deg at the edge of DRAG_RANGE
const DEFAULT_STACK_SIZE = 3;
const DEFAULT_STACK_OFFSET = 14; // px per receding card
const STACK_SCALE_STEP = 0.05;
const DRAG_RANGE = 260; // px input domain for the rotation transform
const VELOCITY_COMMIT_THRESHOLD = 450; // px/s
const EXIT_DISTANCE = 900; // px travelled before unmount
const STAMP_RATIO = 0.85; // stamps hit full strength just before the threshold
const WASH_RATIO = 1.35; // the colour wash lags the stamps slightly
const WASH_MAX_OPACITY = 0.9;
const MIN_THROW_SPEED = 750; // px/s floor so button swipes still fly
const THROW_DURATION = 0.34;
const FADE_DELAY = 0.2;
const FADE_DURATION = 0.14;
const VERTICAL_LIMIT = 90; // px of vertical give while dragging
const STAMP_MIN_SCALE = 0.7;
const DEFAULT_THROW_LIFT = -160; // px/s upward bias for non-drag commits
/**
 * Rotation pivot sits *below* the bottom edge of the card. This is the detail
 * that makes the Tinder tilt read correctly: the card swings around a point
 * near the user's hand rather than around its own centre.
 */
const PIVOT_ORIGIN = "50% 165%";
const THROW_TRANSITION = {
  bounce: 0,
  duration: THROW_DURATION,
  type: "spring" as const,
};
const SNAP_BACK_TRANSITION = {
  bounce: 0.3,
  duration: 0.45,
  type: "spring" as const,
};
const STACK_TRANSITION = {
  bounce: 0.1,
  duration: 0.25,
  type: "spring" as const,
};
const FADE_EASE = [0.645, 0.045, 0.355, 1] as const;

export type SwipeDirection = "left" | "right";

export interface CardSwipeDeckItem {
  content: ReactNode;
  id: string;
}

export interface CardSwipeDeckLabels {
  left?: string;
  right?: string;
}

export interface CardSwipeDeckHandle {
  reset: () => void;
  swipeLeft: () => void;
  swipeRight: () => void;
}

export interface CardSwipeDeckProps {
  className?: string;
  disabled?: boolean;
  items: CardSwipeDeckItem[];
  /** Stamp copy burned into the top corners, e.g. `{ left: "Nope", right: "Like" }`. */
  labels?: CardSwipeDeckLabels;
  onEmpty?: () => void;
  onSwipe?: (id: string, direction: SwipeDirection) => void;
  ref?: Ref<CardSwipeDeckHandle>;
  /** Max rotation (degrees) applied at the edge of the drag range. */
  rotationFactor?: number;
  /** Vertical offset (px) applied to each receding card in the stack. */
  stackOffset?: number;
  /** How many cards are visible in the stack, front card included. */
  stackSize?: number;
  /** Drag distance (px) required to commit a swipe. */
  threshold?: number;
}

interface ThrowVector {
  direction: SwipeDirection;
  vx: number;
  vy: number;
}

interface DeckCardProps {
  disabled: boolean;
  isFront: boolean;
  item: CardSwipeDeckItem;
  labels: Required<CardSwipeDeckLabels>;
  onCommit: (direction: SwipeDirection, info?: PanInfo) => void;
  onExitComplete: () => void;
  pos: number;
  rotationFactor: number;
  shouldReduceMotion: boolean;
  stackOffset: number;
  stackSize: number;
  threshold: number;
  throwVector: ThrowVector | null;
  zIndex: number;
}

const DeckCard = ({
  disabled,
  isFront,
  item,
  labels,
  onCommit,
  onExitComplete,
  pos,
  rotationFactor,
  shouldReduceMotion,
  stackOffset,
  stackSize,
  threshold,
  throwVector,
  zIndex,
}: DeckCardProps) => {
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const isExiting = throwVector !== null;

  const rotate = useTransform(
    x,
    [-DRAG_RANGE, DRAG_RANGE],
    [-rotationFactor, rotationFactor]
  );

  const stampSpan = threshold * STAMP_RATIO;
  const washSpan = threshold * WASH_RATIO;

  // Stamps and wash are driven straight off the drag distance, so they bloom
  // continuously under the finger instead of snapping in at the threshold.
  const likeOpacity = useTransform(x, [0, stampSpan], [0, 1]);
  const likeScale = useTransform(x, [0, stampSpan], [STAMP_MIN_SCALE, 1]);
  const nopeOpacity = useTransform(x, [-stampSpan, 0], [1, 0]);
  const nopeScale = useTransform(x, [-stampSpan, 0], [1, STAMP_MIN_SCALE]);
  const likeWash = useTransform(x, [0, washSpan], [0, WASH_MAX_OPACITY]);
  const nopeWash = useTransform(x, [-washSpan, 0], [WASH_MAX_OPACITY, 0]);

  useEffect(() => {
    if (!throwVector || shouldReduceMotion) {
      return;
    }
    const targetX =
      throwVector.direction === "left" ? -EXIT_DISTANCE : EXIT_DISTANCE;
    const speed = Math.max(Math.abs(throwVector.vx), MIN_THROW_SPEED);
    const signedVx = throwVector.direction === "left" ? -speed : speed;
    // Keep the throw on the trajectory the finger was already describing.
    const targetY = y.get() + throwVector.vy * THROW_DURATION;

    const xControls = animate(x, targetX, {
      ...THROW_TRANSITION,
      velocity: signedVx,
    });
    const yControls = animate(y, targetY, {
      ...THROW_TRANSITION,
      velocity: throwVector.vy,
    });

    return () => {
      xControls.stop();
      yControls.stop();
    };
  }, [throwVector, shouldReduceMotion, x, y]);

  const handleDragEnd = useCallback(
    (_event: unknown, info: PanInfo) => {
      if (disabled) {
        return;
      }
      const shouldCommit =
        Math.abs(info.offset.x) > threshold ||
        Math.abs(info.velocity.x) > VELOCITY_COMMIT_THRESHOLD;

      if (shouldCommit) {
        onCommit(info.offset.x > 0 ? "right" : "left", info);
        return;
      }
      // Below threshold: elastic snap back to centre.
      animate(x, 0, SNAP_BACK_TRANSITION);
      animate(y, 0, SNAP_BACK_TRANSITION);
    },
    [disabled, onCommit, threshold, x, y]
  );

  const isBuried = pos >= stackSize;
  const canDrag = isFront && !disabled && !isExiting;

  return (
    <motion.div
      animate={{
        scale: 1 - pos * STACK_SCALE_STEP,
        y: pos * stackOffset,
      }}
      className="absolute inset-0"
      initial={false}
      style={{ zIndex }}
      transition={shouldReduceMotion ? { duration: 0 } : STACK_TRANSITION}
    >
      <motion.div
        animate={
          isExiting
            ? {
                opacity: 0,
                transition: shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      delay: FADE_DELAY,
                      duration: FADE_DURATION,
                      ease: FADE_EASE,
                    },
              }
            : { opacity: isBuried ? 0 : 1 }
        }
        className="relative h-full w-full cursor-grab overflow-hidden rounded-[28px] bg-background shadow-[0_1px_2px_rgba(0,0,0,0.06),0_10px_20px_-8px_rgba(0,0,0,0.18),0_28px_56px_-20px_rgba(0,0,0,0.32)] ring-1 ring-foreground/10 active:cursor-grabbing"
        drag={canDrag}
        initial={false}
        dragConstraints={{ bottom: VERTICAL_LIMIT, top: -VERTICAL_LIMIT }}
        dragElastic={{ bottom: 0.35, left: 1, right: 1, top: 0.35 }}
        dragMomentum={false}
        onAnimationComplete={() => {
          if (isExiting) {
            onExitComplete();
          }
        }}
        onDragEnd={handleDragEnd}
        style={{
          rotate,
          transformOrigin: PIVOT_ORIGIN,
          x,
          y,
        }}
        transition={shouldReduceMotion ? { duration: 0 } : STACK_TRANSITION}
        whileDrag={shouldReduceMotion ? undefined : { scale: 1.02 }}
      >
        {item.content}

        {/* Kept mounted through the throw so the stamp flies off with the card. */}
        {isFront ? (
          <>
            {/* Colour wash — the card itself tints toward the outcome. */}
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 bg-gradient-to-l from-green/55 via-green/15 to-transparent"
              style={{ opacity: likeWash }}
            />
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 bg-gradient-to-r from-destructive/55 via-destructive/15 to-transparent"
              style={{ opacity: nopeWash }}
            />

            {/* Stamps — outlined, rotated, driven by drag distance. */}
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute top-7 left-6 rounded-xl border-[3px] border-green px-3 py-1 font-black text-2xl text-green uppercase leading-none tracking-[0.08em] drop-shadow-sm"
              style={{
                opacity: likeOpacity,
                rotate: -20,
                scale: likeScale,
              }}
            >
              {labels.right}
            </motion.div>
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute top-7 right-6 rounded-xl border-[3px] border-destructive px-3 py-1 font-black text-2xl text-destructive uppercase leading-none tracking-[0.08em] drop-shadow-sm"
              style={{
                opacity: nopeOpacity,
                rotate: 20,
                scale: nopeScale,
              }}
            >
              {labels.left}
            </motion.div>
          </>
        ) : null}
      </motion.div>
    </motion.div>
  );
};

export default function CardSwipeDeck({
  className,
  disabled = false,
  items,
  labels,
  onEmpty,
  onSwipe,
  ref,
  rotationFactor = DEFAULT_ROTATION_FACTOR,
  stackOffset = DEFAULT_STACK_OFFSET,
  stackSize = DEFAULT_STACK_SIZE,
  threshold = DEFAULT_THRESHOLD,
}: CardSwipeDeckProps) {
  const shouldReduceMotion = useReducedMotion();
  const [removedIds, setRemovedIds] = useState<Set<string>>(new Set());
  const [exiting, setExiting] = useState<{
    id: string;
    vector: ThrowVector;
  } | null>(null);

  const remaining = items.filter((item) => !removedIds.has(item.id));
  // One extra card is mounted so the stack keeps its depth while the top
  // card is flying away.
  const visible = remaining.slice(0, stackSize + 1);

  const commitSwipe = useCallback(
    (direction: SwipeDirection, info?: PanInfo) => {
      if (disabled || exiting) {
        return;
      }
      const [top] = remaining;
      if (!top) {
        return;
      }
      onSwipe?.(top.id, direction);
      const wasLast = remaining.length === 1;

      if (shouldReduceMotion) {
        setRemovedIds((prev) => new Set(prev).add(top.id));
      } else {
        setExiting({
          id: top.id,
          vector: {
            direction,
            vx: info?.velocity.x ?? 0,
            vy: info?.velocity.y ?? DEFAULT_THROW_LIFT,
          },
        });
      }
      if (wasLast) {
        onEmpty?.();
      }
    },
    [disabled, exiting, onEmpty, onSwipe, remaining, shouldReduceMotion]
  );

  const handleExitComplete = useCallback((id: string) => {
    setRemovedIds((prev) => new Set(prev).add(id));
    setExiting(null);
  }, []);

  useImperativeHandle(
    ref,
    () => ({
      reset: () => {
        setRemovedIds(new Set());
        setExiting(null);
      },
      swipeLeft: () => commitSwipe("left"),
      swipeRight: () => commitSwipe("right"),
    }),
    [commitSwipe]
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) {
      return;
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      commitSwipe("left");
    } else if (event.key === "ArrowRight" || event.key === "Enter") {
      event.preventDefault();
      commitSwipe("right");
    }
  };

  const resolvedLabels: Required<CardSwipeDeckLabels> = {
    left: labels?.left ?? "Nope",
    right: labels?.right ?? "Like",
  };

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: Interactive swipeable widget requires event handlers
    <div
      aria-label="Swipeable card deck"
      className={cn(
        "relative h-[480px] w-[340px] max-w-full touch-pan-y outline-none",
        className
      )}
      onKeyDown={handleKeyDown}
      role="application"
      // biome-ignore lint/a11y/noNoninteractiveTabindex: Required for keyboard navigation
      tabIndex={0}
    >
      {visible.length === 0 ? (
        <div className="flex h-full w-full items-center justify-center rounded-[28px] border border-foreground/10 border-dashed">
          <p className="text-center text-muted-foreground text-sm">
            No more cards
          </p>
        </div>
      ) : (
        visible.map((item, index) => {
          const isExitingCard = exiting?.id === item.id;
          // While the top card leaves, everything behind it slides forward
          // one slot — the next card scales up as the throw happens.
          const pos = exiting ? Math.max(index - 1, 0) : index;

          return (
            <DeckCard
              disabled={disabled}
              isFront={index === 0}
              item={item}
              key={item.id}
              labels={resolvedLabels}
              onCommit={commitSwipe}
              onExitComplete={() => handleExitComplete(item.id)}
              pos={isExitingCard ? 0 : pos}
              rotationFactor={rotationFactor}
              shouldReduceMotion={Boolean(shouldReduceMotion)}
              stackOffset={stackOffset}
              stackSize={stackSize}
              threshold={threshold}
              throwVector={isExitingCard ? exiting.vector : null}
              zIndex={visible.length - index}
            />
          );
        })
      )}
      <div aria-live="polite" className="sr-only">
        {remaining.length > 0
          ? `${remaining.length} card${remaining.length === 1 ? "" : "s"} remaining`
          : "No cards remaining"}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { Checkbox as CheckboxPrimitive } from "radix-ui";
import { SPRING_DEFAULT } from "@/components/smoothui/lib/animation";

export interface CheckboxProps {
  /** Accessible name, for checkboxes without a visible `<label>` */
  "aria-label"?: string;
  /** ID of the element labelling the checkbox */
  "aria-labelledby"?: string;
  /** Whether the checkbox is checked */
  checked?: boolean;
  /** Optional CSS class */
  className?: string;
  /** Whether the checkbox is disabled */
  disabled?: boolean;
  /** ID for label association */
  id?: string;
  /** Whether the checkbox is in an indeterminate state */
  indeterminate?: boolean;
  /** Name attribute for form submission */
  name?: string;
  /** Callback when the checked state changes */
  onCheckedChange?: (checked: boolean) => void;
  /** Whether the checkbox is required */
  required?: boolean;
  /** Value attribute for form submission */
  value?: string;
}

const CheckmarkPath = motion.path;
const MotionSvg = motion.svg;

export default function Checkbox({
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  checked = false,
  indeterminate = false,
  onCheckedChange,
  disabled = false,
  className,
  name,
  value,
  id,
  required,
}: CheckboxProps) {
  const shouldReduceMotion = useReducedMotion();

  const derivedState = indeterminate
    ? "indeterminate"
    : checked
      ? "checked"
      : "unchecked";

  const handleChange = (state: boolean | "indeterminate") => {
    if (state === "indeterminate") {
      return;
    }
    onCheckedChange?.(state);
  };

  return (
    <CheckboxPrimitive.Root
      aria-checked={indeterminate ? "mixed" : checked}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      checked={indeterminate ? "indeterminate" : checked}
      className={cn(
        "peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs outline-none transition-shadow focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-foreground data-[state=indeterminate]:border-foreground data-[state=checked]:bg-foreground data-[state=indeterminate]:bg-foreground data-[state=unchecked]:bg-background data-[state=checked]:text-background data-[state=indeterminate]:text-background dark:data-[state=unchecked]:bg-input/30 dark:aria-invalid:ring-destructive/40",
        className
      )}
      data-slot="checkbox"
      disabled={disabled}
      id={id}
      name={name}
      onCheckedChange={handleChange}
      required={required}
      value={value}
    >
      <CheckboxPrimitive.Indicator
        className="grid place-content-center text-current"
        data-slot="checkbox-indicator"
        forceMount
      >
        <AnimatePresence mode="wait">
          {derivedState === "checked" && (
            <MotionSvg
              animate={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }
              }
              className="size-3.5"
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, scale: 0.8 }
              }
              fill="none"
              initial={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.8 }
              }
              key="check"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={3}
              transition={shouldReduceMotion ? { duration: 0 } : SPRING_DEFAULT}
              viewBox="0 0 24 24"
            >
              <title>Checked</title>
              <CheckmarkPath
                animate={shouldReduceMotion ? {} : { pathLength: 1 }}
                d="M20 6L9 17l-5-5"
                initial={shouldReduceMotion ? {} : { pathLength: 0 }}
                transition={
                  shouldReduceMotion
                    ? { duration: 0 }
                    : { ...SPRING_DEFAULT, delay: 0.05 }
                }
              />
            </MotionSvg>
          )}
          {derivedState === "indeterminate" && (
            <MotionSvg
              animate={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }
              }
              className="size-3.5"
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, scale: 0.8 }
              }
              fill="none"
              initial={
                shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.8 }
              }
              key="indeterminate"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={3}
              transition={shouldReduceMotion ? { duration: 0 } : SPRING_DEFAULT}
              viewBox="0 0 24 24"
            >
              <title>Indeterminate</title>
              <CheckmarkPath
                animate={shouldReduceMotion ? {} : { pathLength: 1 }}
                d="M5 12h14"
                initial={shouldReduceMotion ? {} : { pathLength: 0 }}
                transition={
                  shouldReduceMotion
                    ? { duration: 0 }
                    : { ...SPRING_DEFAULT, delay: 0.05 }
                }
              />
            </MotionSvg>
          )}
        </AnimatePresence>
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

export interface ChromaBlurTransitionProps {
  children: ReactNode;
  className?: string;
  duration?: number;
  onRest?: () => void;
  transitionKey: string | number;
}

const DEFAULT_DURATION_MS = 1040;
const MIDPOINT = 0.5;
const MAX_DPR = 2;
const VERTEX_SHADER =
  "attribute vec2 a; void main(){ gl_Position = vec4(a, 0.0, 1.0); }";
const FRAGMENT_SHADER = `
precision mediump float;
uniform vec2 uRes;
uniform float uTime;
uniform float uProgress;
uniform float uAlpha;
#define PI 3.14159265359

float hash(vec2 p){ return fract(sin(dot(p, vec2(41.0, 289.0))) * 45758.5453); }
float noise(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void main(){
  vec2 uv = gl_FragCoord.xy / uRes;
  float p = smoothstep(0.0, 1.0, uProgress);
  float field = uv.x * 0.62 + uv.y * 0.38;
  float n = noise(uv * 10.0 + vec2(uTime * 0.28, -uTime * 0.18));
  float wave = sin((uv.y + n * 0.12) * 28.0 + uTime * 2.2) * 0.018;
  float front = p * 1.42 - 0.2;
  float d = field + wave - front;

  float curtain = exp(-d * d * 34.0);
  float softGrain = noise(uv * 34.0 + uTime * 0.18) * 0.055;
  float chroma = exp(-(d + 0.045) * (d + 0.045) * 52.0) + exp(-(d - 0.045) * (d - 0.045) * 52.0);
  float exitFade = smoothstep(1.0, 0.74, p);
  float entryFade = smoothstep(0.0, 0.16, p);

  vec3 brandPink = vec3(1.0, 0.32, 0.64);
  vec3 champagne = vec3(1.0, 0.82, 0.56);
  vec3 seafoam = vec3(0.52, 0.90, 0.78);
  vec3 porcelain = vec3(1.0, 0.97, 0.90);
  vec3 color = mix(brandPink, champagne, smoothstep(-0.18, 0.18, sin((uv.y + n) * PI * 2.0)));
  color = mix(color, seafoam, smoothstep(0.2, 1.0, chroma) * 0.34);
  color = mix(color, porcelain, 0.16);

  float alpha = (curtain * 0.72 + chroma * 0.18 + softGrain * curtain) * entryFade * exitFade * uAlpha;
  gl_FragColor = vec4(color * alpha, clamp(alpha, 0.0, 0.86));
}
`;
const STRIP = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

interface Playback {
  cancel: () => void;
}
interface Controller {
  destroy: () => void;
  setAlpha: (alpha: number) => void;
  setProgress: (progress: number) => void;
}

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const easeOutQuart = (value: number) => 1 - (1 - value) ** 4;
const easeInOutCubic = (value: number) =>
  value < 0.5 ? 4 * value ** 3 : 1 - (-2 * value + 2) ** 3 / 2;

const compile = (gl: WebGLRenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

const resize = (canvas: HTMLCanvasElement, gl: WebGLRenderingContext) => {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
  const width = Math.max(1, Math.round(rect.width * dpr));
  const height = Math.max(1, Math.round(rect.height * dpr));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
  gl.viewport(0, 0, width, height);
};

const createController = (canvas: HTMLCanvasElement): Controller | null => {
  const gl = canvas.getContext("webgl", {
    alpha: true,
    antialias: false,
    premultipliedAlpha: true,
  });
  if (!gl) {
    return null;
  }
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  const program = gl.createProgram();
  if (!(vertex && fragment && program)) {
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }

  // biome-ignore lint/correctness/useHookAtTopLevel: WebGLRenderingContext.useProgram is not a React hook.
  gl.useProgram(program);
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, STRIP, gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, "a");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

  const uRes = gl.getUniformLocation(program, "uRes");
  const uTime = gl.getUniformLocation(program, "uTime");
  const uProgress = gl.getUniformLocation(program, "uProgress");
  const uAlpha = gl.getUniformLocation(program, "uAlpha");
  const startedAt = performance.now();
  let progress = 0;
  let alpha = 0;
  let frame = 0;
  let destroyed = false;

  const tick = () => {
    if (destroyed) {
      return;
    }
    resize(canvas, gl);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(uRes, canvas.width, canvas.height);
    gl.uniform1f(uTime, (performance.now() - startedAt) / 1000);
    gl.uniform1f(uProgress, progress);
    gl.uniform1f(uAlpha, alpha);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    frame = requestAnimationFrame(tick);
  };
  frame = requestAnimationFrame(tick);

  return {
    destroy: () => {
      destroyed = true;
      cancelAnimationFrame(frame);
      gl.clear(gl.COLOR_BUFFER_BIT);
      if (buffer) {
        gl.deleteBuffer(buffer);
      }
      gl.deleteProgram(program);
    },
    setAlpha: (nextAlpha: number) => {
      alpha = clamp01(nextAlpha);
    },
    setProgress: (nextProgress: number) => {
      progress = clamp01(nextProgress);
    },
  };
};

const play = (
  controller: Controller,
  duration: number,
  onMidpoint: () => void,
  onComplete: () => void
): Playback => {
  let frame = 0;
  let cancelled = false;
  let didSwap = false;
  const startedAt = performance.now();
  controller.setAlpha(1);

  const advance = () => {
    if (cancelled) {
      return;
    }
    const raw = clamp01((performance.now() - startedAt) / duration);
    const progress = easeOutQuart(raw);
    controller.setProgress(progress);
    if (!(didSwap || progress < MIDPOINT)) {
      didSwap = true;
      onMidpoint();
    }
    if (raw < 1) {
      frame = requestAnimationFrame(advance);
      return;
    }
    if (!didSwap) {
      onMidpoint();
    }
    const fadeStartedAt = performance.now();
    const fade = () => {
      if (cancelled) {
        return;
      }
      const fadeRaw = clamp01((performance.now() - fadeStartedAt) / 90);
      controller.setAlpha(1 - easeInOutCubic(fadeRaw));
      if (fadeRaw < 1) {
        frame = requestAnimationFrame(fade);
        return;
      }
      controller.setAlpha(0);
      controller.setProgress(0);
      onComplete();
    };
    frame = requestAnimationFrame(fade);
  };
  frame = requestAnimationFrame(advance);

  return {
    cancel: () => {
      cancelled = true;
      cancelAnimationFrame(frame);
    },
  };
};

const ChromaBlurTransition = ({
  children,
  className,
  duration = DEFAULT_DURATION_MS,
  onRest,
  transitionKey,
}: ChromaBlurTransitionProps) => {
  const shouldReduceMotion = useReducedMotion();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controllerRef = useRef<Controller | null>(null);
  const playbackRef = useRef<Playback | null>(null);
  const previousKey = useRef(transitionKey);
  const [renderedChildren, setRenderedChildren] = useState(children);
  const [isActive, setIsActive] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const controller = createController(canvas);
    controllerRef.current = controller;
    return () => {
      playbackRef.current?.cancel();
      controller?.destroy();
      controllerRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (previousKey.current === transitionKey) {
      setRenderedChildren(children);
      return;
    }
    previousKey.current = transitionKey;
    playbackRef.current?.cancel();

    if (shouldReduceMotion) {
      setRenderedChildren(children);
      setIsActive(false);
      onRest?.();
      return;
    }

    const controller = controllerRef.current;
    if (!controller) {
      setRenderedChildren(children);
      onRest?.();
      return;
    }
    setIsActive(true);
    playbackRef.current = play(
      controller,
      duration,
      () => setRenderedChildren(children),
      () => {
        setIsActive(false);
        playbackRef.current = null;
        onRest?.();
      }
    );
  }, [children, duration, onRest, shouldReduceMotion, transitionKey]);

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-2xl bg-background text-foreground",
        className
      )}
      data-transitioning={isActive ? "true" : "false"}
    >
      <div className="relative z-0">{renderedChildren}</div>
      <canvas
        className={cn(
          "pointer-events-none absolute inset-0 z-10 h-full w-full transition-opacity duration-75",
          isActive && !shouldReduceMotion ? "opacity-100" : "opacity-0"
        )}
        ref={canvasRef}
      />
    </div>
  );
};

export default ChromaBlurTransition;

"use client";

import SmoothButton from "@/components/smoothui/smooth-button";
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

export interface ClipCornersButtonProps {
  children: React.ReactNode;
  className?: string;
  onClick?: () => void;
}

export function ClipCornersButton({
  children,
  className = "",
  onClick,
}: ClipCornersButtonProps) {
  const [isHovered, setIsHovered] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const [isHoverDevice, setIsHoverDevice] = useState(false);

  // Distance triangles move on hover
  const move = -4;

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mediaQuery.matches);

    const handleChange = (e: MediaQueryListEvent) => {
      setIsHoverDevice(e.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  return (
    <SmoothButton
      className={`relative overflow-hidden rounded-none border-none bg-foreground px-8 py-4 font-mono text-2xl text-background hover:bg-foreground/90 ${className}`}
      onClick={onClick}
      onMouseEnter={() => {
        if (isHoverDevice) {
          setIsHovered(true);
        }
      }}
      onMouseLeave={() => setIsHovered(false)}
      style={{ borderRadius: 8 }}
      type="button"
    >
      {/* Top-left triangle */}
      <motion.div
        animate={
          shouldReduceMotion || !isHoverDevice
            ? {}
            : {
                x: isHovered ? -move : 0,
                y: isHovered ? -move : 0,
              }
        }
        className="absolute top-1.5 left-1.5"
        initial={false}
        style={{ height: 8, width: 8 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                damping: 24,
                duration: 0.2,
                stiffness: 400,
                type: "spring" as const,
              }
        }
      >
        <svg
          aria-label="Top-left triangle"
          className="fill-background"
          height="8"
          width="8"
        >
          <title>Top-left triangle</title>
          <polygon fill="currentColor" points="0,0 8,0 0,8" />
        </svg>
      </motion.div>
      {/* Top-right triangle */}
      <motion.div
        animate={
          shouldReduceMotion || !isHoverDevice
            ? {}
            : {
                x: isHovered ? move : 0,
                y: isHovered ? -move : 0,
              }
        }
        className="absolute top-1.5 right-1.5"
        initial={false}
        style={{ height: 8, width: 8 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                damping: 24,
                duration: 0.2,
                stiffness: 400,
                type: "spring" as const,
              }
        }
      >
        <svg
          aria-label="Top-right triangle"
          className="fill-background"
          height="8"
          width="8"
        >
          <title>Top-right triangle</title>
          <polygon fill="currentColor" points="8,0 8,8 0,0" />
        </svg>
      </motion.div>
      {/* Bottom-left triangle */}
      <motion.div
        animate={
          shouldReduceMotion || !isHoverDevice
            ? {}
            : {
                x: isHovered ? -move : 0,
                y: isHovered ? move : 0,
              }
        }
        className="absolute bottom-1.5 left-1.5"
        initial={false}
        style={{ height: 8, width: 8 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                damping: 24,
                duration: 0.2,
                stiffness: 400,
                type: "spring" as const,
              }
        }
      >
        <svg
          aria-label="Bottom-left triangle"
          className="fill-background"
          height="8"
          width="8"
        >
          <title>Bottom-left triangle</title>
          <polygon fill="currentColor" points="0,8 8,8 0,0" />
        </svg>
      </motion.div>
      {/* Bottom-right triangle */}
      <motion.div
        animate={
          shouldReduceMotion || !isHoverDevice
            ? {}
            : {
                x: isHovered ? move : 0,
                y: isHovered ? move : 0,
              }
        }
        className="absolute right-1.5 bottom-1.5"
        initial={false}
        style={{ height: 8, width: 8 }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                damping: 24,
                duration: 0.2,
                stiffness: 400,
                type: "spring" as const,
              }
        }
      >
        <svg
          aria-label="Bottom-right triangle"
          className="fill-background"
          height="8"
          width="8"
        >
          <title>Bottom-right triangle</title>
          <polygon fill="currentColor" points="8,8 0,8 8,0" />
        </svg>
      </motion.div>
      <span className="relative z-10 flex w-full select-none items-center justify-center">
        {children}
      </span>
    </SmoothButton>
  );
}

