"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { useCallback, useEffect, useMemo, useRef } from "react";

/* -------------------------------------------------------------------------- */
/* Public types                                                               */
/* -------------------------------------------------------------------------- */

export const DITHER_CHART_VARIANTS = [
  "donut",
  "line",
  "bar",
  "stacked",
  "gauge",
  "funnel",
  "heatmap",
  "bubbles",
] as const;

export type DitherChartVariant = (typeof DITHER_CHART_VARIANTS)[number];

/** Bayer matrix order used to quantise every fill into a dot pattern. */
export type DitherChartMatrixOrder = 2 | 4 | 8;

export interface DitherChartPoint {
  /** Optional label, used only by the screen-reader text alternative. */
  label?: string;
  /** Numeric value of the point. */
  value: number;
}

export interface DitherChartSeries {
  /** Overrides the palette colour for this series. */
  color?: string;
  /** Series name, used only by the screen-reader text alternative. */
  name?: string;
  /** Ordered data points of the series. */
  points: DitherChartPoint[];
}

export interface DitherChartProps {
  /** Draw the chart in on mount / when it scrolls into view. */
  animate?: boolean;
  /** Caption rendered under the chart. */
  caption?: string;
  className?: string;
  /**
   * Chart data. Every variant reads the same shape:
   * `donut`, `gauge`, `funnel` use the first series, `heatmap` maps one series
   * per row, the rest render every series.
   */
  data: DitherChartSeries[];
  /** CSS height in pixels. */
  height?: number;
  /** Accessible title rendered above the chart. */
  label?: string;
  /** Bayer matrix order. Larger matrices produce finer gradients. */
  matrix?: DitherChartMatrixOrder;
  /** Colours cycled per series (or per slice for `donut`). */
  palette?: string[];
  /** Size in CSS pixels of one dithered pixel. */
  pixelSize?: number;
  variant?: DitherChartVariant;
  /** CSS width in pixels. */
  width?: number;
}

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const DEFAULT_WIDTH = 320;
const DEFAULT_HEIGHT = 180;
const DEFAULT_PIXEL_SIZE = 3;
const DEFAULT_MATRIX: DitherChartMatrixOrder = 4;
const DEFAULT_VARIANT: DitherChartVariant = "line";

const DRAW_IN_DURATION_MS = 900;
const BEZIER_ITERATIONS = 16;
const EASE_OUT_X1 = 0.23;
const EASE_OUT_Y1 = 1;
const EASE_OUT_X2 = 0.32;
const EASE_OUT_Y2 = 1;

const ALPHA_MAX = 255;
const RGBA_STRIDE = 4;
const ALPHA_OFFSET = 3;
const QUADRANT_OFFSETS = [
  [0, 2],
  [3, 1],
];

/** Alpha ramp that gives each series a distinct dither density. */
const TONE_RAMP = [1, 0.68, 0.46, 0.3, 0.2];
const AREA_TONE_FACTOR = 0.45;
const TRACK_TONE = 0.16;
const HEATMAP_MIN_TONE = 0.08;

const EDGE_INSET = 1;
const LINE_WIDTH = 1;
const BAR_FILL_RATIO = 0.72;
const FUNNEL_ROW_GAP = 1;
const DONUT_INNER_RATIO = 0.55;
const GAUGE_INNER_RATIO = 0.62;
const GAUGE_START_ANGLE = Math.PI * 0.75;
const GAUGE_SWEEP = Math.PI * 1.5;
const GAUGE_MAX_VALUE = 100;
const BUBBLE_MIN_RADIUS = 1;
const BUBBLE_MAX_RATIO = 0.16;
const FULL_TURN = Math.PI * 2;
const QUARTER_TURN = Math.PI / 2;
const HALF = 0.5;
const MIN_DIMENSION = 1;

/* -------------------------------------------------------------------------- */
/* Bayer matrices                                                             */
/* -------------------------------------------------------------------------- */

const buildBayer = (order: number): number[][] => {
  if (order <= 1) {
    return [[0]];
  }
  const half = buildBayer(order / 2);
  const halfSize = half.length;
  const matrix: number[][] = [];
  for (let y = 0; y < order; y++) {
    const row: number[] = [];
    for (let x = 0; x < order; x++) {
      const quadrantY = y < halfSize ? 0 : 1;
      const quadrantX = x < halfSize ? 0 : 1;
      row.push(
        half[y % halfSize][x % halfSize] * QUADRANT_OFFSETS.length ** 2 +
          QUADRANT_OFFSETS[quadrantY][quadrantX]
      );
    }
    matrix.push(row);
  }
  return matrix;
};

const BAYER_MATRICES: Record<DitherChartMatrixOrder, number[][]> = {
  2: buildBayer(2),
  4: buildBayer(4),
  8: buildBayer(8),
};

/* -------------------------------------------------------------------------- */
/* Easing                                                                     */
/* -------------------------------------------------------------------------- */

const bezierAxis = (t: number, a: number, b: number): number => {
  const inverse = 1 - t;
  return 3 * inverse * inverse * t * a + 3 * inverse * t * t * b + t * t * t;
};

/** Solves `cubic-bezier(.23, 1, .32, 1)` for a linear progress value. */
const easeOut = (progress: number): number => {
  let low = 0;
  let high = 1;
  let t = progress;
  for (let i = 0; i < BEZIER_ITERATIONS; i++) {
    if (bezierAxis(t, EASE_OUT_X1, EASE_OUT_X2) < progress) {
      low = t;
    } else {
      high = t;
    }
    t = (low + high) * HALF;
  }
  return bezierAxis(t, EASE_OUT_Y1, EASE_OUT_Y2);
};

/* -------------------------------------------------------------------------- */
/* Drawing helpers                                                            */
/* -------------------------------------------------------------------------- */

interface DrawContext {
  colorAt: (index: number) => string;
  ctx: CanvasRenderingContext2D;
  height: number;
  progress: number;
  series: DitherChartSeries[];
  toneAt: (index: number) => number;
  width: number;
}

const seriesMax = (series: DitherChartSeries[]): number => {
  let max = 0;
  for (const item of series) {
    for (const point of item.points) {
      if (point.value > max) {
        max = point.value;
      }
    }
  }
  return max || 1;
};

const maxPointCount = (series: DitherChartSeries[]): number => {
  let count = 0;
  for (const item of series) {
    if (item.points.length > count) {
      count = item.points.length;
    }
  }
  return count || 1;
};

const sumPoints = (points: DitherChartPoint[]): number => {
  let total = 0;
  for (const point of points) {
    total += point.value;
  }
  return total || 1;
};

const ringSegment = (
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  outer: number,
  inner: number,
  start: number,
  end: number
) => {
  ctx.beginPath();
  ctx.arc(cx, cy, outer, start, end);
  ctx.arc(cx, cy, inner, end, start, true);
  ctx.closePath();
  ctx.fill();
};

const drawLine = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  for (let i = 0; i < series.length; i++) {
    const { points } = series[i];
    if (points.length < 2) {
      continue;
    }
    const step = (width - EDGE_INSET * 2) / (points.length - 1);
    const coords = points.map((point, index) => ({
      x: EDGE_INSET + step * index,
      y: baseline - (point.value / max) * usable * progress,
    }));
    const color = series[i].color ?? colorAt(i);
    const lastX = EDGE_INSET + step * (points.length - 1);

    ctx.fillStyle = color;
    ctx.globalAlpha = toneAt(i) * AREA_TONE_FACTOR;
    ctx.beginPath();
    ctx.moveTo(coords[0].x, baseline);
    for (const coord of coords) {
      ctx.lineTo(coord.x, coord.y);
    }
    ctx.lineTo(lastX, baseline);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = color;
    ctx.globalAlpha = toneAt(i);
    ctx.lineWidth = LINE_WIDTH;
    ctx.beginPath();
    ctx.moveTo(coords[0].x, coords[0].y);
    for (const coord of coords) {
      ctx.lineTo(coord.x, coord.y);
    }
    ctx.stroke();
  }
};

const drawBar = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const groups = maxPointCount(series);
  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  const slot = (width - EDGE_INSET * 2) / groups;
  const barWidth = Math.max(
    MIN_DIMENSION,
    (slot * BAR_FILL_RATIO) / series.length
  );
  const groupWidth = barWidth * series.length;

  for (let group = 0; group < groups; group++) {
    const slotStart = EDGE_INSET + slot * group + (slot - groupWidth) * HALF;
    for (let i = 0; i < series.length; i++) {
      const value = series[i].points[group]?.value ?? 0;
      const barHeight = (value / max) * usable * progress;
      ctx.fillStyle = series[i].color ?? colorAt(i);
      ctx.globalAlpha = toneAt(i);
      ctx.fillRect(
        slotStart + barWidth * i,
        baseline - barHeight,
        barWidth,
        barHeight
      );
    }
  }
};

const drawStacked = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const groups = maxPointCount(series);
  let maxTotal = 1;
  for (let group = 0; group < groups; group++) {
    let total = 0;
    for (const item of series) {
      total += item.points[group]?.value ?? 0;
    }
    if (total > maxTotal) {
      maxTotal = total;
    }
  }

  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  const slot = (width - EDGE_INSET * 2) / groups;
  const barWidth = Math.max(MIN_DIMENSION, slot * BAR_FILL_RATIO);

  for (let group = 0; group < groups; group++) {
    const x = EDGE_INSET + slot * group + (slot - barWidth) * HALF;
    let stacked = 0;
    for (let i = 0; i < series.length; i++) {
      const value = series[i].points[group]?.value ?? 0;
      const segment = (value / maxTotal) * usable * progress;
      ctx.fillStyle = series[i].color ?? colorAt(i);
      ctx.globalAlpha = toneAt(i);
      ctx.fillRect(x, baseline - stacked - segment, barWidth, segment);
      stacked += segment;
    }
  }
};

const drawDonut = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const points = series[0]?.points ?? [];
  if (points.length === 0) {
    return;
  }
  const total = sumPoints(points);
  const cx = width * HALF;
  const cy = height * HALF;
  const outer = Math.min(width, height) * HALF - EDGE_INSET;
  const inner = outer * DONUT_INNER_RATIO;
  let angle = -QUARTER_TURN;

  for (let i = 0; i < points.length; i++) {
    const sweep = (points[i].value / total) * FULL_TURN * progress;
    ctx.fillStyle = colorAt(i);
    ctx.globalAlpha = toneAt(i);
    ringSegment(ctx, cx, cy, outer, inner, angle, angle + sweep);
    angle += sweep;
  }
};

const drawGauge = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const value = series[0]?.points[0]?.value ?? 0;
  const ratio = Math.min(1, Math.max(0, value / GAUGE_MAX_VALUE));
  const cx = width * HALF;
  const cy = height * HALF;
  const outer = Math.min(width, height) * HALF - EDGE_INSET;
  const inner = outer * GAUGE_INNER_RATIO;

  ctx.fillStyle = colorAt(0);
  ctx.globalAlpha = TRACK_TONE;
  ringSegment(
    ctx,
    cx,
    cy,
    outer,
    inner,
    GAUGE_START_ANGLE,
    GAUGE_START_ANGLE + GAUGE_SWEEP
  );

  ctx.globalAlpha = toneAt(0);
  ringSegment(
    ctx,
    cx,
    cy,
    outer,
    inner,
    GAUGE_START_ANGLE,
    GAUGE_START_ANGLE + GAUGE_SWEEP * ratio * progress
  );
};

const drawFunnel = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const points = series[0]?.points ?? [];
  if (points.length === 0) {
    return;
  }
  const max = seriesMax(series);
  const rowHeight = (height - EDGE_INSET * 2) / points.length;
  const usable = width - EDGE_INSET * 2;

  for (let i = 0; i < points.length; i++) {
    const rowWidth = (points[i].value / max) * usable * progress;
    ctx.fillStyle = colorAt(i);
    ctx.globalAlpha = toneAt(i);
    ctx.fillRect(
      (width - rowWidth) * HALF,
      EDGE_INSET + rowHeight * i,
      rowWidth,
      Math.max(MIN_DIMENSION, rowHeight - FUNNEL_ROW_GAP)
    );
  }
};

const drawHeatmap = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const columns = maxPointCount(series);
  const cellWidth = (width - EDGE_INSET * 2) / columns;
  const cellHeight = (height - EDGE_INSET * 2) / series.length;
  ctx.fillStyle = colorAt(0);

  for (let row = 0; row < series.length; row++) {
    for (let column = 0; column < columns; column++) {
      const value = series[row].points[column]?.value ?? 0;
      const intensity =
        HEATMAP_MIN_TONE + (value / max) * (1 - HEATMAP_MIN_TONE);
      ctx.globalAlpha = intensity * progress;
      ctx.fillRect(
        EDGE_INSET + cellWidth * column,
        EDGE_INSET + cellHeight * row,
        cellWidth,
        cellHeight
      );
    }
  }
};

const drawBubbles = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const columns = maxPointCount(series);
  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  const step = (width - EDGE_INSET * 2) / columns;
  const maxRadius = Math.min(width, height) * BUBBLE_MAX_RATIO;

  for (let i = 0; i < series.length; i++) {
    ctx.fillStyle = series[i].color ?? colorAt(i);
    ctx.globalAlpha = toneAt(i);
    const { points } = series[i];
    for (let j = 0; j < points.length; j++) {
      const ratio = points[j].value / max;
      const radius =
        (BUBBLE_MIN_RADIUS + ratio * (maxRadius - BUBBLE_MIN_RADIUS)) *
        progress;
      if (radius <= 0) {
        continue;
      }
      ctx.beginPath();
      ctx.arc(
        EDGE_INSET + step * (j + HALF),
        baseline - ratio * usable,
        radius,
        0,
        FULL_TURN
      );
      ctx.fill();
    }
  }
};

const VARIANT_PAINTERS: Record<
  DitherChartVariant,
  (context: DrawContext) => void
> = {
  bar: drawBar,
  bubbles: drawBubbles,
  donut: drawDonut,
  funnel: drawFunnel,
  gauge: drawGauge,
  heatmap: drawHeatmap,
  line: drawLine,
  stacked: drawStacked,
};

/** Quantises every pixel's alpha through the Bayer matrix. */
const applyDither = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  order: DitherChartMatrixOrder
) => {
  const image = ctx.getImageData(0, 0, width, height);
  const pixels = image.data;
  const matrix = BAYER_MATRICES[order];
  const levels = order * order;

  for (let y = 0; y < height; y++) {
    const row = matrix[y % order];
    for (let x = 0; x < width; x++) {
      const index = (y * width + x) * RGBA_STRIDE + ALPHA_OFFSET;
      const coverage = pixels[index] / ALPHA_MAX;
      const threshold = (row[x % order] + HALF) / levels;
      pixels[index] = coverage > threshold ? ALPHA_MAX : 0;
    }
  }

  ctx.putImageData(image, 0, 0);
};

const resolvePalette = (element: HTMLElement, palette?: string[]): string[] => {
  if (palette && palette.length > 0) {
    return palette;
  }
  const styles = getComputedStyle(element);
  const current = styles.color || "#000000";
  const brand = styles.getPropertyValue("--color-brand").trim();
  return brand ? [brand, current] : [current];
};

/* -------------------------------------------------------------------------- */
/* Component                                                                  */
/* -------------------------------------------------------------------------- */

const DitherChart = ({
  animate = true,
  caption,
  className,
  data,
  height = DEFAULT_HEIGHT,
  label,
  matrix = DEFAULT_MATRIX,
  palette,
  pixelSize = DEFAULT_PIXEL_SIZE,
  variant = DEFAULT_VARIANT,
  width = DEFAULT_WIDTH,
}: DitherChartProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const bufferRef = useRef<HTMLCanvasElement | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const draw = useCallback(
    (progress: number) => {
      const canvas = canvasRef.current;
      if (!canvas || data.length === 0) {
        return;
      }

      const buffer = bufferRef.current ?? document.createElement("canvas");
      bufferRef.current = buffer;

      const lowWidth = Math.max(MIN_DIMENSION, Math.round(width / pixelSize));
      const lowHeight = Math.max(MIN_DIMENSION, Math.round(height / pixelSize));
      buffer.width = lowWidth;
      buffer.height = lowHeight;

      const bufferCtx = buffer.getContext("2d", { willReadFrequently: true });
      if (!bufferCtx) {
        return;
      }
      bufferCtx.clearRect(0, 0, lowWidth, lowHeight);
      bufferCtx.globalAlpha = 1;

      const colors = resolvePalette(canvas, palette);
      const painter = VARIANT_PAINTERS[variant];
      painter({
        colorAt: (index: number) => colors[index % colors.length],
        ctx: bufferCtx,
        height: lowHeight,
        progress,
        series: data,
        toneAt: (index: number) => TONE_RAMP[index % TONE_RAMP.length],
        width: lowWidth,
      });
      bufferCtx.globalAlpha = 1;
      applyDither(bufferCtx, lowWidth, lowHeight, matrix);

      const ratio = window.devicePixelRatio || 1;
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(height * ratio);
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        return;
      }
      ctx.imageSmoothingEnabled = false;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(
        buffer,
        0,
        0,
        lowWidth,
        lowHeight,
        0,
        0,
        canvas.width,
        canvas.height
      );
    },
    [data, height, matrix, palette, pixelSize, variant, width]
  );

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }

    if (!animate || shouldReduceMotion) {
      draw(1);
      return;
    }

    let frame = 0;
    let elapsed = 0;
    let last = 0;
    let running = false;
    draw(0);

    const tick = (time: number) => {
      if (last === 0) {
        last = time;
      }
      elapsed += time - last;
      last = time;
      const progress = Math.min(1, elapsed / DRAW_IN_DURATION_MS);
      draw(easeOut(progress));
      if (progress < 1) {
        frame = requestAnimationFrame(tick);
      } else {
        running = false;
      }
    };

    const start = () => {
      if (running || elapsed >= DRAW_IN_DURATION_MS) {
        return;
      }
      running = true;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    const stop = () => {
      if (!running) {
        return;
      }
      cancelAnimationFrame(frame);
      running = false;
    };

    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          start();
        } else {
          stop();
        }
      }
    });
    observer.observe(canvas);

    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [animate, draw, shouldReduceMotion]);

  const description = useMemo(() => {
    const summaries = data.map((item, index) => {
      const name = item.name ?? `Series ${index + 1}`;
      const values = item.points
        .map(
          (point, pointIndex) =>
            `${point.label ?? `Point ${pointIndex + 1}`}: ${point.value}`
        )
        .join(", ");
      return `${name} — ${values}`;
    });
    return `${label ?? "Dithered chart"}, ${variant} variant. ${summaries.join(". ")}.`;
  }, [data, label, variant]);

  return (
    <figure
      className={cn("inline-flex flex-col gap-2 text-foreground", className)}
    >
      {label ? (
        <span className="font-medium text-foreground text-sm">{label}</span>
      ) : null}
      <canvas
        aria-hidden="true"
        className="block"
        height={height}
        ref={canvasRef}
        style={{ height: `${height}px`, width: `${width}px` }}
        tabIndex={-1}
        width={width}
      />
      <span className="sr-only">{description}</span>
      {caption ? (
        <figcaption className="text-muted-foreground text-xs">
          {caption}
        </figcaption>
      ) : null}
    </figure>
  );
};

export default DitherChart;

"use client";

import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useMemo, useRef, useState } from "react";

export type DitherAlgorithm =
  | "bayer"
  | "atkinson"
  | "floyd-steinberg"
  | "threshold";

export interface DitherImageProps {
  /** Dithering kernel used to quantise the image. */
  algorithm?: DitherAlgorithm;
  /** Alternative text. Always required — it is the accessible name of the result. */
  alt: string;
  /** Extra classes for the wrapper. */
  className?: string;
  /** Rendered height in CSS pixels. */
  height?: number;
  /** Number of tones in the ramp, clamped to `2`–`8`. */
  levels?: number;
  /** Colour ramp, dark to light. Defaults to a monochrome ramp from the theme. */
  palette?: string[];
  /** Size of one dithered block in CSS pixels. */
  pixelSize?: number;
  /** Wipe the dithered pass in when the image scrolls into view. */
  progressive?: boolean;
  /** Image URL. Must allow cross-origin reads to be dithered. */
  src: string;
  /** Rendered width in CSS pixels. */
  width?: number;
}

type Rgb = [number, number, number];
type RenderStatus = "fallback" | "loading" | "ready";

const DEFAULT_WIDTH = 480;
const DEFAULT_HEIGHT = 320;
const DEFAULT_PIXEL_SIZE = 4;
const DEFAULT_LEVELS = 2;
const MIN_LEVELS = 2;
const MAX_LEVELS = 8;
const MIN_PIXEL_SIZE = 1;
const MAX_DPR = 2;
const CHANNELS = 4;
const MAX_CHANNEL = 255;
const BAYER_SIZE = 8;
const BAYER_DIVISOR = BAYER_SIZE * BAYER_SIZE;
const LUMA_R = 0.2126;
const LUMA_G = 0.7152;
const LUMA_B = 0.0722;
const REVEAL_DURATION_S = 0.6;
const REVEAL_EASE: [number, number, number, number] = [0.23, 1, 0.32, 1];
const REVEAL_MARGIN = "0px 0px -10% 0px";
const HIDDEN_CLIP = "inset(0% 0% 100% 0%)";
const VISIBLE_CLIP = "inset(0% 0% 0% 0%)";
const FALLBACK_DARK = "black";
const FALLBACK_LIGHT = "white";

const BAYER_MATRIX = [
  0, 32, 8, 40, 2, 34, 10, 42, 48, 16, 56, 24, 50, 18, 58, 26, 12, 44, 4, 36,
  14, 46, 6, 38, 60, 28, 52, 20, 62, 30, 54, 22, 3, 35, 11, 43, 1, 33, 9, 41,
  51, 19, 59, 27, 49, 17, 57, 25, 15, 47, 7, 39, 13, 45, 5, 37, 63, 31, 55, 23,
  61, 29, 53, 21,
];

const FLOYD_STEINBERG_KERNEL = [
  { dx: 1, dy: 0, weight: 7 / 16 },
  { dx: -1, dy: 1, weight: 3 / 16 },
  { dx: 0, dy: 1, weight: 5 / 16 },
  { dx: 1, dy: 1, weight: 1 / 16 },
];

const ATKINSON_WEIGHT = 1 / 8;
const ATKINSON_KERNEL = [
  { dx: 1, dy: 0, weight: ATKINSON_WEIGHT },
  { dx: 2, dy: 0, weight: ATKINSON_WEIGHT },
  { dx: -1, dy: 1, weight: ATKINSON_WEIGHT },
  { dx: 0, dy: 1, weight: ATKINSON_WEIGHT },
  { dx: 1, dy: 1, weight: ATKINSON_WEIGHT },
  { dx: 0, dy: 2, weight: ATKINSON_WEIGHT },
];

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(max, value));

const luminanceOf = ([r, g, b]: Rgb) =>
  (r * LUMA_R + g * LUMA_G + b * LUMA_B) / MAX_CHANNEL;

const readCssColor = (
  scratch: CanvasRenderingContext2D,
  value: string
): Rgb => {
  scratch.clearRect(0, 0, 1, 1);
  scratch.fillStyle = value;
  scratch.fillRect(0, 0, 1, 1);
  const { data } = scratch.getImageData(0, 0, 1, 1);
  return [data[0], data[1], data[2]];
};

const readThemeStops = (
  scratch: CanvasRenderingContext2D,
  element: HTMLElement
): Rgb[] => {
  const styles = getComputedStyle(element);
  const foreground =
    styles.getPropertyValue("--color-foreground").trim() || FALLBACK_DARK;
  const background =
    styles.getPropertyValue("--color-background").trim() || FALLBACK_LIGHT;
  const first = readCssColor(scratch, foreground);
  const second = readCssColor(scratch, background);
  return luminanceOf(first) <= luminanceOf(second)
    ? [first, second]
    : [second, first];
};

const buildRamp = (stops: Rgb[], levels: number): Rgb[] => {
  if (stops.length === 1) {
    return Array.from({ length: levels }, () => stops[0]);
  }
  const lastStop = stops.length - 1;
  const lastLevel = levels - 1;
  return Array.from({ length: levels }, (_unused, index) => {
    const position = (index / lastLevel) * lastStop;
    const lower = Math.floor(position);
    const upper = Math.min(lastStop, lower + 1);
    const mix = position - lower;
    const from = stops[lower];
    const to = stops[upper];
    return [
      Math.round(from[0] + (to[0] - from[0]) * mix),
      Math.round(from[1] + (to[1] - from[1]) * mix),
      Math.round(from[2] + (to[2] - from[2]) * mix),
    ] as Rgb;
  });
};

const readLuminance = (data: Uint8ClampedArray) => {
  const values = new Float32Array(data.length / CHANNELS);
  for (let index = 0; index < values.length; index++) {
    const offset = index * CHANNELS;
    values[index] =
      (data[offset] * LUMA_R +
        data[offset + 1] * LUMA_G +
        data[offset + 2] * LUMA_B) /
      MAX_CHANNEL;
  }
  return values;
};

const diffuse = (
  values: Float32Array,
  gridWidth: number,
  gridHeight: number,
  levels: number,
  kernel: { dx: number; dy: number; weight: number }[]
) => {
  const steps = levels - 1;
  const quantised = new Uint8Array(values.length);
  for (let y = 0; y < gridHeight; y++) {
    for (let x = 0; x < gridWidth; x++) {
      const index = y * gridWidth + x;
      const original = values[index];
      const level = clamp(Math.round(original * steps), 0, steps);
      quantised[index] = level;
      const error = original - level / steps;
      for (const tap of kernel) {
        const nx = x + tap.dx;
        const ny = y + tap.dy;
        if (nx < 0 || nx >= gridWidth || ny >= gridHeight) {
          continue;
        }
        values[ny * gridWidth + nx] += error * tap.weight;
      }
    }
  }
  return quantised;
};

const quantiseOrdered = (
  values: Float32Array,
  gridWidth: number,
  levels: number,
  ordered: boolean
) => {
  const steps = levels - 1;
  const quantised = new Uint8Array(values.length);
  for (let index = 0; index < values.length; index++) {
    let value = values[index];
    if (ordered) {
      const x = index % gridWidth;
      const y = Math.floor(index / gridWidth);
      const cell =
        BAYER_MATRIX[(y % BAYER_SIZE) * BAYER_SIZE + (x % BAYER_SIZE)];
      value += ((cell + 0.5) / BAYER_DIVISOR - 0.5) / steps;
    }
    quantised[index] = clamp(Math.round(value * steps), 0, steps);
  }
  return quantised;
};

const applyRamp = (
  data: Uint8ClampedArray,
  quantised: Uint8Array,
  ramp: Rgb[]
) => {
  for (let index = 0; index < quantised.length; index++) {
    const offset = index * CHANNELS;
    const tone = ramp[quantised[index]];
    data[offset] = tone[0];
    data[offset + 1] = tone[1];
    data[offset + 2] = tone[2];
  }
};

const DitherImage = ({
  algorithm = "bayer",
  alt,
  className,
  height = DEFAULT_HEIGHT,
  levels = DEFAULT_LEVELS,
  palette,
  pixelSize = DEFAULT_PIXEL_SIZE,
  progressive = false,
  src,
  width = DEFAULT_WIDTH,
}: DitherImageProps) => {
  const shouldReduceMotion = useReducedMotion();
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [status, setStatus] = useState<RenderStatus>("loading");
  const [isRevealed, setIsRevealed] = useState(false);

  const paletteKey = palette?.join("|") ?? "";
  const resolvedPalette = useMemo(
    () => (paletteKey ? paletteKey.split("|") : undefined),
    [paletteKey]
  );

  const safeLevels = clamp(Math.round(levels), MIN_LEVELS, MAX_LEVELS);
  const safePixelSize = Math.max(MIN_PIXEL_SIZE, Math.round(pixelSize));

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!(canvas && container)) {
      return;
    }

    const context = canvas.getContext("2d", { willReadFrequently: true });
    const scratchCanvas = document.createElement("canvas");
    scratchCanvas.width = 1;
    scratchCanvas.height = 1;
    const scratch = scratchCanvas.getContext("2d", {
      willReadFrequently: true,
    });
    const grid = document.createElement("canvas");
    const gridContext = grid.getContext("2d", { willReadFrequently: true });

    if (!(context && scratch && gridContext)) {
      setStatus("fallback");
      return;
    }

    let isCancelled = false;
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.decoding = "async";

    const render = () => {
      const gridWidth = Math.max(1, Math.round(width / safePixelSize));
      const gridHeight = Math.max(1, Math.round(height / safePixelSize));
      grid.width = gridWidth;
      grid.height = gridHeight;
      gridContext.clearRect(0, 0, gridWidth, gridHeight);
      gridContext.drawImage(image, 0, 0, gridWidth, gridHeight);

      const frame = gridContext.getImageData(0, 0, gridWidth, gridHeight);
      const values = readLuminance(frame.data);
      let quantised: Uint8Array;
      if (algorithm === "floyd-steinberg") {
        quantised = diffuse(
          values,
          gridWidth,
          gridHeight,
          safeLevels,
          FLOYD_STEINBERG_KERNEL
        );
      } else if (algorithm === "atkinson") {
        quantised = diffuse(
          values,
          gridWidth,
          gridHeight,
          safeLevels,
          ATKINSON_KERNEL
        );
      } else {
        quantised = quantiseOrdered(
          values,
          gridWidth,
          safeLevels,
          algorithm === "bayer"
        );
      }

      const stops = resolvedPalette
        ? resolvedPalette.map((entry) => readCssColor(scratch, entry))
        : readThemeStops(scratch, container);
      applyRamp(frame.data, quantised, buildRamp(stops, safeLevels));
      gridContext.putImageData(frame, 0, 0);

      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      context.imageSmoothingEnabled = false;
      context.clearRect(0, 0, canvas.width, canvas.height);
      context.drawImage(grid, 0, 0, canvas.width, canvas.height);
      setStatus("ready");
    };

    image.onload = () => {
      if (isCancelled) {
        return;
      }
      try {
        render();
      } catch {
        setStatus("fallback");
      }
    };
    image.onerror = () => {
      if (!isCancelled) {
        setStatus("fallback");
      }
    };
    image.src = src;

    return () => {
      isCancelled = true;
      image.onload = null;
      image.onerror = null;
      image.src = "";
      context.clearRect(0, 0, canvas.width, canvas.height);
      canvas.width = 0;
      canvas.height = 0;
      grid.width = 0;
      grid.height = 0;
      scratchCanvas.width = 0;
      scratchCanvas.height = 0;
    };
  }, [
    algorithm,
    height,
    resolvedPalette,
    safeLevels,
    safePixelSize,
    src,
    width,
  ]);

  useEffect(() => {
    const container = containerRef.current;
    if (!progressive || shouldReduceMotion) {
      setIsRevealed(true);
      return;
    }
    if (!(container && typeof IntersectionObserver !== "undefined")) {
      setIsRevealed(true);
      return;
    }
    setIsRevealed(false);
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setIsRevealed(true);
            observer.disconnect();
          }
        }
      },
      { rootMargin: REVEAL_MARGIN }
    );
    observer.observe(container);
    return () => {
      observer.disconnect();
    };
  }, [progressive, shouldReduceMotion]);

  const isDithered = status === "ready";
  const animatesReveal = progressive && !shouldReduceMotion;

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-xl bg-background",
        className
      )}
      ref={containerRef}
      style={{ height, width }}
    >
      <img
        alt={alt}
        className="absolute inset-0 h-full w-full object-cover"
        height={height}
        src={src}
        width={width}
      />
      <motion.canvas
        animate={{
          clipPath: animatesReveal && !isRevealed ? HIDDEN_CLIP : VISIBLE_CLIP,
          opacity: isDithered ? 1 : 0,
        }}
        aria-hidden="true"
        className="absolute inset-0 h-full w-full"
        initial={false}
        ref={canvasRef}
        style={{ imageRendering: "pixelated" }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : { duration: REVEAL_DURATION_S, ease: REVEAL_EASE }
        }
      />
    </div>
  );
};

export default DitherImage;

"use client";

import { cn } from "@/lib/utils";
import {
  AnimatePresence,
  animate,
  type MotionValue,
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import {
  type FocusEvent as ReactFocusEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  type PointerEvent as ReactPointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";

const DEFAULT_BASE_SIZE = 48;
const DEFAULT_GAP = 10;
const DEFAULT_MAGNIFICATION = 1.55;
/** ~3x the item pitch, so growth tapers off across 2-3 neighbours. */
const DEFAULT_DISTANCE = 174;
const CHROME_PADDING = 8;
const HALF = 0.5;
const QUARTER = 0.25;
const POINTER_SOLVE_STEPS = 3;
const TRACK_SPRING = { bounce: 0, duration: 0.18 };
const INFLUENCE_SPRING = { bounce: 0, duration: 0.28 };
const TOOLTIP_DURATION = 0.14;
const TOOLTIP_HIDDEN_SCALE = 0.94;
const BOUNCE_DURATION = 0.6;
const BOUNCE_PEAK = -0.4;
const BOUNCE_ECHO = -0.13;
const BOUNCE_TIMES = [0, 0.3, 0.58, 0.8, 1];
const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];
const EASE_IN: [number, number, number, number] = [0.55, 0, 1, 0.45];

export type DockOrientation = "horizontal" | "vertical";

export interface DockItem {
  /** Draws the macOS "app is running" dot beside the tile. */
  active?: boolean;
  href?: string;
  icon: ReactNode;
  id: string;
  label: string;
  onSelect?: () => void;
}

export interface DockProps {
  /** Resting edge length of every tile, in px. */
  baseSize?: number;
  className?: string;
  /** Radius of cursor influence in px. Around 3x the item pitch reads best. */
  distance?: number;
  /** Resting space between tiles, in px. */
  gap?: number;
  items: DockItem[];
  /** Scale of the tile directly under the cursor. */
  magnification?: number;
  orientation?: DockOrientation;
  /** Keep every label visible instead of only on hover/focus. */
  showLabels?: boolean;
}

type DockField = {
  baseSize: number;
  count: number;
  distance: number;
  gap: number;
  influence: number;
  magnification: number;
  pointer: number;
};

/**
 * Raised-cosine falloff: flat near the cursor, flat at the edge of the
 * influence radius. A linear ramp is what makes a dock look like only the
 * hovered icon reacts — this curve gives the neighbours real growth and lets
 * the wave die out smoothly.
 */
const falloffAt = (delta: number, distance: number) => {
  const spread = Math.abs(delta);
  if (spread >= distance) {
    return 0;
  }
  return (Math.cos((Math.PI * spread) / distance) + 1) * HALF;
};

/**
 * Signed integral of `falloffAt` from 0 to `delta`. Laying the row out by
 * integrating the local stretch is what makes every tile push its neighbours
 * by exactly the space its own growth needs — no overlap, no guesswork.
 */
const falloffIntegral = (delta: number, distance: number) => {
  const sign = delta < 0 ? -1 : 1;
  const spread = Math.min(Math.abs(delta), distance);
  return (
    sign *
    ((distance / (2 * Math.PI)) * Math.sin((Math.PI * spread) / distance) +
      spread * HALF)
  );
};

const restingCenter = (index: number, field: DockField) =>
  index * (field.baseSize + field.gap) + field.baseSize * HALF;

const gainOf = (field: DockField) =>
  field.influence * (field.magnification - 1);

const scaleAt = (index: number, field: DockField) =>
  1 +
  gainOf(field) *
    falloffAt(restingCenter(index, field) - field.pointer, field.distance);

/** Shift that keeps the magnified row centred on its resting centre. */
const centreShift = (field: DockField) => {
  const first = restingCenter(0, field) - field.pointer;
  const last = restingCenter(field.count - 1, field) - field.pointer;
  return (
    (falloffIntegral(first, field.distance) +
      falloffIntegral(last, field.distance)) *
      HALF +
    field.baseSize *
      (falloffAt(last, field.distance) - falloffAt(first, field.distance)) *
      QUARTER
  );
};

const centreAt = (index: number, field: DockField) => {
  const resting = restingCenter(index, field);
  return (
    resting +
    gainOf(field) *
      (falloffIntegral(resting - field.pointer, field.distance) -
        centreShift(field))
  );
};

const rowLength = (field: DockField) => {
  const last = Math.max(0, field.count - 1);
  const start = centreAt(0, field) - field.baseSize * scaleAt(0, field) * HALF;
  const end =
    centreAt(last, field) + field.baseSize * scaleAt(last, field) * HALF;
  return end - start;
};

/**
 * The cursor arrives in rendered pixels, but the layout is defined in resting
 * coordinates. `rendered = pointer - gain * centreShift(pointer)` is smooth and
 * near-identity, so a few fixed-point steps invert it well enough — and that
 * keeps the magnified peak glued to the cursor, instead of drifting the way a
 * live `getBoundingClientRect` feedback loop does.
 */
const solvePointer = (rendered: number, field: DockField) => {
  const gain = gainOf(field);
  const probe: DockField = { ...field, pointer: rendered };
  for (let step = 0; step < POINTER_SOLVE_STEPS; step += 1) {
    probe.pointer = rendered + gain * centreShift(probe);
  }
  return probe.pointer;
};

const useHoverCapable = () => {
  const [isHoverCapable, setIsHoverCapable] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverCapable(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverCapable(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  return isHoverCapable;
};

type DockIconElement = HTMLAnchorElement | HTMLButtonElement;

type DockIconProps = {
  baseSize: number;
  fieldRef: { current: DockField };
  index: number;
  influence: MotionValue<number>;
  isTooltipInstant: boolean;
  item: DockItem;
  onFocusItem: () => void;
  onKeyDown: (event: ReactKeyboardEvent<DockIconElement>) => void;
  onPointerEnter: () => void;
  orientation: DockOrientation;
  pointer: MotionValue<number>;
  registerRef: (element: DockIconElement | null) => void;
  shouldReduceMotion: boolean;
  showTooltip: boolean;
  tabIndex: number;
};

const DockIcon = ({
  baseSize,
  fieldRef,
  index,
  influence,
  isTooltipInstant,
  item,
  onFocusItem,
  onKeyDown,
  onPointerEnter,
  orientation,
  pointer,
  registerRef,
  shouldReduceMotion,
  showTooltip,
  tabIndex,
}: DockIconProps) => {
  const isHorizontal = orientation === "horizontal";
  const bounce = useMotionValue(0);

  const offset = useTransform([pointer, influence], (latest: number[]) => {
    const field: DockField = {
      ...fieldRef.current,
      influence: latest[1],
      pointer: latest[0],
    };
    return centreAt(index, field) - field.baseSize * HALF;
  });

  const scale = useTransform([pointer, influence], (latest: number[]) => {
    const field: DockField = {
      ...fieldRef.current,
      influence: latest[1],
      pointer: latest[0],
    };
    return scaleAt(index, field);
  });

  /** Ride above the magnified tile instead of overlapping it. */
  const tooltipShift = useTransform(scale, (value) => -(value - 1) * baseSize);

  const handleSelect = () => {
    if (!shouldReduceMotion) {
      bounce.jump(0);
      animate(
        bounce,
        [0, BOUNCE_PEAK * baseSize, 0, BOUNCE_ECHO * baseSize, 0],
        {
          duration: BOUNCE_DURATION,
          ease: [EASE_OUT, EASE_IN, EASE_OUT, EASE_IN],
          times: BOUNCE_TIMES,
        }
      );
    }
    item.onSelect?.();
  };

  const sharedProps = {
    "aria-label": item.active ? `${item.label} (running)` : item.label,
    className:
      "flex size-full items-center justify-center rounded-[26%] bg-foreground/[0.07] text-foreground outline-none ring-1 ring-foreground/10 ring-inset transition-transform duration-150 ease-out focus-visible:ring-2 focus-visible:ring-brand active:scale-[0.94] motion-reduce:transition-none motion-reduce:active:scale-100",
    onClick: handleSelect,
    onFocus: onFocusItem,
    onKeyDown,
    tabIndex,
  };

  return (
    <motion.div
      className={cn(
        "absolute",
        isHorizontal ? "bottom-0 left-0" : "top-0 right-0"
      )}
      onPointerEnter={onPointerEnter}
      style={{
        height: baseSize,
        width: baseSize,
        ...(isHorizontal ? { x: offset } : { y: offset }),
      }}
    >
      <AnimatePresence>
        {showTooltip ? (
          <motion.span
            animate={{ opacity: 1, scale: 1 }}
            className={cn(
              "pointer-events-none absolute z-20 whitespace-nowrap rounded-md bg-foreground px-2 py-1 font-medium text-[11px] text-background shadow-sm",
              isHorizontal
                ? "bottom-full left-1/2 mb-2.5"
                : "top-1/2 right-full mr-2.5"
            )}
            exit={{ opacity: 0, scale: TOOLTIP_HIDDEN_SCALE }}
            initial={{ opacity: 0, scale: TOOLTIP_HIDDEN_SCALE }}
            key="tooltip"
            style={
              isHorizontal
                ? { originY: 1, x: "-50%", y: tooltipShift }
                : { originX: 1, x: tooltipShift, y: "-50%" }
            }
            transition={{
              duration:
                shouldReduceMotion || isTooltipInstant ? 0 : TOOLTIP_DURATION,
              ease: EASE_OUT,
            }}
          >
            {item.label}
          </motion.span>
        ) : null}
      </AnimatePresence>

      <motion.div
        className="size-full"
        style={{
          scale,
          transformOrigin: isHorizontal ? "bottom center" : "right center",
          ...(isHorizontal ? { y: bounce } : { x: bounce }),
        }}
      >
        {item.href ? (
          <a href={item.href} ref={registerRef} {...sharedProps}>
            {item.icon}
          </a>
        ) : (
          <button ref={registerRef} type="button" {...sharedProps}>
            {item.icon}
          </button>
        )}
      </motion.div>

      {item.active ? (
        <span
          aria-hidden="true"
          className={cn(
            "absolute size-[3px] rounded-full bg-foreground/45",
            isHorizontal
              ? "-bottom-1.5 left-1/2 -translate-x-1/2"
              : "top-1/2 -right-1.5 -translate-y-1/2"
          )}
        />
      ) : null}
    </motion.div>
  );
};

export default function Dock({
  baseSize = DEFAULT_BASE_SIZE,
  className,
  distance = DEFAULT_DISTANCE,
  gap = DEFAULT_GAP,
  items,
  magnification = DEFAULT_MAGNIFICATION,
  orientation = "horizontal",
  showLabels = false,
}: DockProps) {
  const shouldReduceMotion = Boolean(useReducedMotion());
  const isHoverCapable = useHoverCapable();
  const isHorizontal = orientation === "horizontal";
  const isMagnetic = isHoverCapable && !shouldReduceMotion;

  const count = items.length;
  const restingLength = Math.max(baseSize, count * (baseSize + gap) - gap);

  const fieldRef = useRef<DockField>({
    baseSize,
    count,
    distance,
    gap,
    influence: 0,
    magnification,
    pointer: 0,
  });
  fieldRef.current = {
    baseSize,
    count,
    distance,
    gap,
    influence: 0,
    magnification: isMagnetic ? magnification : 1,
    pointer: 0,
  };

  const frameRef = useRef<HTMLDivElement | null>(null);
  const itemRefs = useRef<(DockIconElement | null)[]>([]);
  const isTrackingRef = useRef(false);
  const hasOpenTooltipRef = useRef(false);

  const rawPointer = useMotionValue(0);
  const rawInfluence = useMotionValue(0);
  const smoothPointer = useSpring(rawPointer, TRACK_SPRING);
  const influence = useSpring(rawInfluence, INFLUENCE_SPRING);

  const fieldPointer = useTransform(
    [smoothPointer, influence],
    (latest: number[]) =>
      solvePointer(latest[0], { ...fieldRef.current, influence: latest[1] })
  );

  /** The bar hugs the magnified row, so it widens with it and never jumps. */
  const barLength = useTransform(
    [fieldPointer, influence],
    (latest: number[]) =>
      rowLength({
        ...fieldRef.current,
        influence: latest[1],
        pointer: latest[0],
      }) +
      CHROME_PADDING * 2
  );

  const [focusedIndex, setFocusedIndex] = useState(0);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [isTooltipInstant, setIsTooltipInstant] = useState(false);

  const releasePointer = () => {
    isTrackingRef.current = false;
    rawInfluence.set(0);
  };

  const handlePointerMove = (event: ReactPointerEvent<HTMLElement>) => {
    const frame = frameRef.current;
    if (!(isMagnetic && frame)) {
      return;
    }
    const rect = frame.getBoundingClientRect();
    const value = isHorizontal
      ? event.clientX - rect.left
      : event.clientY - rect.top;

    if (!isTrackingRef.current) {
      rawPointer.jump(value);
      smoothPointer.jump(value);
      isTrackingRef.current = true;
    }
    rawPointer.set(value);
    rawInfluence.set(1);
  };

  const handlePointerLeave = () => {
    releasePointer();
    setHoveredId(null);
    setIsTooltipInstant(false);
    hasOpenTooltipRef.current = false;
  };

  const handleItemPointerEnter = (id: string) => {
    if (!isHoverCapable) {
      return;
    }
    setIsTooltipInstant(hasOpenTooltipRef.current);
    hasOpenTooltipRef.current = true;
    setHoveredId(id);
  };

  const focusItem = (index: number) => {
    if (count === 0) {
      return;
    }
    const nextIndex = (index + count) % count;
    setFocusedIndex(nextIndex);
    itemRefs.current[nextIndex]?.focus();
  };

  const handleKeyDown = (event: ReactKeyboardEvent<DockIconElement>) => {
    const forwardKey = isHorizontal ? "ArrowRight" : "ArrowDown";
    const backwardKey = isHorizontal ? "ArrowLeft" : "ArrowUp";

    if (event.key === forwardKey) {
      event.preventDefault();
      focusItem(focusedIndex + 1);
    } else if (event.key === backwardKey) {
      event.preventDefault();
      focusItem(focusedIndex - 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      focusItem(0);
    } else if (event.key === "End") {
      event.preventDefault();
      focusItem(count - 1);
    }
  };

  const handleFocusItem = (index: number, id: string) => {
    setFocusedIndex(index);
    setHoveredId(id);
    if (shouldReduceMotion) {
      return;
    }
    const target = restingCenter(index, fieldRef.current);
    rawPointer.jump(target);
    smoothPointer.jump(target);
    isTrackingRef.current = true;
    rawInfluence.set(1);
  };

  const handleBlur = (event: ReactFocusEvent<HTMLElement>) => {
    if (event.currentTarget.contains(event.relatedTarget)) {
      return;
    }
    setHoveredId(null);
    releasePointer();
  };

  const axisReserve = CHROME_PADDING + (magnification - 1) * distance * HALF;
  const crossReserve = CHROME_PADDING + baseSize * (magnification - 1);

  return (
    <nav
      aria-label="Application dock"
      className={cn("relative inline-flex", className)}
      onBlur={handleBlur}
      onPointerLeave={handlePointerLeave}
      onPointerMove={handlePointerMove}
      style={
        isHorizontal
          ? {
              paddingBottom: CHROME_PADDING,
              paddingLeft: axisReserve,
              paddingRight: axisReserve,
              paddingTop: crossReserve,
            }
          : {
              paddingBottom: axisReserve,
              paddingLeft: crossReserve,
              paddingRight: CHROME_PADDING,
              paddingTop: axisReserve,
            }
      }
    >
      {/* Fixed resting-size frame — the stable coordinate space the cursor is
          measured against, so no layout in here can ever jump. */}
      <div
        className="relative"
        ref={frameRef}
        style={
          isHorizontal
            ? { height: baseSize, width: restingLength }
            : { height: restingLength, width: baseSize }
        }
      >
        <motion.div
          aria-hidden="true"
          className="pointer-events-none absolute top-1/2 left-1/2 rounded-[18px] border border-foreground/10 border-t-foreground/20 bg-background/65 shadow-black/10 shadow-lg backdrop-blur-xl"
          style={
            isHorizontal
              ? {
                  height: baseSize + CHROME_PADDING * 2,
                  width: barLength,
                  x: "-50%",
                  y: "-50%",
                }
              : {
                  height: barLength,
                  width: baseSize + CHROME_PADDING * 2,
                  x: "-50%",
                  y: "-50%",
                }
          }
        />

        <div
          aria-orientation={orientation}
          className="absolute inset-0"
          role="toolbar"
        >
          {items.map((item, index) => (
            <DockIcon
              baseSize={baseSize}
              fieldRef={fieldRef}
              index={index}
              influence={influence}
              isTooltipInstant={isTooltipInstant}
              item={item}
              key={item.id}
              onFocusItem={() => handleFocusItem(index, item.id)}
              onKeyDown={handleKeyDown}
              onPointerEnter={() => handleItemPointerEnter(item.id)}
              orientation={orientation}
              pointer={fieldPointer}
              registerRef={(element) => {
                itemRefs.current[index] = element;
              }}
              shouldReduceMotion={shouldReduceMotion}
              showTooltip={showLabels || hoveredId === item.id}
              tabIndex={index === focusedIndex ? 0 : -1}
            />
          ))}
        </div>
      </div>
    </nav>
  );
}

"use client";

import SmoothButton from "@/components/smoothui/smooth-button";
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

export interface DotMorphButtonProps {
  className?: string;
  label: string;
  onClick?: () => void;
}

export function DotMorphButton({
  label,
  className = "",
  onClick,
}: DotMorphButtonProps) {
  const [isHovered, setIsHovered] = useState(false);
  const shouldReduceMotion = useReducedMotion();
  const [isHoverDevice, setIsHoverDevice] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mediaQuery.matches);

    const handleChange = (e: MediaQueryListEvent) => {
      setIsHoverDevice(e.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  return (
    <SmoothButton
      className={`flex items-center gap-3 rounded-full border bg-background ${className}`}
      onClick={onClick}
      onMouseEnter={() => {
        if (isHoverDevice) {
          setIsHovered(true);
        }
      }}
      onMouseLeave={() => setIsHovered(false)}
      type="button"
    >
      <motion.span
        animate={
          shouldReduceMotion || !isHoverDevice || !isHovered
            ? {
                borderRadius: 999,
                height: 16,
                width: 16,
              }
            : {
                borderRadius: 999,
                height: 28,
                width: 12,
              }
        }
        className="flex items-center justify-center"
        initial={false}
        style={{
          background: "var(--color-brand)",
          display: "inline-block",
        }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                damping: 22,
                duration: 0.25,
                stiffness: 600,
                type: "spring" as const,
              }
        }
      />
      <span className="select-none font-medium text-2xl text-foreground">
        {label}
      </span>
    </SmoothButton>
  );
}

export default DotMorphButton;

"use client";

import {
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  Drawer as DrawerPrimitive,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

/* ------------------------------------------------------------------ */
/*  Animation constants                                                */
/* ------------------------------------------------------------------ */

const BACKDROP_DURATION = 0.2;
const STAGGER_BASE_DELAY = 0.12;
const STAGGER_CHILD_DELAY = 0.05;

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type DrawerSide = "top" | "right" | "bottom" | "left";

export interface DrawerProps {
  /** Drawer content */
  children?: React.ReactNode;
  /** Additional CSS class names */
  className?: string;
  /** Description displayed below the title */
  description?: string;
  /** Footer content */
  footer?: React.ReactNode;
  /** Callback when the open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Whether the drawer is open */
  open?: boolean;
  /** The side from which the drawer opens */
  side?: DrawerSide;
  /** Title displayed in the drawer header */
  title?: string;
  /** Trigger element that opens the drawer */
  trigger?: React.ReactNode;
}

/* ------------------------------------------------------------------ */
/*  Stagger child — animates content items in sequence after open      */
/* ------------------------------------------------------------------ */

const StaggerChild = ({
  children,
  index,
  shouldReduceMotion,
}: {
  children: React.ReactNode;
  index: number;
  shouldReduceMotion: boolean | null;
}) => (
  <motion.div
    animate={
      shouldReduceMotion
        ? { opacity: 1 }
        : { opacity: 1, transform: "translateY(0px)" }
    }
    exit={
      shouldReduceMotion
        ? { opacity: 0, transition: { duration: 0 } }
        : { opacity: 0, transition: { duration: 0.1 } }
    }
    initial={
      shouldReduceMotion
        ? { opacity: 1 }
        : { opacity: 0, transform: "translateY(6px)" }
    }
    transition={
      shouldReduceMotion
        ? { duration: 0 }
        : {
            bounce: 0,
            delay: STAGGER_BASE_DELAY + index * STAGGER_CHILD_DELAY,
            duration: 0.25,
            type: "spring" as const,
          }
    }
  >
    {children}
  </motion.div>
);

/* ------------------------------------------------------------------ */
/*  Animated handle bar with glow pulse                                */
/* ------------------------------------------------------------------ */

const AnimatedHandle = ({
  shouldReduceMotion,
}: {
  shouldReduceMotion: boolean | null;
}) => (
  <motion.div
    animate={
      shouldReduceMotion
        ? {}
        : {
            opacity: [0.5, 1, 0.5],
          }
    }
    className="mx-auto mt-4 h-2 w-[100px] shrink-0 rounded-full bg-muted"
    transition={
      shouldReduceMotion
        ? { duration: 0 }
        : {
            duration: 2,
            ease: [0.645, 0.045, 0.355, 1],
            repeat: Number.POSITIVE_INFINITY,
          }
    }
  />
);

/* ------------------------------------------------------------------ */
/*  Drawer                                                             */
/* ------------------------------------------------------------------ */

export default function Drawer({
  open,
  onOpenChange,
  side = "bottom",
  title,
  description,
  className,
  children,
  trigger,
  footer,
}: DrawerProps) {
  const shouldReduceMotion = useReducedMotion();
  const [isAnimatingOut, setIsAnimatingOut] = useState(false);
  const prevOpenRef = useRef(false);

  useEffect(() => {
    // When going from open -> closed, we need animation-out time
    if (prevOpenRef.current && !open) {
      setIsAnimatingOut(true);
    }
    prevOpenRef.current = !!open;
  }, [open]);

  const handleExitComplete = useCallback(() => {
    setIsAnimatingOut(false);
  }, []);

  // Keep vaul's drawer open during exit animation so the portal stays mounted
  const vaulOpen = open || isAnimatingOut;

  return (
    <DrawerPrimitive
      direction={side}
      onOpenChange={(next) => {
        if (!next && isAnimatingOut) {
          return; // Ignore vaul's close during our exit animation
        }
        onOpenChange?.(next);
      }}
      open={vaulOpen}
    >
      {trigger ? <DrawerTrigger asChild>{trigger}</DrawerTrigger> : null}

      {/*
        We render DrawerContent so vaul's drag gestures still work, but we
        layer motion.div overlays on top for the visual polish (backdrop blur,
        spring slide-in, content stagger, handle pulse).
      */}
      <DrawerContent
        className={cn(
          // Hide vaul's default CSS transition — we animate with motion
          "!transition-none !duration-0",
          // Hide the default handle for bottom drawers — we render our own animated one
          side === "bottom" &&
            "[&>[class*='h-2'][class*='rounded-full']]:hidden",
          className
        )}
      >
        {/* Animated handle for bottom drawers */}
        {side === "bottom" && (
          <AnimatedHandle shouldReduceMotion={shouldReduceMotion} />
        )}

        <AnimatePresence onExitComplete={handleExitComplete}>
          {open ? (
            <motion.div
              animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1 }}
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { opacity: 0, transition: { duration: 0.15 } }
              }
              initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }}
              transition={{
                duration: shouldReduceMotion ? 0 : BACKDROP_DURATION,
              }}
            >
              {/* Staggered header */}
              {title || description ? (
                <StaggerChild index={0} shouldReduceMotion={shouldReduceMotion}>
                  <DrawerHeader>
                    {title ? <DrawerTitle>{title}</DrawerTitle> : null}
                    {description ? (
                      <DrawerDescription>{description}</DrawerDescription>
                    ) : null}
                  </DrawerHeader>
                </StaggerChild>
              ) : null}

              {/* Staggered body */}
              {children ? (
                <StaggerChild
                  index={title || description ? 1 : 0}
                  shouldReduceMotion={shouldReduceMotion}
                >
                  <div className="px-4">{children}</div>
                </StaggerChild>
              ) : null}

              {/* Staggered footer */}
              {footer ? (
                <StaggerChild
                  index={(title || description ? 1 : 0) + (children ? 1 : 0)}
                  shouldReduceMotion={shouldReduceMotion}
                >
                  <DrawerFooter>{footer}</DrawerFooter>
                </StaggerChild>
              ) : null}
            </motion.div>
          ) : null}
        </AnimatePresence>
      </DrawerContent>
    </DrawerPrimitive>
  );
}

/* ------------------------------------------------------------------ */
/*  Re-exports                                                         */
/* ------------------------------------------------------------------ */

export {
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
};

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import type { ReactNode, Ref } from "react";
import { useEffect, useImperativeHandle, useRef, useState } from "react";

export type DrawingCursorHandle = {
  clear: () => void;
  toDataURL: (type?: string, quality?: number) => string;
};

export type DrawingCursorProps = {
  blend?: GlobalCompositeOperation;
  children?: ReactNode;
  className?: string;
  clearOnLeave?: boolean;
  color?: string;
  decay?: number;
  lineWidth?: number;
  paused?: boolean;
  ref?: Ref<DrawingCursorHandle>;
  smoothing?: number;
  taper?: boolean;
};

type StrokePoint = { time: number; width: number; x: number; y: number };
type Stroke = { points: StrokePoint[] };

const DEFAULT_COLOR = "var(--color-brand, #6366f1)";
const DEFAULT_LINE_WIDTH = 3;
const DEFAULT_DECAY = 800;
const DEFAULT_SMOOTHING = 0.5;
const MAX_DEVICE_PIXEL_RATIO = 2;
const STROKE_BREAK_MS = 120;
const MIN_WIDTH_FACTOR = 0.35;
const SPEED_TO_WIDTH_SCALE = 0.12;
const MAX_POINTS_PER_STROKE = 600;
const MAX_STROKES = 40;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const getPointerCoordinates = (
  event: PointerEvent,
  rect: DOMRect
): { x: number; y: number }[] => {
  const coalesced =
    typeof event.getCoalescedEvents === "function"
      ? event.getCoalescedEvents()
      : null;
  const events = coalesced && coalesced.length > 0 ? coalesced : [event];
  return events.map((coalescedEvent) => ({
    x: coalescedEvent.clientX - rect.left,
    y: coalescedEvent.clientY - rect.top,
  }));
};

const DrawingCursor = ({
  blend = "source-over",
  children,
  className,
  clearOnLeave = true,
  color = DEFAULT_COLOR,
  decay = DEFAULT_DECAY,
  lineWidth = DEFAULT_LINE_WIDTH,
  paused = false,
  ref,
  smoothing = DEFAULT_SMOOTHING,
  taper = true,
}: DrawingCursorProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isPointerCapable, setIsPointerCapable] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const strokesRef = useRef<Stroke[]>([]);
  const activeStrokeRef = useRef<Stroke | null>(null);
  const rafRef = useRef<number | null>(null);
  const sizeRef = useRef({ height: 0, width: 0 });

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsPointerCapable(mediaQuery.matches);
    const handleChange = (event: MediaQueryListEvent) => {
      setIsPointerCapable(event.matches);
    };
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const isMounted = isPointerCapable && !shouldReduceMotion;

  useImperativeHandle(
    ref,
    () => ({
      clear: () => {
        strokesRef.current = [];
        activeStrokeRef.current = null;
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext("2d");
        if (canvas && ctx) {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
      },
      toDataURL: (type?: string, quality?: number) =>
        canvasRef.current?.toDataURL(type, quality) ?? "",
    }),
    []
  );

  useEffect(() => {
    if (!isMounted) {
      return;
    }
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!(container && canvas)) {
      return;
    }
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }

    const resize = () => {
      const rect = container.getBoundingClientRect();
      const dpr = Math.min(
        window.devicePixelRatio || 1,
        MAX_DEVICE_PIXEL_RATIO
      );
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sizeRef.current = { height: rect.height, width: rect.width };
    };

    resize();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);

    let lastPointTime = 0;

    const pushPoint = (x: number, y: number, time: number) => {
      const isNewStroke =
        !activeStrokeRef.current || time - lastPointTime > STROKE_BREAK_MS;
      if (isNewStroke) {
        const stroke: Stroke = { points: [] };
        activeStrokeRef.current = stroke;
        strokesRef.current.push(stroke);
        if (strokesRef.current.length > MAX_STROKES) {
          strokesRef.current.shift();
        }
      }
      const stroke = activeStrokeRef.current;
      if (!stroke) {
        return;
      }
      const previous = stroke.points.at(-1);
      let width = lineWidth;
      if (taper && previous) {
        const dt = Math.max(1, time - previous.time);
        const distance = Math.hypot(x - previous.x, y - previous.y);
        const speed = distance / dt;
        const factor = clamp(
          1 - speed * SPEED_TO_WIDTH_SCALE,
          MIN_WIDTH_FACTOR,
          1
        );
        width = lineWidth * factor;
      }
      stroke.points.push({ time, width, x, y });
      if (stroke.points.length > MAX_POINTS_PER_STROKE) {
        stroke.points.shift();
      }
      lastPointTime = time;
    };

    const handlePointerMove = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const coordinates = getPointerCoordinates(event, rect);
      for (const point of coordinates) {
        pushPoint(point.x, point.y, performance.now());
      }
    };

    const handlePointerLeave = () => {
      activeStrokeRef.current = null;
      if (clearOnLeave) {
        strokesRef.current = [];
        ctx.clearRect(0, 0, canvas.width, canvas.height);
      }
    };

    container.addEventListener("pointermove", handlePointerMove, {
      passive: true,
    });
    container.addEventListener("pointerleave", handlePointerLeave, {
      passive: true,
    });

    const drawStroke = (stroke: Stroke, now: number) => {
      const { points } = stroke;
      if (points.length < 2) {
        return;
      }
      if (points.length === 2) {
        const [start, end] = points;
        const age = decay > 0 ? clamp(1 - (now - end.time) / decay, 0, 1) : 1;
        if (age <= 0) {
          return;
        }
        ctx.beginPath();
        ctx.moveTo(start.x, start.y);
        ctx.lineTo(end.x, end.y);
        ctx.globalAlpha = age;
        ctx.strokeStyle = color;
        ctx.lineWidth = end.width;
        ctx.stroke();
        return;
      }
      for (let i = 1; i < points.length - 1; i++) {
        const prev = points[i - 1];
        const curr = points[i];
        const next = points[i + 1];
        const age = decay > 0 ? clamp(1 - (now - curr.time) / decay, 0, 1) : 1;
        if (age <= 0) {
          continue;
        }
        const midPrevX = (prev.x + curr.x) / 2;
        const midPrevY = (prev.y + curr.y) / 2;
        const midNextX = (curr.x + next.x) / 2;
        const midNextY = (curr.y + next.y) / 2;
        const startX = prev.x + (midPrevX - prev.x) * smoothing;
        const startY = prev.y + (midPrevY - prev.y) * smoothing;
        const endX = next.x + (midNextX - next.x) * smoothing;
        const endY = next.y + (midNextY - next.y) * smoothing;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.quadraticCurveTo(curr.x, curr.y, endX, endY);
        ctx.globalAlpha = age;
        ctx.strokeStyle = color;
        ctx.lineWidth = curr.width;
        ctx.stroke();
      }
    };

    const draw = () => {
      const now = performance.now();
      const { width, height } = sizeRef.current;
      ctx.clearRect(0, 0, width, height);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.globalCompositeOperation = blend;

      for (const stroke of strokesRef.current) {
        if (decay > 0) {
          while (
            stroke.points.length > 0 &&
            now - stroke.points[0].time > decay
          ) {
            stroke.points.shift();
          }
        }
        drawStroke(stroke, now);
      }

      strokesRef.current = strokesRef.current.filter(
        (stroke) => stroke.points.length > 0
      );

      if (!paused) {
        rafRef.current = requestAnimationFrame(draw);
      }
    };

    if (!paused) {
      rafRef.current = requestAnimationFrame(draw);
    }

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
      resizeObserver.disconnect();
      container.removeEventListener("pointermove", handlePointerMove);
      container.removeEventListener("pointerleave", handlePointerLeave);
    };
  }, [
    blend,
    clearOnLeave,
    color,
    decay,
    isMounted,
    lineWidth,
    paused,
    smoothing,
    taper,
  ]);

  return (
    <div className={cn("relative", className)} ref={containerRef}>
      {children}
      {isMounted ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        >
          <canvas className="h-full w-full" ref={canvasRef} />
        </div>
      ) : null}
    </div>
  );
};

export default DrawingCursor;

"use client";

import {
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenu as DropdownMenuRoot,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import type React from "react";
import { useState } from "react";
import { SPRING_DEFAULT } from "@/components/smoothui/lib/animation";

export interface DropdownMenuProps {
  /** Alignment of the dropdown relative to the trigger */
  align?: "start" | "center" | "end";
  /** The trigger element that opens the menu */
  children: React.ReactNode;
  /** Optional CSS class for the content container */
  className?: string;
  /** Menu items to render */
  items: DropdownMenuItemConfig[];
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Controlled open state */
  open?: boolean;
  /** Side offset for the dropdown content */
  sideOffset?: number;
}

export interface DropdownMenuItemConfig {
  /** Nested submenu items */
  children?: DropdownMenuItemConfig[];
  /** Whether the item is disabled */
  disabled?: boolean;
  /** Renders a group label instead of an item */
  groupLabel?: string;
  /** Optional icon to display before the label */
  icon?: React.ReactNode;
  /** Unique key for the item */
  key: string;
  /** Display label */
  label: string;
  /** Callback when item is selected */
  onSelect?: () => void;
  /** Renders a separator instead of an item */
  separator?: boolean;
  /** Optional keyboard shortcut text to display */
  shortcut?: string;
  /** Destructive variant styling */
  variant?: "default" | "destructive";
}

export default function DropdownMenu({
  children,
  items,
  className,
  open,
  onOpenChange,
  sideOffset = 4,
  align = "start",
}: DropdownMenuProps) {
  const shouldReduceMotion = useReducedMotion();
  const [isOpen, setIsOpen] = useState(false);

  const controlledOpen = open ?? isOpen;
  const handleOpenChange = (value: boolean) => {
    setIsOpen(value);
    onOpenChange?.(value);
  };

  const renderItem = (item: DropdownMenuItemConfig, index: number) => {
    if (item.separator) {
      return <DropdownMenuSeparator key={item.key} />;
    }

    if (item.groupLabel) {
      return (
        <DropdownMenuLabel key={item.key}>{item.groupLabel}</DropdownMenuLabel>
      );
    }

    if (item.children && item.children.length > 0) {
      return (
        <DropdownMenuSub key={item.key}>
          <DropdownMenuSubTrigger disabled={item.disabled}>
            {item.icon ? <span className="mr-2">{item.icon}</span> : null}
            {item.label}
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            {item.children.map((child, childIndex) =>
              renderItem(child, childIndex)
            )}
          </DropdownMenuSubContent>
        </DropdownMenuSub>
      );
    }

    return (
      <motion.div
        animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }}
        initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: -4 }}
        key={item.key}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : { ...SPRING_DEFAULT, delay: index * 0.02 }
        }
      >
        <DropdownMenuItem
          disabled={item.disabled}
          onSelect={item.onSelect}
          variant={item.variant}
        >
          {item.icon ? <span className="mr-2">{item.icon}</span> : null}
          {item.label}
          {item.shortcut ? (
            <DropdownMenuShortcut>{item.shortcut}</DropdownMenuShortcut>
          ) : null}
        </DropdownMenuItem>
      </motion.div>
    );
  };

  return (
    <DropdownMenuRoot onOpenChange={handleOpenChange} open={controlledOpen}>
      <DropdownMenuTrigger asChild>{children}</DropdownMenuTrigger>
      <DropdownMenuContent
        align={align}
        className={cn("origin-top", className)}
        sideOffset={sideOffset}
      >
        <motion.div
          animate={
            shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1, y: 0 }
          }
          initial={
            shouldReduceMotion
              ? { opacity: 1 }
              : { opacity: 0, scale: 0.95, y: -4 }
          }
          transition={shouldReduceMotion ? { duration: 0 } : SPRING_DEFAULT}
        >
          <DropdownMenuGroup>
            {items.map((item, index) => renderItem(item, index))}
          </DropdownMenuGroup>
        </motion.div>
      </DropdownMenuContent>
    </DropdownMenuRoot>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";

export type DurationUnit = "hours" | "minutes" | "seconds";

export type DurationPickerProps = {
  /** Additional CSS classes */
  className?: string;
  /** Controlled value in seconds */
  value?: number;
  /** Default value (uncontrolled) in seconds */
  defaultValue?: number;
  /** Called whenever the duration changes, with the new value in seconds */
  onValueChange?: (value: number) => void;
  /** Which unit segments to render, most-significant first */
  units?: DurationUnit[];
  /** Minimum total duration in seconds */
  min?: number;
  /** Maximum total duration in seconds */
  max?: number;
  /** Increment applied per arrow key press, in the focused unit's own scale */
  step?: number;
  /** Enable horizontal pointer drag to scrub a segment's value */
  scrub?: boolean;
  /** Disable all interaction */
  disabled?: boolean;
  /** Visible label rendered above the picker */
  label?: string;
};

const UNIT_ORDER: DurationUnit[] = ["hours", "minutes", "seconds"];
const UNIT_DIVISOR: Record<DurationUnit, number> = {
  hours: 3600,
  minutes: 60,
  seconds: 1,
};
const UNIT_LABEL: Record<DurationUnit, string> = {
  hours: "hour",
  minutes: "minute",
  seconds: "second",
};

const DEFAULT_UNITS: DurationUnit[] = ["hours", "minutes", "seconds"];
const DEFAULT_MIN = 0;
const DEFAULT_MAX = 359_999;
const DEFAULT_STEP = 1;
const SHIFT_MULTIPLIER = 10;
const PAGE_STEP_MULTIPLIER = 5;
const TYPE_BUFFER_TIMEOUT_MS = 600;
const PX_PER_DRAG_STEP = 6;
const DIGIT_HEIGHT = 24;
const DIGIT_ROLL_DISTANCE = 12;
const DIGIT_KEY_PATTERN = /^[0-9]$/;

const PAD_FORMATTER = new Intl.NumberFormat(undefined, {
  minimumIntegerDigits: 2,
  useGrouping: false,
});

const clamp = (val: number, min: number, max: number) =>
  Math.min(Math.max(val, min), max);

const sortUnits = (units: DurationUnit[]): DurationUnit[] => {
  const sorted = UNIT_ORDER.filter((unit) => units.includes(unit));
  return sorted.length > 0 ? sorted : DEFAULT_UNITS;
};

const decomposeDuration = (
  totalSeconds: number,
  units: DurationUnit[]
): number[] => {
  let remaining = Math.max(0, Math.trunc(totalSeconds));
  const values: number[] = [];
  for (const unit of units) {
    const divisor = UNIT_DIVISOR[unit];
    const segmentValue = Math.floor(remaining / divisor);
    values.push(segmentValue);
    remaining -= segmentValue * divisor;
  }
  return values;
};

const getSegmentMax = (
  index: number,
  units: DurationUnit[],
  overallMax: number
): number => {
  if (index === 0) {
    return Math.floor(overallMax / UNIT_DIVISOR[units[0]]);
  }
  const higherDivisor = UNIT_DIVISOR[units[index - 1]];
  const thisDivisor = UNIT_DIVISOR[units[index]];
  return Math.floor(higherDivisor / thisDivisor) - 1;
};

const pluralize = (count: number, unit: DurationUnit) =>
  `${count} ${UNIT_LABEL[unit]}${count === 1 ? "" : "s"}`;

/** Formats a duration in seconds into a padded, colon-separated string for the given units. */
export const formatDuration = (
  totalSeconds: number,
  units: DurationUnit[] = DEFAULT_UNITS
): string => {
  const sortedUnits = sortUnits(units);
  const values = decomposeDuration(totalSeconds, sortedUnits);
  return values.map((value) => PAD_FORMATTER.format(value)).join(":");
};

type AnimatedDigitProps = {
  char: string;
  reduceMotion: boolean;
};

const AnimatedDigit = ({ char, reduceMotion }: AnimatedDigitProps) => (
  <span
    className="relative inline-block w-[0.62em] text-center"
    style={{ height: DIGIT_HEIGHT }}
  >
    <AnimatePresence initial={false} mode="popLayout">
      <motion.span
        animate={reduceMotion ? { opacity: 1, y: 0 } : { opacity: 1, y: 0 }}
        className="absolute inset-0 flex items-center justify-center"
        exit={
          reduceMotion
            ? { opacity: 0, transition: { duration: 0 } }
            : { opacity: 0, y: DIGIT_ROLL_DISTANCE }
        }
        initial={
          reduceMotion
            ? { opacity: 1, y: 0 }
            : { opacity: 0, y: -DIGIT_ROLL_DISTANCE }
        }
        key={char}
        transition={
          reduceMotion
            ? { duration: 0 }
            : { bounce: 0.1, duration: 0.25, type: "spring" }
        }
      >
        {char}
      </motion.span>
    </AnimatePresence>
  </span>
);

type TypingState = { index: number; text: string };

const DurationPicker = ({
  className,
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  units = DEFAULT_UNITS,
  min = DEFAULT_MIN,
  max = DEFAULT_MAX,
  step = DEFAULT_STEP,
  scrub = true,
  disabled = false,
  label,
}: DurationPickerProps) => {
  const shouldReduceMotion = useReducedMotion();
  const labelId = useId();
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState(
    clamp(defaultValue, min, max)
  );
  const value = isControlled ? controlledValue : internalValue;

  const sortedUnits = useMemo(() => sortUnits(units), [units]);
  const values = useMemo(
    () => decomposeDuration(value, sortedUnits),
    [value, sortedUnits]
  );

  const segmentRefs = useRef<(HTMLDivElement | null)[]>([]);
  const dragStateRef = useRef<{
    index: number;
    startX: number;
    startValue: number;
  } | null>(null);
  const typingRef = useRef<TypingState | null>(null);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  );
  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);

  const setTotal = useCallback(
    (next: number) => {
      const clamped = clamp(Math.round(next), min, max);
      if (!isControlled) {
        setInternalValue(clamped);
      }
      onValueChange?.(clamped);
    },
    [isControlled, min, max, onValueChange]
  );

  const commitSegmentValue = useCallback(
    (index: number, rawValue: number) => {
      const divisor = UNIT_DIVISOR[sortedUnits[index]];
      const currentValues = decomposeDuration(value, sortedUnits);
      const delta = (rawValue - currentValues[index]) * divisor;
      setTotal(value + delta);
    },
    [sortedUnits, value, setTotal]
  );

  const clearTypingTimeout = useCallback(() => {
    if (typingTimeoutRef.current !== undefined) {
      clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = undefined;
    }
  }, []);

  useEffect(() => clearTypingTimeout, [clearTypingTimeout]);

  const focusSegment = useCallback((index: number) => {
    segmentRefs.current[index]?.focus();
  }, []);

  const commitTyped = useCallback(
    (index: number, text: string, advance: boolean) => {
      commitSegmentValue(index, Number.parseInt(text, 10));
      typingRef.current = null;
      clearTypingTimeout();
      if (advance) {
        focusSegment(index + 1);
      }
    },
    [commitSegmentValue, clearTypingTimeout, focusSegment]
  );

  const handleDigit = useCallback(
    (index: number, digit: string) => {
      const isLast = index === sortedUnits.length - 1;
      const { current } = typingRef;
      clearTypingTimeout();

      if (current && current.index === index && current.text.length === 1) {
        commitTyped(index, current.text + digit, !isLast);
        return;
      }

      typingRef.current = { index, text: digit };
      commitSegmentValue(index, Number.parseInt(digit, 10));
      typingTimeoutRef.current = setTimeout(() => {
        commitTyped(index, digit, !isLast);
      }, TYPE_BUFFER_TIMEOUT_MS);
    },
    [sortedUnits, clearTypingTimeout, commitTyped, commitSegmentValue]
  );

  const handleSegmentKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>, index: number) => {
      if (disabled) {
        return;
      }
      const unit = sortedUnits[index];
      const divisor = UNIT_DIVISOR[unit];
      const multiplier = event.shiftKey ? SHIFT_MULTIPLIER : 1;

      if (DIGIT_KEY_PATTERN.test(event.key)) {
        event.preventDefault();
        handleDigit(index, event.key);
        return;
      }

      switch (event.key) {
        case "ArrowUp":
          event.preventDefault();
          setTotal(value + step * multiplier * divisor);
          break;
        case "ArrowDown":
          event.preventDefault();
          setTotal(value - step * multiplier * divisor);
          break;
        case "PageUp":
          event.preventDefault();
          setTotal(value + step * PAGE_STEP_MULTIPLIER * divisor);
          break;
        case "PageDown":
          event.preventDefault();
          setTotal(value - step * PAGE_STEP_MULTIPLIER * divisor);
          break;
        case "Home":
          event.preventDefault();
          commitSegmentValue(index, 0);
          break;
        case "End":
          event.preventDefault();
          commitSegmentValue(index, getSegmentMax(index, sortedUnits, max));
          break;
        case "ArrowRight":
          event.preventDefault();
          focusSegment(index + 1);
          break;
        case "ArrowLeft":
          event.preventDefault();
          focusSegment(index - 1);
          break;
        default:
          break;
      }
    },
    [
      disabled,
      sortedUnits,
      step,
      value,
      max,
      setTotal,
      commitSegmentValue,
      focusSegment,
      handleDigit,
    ]
  );

  const handleSegmentBlur = useCallback(
    (index: number) => {
      if (typingRef.current?.index === index) {
        clearTypingTimeout();
        typingRef.current = null;
      }
    },
    [clearTypingTimeout]
  );

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>, index: number) => {
      if (!scrub || disabled) {
        return;
      }
      event.currentTarget.setPointerCapture(event.pointerId);
      dragStateRef.current = {
        index,
        startValue: value,
        startX: event.clientX,
      };
      setDraggingIndex(index);
    },
    [scrub, disabled, value]
  );

  const handlePointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragStateRef.current;
      if (!drag) {
        return;
      }
      const divisor = UNIT_DIVISOR[sortedUnits[drag.index]];
      const deltaSteps = Math.round(
        (event.clientX - drag.startX) / PX_PER_DRAG_STEP
      );
      setTotal(drag.startValue + deltaSteps * step * divisor);
    },
    [sortedUnits, step, setTotal]
  );

  const handlePointerUp = useCallback(() => {
    dragStateRef.current = null;
    setDraggingIndex(null);
  }, []);

  return (
    <div className={cn("inline-flex flex-col gap-1.5", className)}>
      {label ? (
        <span
          className="font-medium text-muted-foreground text-xs"
          id={labelId}
        >
          {label}
        </span>
      ) : null}
      <div
        aria-label={label ? undefined : "Duration"}
        aria-labelledby={label ? labelId : undefined}
        className={cn(
          "inline-flex items-center gap-0.5 rounded-lg border border-border bg-muted/40 px-2 py-1.5",
          disabled && "opacity-50"
        )}
        role="group"
      >
        {sortedUnits.map((unit, index) => {
          const text = PAD_FORMATTER.format(values[index]);
          const isDragging = draggingIndex === index;
          return (
            // biome-ignore lint/suspicious/noArrayIndexKey: segments are stable per unit
            <span className="flex items-center" key={unit}>
              {index > 0 && (
                <span aria-hidden="true" className="mx-0.5 text-foreground/40">
                  :
                </span>
              )}
              <div
                aria-disabled={disabled || undefined}
                aria-label={UNIT_LABEL[unit]}
                aria-valuemax={getSegmentMax(index, sortedUnits, max)}
                aria-valuemin={0}
                aria-valuenow={values[index]}
                aria-valuetext={pluralize(values[index], unit)}
                className={cn(
                  "relative flex select-none items-center justify-center rounded-md px-1 py-0.5 font-medium text-foreground tabular-nums outline-none",
                  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                  scrub && !disabled && "cursor-ew-resize",
                  disabled && "pointer-events-none",
                  isDragging && "bg-foreground/10"
                )}
                onBlur={() => handleSegmentBlur(index)}
                onKeyDown={(event) => handleSegmentKeyDown(event, index)}
                onPointerDown={(event) => handlePointerDown(event, index)}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                ref={(el) => {
                  segmentRefs.current[index] = el;
                }}
                role="spinbutton"
                style={{ fontSize: 18, touchAction: "none" }}
                tabIndex={disabled ? -1 : 0}
              >
                {text.split("").map((char, charIndex) => (
                  <AnimatedDigit
                    char={char}
                    // biome-ignore lint/suspicious/noArrayIndexKey: digit position within a segment is stable
                    key={charIndex}
                    reduceMotion={Boolean(shouldReduceMotion)}
                  />
                ))}
              </div>
            </span>
          );
        })}
      </div>
    </div>
  );
};

export default DurationPicker;

