                          <p className="font-semibold text-foreground">
                            {card.author.name}
                          </p>
                          <p className="text-primary-foreground text-xs">
                            {card.author.role}
                          </p>
                        </div>
                      </div>
                    ) : null}
                  </motion.div>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type FocusEvent,
  type KeyboardEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

export type ExpandableNavbarItem = {
  id: string;
  label: string;
  panel: ReactNode;
};

export type ExpandableNavbarProps = {
  className?: string;
  closeDelay?: number;
  items: ExpandableNavbarItem[];
  onOpenChange?: (id: string | null) => void;
  openId?: string | null;
  openOnHover?: boolean;
  width?: number | string;
};

const DEFAULT_CLOSE_DELAY = 200;
const SLIDE_DISTANCE = 16;
const HEIGHT_SPRING = { bounce: 0.08, duration: 0.3, type: "spring" as const };
const PANEL_TRANSITION = {
  duration: 0.2,
  ease: [0.645, 0.045, 0.355, 1] as [number, number, number, number],
};

export default function ExpandableNavbar({
  items,
  openId: controlledOpenId,
  onOpenChange,
  openOnHover = true,
  closeDelay = DEFAULT_CLOSE_DELAY,
  width = 640,
  className,
}: ExpandableNavbarProps) {
  const shouldReduceMotion = useReducedMotion();
  const generatedId = useId();
  const navRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const visiblePanelRef = useRef<HTMLDivElement>(null);
  const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const previousIndexRef = useRef(-1);

  const [internalOpenId, setInternalOpenId] = useState<string | null>(null);
  const [height, setHeight] = useState<number | "auto">(0);
  const [direction, setDirection] = useState(1);

  const isControlled = controlledOpenId !== undefined;
  const openId = isControlled ? controlledOpenId : internalOpenId;
  const activeIndex = items.findIndex((item) => item.id === openId);
  const activeItem = activeIndex >= 0 ? items[activeIndex] : null;

  const setOpenId = useCallback(
    (id: string | null) => {
      if (!isControlled) {
        setInternalOpenId(id);
      }
      onOpenChange?.(id);
    },
    [isControlled, onOpenChange]
  );

  useEffect(() => {
    if (activeIndex >= 0) {
      if (previousIndexRef.current >= 0) {
        setDirection(activeIndex > previousIndexRef.current ? 1 : -1);
      }
      previousIndexRef.current = activeIndex;
    }
  }, [activeIndex]);

  useLayoutEffect(() => {
    const measureNode = measureRef.current;
    if (!measureNode) {
      return;
    }
    const nextHeight = activeItem ? measureNode.scrollHeight : 0;

    setHeight((previousHeight) => {
      if (previousHeight === "auto" && visiblePanelRef.current) {
        const snapshot = visiblePanelRef.current.getBoundingClientRect();
        requestAnimationFrame(() => setHeight(nextHeight));
        return snapshot.height;
      }
      return nextHeight;
    });
  }, [activeItem]);

  const clearCloseTimeout = useCallback(() => {
    if (closeTimeoutRef.current) {
      clearTimeout(closeTimeoutRef.current);
      closeTimeoutRef.current = null;
    }
  }, []);

  const scheduleClose = useCallback(() => {
    clearCloseTimeout();
    closeTimeoutRef.current = setTimeout(() => {
      setOpenId(null);
    }, closeDelay);
  }, [clearCloseTimeout, closeDelay, setOpenId]);

  useEffect(() => clearCloseTimeout, [clearCloseTimeout]);

  const handleItemEnter = (id: string) => {
    if (!openOnHover) {
      return;
    }
    clearCloseTimeout();
    setOpenId(id);
  };

  const handlePanelLeave = () => {
    if (!openOnHover) {
      return;
    }
    scheduleClose();
  };

  const handleItemClick = (id: string) => {
    clearCloseTimeout();
    setOpenId(openId === id ? null : id);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape" && openId !== null) {
      event.preventDefault();
      setOpenId(null);
    }
  };

  const handleBlurCapture = (event: FocusEvent<HTMLDivElement>) => {
    const nextFocused = event.relatedTarget as Node | null;
    if (!(nextFocused && navRef.current?.contains(nextFocused))) {
      setOpenId(null);
    }
  };

  useEffect(() => {
    if (!openId) {
      return;
    }

    const handlePointerDown = (event: PointerEvent) => {
      if (!navRef.current?.contains(event.target as Node)) {
        setOpenId(null);
      }
    };

    document.addEventListener("pointerdown", handlePointerDown);
    return () => document.removeEventListener("pointerdown", handlePointerDown);
  }, [openId, setOpenId]);

  return (
    <nav
      aria-label="Expandable navigation"
      className={cn(
        "relative rounded-2xl border border-foreground/10 bg-background shadow-lg",
        className
      )}
      onBlurCapture={handleBlurCapture}
      onKeyDown={handleKeyDown}
      onPointerLeave={handlePanelLeave}
      ref={navRef}
      style={{ width }}
    >
      <ul className="flex items-center gap-1 p-2">
        {items.map((item) => {
          const isOpen = item.id === openId;
          const panelId = `expandable-navbar-${generatedId}-${item.id}`;
          return (
            <li key={item.id}>
              <button
                aria-controls={panelId}
                aria-expanded={isOpen}
                className={cn(
                  "rounded-lg px-3 py-2 font-medium text-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-brand",
                  isOpen
                    ? "bg-foreground/10 text-foreground"
                    : "text-muted-foreground hover:text-foreground"
                )}
                onClick={() => handleItemClick(item.id)}
                onFocus={() => handleItemEnter(item.id)}
                onPointerEnter={() => handleItemEnter(item.id)}
                type="button"
              >
                {item.label}
              </button>
            </li>
          );
        })}
      </ul>

      {/* Hidden mirror used to measure the target panel height without
          waiting for the visible cross-fade animation to settle. */}
      <div
        aria-hidden="true"
        className="invisible absolute inset-x-0 top-0"
        ref={measureRef}
        style={{ pointerEvents: "none" }}
      >
        <div className="p-4">{activeItem?.panel}</div>
      </div>

      <motion.div
        animate={{
          height: shouldReduceMotion ? (activeItem ? "auto" : 0) : height,
        }}
        className="overflow-hidden"
        initial={false}
        onAnimationComplete={() => {
          if (activeItem) {
            setHeight("auto");
          }
        }}
        transition={shouldReduceMotion ? { duration: 0 } : HEIGHT_SPRING}
      >
        <div className="relative" ref={visiblePanelRef}>
          <AnimatePresence custom={direction} initial={false} mode="wait">
            {activeItem ? (
              <motion.div
                animate={{ opacity: 1, x: 0 }}
                exit={
                  shouldReduceMotion
                    ? { opacity: 0, transition: { duration: 0 } }
                    : { opacity: 0, x: direction * -SLIDE_DISTANCE }
                }
                id={`expandable-navbar-${generatedId}-${activeItem.id}`}
                initial={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { opacity: 0, x: direction * SLIDE_DISTANCE }
                }
                key={activeItem.id}
                role="region"
                transition={
                  shouldReduceMotion ? { duration: 0 } : PANEL_TRANSITION
                }
              >
                <div className="p-4">{activeItem.panel}</div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>
      </motion.div>
    </nav>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  type MotionValue,
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import { useCallback, useRef } from "react";

export interface ExposureSliderProps {
  /** Accent color for the active notch and progress ring (CSS color value) */
  accentColor?: string;
  /** Additional CSS classes */
  className?: string;
  /** Initial value */
  defaultValue?: number;
  /** Maximum value */
  max?: number;
  /** Minimum value */
  min?: number;
  /** Callback fired when the value changes */
  onChange?: (value: number) => void;
  /** Show the circular progress indicator with the current value */
  showIndicator?: boolean;
  /** Step size between values */
  step?: number;
}

const NOTCH_WIDTH = 13; // px per notch (3px notch + 10px gap)
const SPRING_CONFIG = { damping: 30, mass: 0.5, stiffness: 300 };

const DEFAULT_ACCENT = "var(--color-brand, oklch(0.65 0.25 12))";

const ExposureSlider = ({
  min = -20,
  max = 20,
  step = 1,
  defaultValue = 0,
  onChange,
  showIndicator = true,
  accentColor,
  className,
}: ExposureSliderProps) => {
  const shouldReduceMotion = useReducedMotion();
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const count = Math.floor((max - min) / step) + 1;
  const centerIndex = Math.floor((defaultValue - min) / step);

  // Raw drag offset and spring-smoothed version
  const rawX = useMotionValue(0);
  const x = shouldReduceMotion ? rawX : useSpring(rawX, SPRING_CONFIG);

  // Current value derived from offset
  const currentValue = useTransform(x, (latest) => {
    const indexOffset = Math.round(-latest / NOTCH_WIDTH);
    const val = Math.max(
      min,
      Math.min(max, (centerIndex + indexOffset) * step + min)
    );
    return val;
  });

  // Track value for circle and display
  const displayValue = useTransform(currentValue, (v) => Math.round(v));
  const normalizedValue = useTransform(currentValue, [min, max], [-1, 1]);

  const snapToNearest = useCallback(() => {
    const current = rawX.get();
    const snapped = Math.round(current / NOTCH_WIDTH) * NOTCH_WIDTH;
    rawX.set(snapped);
  }, [rawX]);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      isDragging.current = true;
      const startX = e.clientX;
      const startOffset = rawX.get();

      const handleMove = (moveEvent: PointerEvent) => {
        const delta = moveEvent.clientX - startX;
        const newOffset = startOffset + delta;
        // Clamp to bounds
        const maxOffset = (count - 1 - centerIndex) * NOTCH_WIDTH;
        const minOffset = -centerIndex * NOTCH_WIDTH;
        rawX.set(Math.max(-maxOffset, Math.min(-minOffset, newOffset)));

        // Fire onChange
        const indexOffset = Math.round(-rawX.get() / NOTCH_WIDTH);
        const val = Math.max(
          min,
          Math.min(max, (centerIndex + indexOffset) * step + min)
        );
        onChange?.(Math.round(val));
      };

      const handleUp = () => {
        isDragging.current = false;
        snapToNearest();
        // Fire final onChange
        const indexOffset = Math.round(-rawX.get() / NOTCH_WIDTH);
        const val = Math.max(
          min,
          Math.min(max, (centerIndex + indexOffset) * step + min)
        );
        onChange?.(Math.round(val));
        window.removeEventListener("pointermove", handleMove);
        window.removeEventListener("pointerup", handleUp);
      };

      window.addEventListener("pointermove", handleMove);
      window.addEventListener("pointerup", handleUp);
    },
    [rawX, centerIndex, count, min, max, step, onChange, snapToNearest]
  );

  const items = Array.from({ length: count }, (_, i) => i);

  return (
    <div
      className={cn(
        "flex w-full max-w-[500px] flex-col items-center gap-6 text-foreground",
        className
      )}
      style={
        { "--es-accent": accentColor ?? DEFAULT_ACCENT } as React.CSSProperties
      }
    >
      {/* Progress circle */}
      {showIndicator ? (
        <ProgressCircle
          displayValue={displayValue}
          normalizedValue={normalizedValue}
        />
      ) : null}

      {/* Ticker slider */}
      <div
        className="relative flex h-10 w-full items-center justify-center"
        style={{
          maskImage:
            "linear-gradient(to right, transparent 0%, black 20%, black 80%, transparent 100%)",
          WebkitMaskImage:
            "linear-gradient(to right, transparent 0%, black 20%, black 80%, transparent 100%)",
        }}
      >
        <div
          className="relative h-full w-full cursor-grab select-none active:cursor-grabbing"
          onPointerDown={handlePointerDown}
          ref={containerRef}
          style={{
            padding: `0 calc(50% - ${NOTCH_WIDTH / 2}px)`,
            touchAction: "pan-y",
          }}
        >
          <motion.ul
            className="relative m-0 flex h-full list-none items-center p-0"
            style={{ marginLeft: -centerIndex * NOTCH_WIDTH, x }}
          >
            {items.map((i) => (
              <Notch centerIndex={centerIndex} index={i} key={i} x={x} />
            ))}
          </motion.ul>
        </div>
      </div>
    </div>
  );
};

/** Individual notch mark in the ticker */
const Notch = ({
  index,
  centerIndex,
  x,
}: {
  index: number;
  centerIndex: number;
  x: MotionValue<number>;
}) => {
  // Distance from center in notch units
  const distance = useTransform(x, (latest) => {
    const currentCenter = centerIndex + -latest / NOTCH_WIDTH;
    return Math.abs(index - currentCenter);
  });

  const opacity = useTransform(distance, [0, 1, 3], [1, 0.6, 0.3]);
  const clipTop = useTransform(distance, [0, 1, 2], [0, 30, 50]);
  const clipPath = useTransform(clipTop, (v) => `inset(${v}% 0px 0px)`);

  const isCenter = useTransform(distance, (d) => d < 0.5);
  const bg = useTransform(isCenter, (center) =>
    center ? "var(--es-accent)" : "currentColor"
  );

  return (
    <li
      className="relative flex-shrink-0 flex-grow-0"
      style={{ height: "fit-content" }}
    >
      <div style={{ padding: "0 5px" }}>
        <motion.div
          className="rounded-sm"
          style={{
            backgroundColor: bg,
            clipPath,
            height: 40,
            opacity,
            width: 3,
            willChange: "clip-path, opacity",
          }}
        />
      </div>
    </li>
  );
};

/** SVG progress ring showing positive/negative value */
const ProgressCircle = ({
  normalizedValue,
  displayValue,
}: {
  normalizedValue: MotionValue<number>;
  displayValue: MotionValue<number>;
}) => {
  // Positive arc (right side, 0 to 1)
  const positiveDash = useTransform(normalizedValue, (v) =>
    v > 0 ? `${v} ${1 - v}` : "0 1"
  );

  // Negative arc (left side, mirrored)
  const negativeDash = useTransform(normalizedValue, (v) =>
    v < 0 ? `${-v} ${1 + v}` : "0 1"
  );

  // Color: accent when non-zero, foreground when zero
  const color = useTransform(normalizedValue, (v) =>
    Math.abs(v) > 0.01 ? "var(--es-accent)" : "currentColor"
  );

  return (
    <div className="relative flex h-[75px] w-[75px] items-center justify-center">
      <svg className="absolute inset-0 h-full w-full" viewBox="0 0 100 100">
        {/* Background ring */}
        <circle
          cx="50"
          cy="50"
          fill="currentColor"
          fillOpacity={0.067}
          r="48"
          stroke="currentColor"
          strokeOpacity={0.3}
          strokeWidth="3"
        />
        {/* Positive indicator */}
        <motion.circle
          cx="50"
          cy="50"
          fill="none"
          pathLength={1}
          r="48"
          stroke="var(--es-accent)"
          strokeDasharray={positiveDash}
          strokeDashoffset={0}
          strokeWidth="3"
          style={{
            transform: "rotate(-90deg)",
            transformBox: "fill-box",
            transformOrigin: "50% 50%",
          }}
        />
        {/* Negative indicator */}
        <motion.circle
          cx="50"
          cy="50"
          fill="none"
          pathLength={1}
          r="48"
          stroke="var(--es-accent)"
          strokeDasharray={negativeDash}
          strokeDashoffset={0}
          strokeWidth="3"
          style={{
            transform: "scaleX(-1) rotate(-90deg)",
            transformBox: "fill-box",
            transformOrigin: "50% 50%",
          }}
        />
      </svg>
      <motion.span className="absolute font-semibold text-lg" style={{ color }}>
        {displayValue}
      </motion.span>
    </div>
  );
};

