    [1, 0, 1],
    [1, 0, 1],
    [1, 0, 1],
  ],
  "T-bot": [
    [0, 0, 0],
    [0, 1, 0],
    [1, 1, 1],
  ],
  "T-left": [
    [1, 0, 0],
    [1, 1, 0],
    [1, 0, 0],
  ],
  "T-right": [
    [0, 0, 1],
    [0, 1, 1],
    [0, 0, 1],
  ],

  // T-shapes
  "T-top": [
    [1, 1, 1],
    [0, 1, 0],
    [0, 0, 0],
  ],
  twinkle: [
    [1, 0, 0],
    [0, 0, 1],
    [0, 1, 0],
  ],

  // Effects
  waterfall: [
    [1, 1, 0],
    [0, 0, 0],
    [0, 0, 0],
  ],
  "wave-bt": [
    [0, 0, 0],
    [1, 1, 1],
    [1, 1, 1],
  ],

  // Waves
  "wave-lr": [
    [1, 1, 0],
    [1, 1, 0],
    [1, 1, 0],
  ],
  "wave-rl": [
    [0, 1, 1],
    [0, 1, 1],
    [0, 1, 1],
  ],
  "wave-tb": [
    [1, 1, 1],
    [1, 1, 1],
    [0, 0, 0],
  ],
  "x-shape": [
    [1, 0, 1],
    [0, 1, 0],
    [1, 0, 1],
  ],
};

// Color presets
const COLORS: Record<string, string> = {
  amber: "#fbbf24",
  blue: "#38bdf8",
  green: "#4ade80",
  red: "#f87171",
  white: "#f5f5f4",
};

// Size presets in pixels
const SIZES: Record<string, number> = {
  lg: 48,
  md: 32,
  sm: 24,
  xl: 64,
};

// Speed presets in milliseconds
const SPEEDS: Record<string, number> = {
  fast: 400,
  normal: 800,
  slow: 1500,
};

// Helper to resolve pattern to GridMatrix
const resolvePattern = (
  pattern: PresetPattern | GridMatrix | undefined
): GridMatrix => {
  if (!pattern) {
    return PATTERNS["plus-hollow"];
  }
  if (typeof pattern === "string") {
    return PATTERNS[pattern] ?? PATTERNS["plus-hollow"];
  }
  return pattern;
};

// Helper to resolve color
const resolveColor = (color: string | undefined): string => {
  if (!color) {
    return COLORS.white;
  }
  return COLORS[color] ?? color;
};

// Helper to resolve size
const resolveSize = (
  size: "sm" | "md" | "lg" | "xl" | number | undefined
): number => {
  if (size === undefined) {
    return SIZES.md;
  }
  if (typeof size === "number") {
    return size;
  }
  return SIZES[size] ?? SIZES.md;
};

// Cell component for individual grid cells
const GridCell = ({
  active,
  color,
  cellSize,
  animationDelay,
  mode,
  cycleDuration,
  shouldReduceMotion,
  rounded,
}: {
  active: boolean;
  color: string;
  cellSize: number;
  animationDelay: number;
  mode: "pulse" | "sequence" | "stagger";
  cycleDuration: number;
  shouldReduceMotion: boolean | null;
  rounded?: boolean;
}) => {
  const glowSize = cellSize * 0.8;
  const borderRadius = rounded ? "50%" : undefined;

  if (!active) {
    return (
      <div
        style={{
          height: cellSize,
          width: cellSize,
        }}
      />
    );
  }

  // For reduced motion, show static cells
  if (shouldReduceMotion) {
    return (
      <div
        style={{
          backgroundColor: color,
          borderRadius,
          boxShadow: `
            0 0 ${glowSize * 0.3}px ${color},
            0 0 ${glowSize * 0.6}px ${color}40,
            0 0 ${glowSize * 1.2}px ${color}20
          `,
          height: cellSize,
          width: cellSize,
        }}
      />
    );
  }

  const pulseAnimation = {
    opacity: [0.4, 1, 0.4],
    scale: [0.95, 1, 0.95],
  };

  const staggerAnimation = {
    opacity: [0, 1, 1, 0],
    scale: [0.8, 1, 1, 0.8],
  };

  return (
    <motion.div
      animate={mode === "stagger" ? staggerAnimation : pulseAnimation}
      style={{
        backgroundColor: color,
        borderRadius,
        boxShadow: `
          0 0 ${glowSize * 0.3}px ${color},
          0 0 ${glowSize * 0.6}px ${color}40,
          0 0 ${glowSize * 1.2}px ${color}20
        `,
        height: cellSize,
        width: cellSize,
      }}
      transition={{
        delay: mode === "stagger" ? animationDelay : 0,
        duration: cycleDuration / 1000,
        ease: [0.645, 0.045, 0.355, 1],
        repeat: Number.POSITIVE_INFINITY,
        times: mode === "stagger" ? [0, 0.2, 0.8, 1] : undefined,
      }}
    />
  );
};

const GridLoader = ({
  pattern,
  mode = "pulse",
  sequence,
  speed = "normal",
  color,
  size,
  blur,
  gap: gapProp,
  rounded,
  static: isStatic,
  className,
}: GridLoaderProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [sequenceIndex, setSequenceIndex] = useState(0);

  const sizeInPx = resolveSize(size);
  const gapSize = gapProp ?? 0;
  const cellSize = (sizeInPx - gapSize * 2) / 3;
  const resolvedColor = resolveColor(color);
  const cycleDuration = SPEEDS[speed] ?? SPEEDS.normal;
  const disableAnimation = isStatic || shouldReduceMotion;

  // Handle sequence mode
  useEffect(() => {
    if (mode !== "sequence" || !sequence || sequence.length === 0) {
      return;
    }
    if (disableAnimation) {
      return;
    }

    const interval = setInterval(() => {
      setSequenceIndex((prev) => (prev + 1) % sequence.length);
    }, cycleDuration);

    return () => clearInterval(interval);
  }, [mode, sequence, cycleDuration, disableAnimation]);

  // Determine current grid to display
  const currentGrid = useMemo(() => {
    if (mode === "sequence" && sequence && sequence.length > 0) {
      return resolvePattern(sequence[sequenceIndex]);
    }
    return resolvePattern(pattern);
  }, [mode, sequence, sequenceIndex, pattern]);

  // Flatten grid for rendering
  const cells = currentGrid.flat();

  // Calculate stagger delays based on active cells
  const staggerDelays = useMemo(() => {
    if (mode !== "stagger") {
      return cells.map(() => 0);
    }

    const activeCells = cells.reduce<number[]>((acc, cell, idx) => {
      if (cell === 1) {
        acc.push(idx);
      }
      return acc;
    }, []);

    const delayPerCell = cycleDuration / 1000 / (activeCells.length + 2);

    return cells.map((cell, idx) => {
      if (cell === 0) {
        return 0;
      }
      const activeIndex = activeCells.indexOf(idx);
      return activeIndex * delayPerCell;
    });
  }, [cells, mode, cycleDuration]);

  // Generate stable keys for grid positions (0-8 in a 3x3 grid)
  const cellKeys = ["tl", "tm", "tr", "ml", "mm", "mr", "bl", "bm", "br"];

  return (
    <output
      aria-label="Loading"
      className={cn("grid grid-cols-3", className)}
      style={{
        filter: blur ? `blur(${blur}px)` : undefined,
        gap: gapSize,
        height: sizeInPx,
        width: sizeInPx,
      }}
    >
      {cells.map((active, idx) => (
        <GridCell
          active={active === 1}
          animationDelay={staggerDelays[idx]}
          cellSize={cellSize}
          color={resolvedColor}
          cycleDuration={cycleDuration}
          key={cellKeys[idx]}
          mode={mode}
          rounded={rounded}
          shouldReduceMotion={disableAnimation}
        />
      ))}
    </output>
  );
};

export default GridLoader;

// Export patterns for advanced usage
export { COLORS, PATTERNS, SIZES };

"use client";

import { cn } from "@/lib/utils";
import {
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import {
  type CSSProperties,
  type ReactNode,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type BlendMode = NonNullable<CSSProperties["mixBlendMode"]>;

export type HolographicFoilPattern = "aurora" | "gold" | "oil" | "prism";

export interface HolographicFoilProps {
  /** Card content. It renders above the foil, so give text a solid backing. */
  children: ReactNode;
  /** Extra classes for the card surface. */
  className?: string;
  /**
   * Lay the foil over the content instead of printing it underneath.
   *
   * The default suits a card you assemble here — bare stock and translucent
   * artwork let the print show through from below. Turn this on when the child
   * is one opaque image of a finished card face, which would otherwise hide the
   * foil completely.
   */
  foilOver?: boolean;
  /** Strength of the highlight that passes over the content, `0` to `1`. */
  glare?: number;
  /** Foil strength, `0` (barely there) to `1` (full holo). */
  intensity?: number;
  /** Which foil material the card is printed with. */
  pattern?: HolographicFoilPattern;
  /** Speed multiplier for the idle sheen sweep. `1` is the default cadence. */
  sheenSpeed?: number;
  /** Couple the foil to a subtle 3D card tilt. */
  tilt?: boolean;
  /** Opt into device tilt on touch devices. Permission is requested on demand. */
  useDeviceOrientation?: boolean;
}

interface FoilMaterial {
  /** Banded gradient stack — bands with gaps, never a uniform wash. */
  background: string;
  blend: BlendMode;
  /** Degrees of hue travel across the full tilt range. Narrow keeps identity. */
  hueRange: number;
  /** Per-material saturation multiplier. */
  saturation: number;
}

type OrientationAccess = "denied" | "granted" | "idle" | "prompt";

interface OrientationPermissionApi {
  requestPermission?: () => Promise<"denied" | "granted">;
}

const HOVER_QUERY = "(hover: hover) and (pointer: fine)";
const MAX_TILT_DEG = 9;
const PERSPECTIVE_PX = 900;
const FOIL_DRIFT = 14;
const GLARE_DRIFT = 42;
const SHEEN_BASE_DURATION_S = 6;
const ORIENTATION_RANGE_DEG = 32;
const AXIS_MIN = -0.5;
const AXIS_MAX = 0.5;
const MIN_SHEEN_SPEED = 0.05;
const SPRING_CONFIG = { damping: 28, mass: 0.6, stiffness: 240 } as const;
const LINEAR_EASE: [number, number, number, number] = [0.25, 0.25, 0.75, 0.75];

const FOIL_MIN_OPACITY = 0.05;
const FOIL_MAX_OPACITY = 0.85;
const FOIL_MIN_SATURATION = 0.5;
const FOIL_SATURATION_GAIN = 0.85;
const FOIL_MIN_CONTRAST = 0.95;
const FOIL_CONTRAST_GAIN = 0.3;
/** The sheen never runs at full strength: it crosses text. */
const SHEEN_OPACITY_RATIO = 0.34;
const GLARE_OPACITY_RATIO = 0.18;
const SHEEN_FROM = "-120%";
const SHEEN_TO = "220%";

/**
 * Concentrates the foil into a diagonal band. Because the layer translates with
 * the tilt, the band travels across the card instead of tinting all of it.
 */
const FOIL_MASK =
  "linear-gradient(104deg, transparent 0%, oklch(0 0 0 / 0.35) 14%, oklch(0 0 0) 30%, oklch(0 0 0) 70%, oklch(0 0 0 / 0.35) 86%, transparent 100%)";

const SHEEN_GRADIENT =
  "linear-gradient(102deg, transparent 0%, oklch(0.86 0.07 220 / 0.55) 34%, oklch(1 0 0 / 0.85) 50%, oklch(0.82 0.08 330 / 0.5) 66%, transparent 100%)";
/**
 * The sheen gradient is tilted, so its `transparent` stops run diagonally while
 * the band it paints is a rectangle. Near the top the band's own left edge lands
 * mid-gradient, and the box boundary shows up as a straight vertical cut
 * travelling across the card. This fades the band's vertical edges so only the
 * gradient decides where the sheen ends.
 */
const SHEEN_EDGE_FADE =
  "linear-gradient(to right, transparent 0%, oklch(0 0 0) 22%, oklch(0 0 0) 78%, transparent 100%)";
const GLARE_GRADIENT =
  "radial-gradient(closest-side, oklch(1 0 0 / 0.75), oklch(1 0 0 / 0.12) 55%, transparent 78%)";

const MATERIALS: Record<HolographicFoilPattern, FoilMaterial> = {
  // Cool foil: blue → violet → cyan only.
  aurora: {
    background: [
      "repeating-linear-gradient(103deg, transparent 0 5%, oklch(0.74 0.12 232 / 0.85) 7.5%, oklch(0.66 0.13 288 / 0.8) 10.5%, oklch(0.8 0.1 205 / 0.85) 13.5%, transparent 16% 26%)",
      "linear-gradient(160deg, oklch(0.45 0.09 262 / 0.5), transparent 65%)",
    ].join(", "),
    blend: "screen",
    hueRange: 20,
    saturation: 1,
  },
  // Warm foil: gold → amber → magenta only.
  gold: {
    background: [
      "repeating-linear-gradient(97deg, transparent 0 5%, oklch(0.86 0.12 96 / 0.85) 7.5%, oklch(0.78 0.14 62 / 0.8) 10.5%, oklch(0.7 0.15 355 / 0.78) 14%, transparent 17% 27%)",
      "linear-gradient(150deg, oklch(0.5 0.1 55 / 0.45), transparent 68%)",
    ].join(", "),
    blend: "screen",
    hueRange: 24,
    saturation: 1,
  },
  // Oil slick: wide hue spread held at very low chroma, so it reads as a film.
  oil: {
    background: [
      "repeating-linear-gradient(110deg, transparent 0 6%, oklch(0.7 0.06 190 / 0.7) 8.5%, oklch(0.62 0.06 300 / 0.65) 12%, oklch(0.72 0.05 140 / 0.6) 15.5%, transparent 18.5% 30%)",
      "linear-gradient(135deg, oklch(0.4 0.04 250 / 0.4), transparent 70%)",
    ].join(", "),
    blend: "screen",
    hueRange: 30,
    saturation: 0.7,
  },
  // The full holo, still capped: cyan → violet → magenta with one gold band.
  prism: {
    background: [
      "repeating-linear-gradient(100deg, transparent 0 4%, oklch(0.8 0.14 200 / 0.9) 6%, oklch(0.7 0.16 268 / 0.88) 9%, oklch(0.72 0.17 330 / 0.86) 12%, oklch(0.84 0.12 60 / 0.7) 15%, transparent 17.5% 25%)",
      "radial-gradient(120% 90% at 30% 15%, oklch(0.6 0.12 250 / 0.5), transparent 65%)",
    ].join(", "),
    blend: "screen",
    hueRange: 34,
    saturation: 1.1,
  },
};

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

const clampAxis = (value: number) =>
  Math.max(AXIS_MIN, Math.min(AXIS_MAX, value));

const readOrientationApi = (): OrientationPermissionApi | undefined => {
  if (typeof window === "undefined" || !("DeviceOrientationEvent" in window)) {
    return;
  }
  return window.DeviceOrientationEvent as unknown as OrientationPermissionApi;
};

const HolographicFoil = ({
  children,
  className,
  foilOver = false,
  glare = 0.5,
  intensity = 0.6,
  pattern = "prism",
  sheenSpeed = 1,
  tilt = true,
  useDeviceOrientation = false,
}: HolographicFoilProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const [orientationAccess, setOrientationAccess] =
    useState<OrientationAccess>("idle");

  const material = MATERIALS[pattern];
  const foilLevel = clamp01(intensity);
  const glareLevel = clamp01(glare);

  const pointerX = useMotionValue(0);
  const pointerY = useMotionValue(0);
  const springX = useSpring(pointerX, SPRING_CONFIG);
  const springY = useSpring(pointerY, SPRING_CONFIG);

  const rotateX = useTransform(
    springY,
    [AXIS_MIN, AXIS_MAX],
    [MAX_TILT_DEG, -MAX_TILT_DEG]
  );
  const rotateY = useTransform(
    springX,
    [AXIS_MIN, AXIS_MAX],
    [-MAX_TILT_DEG, MAX_TILT_DEG]
  );
  const hue = useTransform(
    springX,
    [AXIS_MIN, AXIS_MAX],
    [-material.hueRange, material.hueRange]
  );
  const foilX = useTransform(
    springX,
    [AXIS_MIN, AXIS_MAX],
    [`${-FOIL_DRIFT}%`, `${FOIL_DRIFT}%`]
  );
  const foilY = useTransform(
    springY,
    [AXIS_MIN, AXIS_MAX],
    [`${-FOIL_DRIFT}%`, `${FOIL_DRIFT}%`]
  );
  const glareX = useTransform(
    springX,
    [AXIS_MIN, AXIS_MAX],
    [`${-GLARE_DRIFT}%`, `${GLARE_DRIFT}%`]
  );
  const glareY = useTransform(
    springY,
    [AXIS_MIN, AXIS_MAX],
    [`${-GLARE_DRIFT}%`, `${GLARE_DRIFT}%`]
  );
  const sheenX = useTransform(springX, [AXIS_MIN, AXIS_MAX], ["-18%", "18%"]);

  const saturation =
    (FOIL_MIN_SATURATION + foilLevel * FOIL_SATURATION_GAIN) *
    material.saturation;
  const contrast = FOIL_MIN_CONTRAST + foilLevel * FOIL_CONTRAST_GAIN;
  const foilFilter = useMotionTemplate`hue-rotate(${hue}deg) saturate(${saturation}) contrast(${contrast})`;
  const foilOpacity =
    FOIL_MIN_OPACITY + foilLevel * (FOIL_MAX_OPACITY - FOIL_MIN_OPACITY);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return;
    }
    const query = window.matchMedia(HOVER_QUERY);
    setIsHoverDevice(query.matches);
    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverDevice(event.matches);
    };
    query.addEventListener("change", handleChange);
    return () => {
      query.removeEventListener("change", handleChange);
    };
  }, []);

  useEffect(() => {
    if (!useDeviceOrientation || shouldReduceMotion) {
      setOrientationAccess("idle");
      return;
    }
    const api = readOrientationApi();
    if (!api) {
      setOrientationAccess("denied");
      return;
    }
    setOrientationAccess(
      typeof api.requestPermission === "function" ? "prompt" : "granted"
    );
  }, [shouldReduceMotion, useDeviceOrientation]);

  const orientationActive =
    useDeviceOrientation &&
    !shouldReduceMotion &&
    orientationAccess === "granted";

  useEffect(() => {
    if (!orientationActive || typeof window === "undefined") {
      return;
    }
    const handleOrientation = (event: DeviceOrientationEvent) => {
      const gamma = event.gamma ?? 0;
      const beta = event.beta ?? 0;
      pointerX.set(clampAxis(gamma / ORIENTATION_RANGE_DEG / 2));
      pointerY.set(clampAxis(beta / ORIENTATION_RANGE_DEG / 2));
    };
    window.addEventListener("deviceorientation", handleOrientation);
    return () => {
      window.removeEventListener("deviceorientation", handleOrientation);
    };
  }, [orientationActive, pointerX, pointerY]);

  const requestOrientation = useCallback(async () => {
    const api = readOrientationApi();
    if (typeof api?.requestPermission !== "function") {
      setOrientationAccess("denied");
      return;
    }
    try {
      const result = await api.requestPermission();
      setOrientationAccess(result === "granted" ? "granted" : "denied");
    } catch {
      setOrientationAccess("denied");
    }
  }, []);

  const tracksPointer = !shouldReduceMotion && isHoverDevice;

  const handlePointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const rect = event.currentTarget.getBoundingClientRect();
      pointerX.set(clampAxis((event.clientX - rect.left) / rect.width - 0.5));
      pointerY.set(clampAxis((event.clientY - rect.top) / rect.height - 0.5));
    },
    [pointerX, pointerY]
  );

  const handlePointerLeave = useCallback(() => {
    pointerX.set(0);
    pointerY.set(0);
  }, [pointerX, pointerY]);

  const isLive = tracksPointer || orientationActive;

  /**
   * The print itself. Placed either under or over the content depending on
   * `foilOver`, which is the only thing that differs between the two modes.
   */
  const foilLayer = (
    <motion.div
      aria-hidden="true"
      className="pointer-events-none absolute"
      style={{
        backgroundImage: material.background,
        filter: isLive ? foilFilter : undefined,
        inset: `-${FOIL_DRIFT * 2}%`,
        maskImage: FOIL_MASK,
        mixBlendMode: material.blend,
        opacity: foilOpacity,
        WebkitMaskImage: FOIL_MASK,
        willChange: "transform",
        x: isLive ? foilX : 0,
        y: isLive ? foilY : 0,
      }}
    />
  );

  const foilUnder = foilOver ? null : foilLayer;
  const foilAbove = foilOver ? foilLayer : null;
  const sheenDuration =
    SHEEN_BASE_DURATION_S / Math.max(MIN_SHEEN_SPEED, sheenSpeed);
  const showPermissionButton =
    useDeviceOrientation &&
    !shouldReduceMotion &&
    orientationAccess === "prompt";

  return (
    // The tilt lives on the same element as the border, the stock colour and
    // the clip, so the card turns as one rigid object. With the transform on an
    // inner wrapper, this outer box stayed square while its contents leaned —
    // a static window with a card moving behind it, which is very obvious once
    // the child is a full-bleed image rather than a padded layout.
    <motion.div
      className={cn(
        "relative isolate overflow-hidden rounded-2xl border border-white/10 bg-[oklch(0.17_0.015_274)] shadow-lg",
        className
      )}
      onPointerLeave={tracksPointer ? handlePointerLeave : undefined}
      onPointerMove={tracksPointer ? handlePointerMove : undefined}
      style={
        tilt && isLive
          ? {
              rotateX,
              rotateY,
              transformPerspective: PERSPECTIVE_PX,
              transformStyle: "preserve-3d",
            }
          : undefined
      }
    >
      <div className="relative h-full">
        {/* Layer order is DOM order, deliberately: no `z-index` anywhere, so no
            child creates a stacking context and content can blend with the foil
            (an artwork can; a text scrim stays opaque). Which side of the
            content the print lands on is `foilOver`. */}
        {foilUnder}

        <div className="relative h-full">{children}</div>

        {foilAbove}

        {/* Restrained highlight pass over the content. */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 overflow-hidden rounded-[inherit]"
        >
          <motion.div
            className="absolute inset-0"
            style={{ x: isLive ? sheenX : 0 }}
          >
            <motion.div
              animate={isLive ? { x: [SHEEN_FROM, SHEEN_TO] } : undefined}
              className="absolute inset-y-0 left-0 w-2/3"
              style={{
                backgroundImage: SHEEN_GRADIENT,
                maskImage: SHEEN_EDGE_FADE,
                mixBlendMode: "soft-light",
                opacity: glareLevel * SHEEN_OPACITY_RATIO,
                WebkitMaskImage: SHEEN_EDGE_FADE,
                willChange: "transform",
              }}
              transition={
                isLive
                  ? {
                      duration: sheenDuration,
                      ease: LINEAR_EASE,
                      repeat: Number.POSITIVE_INFINITY,
                      repeatType: "loop",
                    }
                  : { duration: 0 }
              }
            />
          </motion.div>
        </div>

        <motion.div
          aria-hidden="true"
          className="pointer-events-none absolute"
          style={{
            backgroundImage: GLARE_GRADIENT,
            inset: `-${GLARE_DRIFT}%`,
            mixBlendMode: "soft-light",
            opacity: glareLevel * GLARE_OPACITY_RATIO,
            willChange: "transform",
            x: isLive ? glareX : 0,
            y: isLive ? glareY : 0,
          }}
        />
      </div>

      {showPermissionButton ? (
        <button
          // Styled against the card's own dark stock rather than the theme:
          // the foil surface stays dark in light mode too, so theme tokens
          // would render this invisible.
          className="absolute right-2 bottom-2 cursor-pointer rounded-full border border-white/20 bg-[oklch(0.17_0.015_274)]/85 px-3 py-1 font-medium text-white text-xs outline-none transition-colors duration-150 ease-out hover:border-white/35 hover:bg-[oklch(0.17_0.015_274)] focus-visible:ring-2 focus-visible:ring-white/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[oklch(0.17_0.015_274)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100"
          onClick={requestOrientation}
          type="button"
        >
          Enable tilt
        </button>
      ) : null}
    </motion.div>
  );
};

export default HolographicFoil;

"use client";

import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import type { KeyboardEvent } from "react";
import { useEffect, useRef, useState } from "react";

export type HoverExpandOrientation = "horizontal" | "vertical";

export interface HoverExpandItem {
  alt?: string;
  description?: string;
  id: string;
  image?: string;
  title: string;
}

export interface HoverExpandProps {
  activeIndex?: number;
  className?: string;
  collapsedFlex?: number;
  expandedFlex?: number;
  items: HoverExpandItem[];
  onActiveIndexChange?: (index: number) => void;
  orientation?: HoverExpandOrientation;
  showLabelsWhenCollapsed?: boolean;
}

const DEFAULT_EXPANDED_FLEX = 4;
const DEFAULT_COLLAPSED_FLEX = 1;
const LABEL_ROTATION = -90;

const HoverExpand = ({
  items,
  orientation = "horizontal",
  activeIndex: activeIndexProp,
  onActiveIndexChange,
  expandedFlex = DEFAULT_EXPANDED_FLEX,
  collapsedFlex = DEFAULT_COLLAPSED_FLEX,
  showLabelsWhenCollapsed = true,
  className,
}: HoverExpandProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [internalActive, setInternalActive] = useState(0);
  const isControlled = activeIndexProp !== undefined;
  const activeIndex = isControlled ? activeIndexProp : internalActive;
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const panelRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const isHorizontal = orientation === "horizontal";

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverDevice(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const setActive = (index: number) => {
    if (!isControlled) {
      setInternalActive(index);
    }
    onActiveIndexChange?.(index);
  };

  const handleKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
    index: number
  ) => {
    const nextKey = isHorizontal ? "ArrowRight" : "ArrowDown";
    const prevKey = isHorizontal ? "ArrowLeft" : "ArrowUp";

    if (event.key === nextKey) {
      event.preventDefault();
      const next = Math.min(index + 1, items.length - 1);
      setActive(next);
      panelRefs.current[next]?.focus();
    } else if (event.key === prevKey) {
      event.preventDefault();
      const prev = Math.max(index - 1, 0);
      setActive(prev);
      panelRefs.current[prev]?.focus();
    }
  };

  return (
    <div
      aria-label="Expandable image panels"
      className={cn(
        "flex w-full gap-2",
        isHorizontal ? "h-[360px] flex-row" : "h-[520px] flex-col",
        className
      )}
      role="group"
    >
      {items.map((item, index) => {
        const isActive = index === activeIndex;
        const shouldShowLabel = isActive || showLabelsWhenCollapsed;

        return (
          <motion.button
            animate={{ flexGrow: isActive ? expandedFlex : collapsedFlex }}
            aria-label={item.title}
            aria-pressed={isActive}
            className="relative min-h-0 min-w-0 flex-1 overflow-hidden rounded-2xl border border-foreground/10 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand"
            initial={false}
            key={item.id}
            onClick={() => {
              if (!isHoverDevice) {
                setActive(index);
              }
            }}
            onFocus={() => setActive(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
            onMouseEnter={() => {
              if (isHoverDevice) {
                setActive(index);
              }
            }}
            ref={(el) => {
              panelRefs.current[index] = el;
            }}
            style={{ flexBasis: 0 }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { bounce: 0.1, duration: 0.25, type: "spring" }
            }
            type="button"
          >
            {item.image ? (
              <img
                alt={item.alt ?? item.title}
                className="absolute inset-0 h-full w-full object-cover"
                draggable={false}
                src={item.image}
              />
            ) : null}
            <div
              aria-hidden="true"
              className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/10 to-transparent"
            />
            <motion.div
              animate={
                shouldReduceMotion
                  ? { opacity: shouldShowLabel ? 1 : 0 }
                  : {
                      opacity: shouldShowLabel ? 1 : 0,
                      rotate: isHorizontal && !isActive ? LABEL_ROTATION : 0,
                    }
              }
              className="absolute inset-0 flex items-end p-4"
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : { bounce: 0.1, duration: 0.25, type: "spring" }
              }
            >
              <div
                className={cn(
                  isHorizontal && !isActive && "origin-left whitespace-nowrap"
                )}
              >
                <p className="font-semibold text-sm text-white">{item.title}</p>
                {isActive && item.description ? (
                  <p className="mt-1 text-white/80 text-xs">
                    {item.description}
                  </p>
                ) : null}
              </div>
            </motion.div>
          </motion.button>
        );
      })}
    </div>
  );
};

export default HoverExpand;

"use client";

import { cn } from "@/lib/utils";
import { ArrowUpRight } from "lucide-react";
import {
  AnimatePresence,
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
} from "motion/react";
import type { FocusEvent, PointerEvent, ReactNode } from "react";
import { useCallback, useEffect, useRef, useState } from "react";

export interface HoverImageListItem {
  alt: string;
  href?: string;
  id: string;
  image: string;
  meta?: string;
  title: string;
}

export type HoverImageListRevealMode = "cursor" | "fixed";

export interface HoverImageListProps {
  className?: string;
  follow?: boolean;
  imageSize?: number;
  items: HoverImageListItem[];
  revealMode?: HoverImageListRevealMode;
}

type ActivationSource = "focus" | "pointer" | null;

const DEFAULT_IMAGE_SIZE = 240;
const SPRING_CONFIG = { damping: 26, stiffness: 260 };
const SKEW_SPRING_CONFIG = { damping: 18, stiffness: 220 };
const MAX_SKEW = 8;
const SKEW_FACTOR = 0.12;
const MAX_FRAME_DELTA_MS = 50;

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

const HoverImageList = ({
  className,
  follow = true,
  imageSize = DEFAULT_IMAGE_SIZE,
  items,
  revealMode = "cursor",
}: HoverImageListProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [activationSource, setActivationSource] =
    useState<ActivationSource>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const lastPointerRef = useRef<{ t: number; x: number; y: number } | null>(
    null
  );
  const pendingPointerRef = useRef<{ x: number; y: number } | null>(null);
  const frameRequestedRef = useRef(false);
  const rafIdRef = useRef<number | null>(null);

  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const skew = useMotionValue(0);
  const springX = useSpring(x, SPRING_CONFIG);
  const springY = useSpring(y, SPRING_CONFIG);
  const springSkew = useSpring(skew, SKEW_SPRING_CONFIG);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverDevice(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  useEffect(
    () => () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }
    },
    []
  );

  const isFixedPosition =
    shouldReduceMotion ||
    !isHoverDevice ||
    activationSource === "focus" ||
    revealMode === "fixed";

  const activateRow = (index: number, source: ActivationSource) => {
    setActiveIndex(index);
    setActivationSource(source);
  };

  const deactivateRow = (source: ActivationSource) => {
    setActiveIndex((current) => (current === null ? current : null));
    setActivationSource((current) => (current === source ? null : current));
  };

  const handlePointerMove = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (isFixedPosition) {
        return;
      }

      pendingPointerRef.current = { x: event.clientX, y: event.clientY };

      if (frameRequestedRef.current) {
        return;
      }
      frameRequestedRef.current = true;

      rafIdRef.current = requestAnimationFrame((now) => {
        frameRequestedRef.current = false;
        const pending = pendingPointerRef.current;
        const container = containerRef.current;
        if (!(pending && container)) {
          return;
        }

        const rect = container.getBoundingClientRect();
        const localX = pending.x - rect.left;
        const localY = pending.y - rect.top;

        if (follow) {
          let vx = 0;
          if (lastPointerRef.current) {
            const dt = Math.min(
              now - lastPointerRef.current.t,
              MAX_FRAME_DELTA_MS
            );
            if (dt > 0) {
              vx = (localX - lastPointerRef.current.x) / dt;
            }
          }
          lastPointerRef.current = { t: now, x: localX, y: localY };
          skew.set(clamp(vx * SKEW_FACTOR, -MAX_SKEW, MAX_SKEW));
        }

        x.set(localX - imageSize / 2);
        y.set(localY - imageSize / 2);
      });
    },
    [isFixedPosition, follow, imageSize, skew, x, y]
  );

  const handleListPointerLeave = () => {
    deactivateRow("pointer");
    lastPointerRef.current = null;
  };

  const handleListBlur = (event: FocusEvent<HTMLDivElement>) => {
    if (
      activationSource === "focus" &&
      !event.currentTarget.contains(event.relatedTarget)
    ) {
      deactivateRow("focus");
    }
  };

  const activeItem = activeIndex === null ? null : items[activeIndex];

  const previewPositionStyle = isFixedPosition
    ? { height: imageSize, width: imageSize }
    : {
        height: imageSize,
        left: 0,
        top: 0,
        width: imageSize,
        x: follow ? springX : x,
        y: follow ? springY : y,
      };

  const renderRowContent = (item: HoverImageListItem): ReactNode => (
    <>
      <span className="flex flex-col gap-1">
        <span className="font-medium text-foreground text-lg transition-colors duration-200 group-hover:text-brand">
          {item.title}
        </span>
        {item.meta ? (
          <span className="text-muted-foreground text-sm">{item.meta}</span>
        ) : null}
      </span>
      <ArrowUpRight
        aria-hidden="true"
        className="size-4 shrink-0 text-muted-foreground opacity-0 transition-opacity duration-200 group-hover:opacity-100 group-focus-visible:opacity-100"
      />
    </>
  );

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: only tracks pointer/focus leaving the list bounds to clear the preview
    <div
      className={cn("relative", className)}
      onBlur={handleListBlur}
      onPointerLeave={handleListPointerLeave}
      onPointerMove={handlePointerMove}
      ref={containerRef}
    >
      <ul className="flex flex-col">
        {items.map((item, index) => (
          <li
            className="border-foreground/10 border-b last:border-b-0"
            key={item.id}
          >
            {item.href ? (
              <a
                className="group flex w-full items-center justify-between gap-4 py-5 text-left transition-colors duration-200"
                href={item.href}
                onFocus={() => activateRow(index, "focus")}
                onMouseEnter={() => {
                  if (isHoverDevice) {
                    activateRow(index, "pointer");
                  }
                }}
              >
                {renderRowContent(item)}
              </a>
            ) : (
              <button
                className="group flex w-full items-center justify-between gap-4 py-5 text-left transition-colors duration-200"
                onFocus={() => activateRow(index, "focus")}
                onMouseEnter={() => {
                  if (isHoverDevice) {
                    activateRow(index, "pointer");
                  }
                }}
                type="button"
              >
                {renderRowContent(item)}
              </button>
            )}
          </li>
        ))}
      </ul>

      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 overflow-hidden"
      >
        <motion.div
          animate={
            shouldReduceMotion
              ? { opacity: activeItem ? 1 : 0 }
              : { opacity: activeItem ? 1 : 0, scale: activeItem ? 1 : 0.94 }
          }
          className={cn(
            "absolute overflow-hidden rounded-2xl shadow-xl",
            isFixedPosition && "top-1/2 right-6 -translate-y-1/2"
          )}
          initial={{ opacity: 0, scale: shouldReduceMotion ? 1 : 0.94 }}
          style={{
            ...previewPositionStyle,
            skewX: shouldReduceMotion || isFixedPosition ? 0 : springSkew,
          }}
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : { bounce: 0.1, duration: 0.25, type: "spring" }
          }
        >
          <AnimatePresence initial={false}>
            {activeItem ? (
              <motion.img
                alt={activeItem.alt}
                animate={
                  shouldReduceMotion ? { opacity: 1 } : { opacity: 1, scale: 1 }
                }
                className="absolute inset-0 h-full w-full object-cover"
                exit={
                  shouldReduceMotion
                    ? { opacity: 0, transition: { duration: 0 } }
                    : { opacity: 0, scale: 0.96 }
                }
                initial={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { opacity: 0, scale: 0.96 }
                }
                key={activeItem.id}
                src={activeItem.image}
                transition={
                  shouldReduceMotion
                    ? { duration: 0 }
                    : { bounce: 0.1, duration: 0.25, type: "spring" }
                }
              />
            ) : null}
          </AnimatePresence>
        </motion.div>
      </div>
    </div>
  );
};

export default HoverImageList;

"use client";

import { cn } from "@/lib/utils";
import {
  AlertCircle,
  Check,
  Download,
  Image as ImageIcon,
  Shuffle,
  Sparkles,
} from "lucide-react";
import {
  AnimatePresence,
  motion,
  type Transition,
  useReducedMotion,
} from "motion/react";
import { useId, useState } from "react";
import type { AIState } from "../ai-core";
import AILoader from "../ai-loader";
import AIPromptInput from "../ai-prompt-input";

/* -------------------------------------------------------------------------- */
/* Motion + layout constants                                                  */
/* -------------------------------------------------------------------------- */

const SPRING_DEFAULT: Transition = {
  bounce: 0.1,
  duration: 0.25,
  type: "spring",
};
const SPRING_SNAPPY: Transition = { bounce: 0, duration: 0.2, type: "spring" };

const PERCENT = 100;
const DEFAULT_COUNT = 4;
const DEFAULT_ASPECT_RATIO = "1 / 1";

/** How far apart, in overall progress, two neighbouring tiles finish. */
const TILE_FINISH_STAGGER = 0.09;
const MIN_TILE_SPAN = 0.25;
const TILE_ENTER_STAGGER_SECONDS = 0.05;

/** The blurred pass never exceeds ~20px — past that `blur()` gets expensive. */
const MAX_SHARP_BLUR_PX = 18;
const MOSAIC_BLUR_PX = 2;
const MOSAIC_SATURATE = 1.35;
const MOSAIC_SCALE = 1.08;
const MOSAIC_FADE_START = 0.3;
const MOSAIC_FADE_SPAN = 0.5;
const SHARP_FADE_START = 0.12;
const SHARP_FADE_SPAN = 0.5;
const SHARPEN_EXPONENT = 1.35;
/** Extra scale on the sharp pass at 0% — the tile "pulls focus" as it resolves. */
const FOCUS_PULL_SCALE = 0.055;

/**
 * The sweep band is 45% of the tile tall and travels leading-edge-first from
 * the top edge to the bottom. Starting at -100% parks the whole band (and its
 * trail) above the tile; 124% carries the leading edge past the bottom edge.
 */
const SCAN_DURATION_SECONDS = 1.9;
const SCAN_KEYFRAMES = ["translateY(-100%)", "translateY(124%)"];
const SHIMMER_DURATION_SECONDS = 1.6;
const CARET_DURATION_SECONDS = 1;
const CARET_TIMES = [0, 0.5, 0.5, 1];
const CARET_KEYFRAMES = [1, 1, 0, 0];

const PROMPT_PLACEHOLDER = "A lighthouse at dusk, long exposure…";

const ACTION_ICON_SIZE = 15;
const STATUS_ICON_SIZE = 14;
const PLACEHOLDER_ICON_SIZE = 18;

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));

/**
 * Where a single tile sits in its own 0→1 resolve, given the batch progress.
 *
 * Real generators don't finish four images on the same frame, and a grid that
 * does reads as a single image cut into quarters. Offsetting each tile's window
 * makes the batch look like four jobs racing rather than one mask lifting.
 */
const tileProgress = (
  batchProgress: number,
  index: number,
  count: number
): number => {
  const offset = index * TILE_FINISH_STAGGER;
  const span = Math.max(MIN_TILE_SPAN, 1 - (count - 1) * TILE_FINISH_STAGGER);
  return clamp01((batchProgress - offset) / span);
};

const ramp = (value: number, start: number, span: number): number =>
  clamp01((value - start) / span);

/* -------------------------------------------------------------------------- */
/* Public types                                                              */
/* -------------------------------------------------------------------------- */

export type ImageGenerationStatus =
  | "idle"
  | "queued"
  | "generating"
  | "done"
  | "error";

export type ImageGenerationImage = {
  alt: string;
  id: string;
  /**
   * A tiny (16–48px) version of `src`. Rendered pixelated and blurred as the
   * first pass, so the tile starts as a colour mosaic of the real result
   * instead of a grey box. Falls back to `src` when omitted.
   */
  preview?: string;
  /** Surfaced once the tile has resolved. */
  seed?: string;
  src: string;
};

export type ImageGenerationPreset = {
  id: string;
  label: string;
};

export type ImageGenerationAspectRatio = {
  id: string;
  label: string;
  /** Any CSS `aspect-ratio` value, e.g. `"16 / 9"`. */
  value: string;
};

/**
 * How much surrounding chrome the panel renders. `minimal` drops the header,
 * the footer and the batch progress rail, and hides the seed readout — leaving
 * the composer and the tiles. Everything else, including the API, is unchanged.
 */
export type ImageGenerationChrome = "full" | "minimal";

/** Whether the prompt composer sits above or below the tiles. */
export type ImageGenerationComposerPlacement = "top" | "bottom";

export type ImageGenerationPanelProps = {
  /** Controlled `aspect-ratio` value. Omit to let the panel own the choice. */
  aspectRatio?: string;
  aspectRatios?: ImageGenerationAspectRatio[];
  /** How much surrounding chrome renders. Defaults to `"full"`. */
  chrome?: ImageGenerationChrome;
  className?: string;
  /** Where the composer sits relative to the tiles. Defaults to `"top"`. */
  composerPlacement?: ImageGenerationComposerPlacement;
  /** Number of tiles in the grid. */
  count?: number;
  error?: string;
  images?: ImageGenerationImage[];
  /** Model name shown in the header. */
  model?: string;
  onAspectRatioChange?: (value: string) => void;
  /**
   * Cancels the run in flight. Given one, the composer's send control turns
   * into a stop button while the batch renders; without one the composer simply
   * locks until the batch settles.
   */
  onCancel?: () => void;
  onGenerate?: (prompt: string) => unknown;
  onPromptChange?: (value: string) => void;
  onRetry?: () => void;
  onSelect?: (image: ImageGenerationImage) => void;
  onVariations?: (image: ImageGenerationImage) => void;
  presets?: ImageGenerationPreset[];
  /** Batch progress, 0–1. Drives every tile's mosaic-to-sharp resolve. */
  progress?: number;
  prompt?: string;
  /** Batch seed, shown in the composer readout. */
  seed?: string;
  /** Controlled status. Omit to run the panel's own queued → done cycle. */
  status?: ImageGenerationStatus;
  /**
   * Renders the prompt as read-only text with a blinking caret. Use while
   * replaying or streaming a prompt into the field.
   */
  typing?: boolean;
};

/* -------------------------------------------------------------------------- */
/* Static config                                                              */
/* -------------------------------------------------------------------------- */

const DEFAULT_ASPECT_RATIOS: ImageGenerationAspectRatio[] = [
  { id: "square", label: "1:1", value: "1 / 1" },
  { id: "portrait", label: "4:5", value: "4 / 5" },
  { id: "wide", label: "16:9", value: "16 / 9" },
];

const STATUS_META: Record<
  ImageGenerationStatus,
  { dot: string; label: string }
> = {
  done: { dot: "bg-emerald-500", label: "Ready" },
  error: { dot: "bg-destructive", label: "Failed" },
  generating: { dot: "bg-brand", label: "Rendering" },
  idle: { dot: "bg-muted-foreground/40", label: "Idle" },
  queued: { dot: "bg-amber-500", label: "Queued" },
};

const TILE_ACTION_CLASS =
  "relative flex size-8 cursor-pointer items-center justify-center rounded-full bg-black/55 text-white backdrop-blur-sm transition-colors duration-150 ease-out before:absolute before:-inset-1 before:content-[''] hover:bg-black/75 focus-visible:outline-2 focus-visible:outline-white/90 focus-visible:outline-offset-2 motion-reduce:transition-none";

/* -------------------------------------------------------------------------- */
/* Tile                                                                       */
/* -------------------------------------------------------------------------- */

type TileProps = {
  aspectRatio: string;
  image?: ImageGenerationImage;
  index: number;
  onSelect?: (image: ImageGenerationImage) => void;
  onVariations?: (image: ImageGenerationImage) => void;
  progress: number;
  shouldReduceMotion: boolean;
  status: ImageGenerationStatus;
};

const EmptyTile = ({
  aspectRatio,
  isQueued,
  shouldReduceMotion,
}: {
  aspectRatio: string;
  isQueued: boolean;
  shouldReduceMotion: boolean;
}) => (
  <div
    className="relative flex items-center justify-center overflow-hidden rounded-lg border border-border border-dashed bg-muted/40"
    style={{ aspectRatio }}
  >
    {isQueued ? (
      <motion.span
        animate={
          shouldReduceMotion ? { opacity: 0.6 } : { opacity: [0.3, 0.7, 0.3] }
        }
        aria-hidden="true"
        className="absolute inset-0 bg-foreground/5"
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                duration: SHIMMER_DURATION_SECONDS,
                ease: "linear",
                repeat: Number.POSITIVE_INFINITY,
              }
        }
      />
    ) : null}
    <span className="relative flex flex-col items-center gap-1.5 text-muted-foreground/60">
      <ImageIcon aria-hidden="true" size={PLACEHOLDER_ICON_SIZE} />
      <span className="text-[11px]">{isQueued ? "Queued" : "Empty"}</span>
    </span>
  </div>
);

const ImageGenerationTile = ({
  aspectRatio,
  image,
  index,
  onSelect,
  onVariations,
  progress,
  shouldReduceMotion,
  status,
}: TileProps) => {
  if (!image) {
    return (
      <EmptyTile
        aspectRatio={aspectRatio}
        isQueued={status === "queued" || status === "generating"}
        shouldReduceMotion={shouldReduceMotion}
      />
    );
  }

  const local = shouldReduceMotion ? 1 : progress;
  const isResolving = local < 1;
  const sharpness = local ** SHARPEN_EXPONENT;

  const mosaicOpacity = 1 - ramp(local, MOSAIC_FADE_START, MOSAIC_FADE_SPAN);
  const sharpOpacity = ramp(local, SHARP_FADE_START, SHARP_FADE_SPAN);
  const sharpBlur = MAX_SHARP_BLUR_PX * (1 - sharpness);

  const canAct = !isResolving && status === "done";

  return (
    <motion.div
      animate={{ opacity: 1, transform: "scale(1)" }}
      className="group relative isolate overflow-hidden rounded-lg border border-border bg-muted"
      initial={
        shouldReduceMotion ? false : { opacity: 0, transform: "scale(0.96)" }
      }
      style={{ aspectRatio }}
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : { ...SPRING_DEFAULT, delay: index * TILE_ENTER_STAGGER_SECONDS }
      }
    >
      {/* Blocky first pass — a low-res mosaic of the real result. */}
      <img
        alt=""
        aria-hidden="true"
        className="absolute inset-0 size-full object-cover"
        src={image.preview ?? image.src}
        style={{
          filter: `blur(${MOSAIC_BLUR_PX}px) saturate(${MOSAIC_SATURATE})`,
          imageRendering: "pixelated",
          opacity: mosaicOpacity,
          transform: `scale(${MOSAIC_SCALE})`,
        }}
      />

      {/* The result, sharpening as it crossfades over the mosaic. */}
      <img
        alt={image.alt}
        className="absolute inset-0 size-full object-cover"
        src={image.src}
        style={{
          filter: sharpBlur > 0 ? `blur(${sharpBlur}px)` : undefined,
          opacity: sharpOpacity,
          transform: `scale(${1 + FOCUS_PULL_SCALE * (1 - local)})`,
        }}
      />

      {isResolving && !shouldReduceMotion ? (
        <motion.span
          animate={{ transform: SCAN_KEYFRAMES }}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 h-[45%] mix-blend-screen"
          transition={{
            duration: SCAN_DURATION_SECONDS,
            ease: "linear",
            repeat: Number.POSITIVE_INFINITY,
          }}
        >
          {/* Gradient trail — dark at the tail, brightening toward the edge. */}
          <span className="absolute inset-0 bg-gradient-to-b from-transparent via-brand/30 to-brand/70" />
          {/* Soft leading edge: a blurred bloom that glows over the image. */}
          <span className="absolute inset-x-0 bottom-0 h-10 bg-gradient-to-b from-transparent to-white/75 blur-[7px]" />
          {/* The band itself — a crisp, clearly visible bright line. */}
          <span className="absolute inset-x-0 bottom-0 h-[2px] bg-white/95" />
        </motion.span>
      ) : null}

      <div className="pointer-events-none absolute inset-x-0 bottom-0 flex items-end justify-start p-2">
        <AnimatePresence initial={false} mode="wait">
          <motion.span
            animate={{ opacity: 1, transform: "translateY(0px)" }}
            className="rounded-full bg-black/55 px-2 py-0.5 font-mono text-[11px] text-white tabular-nums backdrop-blur-sm"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { opacity: 0, transform: "translateY(-4px)" }
            }
            initial={
              shouldReduceMotion
                ? false
                : { opacity: 0, transform: "translateY(4px)" }
            }
            key={isResolving ? "progress" : "seed"}
            transition={shouldReduceMotion ? { duration: 0 } : SPRING_SNAPPY}
          >
            {isResolving
              ? `${Math.round(local * PERCENT)}%`
              : (image.seed ?? "done")}
          </motion.span>
        </AnimatePresence>
      </div>

      {isResolving ? (
        <span
          aria-hidden="true"
          className="absolute inset-x-0 bottom-0 h-0.5 bg-black/25"
        >
          <span
            className="block h-full origin-left bg-brand"
            style={{ transform: `scaleX(${local})` }}
          />
        </span>
      ) : null}

      {canAct ? (
        <div className="absolute inset-0 flex items-start justify-end gap-1 bg-gradient-to-b from-black/45 via-transparent to-transparent p-2 opacity-0 transition-opacity duration-150 ease-out group-focus-within:opacity-100 group-hover:opacity-100 motion-reduce:transition-none">
          <a
            aria-label={`Download ${image.alt}`}
            className={TILE_ACTION_CLASS}
            download
            href={image.src}
          >
            <Download aria-hidden="true" size={ACTION_ICON_SIZE} />
          </a>
          {onVariations ? (
            <button
              aria-label={`Make variations of ${image.alt}`}
              className={TILE_ACTION_CLASS}
              onClick={() => onVariations(image)}
              type="button"
            >
              <Shuffle aria-hidden="true" size={ACTION_ICON_SIZE} />
            </button>
          ) : null}
          {onSelect ? (
            <button
              aria-label={`Select ${image.alt}`}
              className={TILE_ACTION_CLASS}
              onClick={() => onSelect(image)}
              type="button"
            >
              <Check aria-hidden="true" size={ACTION_ICON_SIZE} />
            </button>
          ) : null}
        </div>
      ) : null}
    </motion.div>
  );
};

