  maxHeight = DEFAULT_MAX_HEIGHT,
  onClose,
  onComplete,
  onMinimize,
  prompt = DEFAULT_PROMPT,
  showTrafficLights = true,
  theme = "dark",
  title = DEFAULT_TITLE,
  typingSpeed = DEFAULT_TYPING_SPEED,
}: MacTerminalProps) {
  const shouldReduceMotion = useReducedMotion();
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const machineRef = useRef<Machine>(createMachine());
  const shouldPlayRef = useRef(false);
  const linesRef = useRef(lines);
  const loopRef = useRef(loop);
  const onCompleteRef = useRef(onComplete);
  const typingSpeedRef = useRef(
    typingSpeed > 0 ? typingSpeed : DEFAULT_TYPING_SPEED
  );
  const calledOnCompleteRef = useRef(false);

  linesRef.current = lines;
  loopRef.current = loop;
  onCompleteRef.current = onComplete;
  typingSpeedRef.current = typingSpeed > 0 ? typingSpeed : DEFAULT_TYPING_SPEED;

  const [completedLines, setCompletedLines] = useState<TerminalLine[]>([]);
  const [typingDraft, setTypingDraft] = useState<TypingDraft | null>(null);
  const [hasStarted, setHasStarted] = useState(autoPlay);
  const [isInView, setIsInView] = useState(false);
  const [isPageVisible, setIsPageVisible] = useState(true);
  const [systemPrefersDark, setSystemPrefersDark] = useState(true);

  const isInteractive = !(autoPlay || hasStarted || shouldReduceMotion);
  const resolvedTheme: "dark" | "light" =
    theme === "auto" ? (systemPrefersDark ? "dark" : "light") : theme;
  const styles = THEME_STYLES[resolvedTheme];
  const resolvedMaxHeight =
    typeof maxHeight === "number" ? `${maxHeight}px` : maxHeight;
  const hasLightHandlers = Boolean(onClose || onMinimize);

  useEffect(() => {
    const node = containerRef.current;
    if (!node) {
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsInView(entry?.isIntersecting ?? false);
      },
      { threshold: INTERSECTION_THRESHOLD }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const handleVisibilityChange = () => {
      setIsPageVisible(document.visibilityState === "visible");
    };

    handleVisibilityChange();
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () =>
      document.removeEventListener("visibilitychange", handleVisibilityChange);
  }, []);

  useEffect(() => {
    if (theme !== "auto" || typeof window === "undefined") {
      return;
    }

    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    setSystemPrefersDark(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setSystemPrefersDark(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, [theme]);

  useEffect(() => {
    shouldPlayRef.current = hasStarted && isInView && isPageVisible;
  }, [hasStarted, isInView, isPageVisible]);

  useEffect(() => {
    if (!shouldReduceMotion) {
      return;
    }

    setCompletedLines(lines);
    setTypingDraft(null);

    if (!calledOnCompleteRef.current) {
      calledOnCompleteRef.current = true;
      onComplete?.();
    }
  }, [shouldReduceMotion, lines, onComplete]);

  useEffect(() => {
    if (shouldReduceMotion) {
      return;
    }

    let loopTimeout = 0;

    const tick = () => {
      if (!shouldPlayRef.current) {
        return;
      }

      const machine = machineRef.current;
      if (machine.finished) {
        return;
      }

      const currentLines = linesRef.current;
      if (machine.lineIndex >= currentLines.length) {
        machine.finished = true;
        onCompleteRef.current?.();

        if (loopRef.current) {
          loopTimeout = window.setTimeout(() => {
            machineRef.current = createMachine();
            setCompletedLines([]);
            setTypingDraft(null);
          }, LOOP_PAUSE_MS);
        }
        return;
      }

      const line = currentLines[machine.lineIndex];
      const isCommand = line.type === "command";
      const delay = line.delay ?? (isCommand ? 0 : OUTPUT_DEFAULT_DELAY_MS);

      machine.phaseElapsed += TICK_MS;

      if (machine.phase === "delay") {
        if (machine.phaseElapsed < delay) {
          return;
        }

        if (isCommand) {
          machine.phase = "typing";
          machine.phaseElapsed = 0;
          setTypingDraft({ chars: 0, line });
        } else {
          setCompletedLines((prev) => [...prev, line]);
          machine.lineIndex += 1;
          machine.phase = "delay";
          machine.phaseElapsed = 0;
        }
        return;
      }

      const msPerChar = 1000 / typingSpeedRef.current;
      const charsToShow = Math.min(
        line.text.length,
        Math.floor(machine.phaseElapsed / msPerChar)
      );
      setTypingDraft({ chars: charsToShow, line });

      if (charsToShow >= line.text.length) {
        setCompletedLines((prev) => [...prev, line]);
        setTypingDraft(null);
        machine.lineIndex += 1;
        machine.phase = "delay";
        machine.phaseElapsed = 0;
      }
    };

    const interval = window.setInterval(tick, TICK_MS);
    return () => {
      window.clearInterval(interval);
      window.clearTimeout(loopTimeout);
    };
  }, [shouldReduceMotion]);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) {
      return;
    }
    el.scrollTop = el.scrollHeight;
  }, [completedLines, typingDraft]);

  const handleActivate = useCallback(() => {
    setHasStarted(true);
  }, []);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (!isInteractive) {
        return;
      }
      if (event.key === KEY_ENTER || event.key === KEY_SPACE) {
        event.preventDefault();
        handleActivate();
      }
    },
    [handleActivate, isInteractive]
  );

  const showIdleHint =
    isInteractive && completedLines.length === 0 && !typingDraft;

  return (
    <div
      aria-label={`${title} terminal`}
      className={cn(
        "overflow-hidden rounded-xl border shadow-lg",
        styles.border,
        isInteractive &&
          "cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2",
        className
      )}
      onClick={isInteractive ? handleActivate : undefined}
      onKeyDown={isInteractive ? handleKeyDown : undefined}
      ref={containerRef}
      role={isInteractive ? "button" : "group"}
      tabIndex={isInteractive ? 0 : undefined}
    >
      <div
        className={cn(
          "flex items-center gap-3 border-b px-4 py-2.5",
          styles.chrome,
          styles.border
        )}
      >
        {showTrafficLights ? (
          <div
            aria-hidden={hasLightHandlers ? undefined : "true"}
            className="flex items-center gap-2"
          >
            {onClose ? (
              <button
                aria-label="Close terminal"
                className={cn(
                  TRAFFIC_LIGHT_CLASS,
                  "bg-[#ff5f57] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500"
                )}
                onClick={(event) => {
                  event.stopPropagation();
                  onClose();
                }}
                type="button"
              />
            ) : (
              <span
                aria-hidden="true"
                className={cn(TRAFFIC_LIGHT_CLASS, "bg-[#ff5f57]")}
              />
            )}
            {onMinimize ? (
              <button
                aria-label="Minimize terminal"
                className={cn(
                  TRAFFIC_LIGHT_CLASS,
                  "bg-[#febc2e] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500"
                )}
                onClick={(event) => {
                  event.stopPropagation();
                  onMinimize();
                }}
                type="button"
              />
            ) : (
              <span
                aria-hidden="true"
                className={cn(TRAFFIC_LIGHT_CLASS, "bg-[#febc2e]")}
              />
            )}
            <span
              aria-hidden="true"
              className={cn(TRAFFIC_LIGHT_CLASS, "bg-[#28c840]")}
            />
          </div>
        ) : null}
        <p
          className={cn(
            "flex-1 truncate text-center font-medium text-xs",
            styles.title
          )}
        >
          {title}
        </p>
        {showTrafficLights ? (
          <span aria-hidden="true" className="w-14" />
        ) : null}
      </div>

      <div
        className={cn(
          "overflow-y-auto px-4 py-3 font-mono text-xs leading-relaxed sm:text-sm",
          styles.body
        )}
        ref={scrollRef}
        style={{ maxHeight: resolvedMaxHeight }}
      >
        <pre
          aria-hidden={shouldReduceMotion ? undefined : "true"}
          className="whitespace-pre-wrap break-words font-mono"
        >
          {completedLines.map((line) => (
            <div className="flex flex-wrap gap-2" key={line.id}>
              {line.type === "command" ? (
                <>
                  <span className={styles.prompt}>{prompt}</span>
                  <span className={styles.command}>{line.text}</span>
                </>
              ) : (
                <span className={getLineToneClass(line.type, styles)}>
                  {line.text}
                </span>
              )}
            </div>
          ))}
          {typingDraft ? (
            <div className="flex flex-wrap gap-2">
              <span className={styles.prompt}>{prompt}</span>
              <span className={styles.command}>
                {typingDraft.line.text.slice(0, typingDraft.chars)}
                <span
                  aria-hidden="true"
                  className={cn(
                    "mac-terminal-caret ml-0.5 inline-block h-[1em] w-[0.55em] translate-y-[0.15em] align-middle",
                    styles.caret
                  )}
                />
              </span>
            </div>
          ) : null}
          {showIdleHint ? (
            <span className={styles.comment}>
              Click or press Enter to run this session
            </span>
          ) : null}
        </pre>
        {!shouldReduceMotion && (
          <div aria-live="off" className="sr-only">
            <pre className="whitespace-pre-wrap">
              {lines.map((line) => line.text).join("\n")}
            </pre>
          </div>
        )}
      </div>

      {!shouldReduceMotion && (
        <style>{`
          @keyframes mac-terminal-caret-blink {
            0%, 49% { opacity: 1; }
            50%, 100% { opacity: 0; }
          }
          .mac-terminal-caret {
            animation: mac-terminal-caret-blink 1s steps(1) infinite;
          }
        `}</style>
      )}
    </div>
  );
}

"use client";

import { Slot } from "@radix-ui/react-slot";
import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";
import { motion, useReducedMotion, useSpring } from "motion/react";
import type { ButtonHTMLAttributes, ReactNode } from "react";
import { useCallback, useEffect, useRef, useState } from "react";

const magneticButtonVariants = cva(
  "inline-flex cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium text-sm ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
  {
    defaultVariants: {
      size: "default",
      variant: "default",
    },
    variants: {
      size: {
        default: "h-10 px-4 py-2",
        icon: "h-10 w-10",
        lg: "h-11 rounded-md px-8",
        sm: "h-9 rounded-md px-3",
      },
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-foreground underline-offset-4 hover:underline",
        outline:
          "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
      },
    },
  }
);

export type MagneticButtonProps = {
  children: ReactNode;
  strength?: number;
  radius?: number;
  springConfig?: { duration?: number; bounce?: number };
  disabled?: boolean;
  asChild?: boolean;
  className?: string;
} & ButtonHTMLAttributes<HTMLButtonElement> &
  VariantProps<typeof magneticButtonVariants>;

const MagneticButton = ({
  children,
  strength = 0.3,
  radius = 150,
  springConfig = { bounce: 0.1, duration: 0.4 },
  disabled = false,
  asChild = false,
  variant,
  size,
  className,
  ...props
}: MagneticButtonProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);

  const x = useSpring(0, {
    bounce: springConfig.bounce ?? 0.1,
    duration: springConfig.duration ?? 0.4,
  });
  const y = useSpring(0, {
    bounce: springConfig.bounce ?? 0.1,
    duration: springConfig.duration ?? 0.4,
  });

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mediaQuery.matches);

    const handleChange = (e: MediaQueryListEvent) => {
      setIsHoverDevice(e.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const isEffectDisabled = disabled || shouldReduceMotion || !isHoverDevice;

  const handleMouseMove = useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      if (isEffectDisabled || !buttonRef.current) {
        return;
      }

      const rect = buttonRef.current.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;

      const distanceX = event.clientX - centerX;
      const distanceY = event.clientY - centerY;
      const distance = Math.sqrt(distanceX * distanceX + distanceY * distanceY);

      if (distance < radius) {
        const factor = 1 - distance / radius;
        const moveX = distanceX * strength * factor;
        const moveY = distanceY * strength * factor;
        x.set(moveX);
        y.set(moveY);
      } else {
        x.set(0);
        y.set(0);
      }
    },
    [isEffectDisabled, radius, strength, x, y]
  );

  const handleMouseLeave = useCallback(() => {
    x.set(0);
    y.set(0);
  }, [x, y]);

  const Comp = asChild ? Slot : "button";

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: Mouse events are for visual effect, not interaction
    <div
      className="inline-block"
      onMouseLeave={handleMouseLeave}
      onMouseMove={handleMouseMove}
      ref={wrapperRef}
      role="presentation"
      style={{
        margin: `-${radius / 2}px`,
        padding: `${radius / 2}px`,
      }}
    >
      <motion.div style={{ x, y }}>
        <Comp
          className={cn(magneticButtonVariants({ className, size, variant }))}
          disabled={disabled}
          ref={buttonRef}
          type="button"
          {...props}
        >
          {children}
        </Comp>
      </motion.div>
    </div>
  );
};

export default MagneticButton;

"use client";

import { cn } from "@/lib/utils";
import {
  type MotionValue,
  motion,
  motionValue,
  useReducedMotion,
} from "motion/react";
import type { ReactElement, ReactNode } from "react";
import { useEffect, useRef, useState } from "react";

export type MagneticFieldMode = "attract" | "repel" | "orbit";

export type MagneticFieldItem = {
  element: ReactElement;
  id: string;
};

export type MagneticFieldProps = {
  children?: ReactNode;
  className?: string;
  damping?: number;
  items?: MagneticFieldItem[];
  mode?: MagneticFieldMode;
  paused?: boolean;
  radius?: number;
  rotate?: boolean;
  stiffness?: number;
  strength?: number;
};

type ParticipantState = {
  centerX: number;
  centerY: number;
  rotate: MotionValue<number>;
  vr: number;
  vx: number;
  vy: number;
  x: MotionValue<number>;
  y: MotionValue<number>;
};

const DEFAULT_RADIUS = 160;
const DEFAULT_STRENGTH = 0.35;
const DEFAULT_STIFFNESS = 180;
const DEFAULT_DAMPING = 18;
const MAX_ROTATE_DEG = 18;
const FALLOFF_POWER = 2;
const MAX_DELTA_SECONDS = 0.05;
const ORBIT_RADIAL_FACTOR = 0.2;
const ORBIT_TANGENTIAL_FACTOR = 0.4;
const MAGNETIC_SELECTOR = "[data-magnetic]";

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const computeFalloff = (distance: number, radius: number) => {
  if (distance >= radius) {
    return 0;
  }
  return (1 - distance / radius) ** FALLOFF_POWER;
};

const computeOffset = (
  dx: number,
  dy: number,
  distance: number,
  falloff: number,
  strength: number,
  mode: MagneticFieldMode
): { x: number; y: number } => {
  if (distance === 0) {
    return { x: 0, y: 0 };
  }
  const directional = mode === "repel" ? -Math.abs(strength) : strength;
  if (mode === "orbit") {
    const tangentX = -dy / distance;
    const tangentY = dx / distance;
    const pull = directional * falloff * distance * ORBIT_TANGENTIAL_FACTOR;
    return {
      x: dx * directional * falloff * ORBIT_RADIAL_FACTOR + tangentX * pull,
      y: dy * directional * falloff * ORBIT_RADIAL_FACTOR + tangentY * pull,
    };
  }
  return { x: dx * directional * falloff, y: dy * directional * falloff };
};

const createParticipant = (): ParticipantState => ({
  centerX: 0,
  centerY: 0,
  rotate: motionValue(0),
  vr: 0,
  vx: 0,
  vy: 0,
  x: motionValue(0),
  y: motionValue(0),
});

const resetParticipant = (state: ParticipantState) => {
  state.x.set(0);
  state.y.set(0);
  state.rotate.set(0);
  state.vx = 0;
  state.vy = 0;
  state.vr = 0;
};

const MagneticField = ({
  children,
  className,
  damping = DEFAULT_DAMPING,
  items,
  mode = "attract",
  paused = false,
  radius = DEFAULT_RADIUS,
  rotate = false,
  stiffness = DEFAULT_STIFFNESS,
  strength = DEFAULT_STRENGTH,
}: MagneticFieldProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isPointerCapable, setIsPointerCapable] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const pointerRef = useRef<{ x: number; y: number } | null>(null);
  const participantsRef = useRef<Map<string, ParticipantState>>(new Map());
  const nodeMapRef = useRef<Map<string, HTMLElement>>(new Map());
  const elementsRef = useRef<Map<HTMLElement, ParticipantState>>(new Map());
  const rafRef = useRef<number | null>(null);
  const lastFrameRef = useRef<number | null>(null);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsPointerCapable(mediaQuery.matches);
    const handleChange = (event: MediaQueryListEvent) => {
      setIsPointerCapable(event.matches);
    };
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const isEffectDisabled = paused || shouldReduceMotion || !isPointerCapable;

  const getOrCreateParticipant = (id: string): ParticipantState => {
    let state = participantsRef.current.get(id);
    if (!state) {
      state = createParticipant();
      participantsRef.current.set(id, state);
    }
    return state;
  };

  // Prune stale participants when the `items` list changes shape.
  useEffect(() => {
    if (!items) {
      participantsRef.current.clear();
      nodeMapRef.current.clear();
      return;
    }
    const ids = new Set(items.map((item) => item.id));
    for (const key of Array.from(participantsRef.current.keys())) {
      if (!ids.has(key)) {
        participantsRef.current.delete(key);
        nodeMapRef.current.delete(key);
      }
    }
  }, [items]);

  // Measure rest positions for `items` participants once per layout change.
  useEffect(() => {
    if (!items) {
      return;
    }
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const measure = () => {
      const containerRect = container.getBoundingClientRect();
      for (const [id, node] of nodeMapRef.current) {
        const state = participantsRef.current.get(id);
        if (!state) {
          continue;
        }
        const rect = node.getBoundingClientRect();
        state.centerX = rect.left + rect.width / 2 - containerRect.left;
        state.centerY = rect.top + rect.height / 2 - containerRect.top;
      }
    };

    measure();
    const resizeObserver = new ResizeObserver(measure);
    for (const node of nodeMapRef.current.values()) {
      resizeObserver.observe(node);
    }
    window.addEventListener("resize", measure);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [items]);

  // Discover and measure `data-magnetic` descendants of `children`.
  useEffect(() => {
    if (items) {
      return;
    }
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const syncElements = () => {
      const found = Array.from(
        container.querySelectorAll<HTMLElement>(MAGNETIC_SELECTOR)
      );
      const map = elementsRef.current;
      for (const el of Array.from(map.keys())) {
        if (!found.includes(el)) {
          el.style.transform = "";
          el.style.willChange = "";
          map.delete(el);
        }
      }
      const containerRect = container.getBoundingClientRect();
      for (const el of found) {
        if (!map.has(el)) {
          el.style.willChange = "transform";
          map.set(el, createParticipant());
        }
        const state = map.get(el);
        if (!state) {
          continue;
        }
        const rect = el.getBoundingClientRect();
        state.centerX = rect.left + rect.width / 2 - containerRect.left;
        state.centerY = rect.top + rect.height / 2 - containerRect.top;
      }
    };

    syncElements();
    const mutationObserver = new MutationObserver(syncElements);
    mutationObserver.observe(container, { childList: true, subtree: true });
    const resizeObserver = new ResizeObserver(syncElements);
    resizeObserver.observe(container);
    window.addEventListener("resize", syncElements);

    return () => {
      mutationObserver.disconnect();
      resizeObserver.disconnect();
      window.removeEventListener("resize", syncElements);
      for (const el of elementsRef.current.keys()) {
        el.style.transform = "";
        el.style.willChange = "";
      }
    };
  }, [items]);

  // Track the pointer position relative to the container with one listener.
  useEffect(() => {
    if (isEffectDisabled) {
      pointerRef.current = null;
      return;
    }
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const handlePointerMove = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      pointerRef.current = {
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
      };
    };
    const handlePointerLeave = () => {
      pointerRef.current = null;
    };

    container.addEventListener("pointermove", handlePointerMove, {
      passive: true,
    });
    container.addEventListener("pointerleave", handlePointerLeave, {
      passive: true,
    });

    return () => {
      container.removeEventListener("pointermove", handlePointerMove);
      container.removeEventListener("pointerleave", handlePointerLeave);
    };
  }, [isEffectDisabled]);

  // Single rAF loop driving a manual spring integrator per participant.
  useEffect(() => {
    if (isEffectDisabled) {
      for (const state of participantsRef.current.values()) {
        resetParticipant(state);
      }
      for (const [el, state] of elementsRef.current) {
        resetParticipant(state);
        el.style.transform = "translate3d(0px, 0px, 0) rotate(0deg)";
      }
      return;
    }

    const applyPhysics = (state: ParticipantState, dt: number) => {
      const pointer = pointerRef.current;
      let targetX = 0;
      let targetY = 0;
      let targetRotate = 0;

      if (pointer) {
        const dx = pointer.x - state.centerX;
        const dy = pointer.y - state.centerY;
        const distance = Math.hypot(dx, dy);
        const falloff = computeFalloff(distance, radius);
        if (falloff > 0) {
          const offset = computeOffset(
            dx,
            dy,
            distance,
            falloff,
            strength,
            mode
          );
          targetX = offset.x;
          targetY = offset.y;
          if (rotate) {
            targetRotate = clamp(
              ((Math.atan2(dy, dx) * 180) / Math.PI) * falloff,
              -MAX_ROTATE_DEG,
              MAX_ROTATE_DEG
            );
          }
        }
      }

      const currentX = state.x.get();
      const currentY = state.y.get();
      const currentRotate = state.rotate.get();

      state.vx += ((targetX - currentX) * stiffness - state.vx * damping) * dt;
      state.vy += ((targetY - currentY) * stiffness - state.vy * damping) * dt;
      state.vr +=
        ((targetRotate - currentRotate) * stiffness - state.vr * damping) * dt;

      state.x.set(currentX + state.vx * dt);
      state.y.set(currentY + state.vy * dt);
      state.rotate.set(currentRotate + state.vr * dt);
    };

    const step = (time: number) => {
      const last = lastFrameRef.current ?? time;
      const dt = clamp((time - last) / 1000, 0, MAX_DELTA_SECONDS);
      lastFrameRef.current = time;

      for (const state of participantsRef.current.values()) {
        applyPhysics(state, dt);
      }
      for (const [el, state] of elementsRef.current) {
        applyPhysics(state, dt);
        const x = state.x.get();
        const y = state.y.get();
        const r = state.rotate.get();
        el.style.transform = `translate3d(${x}px, ${y}px, 0) rotate(${r}deg)`;
      }

      rafRef.current = requestAnimationFrame(step);
    };

    rafRef.current = requestAnimationFrame(step);

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
      lastFrameRef.current = null;
    };
  }, [damping, isEffectDisabled, mode, radius, rotate, stiffness, strength]);

  const content = items
    ? items.map((item) => {
        const state = getOrCreateParticipant(item.id);
        return (
          <motion.div
            className="inline-block will-change-transform"
            key={item.id}
            ref={(node: HTMLDivElement | null) => {
              if (node) {
                nodeMapRef.current.set(item.id, node);
              } else {
                nodeMapRef.current.delete(item.id);
              }
            }}
            style={{ rotate: state.rotate, x: state.x, y: state.y }}
          >
            {item.element}
          </motion.div>
        );
      })
    : children;

  return (
    <div className={cn("relative", className)} ref={containerRef}>
      {content}
    </div>
  );
};

