  size?: number;
  /** Animation speed multiplier. `2` runs twice as fast. */
  speed?: number;
  variant?: MotionLoaderVariant;
}

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const DEFAULT_SIZE = 40;
const DEFAULT_SPEED = 1;
const DEFAULT_LABEL = "Loading";
const DEFAULT_VARIANT: MotionLoaderVariant = "orbit";

const LINEAR: [number, number, number, number] = [0, 0, 1, 1];
const EASE_IN_OUT: [number, number, number, number] = [0.645, 0.045, 0.355, 1];
const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];

const CYCLE = 1.1;
const SLOW_CYCLE = 1.4;
const FULL_TURN = 360;
const HALF_TURN = 180;

const DOT_RATIO = 0.2;
const SMALL_DOT_RATIO = 0.14;
const TRACK_OPACITY = 0.2;
const TRAIL_LENGTH = 4;
const TRAIL_STEP_DEG = 16;
const CRADLE_BALLS = 5;
const CRADLE_SWING_DEG = 34;
const PENDULUM_SWING_DEG = 32;
const WAVE_BARS = 5;
const WAVE_MIN_SCALE = 0.3;
const WAVE_STAGGER = 0.1;
const RING_DOTS = 8;
const RING_DOT_FADE = 0.15;
const RING_STAGGER = 0.09;
const SNAKE_CELL_RATIO = 0.38;
const SNAKE_CORNERS = 4;
const GLOW_SCALE = 1.25;
const GLOW_MIN_OPACITY = 0.45;
const HALF = 0.5;

const loop = (duration: number, ease: [number, number, number, number]) => ({
  duration,
  ease,
  repeat: Number.POSITIVE_INFINITY,
  repeatType: "loop" as const,
});

const delayedLoop = (
  duration: number,
  ease: [number, number, number, number],
  delay: number
) => ({ ...loop(duration, ease), delay });

interface LoaderVariantProps {
  reduce: boolean;
  size: number;
  speed: number;
}

const dotStyle = (diameter: number): CSSProperties => ({
  height: `${diameter}px`,
  width: `${diameter}px`,
});

/** Stable React keys for the fixed-length element lists of each variant. */
const idList = (prefix: string, count: number): string[] =>
  Array.from({ length: count }, (_, index) => `${prefix}-${index}`);

const CRADLE_IDS = idList("cradle", CRADLE_BALLS);
const SNAKE_IDS = idList("snake", SNAKE_CORNERS);
const COMET_IDS = idList("comet", TRAIL_LENGTH);
const WAVE_IDS = idList("wave", WAVE_BARS);
const RING_IDS = idList("ring", RING_DOTS);

/* -------------------------------------------------------------------------- */
/* Variants                                                                   */
/* -------------------------------------------------------------------------- */

const OrbitLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const dot = size * DOT_RATIO;
  return (
    <>
      <span
        className="absolute inset-0 rounded-full border border-current"
        style={{ opacity: TRACK_OPACITY }}
      />
      <motion.span
        animate={reduce ? undefined : { rotate: FULL_TURN }}
        className="absolute inset-0"
        transition={reduce ? undefined : loop(CYCLE / speed, LINEAR)}
      >
        <span
          className="absolute top-0 left-1/2 rounded-full bg-current"
          style={{
            ...dotStyle(dot),
            marginLeft: -dot * HALF,
            marginTop: -dot * HALF,
          }}
        />
      </motion.span>
    </>
  );
};

const CRADLE_TIMES = [0, 0.25, 0.5, 0.75, 1];

const cradleKeyframes = (index: number): number[] | undefined => {
  if (index === 0) {
    return [0, -CRADLE_SWING_DEG, 0, 0, 0];
  }
  if (index === CRADLE_BALLS - 1) {
    return [0, 0, 0, CRADLE_SWING_DEG, 0];
  }
};

const NewtonCradleLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const ball = size / CRADLE_BALLS;
  return (
    <span className="absolute inset-0 flex items-start justify-center">
      {CRADLE_IDS.map((id, index) => {
        const keyframes = cradleKeyframes(index);
        return (
          <motion.span
            animate={reduce || !keyframes ? undefined : { rotate: keyframes }}
            className="relative block"
            key={id}
            style={{
              height: `${size}px`,
              transformOrigin: "top center",
              width: `${ball}px`,
            }}
            transition={
              reduce || !keyframes
                ? undefined
                : {
                    ...loop(SLOW_CYCLE / speed, EASE_IN_OUT),
                    times: CRADLE_TIMES,
                  }
            }
          >
            <span
              className="absolute top-0 bottom-0 left-1/2 w-px bg-current"
              style={{ opacity: TRACK_OPACITY }}
            />
            <span
              className="absolute bottom-0 left-1/2 rounded-full bg-current"
              style={{ ...dotStyle(ball), marginLeft: -ball * HALF }}
            />
          </motion.span>
        );
      })}
    </span>
  );
};

const PendulumLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const bob = size * DOT_RATIO * 1.5;
  return (
    <motion.span
      animate={
        reduce
          ? undefined
          : {
              rotate: [
                -PENDULUM_SWING_DEG,
                PENDULUM_SWING_DEG,
                -PENDULUM_SWING_DEG,
              ],
            }
      }
      className="absolute inset-0"
      style={{ transformOrigin: "top center" }}
      transition={reduce ? undefined : loop(SLOW_CYCLE / speed, EASE_IN_OUT)}
    >
      <span
        className="absolute top-0 bottom-2 left-1/2 w-px bg-current"
        style={{ opacity: TRACK_OPACITY }}
      />
      <span
        className="absolute bottom-0 left-1/2 rounded-full bg-current"
        style={{ ...dotStyle(bob), marginLeft: -bob * HALF }}
      />
    </motion.span>
  );
};

const HourglassLoader = ({ reduce, size, speed }: LoaderVariantProps) => (
  <motion.svg
    animate={
      reduce ? undefined : { rotate: [0, 0, HALF_TURN, HALF_TURN, FULL_TURN] }
    }
    className="absolute inset-0 fill-current"
    height={size}
    transition={
      reduce
        ? undefined
        : {
            ...loop(SLOW_CYCLE / speed, EASE_IN_OUT),
            times: [0, 0.3, 0.5, 0.8, 1],
          }
    }
    viewBox="0 0 24 24"
    width={size}
  >
    <path d="M5 2h14v2l-6 8 6 8v2H5v-2l6-8-6-8V2z" opacity={TRACK_OPACITY} />
    <path d="M7 4h10l-5 6.5L7 4zm0 16h10l-5-6.5L7 20z" />
  </motion.svg>
);

const MorphRingLoader = ({ reduce, size, speed }: LoaderVariantProps) => (
  <motion.svg
    animate={reduce ? undefined : { scale: [1, 0.88, 1] }}
    className="absolute inset-0 stroke-current"
    fill="none"
    height={size}
    transition={reduce ? undefined : loop(CYCLE / speed, EASE_IN_OUT)}
    viewBox="0 0 48 48"
    width={size}
  >
    <motion.circle
      animate={reduce ? undefined : { rotate: FULL_TURN }}
      cx="24"
      cy="24"
      r="20"
      strokeDasharray="62 64"
      strokeLinecap="round"
      strokeWidth="4"
      style={{ transformOrigin: "center" }}
      transition={reduce ? undefined : loop(CYCLE / speed, LINEAR)}
    />
    <motion.circle
      animate={reduce ? undefined : { rotate: -FULL_TURN }}
      cx="24"
      cy="24"
      opacity={0.45}
      r="11"
      strokeDasharray="24 45"
      strokeLinecap="round"
      strokeWidth="4"
      style={{ transformOrigin: "center" }}
      transition={reduce ? undefined : loop((CYCLE * 1.5) / speed, LINEAR)}
    />
  </motion.svg>
);

const SquareSnakeLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const cell = size * SNAKE_CELL_RATIO;
  const travel = size - cell;
  const positions: CSSProperties[] = [
    { left: 0, top: 0 },
    { left: travel, top: 0 },
    { left: travel, top: travel },
    { left: 0, top: travel },
  ];
  return (
    <>
      {SNAKE_IDS.map((id, index) => (
        <span
          className="absolute rounded-sm bg-current"
          key={id}
          style={{
            ...positions[index],
            ...dotStyle(cell),
            opacity: TRACK_OPACITY,
          }}
        />
      ))}
      <motion.span
        animate={
          reduce
            ? undefined
            : { x: [0, travel, travel, 0, 0], y: [0, 0, travel, travel, 0] }
        }
        className="absolute top-0 left-0 rounded-sm bg-current"
        style={dotStyle(cell)}
        transition={
          reduce
            ? undefined
            : {
                ...loop(SLOW_CYCLE / speed, EASE_IN_OUT),
                times: [0, 0.25, 0.5, 0.75, 1],
              }
        }
      />
    </>
  );
};

const CometLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const dot = size * SMALL_DOT_RATIO;
  return (
    <motion.span
      animate={reduce ? undefined : { rotate: FULL_TURN }}
      className="absolute inset-0"
      transition={reduce ? undefined : loop(CYCLE / speed, LINEAR)}
    >
      {COMET_IDS.map((id, index) => (
        <span
          className="absolute inset-0"
          key={id}
          style={{ transform: `rotate(${-index * TRAIL_STEP_DEG}deg)` }}
        >
          <span
            className="absolute top-0 left-1/2 rounded-full bg-current"
            style={{
              ...dotStyle(dot * (1 - index / (TRAIL_LENGTH * 2))),
              marginLeft: -dot * HALF,
              opacity: 1 - index / TRAIL_LENGTH,
            }}
          />
        </span>
      ))}
    </motion.span>
  );
};

const RadarLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const dot = size * SMALL_DOT_RATIO;
  return (
    <>
      <span
        className="absolute inset-0 rounded-full border border-current"
        style={{ opacity: TRACK_OPACITY }}
      />
      <span className="absolute inset-0 overflow-hidden rounded-full">
        <motion.span
          animate={reduce ? undefined : { rotate: FULL_TURN }}
          className="absolute inset-0"
          style={{
            background:
              "conic-gradient(from 0deg, transparent 0deg, transparent 260deg, currentColor 360deg)",
          }}
          transition={reduce ? undefined : loop(CYCLE / speed, LINEAR)}
        />
      </span>
      <span
        className="absolute top-1/2 left-1/2 rounded-full bg-current"
        style={{
          ...dotStyle(dot),
          marginLeft: -dot * HALF,
          marginTop: -dot * HALF,
        }}
      />
    </>
  );
};

const CubeFlipLoader = ({ reduce, size, speed }: LoaderVariantProps) => (
  <span className="absolute inset-0" style={{ perspective: `${size * 3}px` }}>
    <motion.span
      animate={
        reduce
          ? undefined
          : {
              rotateX: [0, HALF_TURN, HALF_TURN, FULL_TURN],
              rotateY: [0, 0, HALF_TURN, HALF_TURN],
            }
      }
      className="absolute inset-0 rounded-md bg-current"
      transition={
        reduce
          ? undefined
          : {
              ...loop((SLOW_CYCLE * 1.5) / speed, EASE_IN_OUT),
              times: [0, 0.33, 0.66, 1],
            }
      }
    />
  </span>
);

const WaveBarsLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const barWidth = size / (WAVE_BARS * 2);
  return (
    <span
      className="absolute inset-0 flex items-center justify-between"
      style={{ gap: `${barWidth * HALF}px` }}
    >
      {WAVE_IDS.map((id, index) => (
        <motion.span
          animate={
            reduce ? undefined : { scaleY: [WAVE_MIN_SCALE, 1, WAVE_MIN_SCALE] }
          }
          className="flex-1 rounded-full bg-current"
          key={id}
          style={{
            height: `${size}px`,
            scaleY: reduce ? WAVE_MIN_SCALE + index * WAVE_STAGGER : undefined,
          }}
          transition={
            reduce
              ? undefined
              : delayedLoop(CYCLE / speed, EASE_IN_OUT, index * WAVE_STAGGER)
          }
        />
      ))}
    </span>
  );
};

const BreathingGlowLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const core = size * HALF;
  return (
    <>
      <motion.span
        animate={
          reduce
            ? undefined
            : {
                opacity: [GLOW_MIN_OPACITY, 0, GLOW_MIN_OPACITY],
                scale: [1, GLOW_SCALE, 1],
              }
        }
        className="absolute inset-0 rounded-full bg-current blur-md"
        style={{ opacity: GLOW_MIN_OPACITY }}
        transition={reduce ? undefined : loop(SLOW_CYCLE / speed, EASE_IN_OUT)}
      />
      <motion.span
        animate={reduce ? undefined : { scale: [1, GLOW_SCALE, 1] }}
        className="rounded-full bg-current"
        style={dotStyle(core)}
        transition={reduce ? undefined : loop(SLOW_CYCLE / speed, EASE_OUT)}
      />
    </>
  );
};

const DotRingLoader = ({ reduce, size, speed }: LoaderVariantProps) => {
  const dot = size * SMALL_DOT_RATIO;
  const radius = size * HALF - dot * HALF;
  return (
    <>
      {RING_IDS.map((id, index) => (
        <motion.span
          animate={reduce ? undefined : { opacity: [1, RING_DOT_FADE] }}
          className="absolute top-1/2 left-1/2 rounded-full bg-current"
          key={id}
          style={{
            ...dotStyle(dot),
            marginLeft: -dot * HALF,
            marginTop: -dot * HALF,
            opacity: reduce ? 1 - index * RING_DOT_FADE * HALF : undefined,
            transform: `rotate(${(index * FULL_TURN) / RING_DOTS}deg) translateY(${-radius}px)`,
          }}
          transition={
            reduce
              ? undefined
              : delayedLoop(CYCLE / speed, LINEAR, index * RING_STAGGER)
          }
        />
      ))}
    </>
  );
};

const VARIANT_RENDERERS: Record<
  MotionLoaderVariant,
  (props: LoaderVariantProps) => ReactElement
> = {
  "breathing-glow": BreathingGlowLoader,
  comet: CometLoader,
  "cube-flip": CubeFlipLoader,
  "dot-ring": DotRingLoader,
  hourglass: HourglassLoader,
  "morph-ring": MorphRingLoader,
  "newton-cradle": NewtonCradleLoader,
  orbit: OrbitLoader,
  pendulum: PendulumLoader,
  radar: RadarLoader,
  "square-snake": SquareSnakeLoader,
  "wave-bars": WaveBarsLoader,
};

/* -------------------------------------------------------------------------- */
/* Component                                                                  */
/* -------------------------------------------------------------------------- */

const MotionLoader = ({
  className,
  color,
  label = DEFAULT_LABEL,
  size = DEFAULT_SIZE,
  speed = DEFAULT_SPEED,
  variant = DEFAULT_VARIANT,
}: MotionLoaderProps) => {
  const shouldReduceMotion = useReducedMotion();
  const Renderer = VARIANT_RENDERERS[variant] ?? VARIANT_RENDERERS.orbit;
  const safeSpeed = speed > 0 ? speed : DEFAULT_SPEED;

  return (
    <span
      aria-label={label}
      aria-live="polite"
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center",
        className
      )}
      role="status"
      style={{
        color: color ?? "currentColor",
        height: `${size}px`,
        width: `${size}px`,
      }}
    >
      <Renderer
        reduce={Boolean(shouldReduceMotion)}
        size={size}
        speed={safeSpeed}
      />
      <span className="sr-only">{label}</span>
    </span>
  );
};

export default MotionLoader;

"use client";

import { cn } from "@/lib/utils";
import { Pause, Play } from "lucide-react";
import {
  AnimatePresence,
  motion,
  useAnimationFrame,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import {
  type KeyboardEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

const DEFAULT_SIZE = 96;
const DEFAULT_BARS = 24;
const RING_RADIUS = 46;
const RING_VIEWBOX = 100;
const RING_STROKE_WIDTH = 4;
const ROTATION_DEG_PER_MS = 360 / 15_000;
const SEEK_STEP = 0.05;
const BAR_MIN_SCALE = 0.2;
const BAR_MAX_SCALE = 1;
const BAR_BASE_DURATION = 0.6;
const BAR_DURATION_JITTER = 0.5;
const HASH_MULTIPLIER = 12.9898;
const HASH_SCALE = 43_758.5453;
const SPRING = { bounce: 0.1, duration: 0.25, type: "spring" as const };
const MOVEMENT_EASE: [number, number, number, number] = [
  0.645, 0.045, 0.355, 1,
];

export type MusicToggleProps = {
  /** Number of waveform bars rendered next to the track info */
  bars?: number;
  /** Additional CSS classes */
  className?: string;
  /** Cover art image url shown inside the spinning record */
  cover?: string;
  /** Default playing state for uncontrolled usage */
  defaultPlaying?: boolean;
  /** Called when the seek slider is used to change progress */
  onSeek?: (progress: number) => void;
  /** Called whenever the playing state changes */
  onPlayingChange?: (playing: boolean) => void;
  /** Controlled playing state */
  playing?: boolean;
  /** Current playback progress, from 0 to 1 */
  progress?: number;
  /** Diameter of the record, in pixels */
  size?: number;
  /**
   * Audio source. When provided the component owns an `<audio>` element and
   * plays/pauses it. When omitted the component is purely visual and the
   * caller drives `playing` externally.
   */
  src?: string;
  /** Track artist, shown under the title */
  artist?: string;
  /** Track title, shown above the artist and read by assistive tech */
  title?: string;
};

const hashUnit = (seed: number) => {
  const x = Math.sin(seed * HASH_MULTIPLIER) * HASH_SCALE;
  return x - Math.floor(x);
};

const clampUnit = (value: number) => Math.min(1, Math.max(0, value));

const MusicToggle = ({
  playing: controlledPlaying,
  defaultPlaying = false,
  onPlayingChange,
  src,
  cover,
  title,
  artist,
  bars = DEFAULT_BARS,
  progress = 0,
  onSeek,
  size = DEFAULT_SIZE,
  className,
}: MusicToggleProps) => {
  const shouldReduceMotion = !!useReducedMotion();
  const audioRef = useRef<HTMLAudioElement>(null);
  const mountedRef = useRef(false);
  const rotation = useMotionValue(0);

  const [internalPlaying, setInternalPlaying] = useState(defaultPlaying);
  const isControlled = controlledPlaying !== undefined;
  const playing = isControlled ? controlledPlaying : internalPlaying;

  const handleToggle = useCallback(() => {
    const next = !playing;
    if (!isControlled) {
      setInternalPlaying(next);
    }
    onPlayingChange?.(next);
  }, [playing, isControlled, onPlayingChange]);

  useAnimationFrame((_, delta) => {
    if (!playing || shouldReduceMotion) {
      return;
    }
    rotation.set(rotation.get() + delta * ROTATION_DEG_PER_MS);
  });

  useEffect(() => {
    if (!mountedRef.current) {
      mountedRef.current = true;
      return;
    }
    const audio = audioRef.current;
    if (!audio) {
      return;
    }
    if (playing) {
      audio.play().catch(() => {
        // Playback was blocked or interrupted; visual state stays in sync.
      });
    } else {
      audio.pause();
    }
  }, [playing]);

  const handleSeekKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!onSeek) {
      return;
    }
    switch (event.key) {
      case "ArrowRight":
      case "ArrowUp":
        event.preventDefault();
        onSeek(clampUnit(progress + SEEK_STEP));
        break;
      case "ArrowLeft":
      case "ArrowDown":
        event.preventDefault();
        onSeek(clampUnit(progress - SEEK_STEP));
        break;
      case "Home":
        event.preventDefault();
        onSeek(0);
        break;
      case "End":
        event.preventDefault();
        onSeek(1);
        break;
      default:
        break;
    }
  };

  const circumference = 2 * Math.PI * RING_RADIUS;
  const label = [title, artist].filter(Boolean).join(" — ");
  const toggleLabel = `${playing ? "Pause" : "Play"}${label ? ` ${label}` : ""}`;

  return (
    <div className={cn("inline-flex items-center gap-3", className)}>
      <div className="relative shrink-0" style={{ height: size, width: size }}>
        <div
          aria-label={label ? `Seek ${label}` : "Seek track"}
          aria-valuemax={100}
          aria-valuemin={0}
          aria-valuenow={Math.round(progress * 100)}
          className="pointer-events-none absolute inset-0 rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          onKeyDown={handleSeekKeyDown}
          role="slider"
          tabIndex={onSeek ? 0 : -1}
        >
          <svg
            className="h-full w-full -rotate-90"
            viewBox={`0 0 ${RING_VIEWBOX} ${RING_VIEWBOX}`}
          >
            <circle
              className="text-foreground/10"
              cx="50"
              cy="50"
              fill="none"
              r={RING_RADIUS}
              stroke="currentColor"
              strokeWidth={RING_STROKE_WIDTH}
            />
            <motion.circle
              animate={{
                strokeDashoffset: circumference * (1 - progress),
              }}
              className="text-brand"
              cx="50"
              cy="50"
              fill="none"
              r={RING_RADIUS}
              stroke="currentColor"
              strokeDasharray={circumference}
              strokeLinecap="round"
              strokeWidth={RING_STROKE_WIDTH}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : { duration: 0.25, ease: MOVEMENT_EASE }
              }
            />
          </svg>
        </div>

        <motion.div
          aria-hidden="true"
          className="absolute inset-[10%] overflow-hidden rounded-full border border-border bg-muted"
          style={{ rotate: rotation }}
        >
          {cover ? (
            <img alt="" className="h-full w-full object-cover" src={cover} />
          ) : (
            <div className="h-full w-full bg-gradient-to-br from-brand/40 to-brand/10" />
          )}
          <div className="absolute inset-[38%] rounded-full bg-background" />
        </motion.div>

        <button
          aria-label={toggleLabel}
          aria-pressed={playing}
          className="absolute inset-[38%] z-10 flex items-center justify-center rounded-full bg-background text-foreground shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          onClick={handleToggle}
          type="button"
        >
          <AnimatePresence initial={false} mode="wait">
            {playing ? (
              <motion.span
                animate={
                  shouldReduceMotion
                    ? { opacity: 1 }
                    : { opacity: 1, rotate: 0, scale: 1 }
                }
                exit={
                  shouldReduceMotion
                    ? { opacity: 0, transition: { duration: 0 } }
                    : { opacity: 0, rotate: -45, scale: 0.6 }
                }
                initial={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { opacity: 0, rotate: 45, scale: 0.6 }
                }
                key="pause"
                transition={shouldReduceMotion ? { duration: 0 } : SPRING}
              >
                <Pause className="size-4 fill-current" />
              </motion.span>
            ) : (
              <motion.span
                animate={
                  shouldReduceMotion
                    ? { opacity: 1 }
                    : { opacity: 1, rotate: 0, scale: 1 }
                }
                exit={
                  shouldReduceMotion
                    ? { opacity: 0, transition: { duration: 0 } }
                    : { opacity: 0, rotate: 45, scale: 0.6 }
                }
                initial={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { opacity: 0, rotate: -45, scale: 0.6 }
                }
                key="play"
                transition={shouldReduceMotion ? { duration: 0 } : SPRING}
              >
                <Play className="size-4 fill-current" />
              </motion.span>
            )}
          </AnimatePresence>
        </button>
      </div>

      <div className="flex flex-col gap-1.5">
        {title || artist ? (
          <div className="flex flex-col">
            {title ? (
              <span className="font-medium text-foreground text-sm">
                {title}
              </span>
            ) : null}
            {artist ? (
              <span className="text-muted-foreground text-xs">{artist}</span>
            ) : null}
          </div>
        ) : null}
        <div aria-hidden="true" className="flex h-5 items-end gap-[2px]">
          {Array.from({ length: bars }).map((_, index) => {
            const heightSeed = hashUnit(index);
            const durationSeed = hashUnit(index + 0.5);
            const delaySeed = hashUnit(index + 0.25);
            const minScale = BAR_MIN_SCALE + heightSeed * 0.15;
            const maxScale = BAR_MAX_SCALE - (1 - heightSeed) * 0.3;
            const duration =
              BAR_BASE_DURATION + durationSeed * BAR_DURATION_JITTER;
            const delay = delaySeed * duration;
            const animate =
              playing && !shouldReduceMotion
                ? { scaleY: [minScale, maxScale, minScale] }
                : { scaleY: minScale };
            const transition =
              playing && !shouldReduceMotion
                ? {
                    delay,
                    duration,
                    ease: MOVEMENT_EASE,
                    repeat: Number.POSITIVE_INFINITY,
                    repeatType: "mirror" as const,
                  }
                : { duration: 0 };
            return (
              <motion.span
                animate={animate}
                className="w-[2px] rounded-full bg-foreground/70"
                // biome-ignore lint/suspicious/noArrayIndexKey: fixed-count, order-stable waveform bars
                key={index}
                style={{ height: "100%", transformOrigin: "bottom" }}
                transition={transition}
              />
            );
          })}
        </div>
      </div>

      {src ? (
        <audio ref={audioRef} src={src}>
          <track kind="captions" />
        </audio>
      ) : null}
    </div>
  );
};

export default MusicToggle;

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { useEffect, useRef, useState } from "react";

export interface NotificationBadgeProps {
  children?: ReactNode;
  className?: string;
  count?: number;
  max?: number;
  ping?: boolean;
  position?: "top-right" | "top-left" | "bottom-right" | "bottom-left";
  showZero?: boolean;
  status?: "online" | "offline" | "busy" | "away";
  variant?: "dot" | "count" | "status";
}

const statusColors = {
  away: "bg-amber-500",
  busy: "bg-red-500",
  offline: "bg-gray-400",
  online: "bg-emerald-500",
};

const positionClasses = {
  "bottom-left": "-bottom-1 -left-1",
  "bottom-right": "-bottom-1 -right-1",
  "top-left": "-top-1 -left-1",
  "top-right": "-top-1 -right-1",
};

const AnimatedCount = ({
  value,
  max,
  shouldReduceMotion,
}: {
  value: number;
  max: number;
  shouldReduceMotion: boolean | null;
}) => {
  const displayValue = value > max ? `${max}+` : value.toString();
  const prevValueRef = useRef(value);
  const direction = value > prevValueRef.current ? 1 : -1;

  useEffect(() => {
    prevValueRef.current = value;
  }, [value]);

  if (shouldReduceMotion) {
    return <span className="font-medium leading-none">{displayValue}</span>;
  }

  return (
    <span className="relative overflow-hidden font-medium leading-none">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          animate={{ opacity: 1, y: 0 }}
          className="inline-block"
          exit={{ opacity: 0, y: direction * -12 }}
          initial={{ opacity: 0, y: direction * 12 }}
          key={value}
          transition={{ bounce: 0.1, duration: 0.3, type: "spring" as const }}
        >
          {displayValue}
        </motion.span>
      </AnimatePresence>
    </span>
  );
};

const NotificationBadge = ({
  variant = "dot",
  count = 0,
  max = 99,
  status = "online",
  showZero = false,
  ping = false,
  position = "top-right",
  children,
  className,
}: NotificationBadgeProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const shouldShow =
      variant === "dot" ||
      variant === "status" ||
      (variant === "count" && (count > 0 || showZero));
    setIsVisible(shouldShow);
  }, [variant, count, showZero]);

  const getBadgeClasses = () => {
    if (variant === "dot") {
      return "h-2.5 w-2.5";
    }
    if (variant === "status") {
      return "h-3 w-3";
    }
    const displayValue = count > max ? `${max}+` : count.toString();
    if (displayValue.length === 1) {
      return "h-5 w-5 text-xs";
    }
    if (displayValue.length === 2) {
      return "h-5 min-w-5 px-1 text-xs";
    }
    return "h-5 min-w-6 px-1 text-xs";
  };

  const getBackgroundColor = () => {
    if (variant === "status") {
      return statusColors[status];
    }
    return "bg-brand";
  };

  const badgeElement = (
    <AnimatePresence mode="wait">
      {isVisible ? (
        <motion.span
          animate={{ opacity: 1, scale: 1 }}
          className={cn(
            "absolute flex items-center justify-center rounded-full text-white",
            getBackgroundColor(),
            getBadgeClasses(),
            positionClasses[position],
            variant === "status" && "ring-2 ring-white dark:ring-gray-900",
            className
          )}
          exit={
            shouldReduceMotion
              ? { opacity: 0, transition: { duration: 0 } }
              : { opacity: 0, scale: 0, transition: { duration: 0.15 } }
          }
          initial={
            shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0 }
          }
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : { bounce: 0.2, duration: 0.25, type: "spring" as const }
          }
        >
          {variant === "count" && (
            <AnimatedCount
              max={max}
              shouldReduceMotion={shouldReduceMotion}
              value={count}
            />
          )}

          {ping && !shouldReduceMotion && (
            <span
              aria-hidden="true"
              className={cn(
                "absolute inset-0 animate-ping rounded-full opacity-75",
                getBackgroundColor()
              )}
            />
          )}
        </motion.span>
      ) : null}
    </AnimatePresence>
  );

  if (!children) {
    return (
      <span className="relative inline-flex">
        <span className="h-4 w-4" />
        {badgeElement}
      </span>
    );
  }

  return (
    <span className="relative inline-flex">
      {children}
      {badgeElement}
    </span>
  );
};

export default NotificationBadge;

"use client";

import { cn } from "@/lib/utils";
import { Minus, Plus } from "lucide-react";
import { useEffect, useRef, useState } from "react";

const TENS_PLACE = 10;
const HUNDREDS_PLACE = 100;

const animateDigit = (
  previous: HTMLElement | null,
  next: HTMLElement | null,
  increasing: boolean
): Animation[] => {
  if (!(previous?.animate && next?.animate)) {
    return [];
  }
  const options = { duration: 300, easing: "cubic-bezier(0.22, 1, 0.36, 1)" };
  return [
    previous.animate(
      [
        { opacity: 1, transform: "translateY(0%)" },
        { opacity: 0, transform: `translateY(${increasing ? -100 : 100}%)` },
      ],
      options
    ),
    next.animate(
      [
        { opacity: 0, transform: `translateY(${increasing ? 100 : -100}%)` },
        { opacity: 1, transform: "translateY(0%)" },
      ],
      options
    ),
  ];
};

export interface NumberFlowProps {
  buttonClassName?: string;
  className?: string;
  digitClassName?: string;
  max?: number;
  min?: number;
  onChange?: (value: number) => void;
  value?: number;
}

export default function NumberFlow({
  value: controlledValue,
  onChange,
  min = 0,
  max = 999,
  className = "",
  digitClassName = "",
  buttonClassName = "",
}: NumberFlowProps) {
  const [internalValue, setInternalValue] = useState(0);
  const [prevValue, setPrevValue] = useState(controlledValue ?? 0);
  const [reduced, setReduced] = useState(false);

  const value = controlledValue === undefined ? internalValue : controlledValue;
  const lastAnimatedValue = useRef(value);

  const prevValueRef = useRef<HTMLElement>(null);
  const nextValueRef = useRef<HTMLElement>(null);
  const prevValueTens = useRef<HTMLElement>(null);
  const nextValueTens = useRef<HTMLElement>(null);
  const prevValueHunds = useRef<HTMLElement>(null);
  const nextValueHunds = useRef<HTMLElement>(null);

  const setValue = (val: number) => {
    if (onChange) {
      onChange(val);
    } else {
      setInternalValue(val);
    }
  };

  const add = () => {
    if (value < max) {
      setPrevValue(value);
      setValue(value + 1);
    }
  };

  const subtract = () => {
    if (value > min) {
      setPrevValue(value);
      setValue(value - 1);
    }
  };

  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    const changed = lastAnimatedValue.current !== value;
    lastAnimatedValue.current = value;
    if (
      !changed ||
      reduced ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
      value === prevValue
    ) {
      return;
    }
    const animations: Animation[] = [];
    const digits = [
      { next: nextValueRef.current, place: 1, previous: prevValueRef.current },
      {
        next: nextValueTens.current,
        place: TENS_PLACE,
        previous: prevValueTens.current,
      },
      {
        next: nextValueHunds.current,
        place: HUNDREDS_PLACE,
        previous: prevValueHunds.current,
      },
    ];
    for (const digit of digits) {
      if (
        Math.floor(value / digit.place) % TENS_PLACE !==
        Math.floor(prevValue / digit.place) % TENS_PLACE
      ) {
        animations.push(
          ...animateDigit(digit.previous, digit.next, value > prevValue)
        );
      }
    }
    return () => {
      for (const animation of animations) {
        animation.cancel();
      }
    };
  }, [value, prevValue, reduced]);

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-8",
        className
      )}
    >
      <div className="flex items-center gap-2 rounded-xl border bg-background p-4">
        <output aria-label="Current value" className="sr-only">
          {value}
        </output>
        <div
          aria-hidden="true"
          className={cn("flex items-center gap-1", digitClassName)}
        >
          <div
            className={cn(
              "relative h-16 w-12 overflow-hidden rounded-lg border bg-primary"
            )}
          >
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={prevValueHunds}
              style={{ transform: "translateY(-100%)" }}
            >
              {Math.floor(prevValue / HUNDREDS_PLACE)}
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={nextValueHunds}
              style={{ transform: "translateY(0%)" }}
            >
              {Math.floor(value / HUNDREDS_PLACE)}
            </span>
          </div>
          <div
            className={cn(
              "relative h-16 w-12 overflow-hidden rounded-lg border bg-primary"
            )}
          >
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={prevValueTens}
              style={{ transform: "translateY(-100%)" }}
            >
              {Math.floor(prevValue / TENS_PLACE) % TENS_PLACE}
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={nextValueTens}
              style={{ transform: "translateY(0%)" }}
            >
              {Math.floor(value / TENS_PLACE) % TENS_PLACE}
            </span>
          </div>
          <div
            className={cn(
              "relative h-16 w-12 overflow-hidden rounded-lg border bg-primary"
            )}
          >
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={prevValueRef}
              style={{ transform: "translateY(-100%)" }}
            >
              {prevValue % TENS_PLACE}
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={nextValueRef}
              style={{ transform: "translateY(0%)" }}
            >
              {value % TENS_PLACE}
            </span>
          </div>
        </div>

        <div className="flex flex-col gap-1">
          <button
            aria-label="Increase number"
            className={cn(
              "relative flex w-auto cursor-pointer items-center justify-center overflow-hidden rounded-md border bg-background p-2 disabled:cursor-not-allowed disabled:opacity-50",
              buttonClassName
            )}
            disabled={value >= max}
            onClick={add}
            type="button"
          >
            <Plus className="h-3 w-3" />
          </button>
          <button
            aria-label="Decrease number"
            className={cn(
              "relative flex w-auto cursor-pointer items-center justify-center overflow-hidden rounded-md border bg-background p-2 disabled:cursor-not-allowed disabled:opacity-50",
              buttonClassName
            )}
            disabled={value <= min}
            onClick={subtract}
            type="button"
          >
            <Minus className="h-3 w-3" />
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { useEffect, useRef, useState } from "react";

/**
 * A configurable WebGL2 orb: a lit sphere with colour marbling inside it.
 *
 * Two ideas carry the whole thing.
 *
 * The loop is seamless by construction, not by crossfade. Every point walks a
 * circle in a flow field whose angle advances by exactly one turn per loop, so
 * the displacement returns to where it started. Neighbouring points begin at
 * different angles, and that is what reads as swirling — offset the whole
 * domain by one shared vector instead and you get a pulse.
 *
 * Colour is mixed in OkLab. The midpoint between two stops stays clean instead
 * of going muddy through sRGB, each picked colour reproduces exactly at its own
 * stop, and the hue ripple is a real rotation in the a/b plane.
 *
 * Everything else is lighting on a sphere impostor: the normal is derived per
 * pixel from the distance to the centre, which is what lets a rim, a highlight
 * and a shaded side exist at all. A radial gradient has no surface, and that is
 * the entire difference between this and a coloured circle.
 *
 * Contains two public-domain pieces of prior art, marked at their definitions:
 * the MurmurHash3 finalizer (Austin Appleby) and the OkLab transform matrices
 * (Björn Ottosson).
 */

export interface OrbProps {
  /**
   * Rim dispersion. Splits the palette lookup per channel toward the edge, the
   * way a lens fringes.
   */
  aberration?: number;
  /** Which colour dominates. `0.5` is even; below favours the first stop. */
  balance?: number;
  /** Interior cell size. Small is busy, large is one slow swell. */
  blobScale?: number;
  /** Hue ripple through the palette. */
  chroma?: number;
  className?: string;
  /** Two to four stops. Two read as a material, four as iridescent. */
  colors?: string[];
  /** Lightness contrast around the midpoint. */
  contrast?: number;
  /** Seconds for one full, seamless loop. */
  duration?: number;
  /** How far the flow field carries the field over a loop. */
  flow?: number;
  /** A halo cast outside the silhouette. `0` is none. */
  glow?: number;
  /** Film grain. Also hides the banding large soft gradients show. */
  grain?: number;
  /** Internal scatter, offset away from the highlight. Fake subsurface. */
  inner?: number;
  /** Fresnel-driven hue rotation — thin-film sheen. */
  iridescence?: number;
  /** Light direction, x. */
  lightX?: number;
  /** Light direction, y. */
  lightY?: number;
  /** Freeze on the current frame. */
  paused?: boolean;
  /** Bends the noise lookup by the surface normal. */
  refraction?: number;
  /** Fresnel edge brightness. This is what reads as glass. */
  rim?: number;
  /** Blends the palette toward plain diffuse shading. */
  shading?: number;
  /** Rotates the palette. */
  shift?: number;
  /** Rendered size. Numbers are pixels. */
  size?: number | string;
  /** Edge feather. `0` still resolves to about 1.5 device pixels. */
  softness?: number;
  /** Specular highlight strength. */
  specular?: number;
  /** Strength of the second, nested warp — marbling rather than blobs. */
  turbulence?: number;
  /** Silhouette deformation, so the orb is a drop rather than a ball. */
  wobble?: number;
}

/** The editor's own defaults, which are a good orb rather than a neutral one. */
const DEFAULTS = {
  aberration: 0.8,
  balance: 0.5,
  blobScale: 3,
  chroma: 1,
  colors: ["#f25aed", "#ffffff"],
  contrast: 1,
  duration: 7,
  flow: 0.6,
  glow: 0,
  grain: 0.6,
  inner: 0.38,
  iridescence: 0,
  lightX: -0.6,
  lightY: -1,
  refraction: 0.25,
  rim: 1.3,
  shading: 0.05,
  shift: 0.23,
  softness: 0.005,
  specular: 0.2,
  turbulence: 0.4,
  wobble: 0,
} as const;

const MAX_STOPS = 4;
const MAX_DPR = 2;
const RGB_MAX = 255;
const SRGB_KNEE = 0.040_45;
const TAU = Math.PI * 2;
/** Ambient motion gains nothing from 120 Hz. */
const FRAME_CAP_MS = 1000 / 60;
const LIGHT_Z = 0.65;
const BALANCE_BASE = 5;
/** Keeps rendering slightly before the orb scrolls into view. */
const ROOT_MARGIN = "120px";

/* The covering triangle is built from gl_VertexID, so there is no vertex
   buffer and no attribute state to manage. */
const VERTEX = `#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
precision highp int;   // the hash needs full 32-bit ints

uniform vec2  uRes;
uniform float uPhase;
uniform vec3  uLab[4];
uniform float uCount;
uniform float uScaleN;
uniform float uFlow;
uniform float uTurb;
uniform float uShift;
uniform float uBalance;
uniform float uChroma;
uniform float uContrast;
uniform float uRim;
uniform float uSpec;
uniform float uInner;
uniform float uShading;
uniform float uRefract;
uniform float uIrid;
uniform float uAberr;
uniform float uGrain;
uniform float uSoft;
uniform float uWobble;
uniform float uGlow;
uniform vec3  uLight;

out vec4 fragColor;

const float TAU = 6.28318530718;
const float RAD = 0.86;         // sphere radius in uv units; the rest is glow room
const float RMAX = 1.0 / RAD;   // radius reached at the nearest canvas edge

/* MurmurHash3 finalizer, Austin Appleby, public domain. Exact at any lattice
   coordinate, so unlike a fract(sin(...)) hash it never bands as the input
   grows — which matters for the grain, whose input runs into the thousands. */
uint hashU(uint x) {
  x ^= x >> 16; x *= 0x85EBCA6Bu;
  x ^= x >> 13; x *= 0xC2B2AE35u;
  x ^= x >> 16;
  return x;
}
uint hashU2(uvec2 p) { return hashU(p.x * 0x9E3779B9u ^ hashU(p.y)); }
uint hashU3(uvec3 p) { return hashU(p.x * 0x9E3779B9u ^ hashU(p.y) ^ hashU(p.z) * 0x27D4EB2Fu); }
float rand2(ivec2 p) { return float(hashU2(uvec2(p + 4096)) >> 8) / 16777216.0; }
float rand3(ivec3 p) { return float(hashU3(uvec3(p + 4096)) >> 8) / 16777216.0; }

float vnoise(vec2 p) {
  ivec2 i = ivec2(floor(p));
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(rand2(i),               rand2(i + ivec2(1, 0)), u.x),
             mix(rand2(i + ivec2(0, 1)), rand2(i + ivec2(1, 1)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0, a = 0.5;
  for (int k = 0; k < 3; k++) { s += a * vnoise(p); p *= 2.03; a *= 0.5; }
  return s / 0.875;
}

/* Each point walks its own circle, completing exactly one turn per loop. */
vec2 flowField(vec2 p) {
  float ang = TAU * vnoise(p + 11.3) + uPhase;
  float mag = 0.35 + 0.65 * vnoise(p + 27.9);
  return vec2(cos(ang), sin(ang)) * mag;
}

/* Fresnel-driven hue rotation in the a/b plane — thin-film sheen. */
vec3 iridesce(vec3 lab, float f) {
  float a = uIrid * f * -2.2;
  float c = cos(a), s = sin(a);
  return vec3(lab.x, c * lab.y - s * lab.z, s * lab.y + c * lab.z);
}

vec3 labRamp(float x) {
  float xx = clamp(x, 0.0, 1.0) * (uCount - 1.0);
  vec3 c = mix(uLab[0], uLab[1], clamp(xx, 0.0, 1.0));
  c = mix(c, uLab[2], clamp(xx - 1.0, 0.0, 1.0));
  c = mix(c, uLab[3], clamp(xx - 2.0, 0.0, 1.0));
  return c;
}

vec3 paletteLab(float t) {
  float x = pow(clamp(0.5 + 0.5 * cos(TAU * t), 0.0, 1.0), uBalance);
  vec3 lab = labRamp(x);
  float ang = TAU * (t * 2.0 + 0.123);
  lab.yz += 0.17 * uChroma * length(lab.yz) * vec2(sin(ang), cos(ang * 1.37 + 1.1));
  /* Cap to roughly the sRGB chroma ceiling. Scaling a/b keeps the hue angle;
     overshooting and clamping RGB later posterises into flat patches. */
  float ch = length(lab.yz);
  if (ch > 0.33) { lab.yz *= 0.33 / ch; }
  lab.x = clamp(0.5 + (lab.x - 0.5) * uContrast, 0.0, 1.0);
  return lab;
}

/* OkLab transform, Björn Ottosson, public domain. */
vec3 oklabToLinear(vec3 c) {
  float l_ = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
  float m_ = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
  float s_ = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
  vec3 lms = vec3(l_ * l_ * l_, m_ * m_ * m_, s_ * s_ * s_);
  return mat3( 4.0767416621, -1.2684380046, -0.0041960863,
              -3.3077115913,  2.6097574011, -0.7034186147,
               0.2309699292, -0.3413193965,  1.7076147010) * lms;
}

vec3 linearToSrgb(vec3 c) {
  c = clamp(c, 0.0, 1.0);
  vec3 lo = c * 12.92;
  vec3 hi = 1.055 * pow(max(c, 1e-5), vec3(1.0 / 2.4)) - 0.055;
  return mix(lo, hi, step(0.0031308, c));
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / min(uRes.x, uRes.y);
  uv /= RAD;

  /* Silhouette wobble. Integer harmonics of the angle keep it continuous all
     the way round; integer multiples of the phase keep it periodic in time.
     Faded in with radius so the rim deforms like a drop while the core stays
     put — which also keeps it away from atan()'s singularity at the centre. */
  if (uWobble > 0.0) {
    float r0 = length(uv);
    float th = atan(uv.y, uv.x + 1e-6);
    float wob = 0.60 * sin(3.0 * th + uPhase)
              + 0.40 * sin(5.0 * th - 2.0 * uPhase)
              + 0.25 * sin(7.0 * th + 3.0 * uPhase);
    uv *= 1.0 - uWobble * 0.055 * wob * smoothstep(0.0, 0.5, r0);
  }

  float r = length(uv);
  vec2 pd = uv / max(r, 1.0);
  float z = sqrt(max(1.0 - dot(pd, pd), 0.0));
  vec3 n = vec3(pd, z);

  /* Domain warping. The base fBm is static; all the motion comes from warping
     its input through the looping flow field, and nesting a second warp is
     what turns smooth blobs into marbled, ink-in-water flow. */
  vec2 p0 = (pd - n.xy * uRefract) * uScaleN;
  vec2 p1 = p0 + uFlow * flowField(p0);
  vec2 p2 = p1 + uTurb * flowField(p1 * 1.7 + 5.2);
  float t = mix(0.5, fbm(p2 + 3.7), 1.35) + uShift;

  float fres3 = pow(1.0 - n.z, 3.0);
  vec3 lab = iridesce(paletteLab(t), fres3);

  vec3 base;
  if (uAberr > 0.001) {
    // Dispersion: the palette lookup shifts per channel, strongest at the rim.
    float d = uAberr * 0.05 * r * r;
    base = vec3(oklabToLinear(iridesce(paletteLab(t - d), fres3)).r,
                oklabToLinear(lab).g,
                oklabToLinear(iridesce(paletteLab(t + d), fres3)).b);
  } else {
    base = oklabToLinear(lab);
  }
  base = max(base, 0.0);

  // Lighting is added in linear light, which is where it belongs.
  vec3 L = normalize(uLight);
  vec3 col = mix(base, vec3(clamp(dot(n, L), 0.0, 1.0)), uShading);

  // Internal scatter offset away from the highlight: a translucent body rather
  // than a lit opaque ball.
  vec2 op = pd + L.xy * 0.45;
  col += uInner * exp(-dot(op, op) * 2.2) * base;

  vec3 half_ = normalize(L + vec3(0.0, 0.0, 1.0));
  col += pow(1.0 - n.z, 8.0) * uRim
       + pow(max(dot(n, half_), 0.0), 24.3) * uSpec;

  vec3 lit = linearToSrgb(col);
  vec3 flat_ = linearToSrgb(base);

  // Never thinner than ~1.5 device px, so the rim stays smooth when the
  // character is rendered small.
  float w = max(uSoft, 1.5 * fwidth(r));
  float body = 1.0 - smoothstep(1.0 - w, 1.0, r);

  /* The halo has to reach exactly zero before the canvas boundary. Left alone
     it is still ~1.5/255 at the edge and gets cut off square, which shows the
     canvas box as a faint rectangle around the orb. */
  float glowF = uGlow * exp(-max(r - 1.0, 0.0) * 20.0);
  glowF *= 1.0 - smoothstep(0.45, 1.0, (r - 1.0) / (RMAX - 1.0));
  float alpha = clamp(body + glowF * (1.0 - body), 0.0, 1.0);

  vec3 outCol = mix(flat_, lit, body);

  // Grain plus an always-on deband dither, stepped to 24 frames per loop so it
  // animates without breaking the seam.
  int frame = int(uPhase / TAU * 24.0);
  outCol += (rand3(ivec3(ivec2(gl_FragCoord.xy), frame)) - 0.5)
          * (uGrain * 0.1 + 1.0 / 255.0);

  outCol = clamp(outCol, 0.0, 1.0);
  fragColor = vec4(outCol * alpha, alpha);   // premultiplied
}`;

/**
 * Any CSS colour to OkLab, in two steps because neither alone is enough.
 *
 * `getComputedStyle` resolves `var()` and named colours, but Chrome hands back
 * `oklch(0.72 0.21 322)` verbatim rather than converting it — read that as three
 * sRGB channels and a magenta comes out blue. A 1x1 2D canvas rasterises
 * whatever syntax survives into actual pixels, which is the only step that
 * cannot lie about the result.
 */
const cssToOklab = (input: string): [number, number, number] => {
  const probe = document.createElement("span");
  probe.style.color = input;
  document.body.appendChild(probe);
  const resolved = getComputedStyle(probe).color;
  probe.remove();

  const surface = document.createElement("canvas");
  surface.width = 1;
  surface.height = 1;
  const ctx = surface.getContext("2d", { willReadFrequently: true });
  if (!ctx) {
    return [1, 0, 0];
  }
  ctx.fillStyle = resolved;
  ctx.fillRect(0, 0, 1, 1);
  const [r8, g8, b8] = ctx.getImageData(0, 0, 1, 1).data;

  // biome-ignore-start lint/style/useNumericSeparators: published colour-space constants, kept digit-for-digit against the reference
  const [r, g, b] = [r8, g8, b8].map((channel) => {
    const u = channel / RGB_MAX;
    return u <= SRGB_KNEE ? u / 12.92 : ((u + 0.055) / 1.055) ** 2.4;
  });
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [
    0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
  ];
  // biome-ignore-end lint/style/useNumericSeparators: published colour-space constants
};

const compileShader = (
  gl: WebGL2RenderingContext,
  type: number,
  source: string
) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

export default function Orb({ className, size = 240, ...rest }: OrbProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // The fallback lives here rather than in the caller: a stand-in drawn by
  // whoever embeds the orb ends up painted over the canvas, which hides the
  // real thing on every machine that can render it.
  const [supported, setSupported] = useState(true);

  // Read inside the loop rather than closed over, so turning a knob pushes a
  // uniform instead of tearing down and rebuilding the GL context.
  const syncConfig = useRef<(() => void) | null>(null);
  const config = useRef({ ...DEFAULTS, ...rest });
  config.current = { ...DEFAULTS, ...rest };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const gl = canvas.getContext("webgl2", {
      alpha: true,
      antialias: false, // a covering triangle has no geometric edges to sample
      depth: false,
      powerPreference: "low-power",
      premultipliedAlpha: true,
      stencil: false,
    });
    if (!gl) {
      setSupported(false);
      return;
    }

    const vs = compileShader(gl, gl.VERTEX_SHADER, VERTEX);
    const fs = compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT);
    const program = gl.createProgram();
    if (!(vs && fs && program)) {
      setSupported(false);
      return;
    }
    gl.attachShader(program, vs);
    gl.attachShader(program, fs);
    gl.linkProgram(program);
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      setSupported(false);
      return;
    }
    // biome-ignore lint/correctness/useHookAtTopLevel: WebGL2RenderingContext.useProgram is not a React hook.
    gl.useProgram(program);
    // Recoverable: a failed first attempt must not disable the orb forever.
    setSupported(true);
    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.BLEND); // the shader writes premultiplied RGBA straight out

    const at = (name: string) => gl.getUniformLocation(program, name);
    const u = {
      aberr: at("uAberr"),
      balance: at("uBalance"),
      chroma: at("uChroma"),
      contrast: at("uContrast"),
      count: at("uCount"),
      flow: at("uFlow"),
      glow: at("uGlow"),
      grain: at("uGrain"),
      inner: at("uInner"),
      irid: at("uIrid"),
      lab: at("uLab"),
      light: at("uLight"),
      phase: at("uPhase"),
      refract: at("uRefract"),
      res: at("uRes"),
      rim: at("uRim"),
      scaleN: at("uScaleN"),
      shading: at("uShading"),
      shift: at("uShift"),
      soft: at("uSoft"),
      spec: at("uSpec"),
      turb: at("uTurb"),
    };

    const pushConfig = () => {
      const c = config.current;
      const stops = c.colors.slice(0, MAX_STOPS);
      const lab = new Float32Array(MAX_STOPS * 3);
      for (let i = 0; i < MAX_STOPS; i++) {
        const [x, y, z] = cssToOklab(stops[Math.min(i, stops.length - 1)]);
        lab[i * 3] = x;
        lab[i * 3 + 1] = y;
        lab[i * 3 + 2] = z;
      }
      gl.uniform3fv(u.lab, lab);
      gl.uniform1f(u.count, Math.max(2, Math.min(stops.length, MAX_STOPS)));
      // The prop reads as blob size, so invert it into cell frequency.
      gl.uniform1f(u.scaleN, 1.45 / Math.max(c.blobScale, 0.05));
      gl.uniform1f(u.flow, c.flow);
      gl.uniform1f(u.turb, c.turbulence);
      gl.uniform1f(u.shift, c.shift);
      gl.uniform1f(u.balance, BALANCE_BASE ** ((0.5 - c.balance) * 2));
      gl.uniform1f(u.chroma, c.chroma);
      gl.uniform1f(u.contrast, c.contrast);
      gl.uniform1f(u.rim, c.rim);
      gl.uniform1f(u.spec, c.specular);
      gl.uniform1f(u.inner, c.inner);
      gl.uniform1f(u.shading, c.shading);
      gl.uniform1f(u.refract, c.refraction);
      gl.uniform1f(u.irid, c.iridescence);
      gl.uniform1f(u.aberr, c.aberration);
      gl.uniform1f(u.grain, c.grain);
      gl.uniform1f(u.soft, c.softness);
      gl.uniform1f(at("uWobble"), c.wobble);
      gl.uniform1f(u.glow, c.glow);
      gl.uniform3f(u.light, c.lightX, c.lightY, LIGHT_Z);
    };

    const resize = (entry?: ResizeObserverEntry) => {
      const box = entry?.devicePixelContentBoxSize;
      let w: number;
      let h: number;
      if (box?.length) {
        w = box[0].inlineSize;
        h = box[0].blockSize;
      } else {
        const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
        const rect = canvas.getBoundingClientRect();
        w = Math.round(rect.width * dpr);
        h = Math.round(rect.height * dpr);
      }
      w = Math.max(1, w);
      h = Math.max(1, h);
      if (canvas.width === w && canvas.height === h) {
        return false;
      }
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
      gl.uniform2f(u.res, w, h);
      return true;
    };

    const draw = () => {
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    let phase = 0;
    let pending = 0;
    let last = 0;
    let raf = 0;
    let running = false;
    let onScreen = true;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)");

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = last ? Math.min(now - last, 100) : FRAME_CAP_MS;
      last = now;
      pending += dt;
      /* Half a frame of slack: without it, a display whose vsync divides the
         cap almost exactly drops an extra frame and the cadence stutters. */
      if (pending < FRAME_CAP_MS - dt * 0.5) {
        return;
      }
      phase = (phase + pending / 1000 / config.current.duration) % 1;
      pending = 0;
      gl.uniform1f(u.phase, phase * TAU);
      draw();
    };

    const start = () => {
      if (running || reduce.matches || config.current.paused || !onScreen) {
        return;
      }
      running = true;
      last = 0;
      pending = 0;
      raf = requestAnimationFrame(tick);
    };

    const stop = () => {
      running = false;
      if (raf) {
        cancelAnimationFrame(raf);
      }
      raf = 0;
    };

    const applyMotionPreference = () => {
      if (reduce.matches || config.current.paused) {
        stop();
        if (reduce.matches) {
          gl.uniform1f(u.phase, 0);
        }
        draw();
        return;
      }
      start();
    };

    syncConfig.current = () => {
      pushConfig();
      applyMotionPreference();
      if (!running) {
        draw();
      }
    };

    pushConfig();
    resize();
    gl.uniform1f(u.phase, 0);
    draw();

    const observer = new ResizeObserver((entries) => {
      if (resize(entries[0]) && !running) {
        draw();
      }
    });
    try {
      observer.observe(canvas, { box: "device-pixel-content-box" });
    } catch {
      observer.observe(canvas);
    }

    /* Scrolled out of view is the common case. Nothing is gained by burning
       GPU on an orb nobody can see. */
    const seen = new IntersectionObserver(
      (entries) => {
        onScreen = entries.at(-1)?.isIntersecting ?? true;
        if (onScreen) {
          start();
        } else {
          stop();
        }
      },
      { rootMargin: ROOT_MARGIN }
    );
    seen.observe(canvas);

    reduce.addEventListener("change", applyMotionPreference);
    applyMotionPreference();

    return () => {
      syncConfig.current = null;
      stop();
      observer.disconnect();
      seen.disconnect();
      reduce.removeEventListener("change", applyMotionPreference);
      gl.deleteProgram(program);
      /* Deliberately NOT calling WEBGL_lose_context here. React remounts
         effects in development, and the second pass gets the same canvas back
         with a context that is still lost — the program then fails to link and
         the component latches into its fallback for good. Dropping the canvas
         is enough; the context goes with it. */
    };
  }, []);

  // Synchronize committed props even when animation is paused or reduced.
  // Keep the GPU resources stable; never convert colors on every frame.
  useEffect(() => {
    syncConfig.current?.();
  });

  const dimension = typeof size === "number" ? `${size}px` : size;

  if (!supported) {
    const stops = (rest.colors ?? DEFAULTS.colors).slice(0, MAX_STOPS);
    return (
      <div
        aria-hidden="true"
        className={cn("block rounded-full", className)}
        style={{
          // Lit from the same corner as the shader, so the character does not
          // change which way it faces when it falls back.
          backgroundImage: `radial-gradient(circle at 32% 28%, ${stops.join(", ")})`,
          height: dimension,
          width: dimension,
        }}
      />
    );
  }

  return (
    <canvas
      aria-hidden="true"
      className={cn("block", className)}
      ref={canvasRef}
      style={{ height: dimension, width: dimension }}
      tabIndex={-1}
    />
  );
}

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import {
  type KeyboardEvent,
  type FocusEvent as ReactFocusEvent,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

const DEFAULT_RADIUS = 160;
const DEFAULT_AUTO_ROTATE_SPEED = 12; // degrees per second
const ITEM_SIZE = 80; // px, diameter of each thumbnail button
const ROTATE_SENSITIVITY = 0.6; // degrees per pixel of horizontal drag
const VELOCITY_SMOOTHING = 0.35;
const MOMENTUM_FRICTION = 0.94; // velocity decay per ~16ms frame
const MOMENTUM_EPSILON = 0.02; // deg/ms below which momentum stops
const SNAP_DURATION = 250; // ms
const STEP_DURATION = 250; // ms
const DRAG_MOVE_THRESHOLD = 4; // px before a pointer gesture counts as a drag

export interface OrbitalImageWheelItem {
  alt: string;
  id: string;
  image: string;
  label?: string;
}

export interface OrbitalImageWheelProps {
  /** Forces a specific item to be highlighted, overriding the automatic top-of-circle detection. */
  activeId?: string;
  autoRotate?: boolean;
  /** Degrees per second while auto-rotating. */
  autoRotateSpeed?: number;
  className?: string;
  /** Tilts each thumbnail to face outward from the center, like a ferris wheel gondola. */
  faceOutward?: boolean;
  items: OrbitalImageWheelItem[];
  onRotationChange?: (rotation: number) => void;
  /** Circle radius in px. */
  radius?: number;
  /** Controlled rotation in degrees. */
  rotation?: number;
  /** Snap to the nearest item when a drag or momentum settles. */
  snap?: boolean;
}

const normalizeAngle = (angle: number): number => {
  const wrapped = angle % 360;
  return wrapped < 0 ? wrapped + 360 : wrapped;
};

const shortestDelta = (from: number, to: number): number => {
  const diff = normalizeAngle(to - from);
  return diff > 180 ? diff - 360 : diff;
};

const easeInOutCubic = (t: number): number =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;

export default function OrbitalImageWheel({
  activeId,
  autoRotate = false,
  autoRotateSpeed = DEFAULT_AUTO_ROTATE_SPEED,
  className,
  faceOutward = false,
  items,
  onRotationChange,
  radius = DEFAULT_RADIUS,
  rotation,
  snap = false,
}: OrbitalImageWheelProps) {
  const shouldReduceMotion = useReducedMotion();
  const isControlled = rotation !== undefined;
  const [internalRotation, setInternalRotation] = useState(0);
  const currentRotation = isControlled
    ? (rotation as number)
    : internalRotation;

  const rotationRef = useRef(currentRotation);
  rotationRef.current = currentRotation;
  const velocityRef = useRef(0);
  const activeFrameRef = useRef<number | null>(null);
  const dragRef = useRef<{
    lastTime: number;
    lastX: number;
    moved: boolean;
    pointerId: number;
  } | null>(null);
  const justDraggedRef = useRef(false);

  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const pauseReasonsRef = useRef({ focus: false, hidden: false, hover: false });

  const itemAngle = items.length > 0 ? 360 / items.length : 0;

  const commitRotation = useCallback(
    (next: number) => {
      const normalized = normalizeAngle(next);
      if (!isControlled) {
        setInternalRotation(normalized);
      }
      onRotationChange?.(normalized);
    },
    [isControlled, onRotationChange]
  );

  const cancelActiveFrame = useCallback(() => {
    if (activeFrameRef.current !== null) {
      cancelAnimationFrame(activeFrameRef.current);
      activeFrameRef.current = null;
    }
  }, []);

  const nearestItemAngleTo = useCallback(
    (value: number): number => {
      if (itemAngle === 0) {
        return value;
      }
      return Math.round(value / itemAngle) * itemAngle;
    },
    [itemAngle]
  );

  const snapTo = useCallback(
    (target: number, duration = SNAP_DURATION) => {
      cancelActiveFrame();
      if (shouldReduceMotion) {
        rotationRef.current = normalizeAngle(target);
        commitRotation(rotationRef.current);
        return;
      }
      const from = rotationRef.current;
      const delta = shortestDelta(from, target);
      const start = performance.now();
      const tick = (time: number) => {
        const progress =
          duration <= 0 ? 1 : Math.min((time - start) / duration, 1);
        const eased = easeInOutCubic(progress);
        rotationRef.current = normalizeAngle(from + delta * eased);
        commitRotation(rotationRef.current);
        if (progress < 1) {
          activeFrameRef.current = requestAnimationFrame(tick);
        } else {
          activeFrameRef.current = null;
        }
      };
      activeFrameRef.current = requestAnimationFrame(tick);
    },
    [cancelActiveFrame, commitRotation, shouldReduceMotion]
  );

  const startMomentum = useCallback(() => {
    cancelActiveFrame();
    let velocity = velocityRef.current;
    let last = performance.now();
    const tick = (time: number) => {
      const dt = time - last;
      last = time;
      rotationRef.current = normalizeAngle(rotationRef.current + velocity * dt);
      velocity *= MOMENTUM_FRICTION ** (dt / 16);
      commitRotation(rotationRef.current);
      if (Math.abs(velocity) < MOMENTUM_EPSILON) {
        if (snap) {
          snapTo(nearestItemAngleTo(rotationRef.current));
        }
        activeFrameRef.current = null;
        return;
      }
      activeFrameRef.current = requestAnimationFrame(tick);
    };
    activeFrameRef.current = requestAnimationFrame(tick);
  }, [cancelActiveFrame, commitRotation, nearestItemAngleTo, snap, snapTo]);

  // Detect hover-capable pointer devices before enabling hover-based pause.
  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setIsHoverDevice(mediaQuery.matches);
    update();
    mediaQuery.addEventListener("change", update);
    return () => mediaQuery.removeEventListener("change", update);
  }, []);

  const recomputePause = useCallback(() => {
    const { focus, hidden, hover } = pauseReasonsRef.current;
    setIsPaused(focus || hidden || hover);
  }, []);

  // Pause auto-rotate while the tab is hidden.
  useEffect(() => {
    const handleVisibility = () => {
      pauseReasonsRef.current.hidden = document.hidden;
      recomputePause();
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () =>
      document.removeEventListener("visibilitychange", handleVisibility);
  }, [recomputePause]);

  // Continuous auto-rotate loop; restarts cleanly whenever paused state changes.
  useEffect(() => {
    if (shouldReduceMotion || !autoRotate || isPaused || items.length === 0) {
      return;
    }
    let raf = 0;
    let last = performance.now();
    const tick = (time: number) => {
      const dt = time - last;
      last = time;
      rotationRef.current = normalizeAngle(
        rotationRef.current + (autoRotateSpeed * dt) / 1000
      );
      commitRotation(rotationRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [
    autoRotate,
    autoRotateSpeed,
    commitRotation,
    isPaused,
    items.length,
    shouldReduceMotion,
  ]);

  useEffect(() => cancelActiveFrame, [cancelActiveFrame]);

  const handlePointerEnter = useCallback(() => {
    pauseReasonsRef.current.hover = true;
    recomputePause();
  }, [recomputePause]);

  const handlePointerLeave = useCallback(() => {
    pauseReasonsRef.current.hover = false;
    recomputePause();
  }, [recomputePause]);

  const handleFocus = useCallback(() => {
    pauseReasonsRef.current.focus = true;
    recomputePause();
  }, [recomputePause]);

  const handleBlur = useCallback(
    (event: ReactFocusEvent<HTMLDivElement>) => {
      if (event.currentTarget.contains(event.relatedTarget)) {
        return;
      }
      pauseReasonsRef.current.focus = false;
      recomputePause();
    },
    [recomputePause]
  );

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      cancelActiveFrame();
      dragRef.current = {
        lastTime: performance.now(),
        lastX: event.clientX,
        moved: false,
        pointerId: event.pointerId,
      };
      event.currentTarget.setPointerCapture(event.pointerId);
    },
    [cancelActiveFrame]
  );

  const handlePointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      if (!drag) {
        return;
      }
      const now = performance.now();
      const dx = event.clientX - drag.lastX;
      if (Math.abs(dx) > DRAG_MOVE_THRESHOLD) {
        drag.moved = true;
      }
      const dt = Math.max(now - drag.lastTime, 1);
      const delta = dx * ROTATE_SENSITIVITY;
      velocityRef.current =
        velocityRef.current * (1 - VELOCITY_SMOOTHING) +
        (delta / dt) * VELOCITY_SMOOTHING;
      rotationRef.current = normalizeAngle(rotationRef.current + delta);
      commitRotation(rotationRef.current);
      drag.lastX = event.clientX;
      drag.lastTime = now;
    },
    [commitRotation]
  );

  const handlePointerUp = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      dragRef.current = null;
      if (!drag) {
        return;
      }
      event.currentTarget.releasePointerCapture(drag.pointerId);
      justDraggedRef.current = drag.moved;
      if (shouldReduceMotion) {
        velocityRef.current = 0;
        if (snap) {
          snapTo(nearestItemAngleTo(rotationRef.current));
        }
        return;
      }
      startMomentum();
    },
    [nearestItemAngleTo, shouldReduceMotion, snap, snapTo, startMomentum]
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowRight") {
        event.preventDefault();
        snapTo(
          rotationRef.current - itemAngle,
          shouldReduceMotion ? 0 : STEP_DURATION
        );
      } else if (event.key === "ArrowLeft") {
        event.preventDefault();
        snapTo(
          rotationRef.current + itemAngle,
          shouldReduceMotion ? 0 : STEP_DURATION
        );
      }
    },
    [itemAngle, shouldReduceMotion, snapTo]
  );

  const handleItemActivate = useCallback(
    (position: number) => {
      if (justDraggedRef.current) {
        justDraggedRef.current = false;
        return;
      }
      snapTo(-(position * itemAngle));
    },
    [itemAngle, snapTo]
  );

  const nearestTopId = useMemo(() => {
    if (items.length === 0) {
      return;
    }
    let bestId = items[0].id;
    let bestDistance = Number.POSITIVE_INFINITY;
    for (const [position, item] of items.entries()) {
      const angle = normalizeAngle(position * itemAngle + currentRotation);
      const distance = Math.abs(shortestDelta(angle, 0));
      if (distance < bestDistance) {
        bestDistance = distance;
        bestId = item.id;
      }
    }
    return bestId;
  }, [items, itemAngle, currentRotation]);

  const highlightedId = activeId ?? nearestTopId;
  const highlightedItem = items.find((item) => item.id === highlightedId);
  const diameter = radius * 2 + ITEM_SIZE;

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: Interactive draggable widget requires event handlers
    <div
      aria-label="Orbital image wheel"
      className={cn("relative mx-auto touch-none select-none", className)}
      onBlur={handleBlur}
      onFocus={handleFocus}
      onKeyDown={handleKeyDown}
      onPointerDown={handlePointerDown}
      onPointerEnter={isHoverDevice ? handlePointerEnter : undefined}
      onPointerLeave={isHoverDevice ? handlePointerLeave : undefined}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      role="application"
      style={{ height: diameter, width: diameter }}
    >
      {items.map((item, position) => {
        const angle = normalizeAngle(position * itemAngle + currentRotation);
        const angleRad = (angle * Math.PI) / 180;
        const x = radius * Math.sin(angleRad);
        const y = -radius * Math.cos(angleRad);
        const isActive = highlightedId === item.id;

        return (
          <button
            aria-current={isActive ? "true" : undefined}
            aria-label={item.label ?? item.alt}
            className={cn(
              "absolute top-1/2 left-1/2 flex items-center justify-center overflow-hidden rounded-full border-2 border-transparent shadow-md transition-[border-color,box-shadow] duration-200 focus-visible:outline-2 focus-visible:outline-brand focus-visible:outline-offset-2",
              isActive && "border-brand shadow-lg"
            )}
            key={item.id}
            onClick={() => handleItemActivate(position)}
            style={{
              height: ITEM_SIZE,
              transform: `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${
                faceOutward ? angle : 0
              }deg)`,
              width: ITEM_SIZE,
              zIndex: Math.round(y),
            }}
            type="button"
          >
            <img
              alt={item.alt}
              className="h-full w-full object-cover"
              draggable={false}
              src={item.image}
            />
          </button>
        );
      })}
      <span aria-live="polite" className="sr-only">
        {highlightedItem
          ? `${highlightedItem.label ?? highlightedItem.alt} selected`
          : null}
      </span>
    </div>
  );
}

