"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useMemo, useState } from "react";

export const PAGE_PRELOADER_VARIANTS = [
  "words",
  "stairs",
  "pixel",
  "curtain",
] as const;

export type PagePreloaderVariant = (typeof PAGE_PRELOADER_VARIANTS)[number];

export type PagePreloaderProps = {
  /** Whether the overlay is showing. Omit to let the component manage itself. */
  active?: boolean;
  /** Tailwind class(es) used to fill the overlay pieces. */
  background?: string;
  className?: string;
  /** Column count for the "stairs" and "pixel" variants. */
  columns?: number;
  /** Renders the overlay `absolute` inside its parent instead of `fixed` full-screen. */
  container?: boolean;
  /** Initial `active` value when uncontrolled. */
  defaultActive?: boolean;
  /** Hold duration in ms before the exit plays (uncontrolled mode). */
  duration?: number;
  /** Fires once the exit transition has fully finished. */
  onComplete?: () => void;
  variant?: PagePreloaderVariant;
  /** Words cycled by the "words" variant while holding. */
  words?: string[];
};

type Stage = "idle" | "hold" | "exiting";

const DEFAULT_DURATION_MS = 1400;
const DEFAULT_COLUMNS = 6;
const DEFAULT_WORDS = ["Loading", "Almost there", "Ready"];
const DEFAULT_BACKGROUND = "bg-background";
const WORD_STEP_MS = 480;
const STAIRS_STAGGER_S = 0.06;
const PIXEL_STAGGER_S = 0.012;
const CURTAIN_EXIT_S = 0.5;
const STAIRS_EXIT_S = 0.55;
const PIXEL_EXIT_S = 0.4;
const WORDS_EXIT_S = 0.45;
const WORD_ROLL_OFFSET_PERCENT = 100;
const EASE_ENTER = [0.23, 1, 0.32, 1] as const;
const EASE_MOVE = [0.645, 0.045, 0.355, 1] as const;
const MS_PER_S = 1000;
const PIXEL_SEED = 733;
const LCG_MULTIPLIER = 1_664_525;
const LCG_INCREMENT = 1_013_904_223;
const UINT32_MAX = 0xff_ff_ff_ff;

/** Deterministic seeded shuffle — no `Math.random()`, safe to call during render via `useMemo`. */
const seededOrder = (count: number, seed: number): number[] => {
  let state = seed;
  const next = () => {
    state = (state * LCG_MULTIPLIER + LCG_INCREMENT) >>> 0;
    return state / UINT32_MAX;
  };
  const order = Array.from({ length: count }, (_, index) => index);
  for (let i = order.length - 1; i > 0; i -= 1) {
    const j = Math.floor(next() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  return order;
};

const getExitDurationMs = (
  variant: PagePreloaderVariant,
  columns: number
): number => {
  switch (variant) {
    case "stairs":
      return (
        (STAIRS_EXIT_S + Math.max(0, columns - 1) * STAIRS_STAGGER_S) * MS_PER_S
      );
    case "pixel": {
      const total = columns * columns;
      return (
        (PIXEL_EXIT_S + Math.max(0, total - 1) * PIXEL_STAGGER_S) * MS_PER_S
      );
    }
    case "words":
      return WORDS_EXIT_S * MS_PER_S;
    default:
      return CURTAIN_EXIT_S * MS_PER_S;
  }
};

type VariantProps = {
  background: string;
  shouldReduceMotion: boolean;
  stage: Stage;
};

const CurtainVariant = ({
  background,
  shouldReduceMotion,
  stage,
}: VariantProps) => {
  const exiting = stage === "exiting";
  const transition = shouldReduceMotion
    ? { duration: 0 }
    : { duration: CURTAIN_EXIT_S, ease: EASE_MOVE };

  return (
    <div aria-hidden="true" className="absolute inset-0 flex">
      <motion.div
        animate={
          exiting
            ? shouldReduceMotion
              ? { opacity: 0 }
              : { opacity: 1, x: "-100%" }
            : { opacity: 1, x: 0 }
        }
        className={cn("h-full w-1/2", background)}
        initial={false}
        transition={transition}
      />
      <motion.div
        animate={
          exiting
            ? shouldReduceMotion
              ? { opacity: 0 }
              : { opacity: 1, x: "100%" }
            : { opacity: 1, x: 0 }
        }
        className={cn("h-full w-1/2", background)}
        initial={false}
        transition={transition}
      />
    </div>
  );
};

const StairsVariant = ({
  background,
  columns,
  shouldReduceMotion,
  stage,
}: VariantProps & { columns: number }) => {
  const exiting = stage === "exiting";

  return (
    <div aria-hidden="true" className="absolute inset-0 flex">
      {Array.from({ length: columns }, (_, index) => (
        <motion.div
          animate={
            exiting
              ? shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 1, scaleY: 0 }
              : { opacity: 1, scaleY: 1 }
          }
          className={cn("h-full flex-1", background)}
          initial={false}
          // biome-ignore lint/suspicious/noArrayIndexKey: columns are positional decorative tiles
          key={index}
          style={{ transformOrigin: "bottom" }}
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : {
                  delay: exiting ? index * STAIRS_STAGGER_S : 0,
                  duration: STAIRS_EXIT_S,
                  ease: EASE_MOVE,
                }
          }
        />
      ))}
    </div>
  );
};

const PixelVariant = ({
  background,
  columns,
  shouldReduceMotion,
  stage,
}: VariantProps & { columns: number }) => {
  const exiting = stage === "exiting";
  const total = columns * columns;
  const order = useMemo(() => seededOrder(total, PIXEL_SEED), [total]);

  return (
    <div
      aria-hidden="true"
      className="absolute inset-0 grid"
      style={{
        gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
        gridTemplateRows: `repeat(${columns}, minmax(0, 1fr))`,
      }}
    >
      {Array.from({ length: total }, (_, index) => (
        <motion.div
          animate={exiting ? { opacity: 0 } : { opacity: 1 }}
          className={cn(background)}
          initial={false}
          // biome-ignore lint/suspicious/noArrayIndexKey: grid cells are positional decorative tiles
          key={index}
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : {
                  delay: exiting ? (order[index] ?? 0) * PIXEL_STAGGER_S : 0,
                  duration: PIXEL_EXIT_S,
                  ease: EASE_ENTER,
                }
          }
        />
      ))}
    </div>
  );
};

const WordsVariant = ({
  background,
  shouldReduceMotion,
  stage,
  wordIndex,
  words,
}: VariantProps & { wordIndex: number; words: string[] }) => {
  const exiting = stage === "exiting";

  return (
    <motion.div
      animate={
        exiting
          ? shouldReduceMotion
            ? { opacity: 0 }
            : { opacity: 1, y: "-100%" }
          : { opacity: 1, y: 0 }
      }
      aria-hidden="true"
      className={cn(
        "absolute inset-0 flex items-center justify-center overflow-hidden",
        background
      )}
      initial={false}
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : { duration: WORDS_EXIT_S, ease: EASE_MOVE }
      }
    >
      <div className="relative h-8 overflow-hidden">
        <AnimatePresence mode="popLayout">
          <motion.span
            animate={{ opacity: 1, y: 0 }}
            className="block font-medium text-foreground text-xl"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { opacity: 0, y: -WORD_ROLL_OFFSET_PERCENT }
            }
            initial={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, y: WORD_ROLL_OFFSET_PERCENT }
            }
            key={words[wordIndex] ?? wordIndex}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { bounce: 0.1, duration: 0.25, type: "spring" }
            }
          >
            {words[wordIndex]}
          </motion.span>
        </AnimatePresence>
      </div>
    </motion.div>
  );
};

const PagePreloader = ({
  active: activeProp,
  background = DEFAULT_BACKGROUND,
  className,
  columns = DEFAULT_COLUMNS,
  container = false,
  defaultActive = true,
  duration = DEFAULT_DURATION_MS,
  onComplete,
  variant = "curtain",
  words = DEFAULT_WORDS,
}: PagePreloaderProps) => {
  const reduceMotionPreference = useReducedMotion();
  const shouldReduceMotion = Boolean(reduceMotionPreference);
  const isControlled = activeProp !== undefined;
  const [internalActive, setInternalActive] = useState(defaultActive);
  const active = isControlled ? Boolean(activeProp) : internalActive;
  const [stage, setStage] = useState<Stage>(active ? "hold" : "idle");
  const [wordIndex, setWordIndex] = useState(0);

  const finish = useCallback(() => {
    setStage("idle");
    if (!isControlled) {
      setInternalActive(false);
    }
    onComplete?.();
  }, [isControlled, onComplete]);

  // Sync stage with the active flag: entering re-arms the hold, and a
  // controlled dismissal while holding starts the exit.
  useEffect(() => {
    if (active) {
      setStage((current) => (current === "exiting" ? current : "hold"));
      setWordIndex(0);
      return;
    }
    setStage((current) => (current === "hold" ? "exiting" : current));
  }, [active]);

  // Uncontrolled auto-hold: exit on its own after `duration`.
  useEffect(() => {
    if (isControlled || stage !== "hold") {
      return;
    }
    const timer = setTimeout(
      () => setStage("exiting"),
      shouldReduceMotion ? 0 : duration
    );
    return () => clearTimeout(timer);
  }, [duration, isControlled, shouldReduceMotion, stage]);

  // Words cycling while holding.
  useEffect(() => {
    if (variant !== "words" || stage !== "hold" || shouldReduceMotion) {
      return;
    }
    if (words.length <= 1) {
      return;
    }
    const timer = setInterval(() => {
      setWordIndex((index) => (index + 1) % words.length);
    }, WORD_STEP_MS);
    return () => clearInterval(timer);
  }, [shouldReduceMotion, stage, variant, words.length]);

  // Exit finishes after its computed duration.
  useEffect(() => {
    if (stage !== "exiting") {
      return;
    }
    const ms = shouldReduceMotion ? 0 : getExitDurationMs(variant, columns);
    const timer = setTimeout(finish, ms);
    return () => clearTimeout(timer);
  }, [columns, finish, shouldReduceMotion, stage, variant]);

  // Lock body scroll only for full-screen overlays.
  useEffect(() => {
    if (container || stage === "idle") {
      return;
    }
    const original = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = original;
    };
  }, [container, stage]);

  if (stage === "idle") {
    return null;
  }

  return (
    <div
      aria-live="polite"
      className={cn(
        "overflow-hidden",
        container ? "absolute inset-0 z-40" : "fixed inset-0 z-[100]",
        className
      )}
      role="status"
    >
      <span className="sr-only">Loading</span>
      {variant === "curtain" && (
        <CurtainVariant
          background={background}
          shouldReduceMotion={shouldReduceMotion}
          stage={stage}
        />
      )}
      {variant === "stairs" && (
        <StairsVariant
          background={background}
          columns={columns}
          shouldReduceMotion={shouldReduceMotion}
          stage={stage}
        />
      )}
      {variant === "pixel" && (
        <PixelVariant
          background={background}
          columns={columns}
          shouldReduceMotion={shouldReduceMotion}
          stage={stage}
        />
      )}
      {variant === "words" && (
        <WordsVariant
          background={background}
          shouldReduceMotion={shouldReduceMotion}
          stage={stage}
          wordIndex={wordIndex}
          words={words}
        />
      )}
    </div>
  );
};

export default PagePreloader;

"use client";

import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useCallback, useId, useMemo } from "react";
import { SPRING_DEFAULT } from "@/components/smoothui/lib/animation";
import SmoothButton from "../smooth-button";

export type PaginationProps = {
  /** Current active page (1-indexed). */
  page: number;
  /** Total number of pages. */
  totalPages: number;
  /** Called when the user selects a different page. */
  onPageChange: (page: number) => void;
  /** Number of sibling pages to show on each side of current page. Defaults to 1. */
  siblings?: number;
  /** Additional CSS classes for the nav element. */
  className?: string;
};

const ELLIPSIS = "ellipsis" as const;

type PageItem = number | typeof ELLIPSIS;

/** Spring for the sliding active indicator (like animated-tabs) */
const SPRING_INDICATOR = {
  bounce: 0.05,
  duration: 0.25,
  type: "spring" as const,
};

/** Stagger delay per page button on initial render */
const STAGGER_DELAY = 0.03;

const buildPageRange = (
  page: number,
  totalPages: number,
  siblings: number
): PageItem[] => {
  const totalSlots = siblings * 2 + 5; // siblings + current + 2 boundary + 2 potential ellipsis

  if (totalPages <= totalSlots) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const leftSibling = Math.max(page - siblings, 2);
  const rightSibling = Math.min(page + siblings, totalPages - 1);

  const showLeftEllipsis = leftSibling > 2;
  const showRightEllipsis = rightSibling < totalPages - 1;

  const items: PageItem[] = [1];

  if (showLeftEllipsis) {
    items.push(ELLIPSIS);
  } else {
    for (let i = 2; i < leftSibling; i++) {
      items.push(i);
    }
  }

  for (let i = leftSibling; i <= rightSibling; i++) {
    items.push(i);
  }

  if (showRightEllipsis) {
    items.push(ELLIPSIS);
  } else {
    for (let i = rightSibling + 1; i < totalPages; i++) {
      items.push(i);
    }
  }

  items.push(totalPages);

  return items;
};

export default function Pagination({
  page,
  totalPages,
  onPageChange,
  siblings = 1,
  className,
}: PaginationProps) {
  const shouldReduceMotion = useReducedMotion();
  const generatedId = useId();
  const layoutId = `pagination-active-${generatedId}`;

  const pageItems = useMemo(
    () => buildPageRange(page, totalPages, siblings),
    [page, totalPages, siblings]
  );

  const handlePrev = useCallback(() => {
    if (page > 1) {
      onPageChange(page - 1);
    }
  }, [page, onPageChange]);

  const handleNext = useCallback(() => {
    if (page < totalPages) {
      onPageChange(page + 1);
    }
  }, [page, totalPages, onPageChange]);

  return (
    <nav
      aria-label="Pagination"
      className={cn("mx-auto flex w-full justify-center", className)}
    >
      <ul className="flex flex-row items-center gap-1">
        {/* Previous button */}
        <li>
          <SmoothButton
            aria-label="Go to previous page"
            className="gap-1 px-2.5"
            disabled={page <= 1}
            onClick={handlePrev}
            size="sm"
            type="button"
            variant="ghost"
          >
            <ChevronLeft className="size-4" />
            <span className="hidden sm:block">Previous</span>
          </SmoothButton>
        </li>

        {/* Page numbers */}
        {pageItems.map((item, index) => {
          if (item === ELLIPSIS) {
            return (
              <li
                aria-hidden="true"
                className="flex size-9 items-center justify-center"
                key={`ellipsis-${String(index)}`}
              >
                <motion.span
                  animate={
                    shouldReduceMotion
                      ? { opacity: 1 }
                      : { opacity: 1, transform: "translateY(0px)" }
                  }
                  className="text-muted-foreground text-sm"
                  initial={
                    shouldReduceMotion
                      ? { opacity: 1 }
                      : { opacity: 0, transform: "translateY(4px)" }
                  }
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : {
                          ...SPRING_DEFAULT,
                          delay: index * STAGGER_DELAY,
                        }
                  }
                >
                  ...
                </motion.span>
              </li>
            );
          }

          const isActive = item === page;

          return (
            <motion.li
              animate={
                shouldReduceMotion
                  ? { opacity: 1 }
                  : { opacity: 1, transform: "translateY(0px)" }
              }
              initial={
                shouldReduceMotion
                  ? { opacity: 1 }
                  : { opacity: 0, transform: "translateY(4px)" }
              }
              key={item}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      ...SPRING_DEFAULT,
                      delay: index * STAGGER_DELAY,
                    }
              }
            >
              <SmoothButton
                aria-current={isActive ? "page" : undefined}
                aria-label={`Go to page ${String(item)}`}
                className={cn(
                  "relative size-9",
                  isActive ? "text-foreground" : "text-muted-foreground"
                )}
                onClick={() => onPageChange(item)}
                size="icon"
                type="button"
                variant="ghost"
              >
                {isActive && (
                  <motion.span
                    className="absolute inset-0 rounded-md border bg-background shadow-sm"
                    layout
                    layoutId={layoutId}
                    style={{ originY: "0px" }}
                    transition={
                      shouldReduceMotion ? { duration: 0 } : SPRING_INDICATOR
                    }
                  />
                )}
                <span className="relative z-10">{item}</span>
              </SmoothButton>
            </motion.li>
          );
        })}

        {/* Next button */}
        <li>
          <SmoothButton
            aria-label="Go to next page"
            className="gap-1 px-2.5"
            disabled={page >= totalPages}
            onClick={handleNext}
            size="sm"
            type="button"
            variant="ghost"
          >
            <span className="hidden sm:block">Next</span>
            <ChevronRight className="size-4" />
          </SmoothButton>
        </li>
      </ul>
    </nav>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  type MotionValue,
  motion,
  useMotionValue,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import {
  type ReactNode,
  type RefObject,
  useEffect,
  useRef,
  useState,
} from "react";

/** Motion scroll offset tuple, typed from `useScroll` itself. */
export type ScrollOffset = NonNullable<
  Parameters<typeof useScroll>[0]
>["offset"];

const SCROLL_SPRING_CONFIG = {
  damping: 30,
  mass: 0.5,
  stiffness: 200,
} as const;
const POINTER_SPRING_CONFIG = {
  damping: 20,
  mass: 0.3,
  stiffness: 150,
} as const;
const POINTER_PARALLAX_MAX_PX = 20;
const DEFAULT_RANGE_PX = 80;
// Concentrated on the stretch where the scene is actually on screen: over the
// full enter-to-exit range most of the layer separation is spent off-view.
const DEFAULT_OFFSET: ScrollOffset = ["start 0.95", "end 0.6"];
const CENTER_RATIO = 0.5;

export type ParallaxDirection = "vertical" | "horizontal" | "both";

export interface ParallaxLayer {
  /** Optional blur, in pixels, applied to this layer for extra depth. */
  blur?: number;
  content: ReactNode;
  /** 0 (no movement) to 1 (maximum movement). */
  depth: number;
  id: string;
  opacity?: number;
}

export interface ParallaxLayersProps {
  className?: string;
  /** Ref to a scrollable ancestor that drives progress instead of the window. */
  container?: RefObject<HTMLElement | null>;
  direction?: ParallaxDirection;
  layers: ParallaxLayer[];
  /** Also react to pointer position on hover-capable devices. */
  pointerParallax?: boolean;
  /** Maximum travel, in pixels, at depth 1. */
  range?: number;
}

const useHoverCapable = (enabled: boolean) => {
  const [isHoverCapable, setIsHoverCapable] = useState(false);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverCapable(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverCapable(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, [enabled]);

  return isHoverCapable;
};

interface ParallaxLayerItemProps {
  direction: ParallaxDirection;
  layer: ParallaxLayer;
  pointerX: MotionValue<number>;
  pointerY: MotionValue<number>;
  progress: MotionValue<number>;
  range: number;
}

const ParallaxLayerItem = ({
  layer,
  progress,
  pointerX,
  pointerY,
  direction,
  range,
}: ParallaxLayerItemProps) => {
  const shouldReduceMotion = useReducedMotion();
  const { depth, blur, opacity } = layer;

  const scrollX = useTransform(
    progress,
    [0, 1],
    [-range * depth, range * depth]
  );
  const scrollY = useTransform(
    progress,
    [0, 1],
    [-range * depth, range * depth]
  );
  const pointerOffsetX = useTransform(pointerX, (latest) => latest * depth);
  const pointerOffsetY = useTransform(pointerY, (latest) => latest * depth);

  const x = useTransform([scrollX, pointerOffsetX], (latest) => {
    const [scrollValue, pointerValue] = latest as [number, number];
    return shouldReduceMotion || direction === "vertical"
      ? 0
      : scrollValue + pointerValue;
  });
  const y = useTransform([scrollY, pointerOffsetY], (latest) => {
    const [scrollValue, pointerValue] = latest as [number, number];
    return shouldReduceMotion || direction === "horizontal"
      ? 0
      : scrollValue + pointerValue;
  });

  return (
    <motion.div
      className="absolute inset-0"
      style={{
        filter: blur ? `blur(${blur}px)` : undefined,
        opacity: opacity ?? 1,
        x,
        y,
      }}
    >
      {layer.content}
    </motion.div>
  );
};

export default function ParallaxLayers({
  layers,
  direction = "vertical",
  range = DEFAULT_RANGE_PX,
  pointerParallax = false,
  container,
  className,
}: ParallaxLayersProps) {
  const ref = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const isHoverCapable = useHoverCapable(pointerParallax);

  const { scrollYProgress } = useScroll({
    container,
    offset: DEFAULT_OFFSET,
    target: ref,
  });
  const springProgress = useSpring(scrollYProgress, SCROLL_SPRING_CONFIG);

  const pointerXRaw = useMotionValue(0);
  const pointerYRaw = useMotionValue(0);
  const pointerX = useSpring(pointerXRaw, POINTER_SPRING_CONFIG);
  const pointerY = useSpring(pointerYRaw, POINTER_SPRING_CONFIG);

  useEffect(() => {
    const node = ref.current;
    const isPointerActive =
      pointerParallax && isHoverCapable && !shouldReduceMotion;

    if (!(node && isPointerActive)) {
      return;
    }

    const handlePointerMove = (event: PointerEvent) => {
      const rect = node.getBoundingClientRect();
      const relativeX = (event.clientX - rect.left) / rect.width - CENTER_RATIO;
      const relativeY = (event.clientY - rect.top) / rect.height - CENTER_RATIO;
      pointerXRaw.set(relativeX * POINTER_PARALLAX_MAX_PX);
      pointerYRaw.set(relativeY * POINTER_PARALLAX_MAX_PX);
    };

    const handlePointerLeave = () => {
      pointerXRaw.set(0);
      pointerYRaw.set(0);
    };

    node.addEventListener("pointermove", handlePointerMove);
    node.addEventListener("pointerleave", handlePointerLeave);

    return () => {
      node.removeEventListener("pointermove", handlePointerMove);
      node.removeEventListener("pointerleave", handlePointerLeave);
    };
  }, [
    pointerParallax,
    isHoverCapable,
    shouldReduceMotion,
    pointerXRaw,
    pointerYRaw,
  ]);

  return (
    <div className={cn("relative", className)} ref={ref}>
      {layers.map((layer) => (
        <ParallaxLayerItem
          direction={direction}
          key={layer.id}
          layer={layer}
          pointerX={pointerX}
          pointerY={pointerY}
          progress={springProgress}
          range={range}
        />
      ))}
    </div>
  );
}

