import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";

export interface PerWordCrossfadeProps {
  children: string;
  className?: string;
  /** Delay before the animation starts, in milliseconds. */
  delay?: number;
  /** Per-word stagger, in milliseconds. */
  stagger?: number;
  /** Animate only once the text scrolls into view. */
  triggerOnView?: boolean;
}

const DURATION_S = 0.7;
const MS = 1000;
// Calm keynote ease-out.
const EASE = [0.16, 1, 0.3, 1] as const;

/**
 * PerWordCrossfade — per-word fade-in with a subtle upward drift,
 * calm keynote rhythm. From the animate-text catalog
 * (`per-word-crossfade`).
 */
export default function PerWordCrossfade({
  children,
  className = "",
  delay = 0,
  stagger = 70,
  triggerOnView = false,
}: PerWordCrossfadeProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true });
  const shouldReduceMotion = useReducedMotion();
  const play = (!triggerOnView || inView) && !shouldReduceMotion;
  const words = children.split(" ");

  return (
    <span aria-label={children} className={className} ref={ref}>
      {words.map((word, index) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: words have no stable id
        <span key={index} style={{ display: "inline-block" }}>
          <motion.span
            animate={play ? { opacity: 1, y: 0 } : undefined}
            aria-hidden="true"
            initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 8 }}
            style={{ display: "inline-block", whiteSpace: "pre" }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : {
                    delay: delay / MS + (index * stagger) / MS,
                    duration: DURATION_S,
                    ease: EASE,
                  }
            }
          >
            {word}
          </motion.span>
          {index < words.length - 1 && (
            <span
              aria-hidden="true"
              style={{ display: "inline-block", whiteSpace: "pre" }}
            >
              {" "}
            </span>
          )}
        </span>
      ))}
    </span>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  motion,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import type { RefObject } from "react";
import { useEffect, useRef, useState } from "react";

export type PerspectiveTextDriver = "scroll" | "pointer" | "static";
export type PerspectiveTextSplit = "lines" | "words";

export interface PerspectiveText3DProps {
  /** Alternative to `text` when the content is static JSX-free copy. */
  children?: string;
  className?: string;
  /** Scrollable ancestor observed when `driver` is "scroll". */
  container?: RefObject<HTMLElement | null>;
  /** Z-axis separation between lines/words, in pixels. */
  depth?: number;
  driver?: PerspectiveTextDriver;
  /** CSS perspective distance, in pixels. */
  perspective?: number;
  /** Maximum rotation around the X axis, in degrees. */
  rotateX?: number;
  /** Maximum rotation around the Y axis, in degrees. */
  rotateY?: number;
  split?: PerspectiveTextSplit;
  text?: string;
}

const DEFAULT_PERSPECTIVE = 800;
const DEFAULT_DEPTH = 40;
const DEFAULT_ROTATE_X = 8;
const DEFAULT_ROTATE_Y = 10;
const POINTER_RANGE_MULTIPLIER = 2;
const SPRING_TRANSITION = {
  bounce: 0.1,
  duration: 0.25,
  type: "spring" as const,
};

const splitContent = (
  content: string,
  split: PerspectiveTextSplit
): string[] => {
  if (split === "words") {
    return content.split(/\s+/).filter((segment) => segment.length > 0);
  }
  const lines = content.split("\n").filter((line) => line.length > 0);
  return lines.length > 0 ? lines : [content];
};

/**
 * PerspectiveText3D — text on a 3D plane that tilts and separates in
 * depth. Lines or words are pushed along the Z axis and the whole plane
 * reacts to scroll progress or the pointer.
 */
export default function PerspectiveText3D({
  children,
  className,
  container,
  depth = DEFAULT_DEPTH,
  driver = "static",
  perspective = DEFAULT_PERSPECTIVE,
  rotateX = DEFAULT_ROTATE_X,
  rotateY = DEFAULT_ROTATE_Y,
  split = "words",
  text,
}: PerspectiveText3DProps) {
  const content = text ?? children ?? "";
  const wrapperRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const [pointerTilt, setPointerTilt] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    if (!wrapper || driver !== "pointer" || shouldReduceMotion) {
      return;
    }

    const handlePointerMove = (event: PointerEvent) => {
      const rect = wrapper.getBoundingClientRect();
      const relativeX = (event.clientX - rect.left) / rect.width - 0.5;
      const relativeY = (event.clientY - rect.top) / rect.height - 0.5;
      setPointerTilt({
        x: -relativeY * rotateX * POINTER_RANGE_MULTIPLIER,
        y: relativeX * rotateY * POINTER_RANGE_MULTIPLIER,
      });
    };
    const handlePointerLeave = () => setPointerTilt({ x: 0, y: 0 });

    wrapper.addEventListener("pointermove", handlePointerMove);
    wrapper.addEventListener("pointerleave", handlePointerLeave);
    return () => {
      wrapper.removeEventListener("pointermove", handlePointerMove);
      wrapper.removeEventListener("pointerleave", handlePointerLeave);
    };
  }, [driver, rotateX, rotateY, shouldReduceMotion]);

  const { scrollYProgress } = useScroll({ container, target: wrapperRef });
  const scrollRotateXRaw = useTransform(
    scrollYProgress,
    [0, 1],
    [rotateX, -rotateX]
  );
  const scrollRotateYRaw = useTransform(
    scrollYProgress,
    [0, 1],
    [-rotateY, rotateY]
  );
  const scrollRotateX = useSpring(scrollRotateXRaw, SPRING_TRANSITION);
  const scrollRotateY = useSpring(scrollRotateYRaw, SPRING_TRANSITION);

  if (shouldReduceMotion) {
    return (
      <p className={className} style={{ whiteSpace: "pre-line" }}>
        {content}
      </p>
    );
  }

  const segments = splitContent(content, split);
  const midIndex = (segments.length - 1) / 2;
  const planeAnimate =
    driver === "pointer"
      ? { rotateX: pointerTilt.x, rotateY: pointerTilt.y }
      : driver === "static"
        ? { rotateX, rotateY }
        : undefined;
  const planeInitial =
    driver === "scroll" ? undefined : { rotateX: 0, rotateY: 0 };

  return (
    <div
      className={cn("inline-block", className)}
      ref={wrapperRef}
      style={{ perspective }}
    >
      {/* Every segment below is aria-hidden, so the readable copy lives here.
          An aria-label on this plain div would be dropped by assistive tech. */}
      <span className="sr-only">{content}</span>
      <motion.div
        animate={planeAnimate}
        initial={planeInitial}
        style={{
          transformStyle: "preserve-3d",
          ...(driver === "scroll"
            ? { rotateX: scrollRotateX, rotateY: scrollRotateY }
            : {}),
        }}
        transition={SPRING_TRANSITION}
      >
        {segments.map((segment, index) => (
          <div
            aria-hidden="true"
            // biome-ignore lint/suspicious/noArrayIndexKey: segments have no stable id
            key={index}
            style={{
              display: split === "lines" ? "block" : "inline-block",
              transform: `translateZ(${(index - midIndex) * depth}px)`,
            }}
          >
            {segment}
            {split === "words" && index < segments.length - 1 ? " " : null}
          </div>
        ))}
      </motion.div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";

export interface PhotoStackPhoto {
  alt: string;
  id: string;
  /** Optional caption shown over the front card. */
  name?: string;
  role?: string;
  src: string;
}

export interface PhotoStackProps {
  className?: string;
  /** Fired after the top card is sent to the back, with the new id order. */
  onCycle?: (order: string[]) => void;
  /** Cards to stack. The first item starts on top. */
  photos: PhotoStackPhoto[];
}

// Resting offset/scale per stack position (0 = front).
const POSITIONS = [
  { scale: 1, x: 0, y: 0 },
  { scale: 0.95, x: 16, y: 12 },
  { scale: 0.9, x: 32, y: 24 },
];

/**
 * PhotoStack — a draggable deck of photo cards. Drag the top card (Tinder-style)
 * in either direction, or tap it, to send it to the back and reveal the next.
 * Inspired by Josh Puckett's dialkit Photo Stack.
 */
export default function PhotoStack({
  className,
  photos,
  onCycle,
}: PhotoStackProps) {
  const reduceMotion = useReducedMotion();
  const [order, setOrder] = useState<number[]>(() => photos.map((_, i) => i));
  // A real drag fires both onDragEnd and a trailing onClick. Without this guard
  // a short drag would cycle twice and land the card in 2nd place, not last.
  const justDragged = useRef(false);

  const cycle = () => {
    setOrder((prev) => {
      const next = [...prev.slice(1), prev[0]];
      onCycle?.(next.map((i) => photos[i].id));
      return next;
    });
  };

  return (
    <div className={cn("relative h-72 w-56 select-none", className)}>
      {order.map((photoIndex, pos) => {
        const photo = photos[photoIndex];
        const rest = POSITIONS[Math.min(pos, POSITIONS.length - 1)];
        const isFront = pos === 0;

        return (
          <motion.div
            animate={{ rotate: 0, scale: rest.scale, x: rest.x, y: rest.y }}
            aria-label={
              isFront ? `${photo.name ?? photo.alt} — next` : undefined
            }
            className="absolute inset-0 overflow-hidden rounded-2xl border border-black/10 bg-white shadow-[0_1px_2px_rgba(0,0,0,0.06),0_14px_32px_rgba(0,0,0,0.14)] focus-visible:outline-2 focus-visible:outline-blue-600 focus-visible:outline-offset-2"
            drag={isFront && !reduceMotion ? "x" : false}
            dragSnapToOrigin
            key={photo.id}
            onClick={() => {
              if (!isFront) {
                return;
              }
              // Swallow the click that trails a drag so it doesn't double-cycle.
              if (justDragged.current) {
                justDragged.current = false;
                return;
              }
              cycle();
            }}
            onDragEnd={() => {
              // Any drag release sends the dragged (front) card to the back.
              justDragged.current = true;
              cycle();
            }}
            onKeyDown={(e: React.KeyboardEvent) => {
              if (isFront && (e.key === "Enter" || e.key === " ")) {
                e.preventDefault();
                cycle();
              }
            }}
            role={isFront ? "button" : undefined}
            style={{
              cursor: isFront ? "grab" : "default",
              zIndex: photos.length - pos,
            }}
            tabIndex={isFront ? 0 : -1}
            transition={
              reduceMotion
                ? { duration: 0 }
                : { damping: 30, stiffness: 320, type: "spring" }
            }
            whileDrag={{ cursor: "grabbing" }}
          >
            <img
              alt={photo.alt}
              className="h-full w-full object-cover object-top"
              draggable={false}
              src={photo.src}
            />
            {photo.name || photo.role ? (
              <figcaption
                className={cn(
                  "absolute inset-x-0 bottom-0 flex flex-col gap-px bg-gradient-to-t from-black/60 to-transparent p-3.5 text-white transition-opacity",
                  !isFront && "opacity-0"
                )}
              >
                {photo.name ? (
                  <span className="font-semibold text-sm">{photo.name}</span>
                ) : null}
                {photo.role ? (
                  <span className="text-xs opacity-85">{photo.role}</span>
                ) : null}
              </figcaption>
            ) : null}
            {pos > 0 && (
              <span
                aria-hidden
                className="pointer-events-none absolute inset-0 bg-white"
                style={{ opacity: pos === 1 ? 0.2 : 0.36 }}
              />
            )}
          </motion.div>
        );
      })}
    </div>
  );
}

"use client";

import {
  Content as TabsContent,
  List as TabsList,
  Root as TabsRoot,
  Trigger as TabsTrigger,
} from "@radix-ui/react-tabs";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useLayoutEffect, useRef, useState } from "react";

/**
 * Tab definition for Phototab
 */
export interface PhototabTab {
  /** Tab icon (ReactNode) */
  icon: React.ReactNode;
  /** Tab image (string: URL or import) */
  image: string;
  /** Tab label */
  name: string;
}

export interface PhototabProps {
  /** Class name for root */
  className?: string;
  /** Default selected tab name */
  defaultTab?: string;
  /** Height of the component in pixels */
  height?: number;
  /** Class name for image */
  imageClassName?: string;
  /** Class name for tab list */
  tabListClassName?: string;
  /** Array of tabs to display */
  tabs: PhototabTab[];
  /** Class name for tab trigger */
  tabTriggerClassName?: string;
}

const WHITESPACE = /\s+/g;

/**
 * Radix derives the trigger/panel element ids from the tab value, and an id may
 * not contain whitespace — a multi-word tab name such as "Tab 1" produced an
 * `aria-controls` that resolved to nothing, breaking the tab/panel pairing for
 * assistive tech. Values are slugged so the generated ids stay valid.
 */
const toTabValue = (name: string) => name.replace(WHITESPACE, "-");

export default function Phototab({
  tabs,
  defaultTab,
  height = 400,
  className = "",
  tabListClassName = "",
  tabTriggerClassName = "",
  imageClassName = "",
}: PhototabProps) {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [bgStyle, setBgStyle] = useState<{
    left: number;
    top: number;
    width: number;
    height: number;
  } | null>(null);
  const triggersRef = useRef<(HTMLButtonElement | null)[]>([]);
  const listRef = useRef<HTMLDivElement | null>(null);
  const shouldReduceMotion = useReducedMotion();

  useLayoutEffect(() => {
    if (
      hoveredIndex !== null &&
      triggersRef.current[hoveredIndex] &&
      listRef.current
    ) {
      const trigger = triggersRef.current[hoveredIndex];
      if (!trigger) {
        return;
      }
      const listRect = listRef.current.getBoundingClientRect();
      const triggerRect = trigger.getBoundingClientRect();
      setBgStyle({
        height: triggerRect.height,
        left: triggerRect.left - listRect.left,
        top: triggerRect.top - listRect.top,
        width: triggerRect.width,
      });
    } else {
      setBgStyle(null);
    }
  }, [hoveredIndex]);

  return (
    <TabsRoot
      className={`group relative aspect-square w-auto overflow-hidden ${className}`}
      defaultValue={toTabValue(defaultTab || (tabs[0]?.name ?? ""))}
      orientation="horizontal"
      style={{ height: `${height}px` }}
    >
      <TabsList
        aria-label="Phototab Tabs"
        className={`absolute right-0 bottom-2 left-0 mx-auto flex w-40 -translate-y-10 flex-row items-center justify-between rounded-full bg-primary/40 px-3 py-2 font-medium text-sm ring ring-border/70 backdrop-blur-sm transition hover:text-foreground md:translate-y-20 md:group-hover:translate-y-0 ${tabListClassName}`}
        ref={listRef}
        style={{ pointerEvents: "auto" }}
      >
        <AnimatePresence>
          {bgStyle ? (
            <motion.span
              animate={{
                height: bgStyle.height,
                left: bgStyle.left,
                opacity: 1,
                top: bgStyle.top,
                width: bgStyle.width,
              }}
              className="absolute z-0 rounded-full bg-primary transition-colors"
              exit={{ opacity: 0 }}
              initial={{ opacity: 0 }}
              layoutId="hoverBackground"
              style={{ position: "absolute" }}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      damping: 40,
                      duration: 0.25,
                      stiffness: 400,
                      type: "spring" as const,
                    }
              }
            />
          ) : null}
        </AnimatePresence>
        {tabs.map((tab, index) => (
          <TabsTrigger
            aria-label={tab.name}
            className={`relative z-10 cursor-pointer rounded-full p-2 data-[state='active']:bg-background ${tabTriggerClassName}`}
            key={tab.name}
            onMouseEnter={() => {
              setHoveredIndex(index);
            }}
            onMouseLeave={() => {
              setHoveredIndex(null);
            }}
            ref={(el) => {
              triggersRef.current[index] = el;
            }}
            value={toTabValue(tab.name)}
          >
            <span className="relative z-10 rounded-full focus:outline-none">
              {tab.icon}
              <span className="sr-only">{tab.name}</span>
            </span>
          </TabsTrigger>
        ))}
      </TabsList>
      {tabs.map((tab) => (
        <TabsContent
          className="h-full w-full"
          key={tab.name}
          value={toTabValue(tab.name)}
        >
          <img
            alt={tab.name}
            className={`h-full w-full rounded-2xl bg-primary object-cover ${imageClassName}`}
            draggable={false}
            height={height}
            loading="lazy"
            src={tab.image}
            width={400}
          />
        </TabsContent>
      ))}
    </TabsRoot>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { Pin } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { KeyboardEvent, ReactNode } from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

const DEFAULT_MAX_PINNED = 5;

/* -------------------------------------------------------------------------- */
/* Motion tokens                                                              */
/* -------------------------------------------------------------------------- */

const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];
const INSTANT = { duration: 0 };
/** Entrance/exit of a brand-new row — restrained. */
const ENTER_SPRING = { bounce: 0.1, duration: 0.25, type: "spring" as const };
/** Leaving is the user's decision already made — get out of the way faster. */
const EXIT_TRANSITION = { duration: 0.15, ease: EASE_OUT };
/** The row launching into (or back out of) the pinned group — real overshoot. */
const LAUNCH_SPRING = { bounce: 0.3, duration: 0.4, type: "spring" as const };
/** The pin icon's own, snappier spring. */
const PIN_SPRING = { bounce: 0.32, duration: 0.2, type: "spring" as const };
/** Rows closing the gap settle one after the other instead of as a rigid block. */
const STAGGER_STEP = 0.025;
const MAX_STAGGER = 0.1;
/**
 * The landing pop, as a damped squash rather than an inflate. A row that grows
 * past 1 pushes outside the list's box, and the list almost always sits inside
 * a scroller — so the pop got sliced off exactly when it was biggest. Every
 * keyframe here stays at or below 1, so the row can never breach its own
 * bounds no matter how wide it is; the compression settles in two decaying
 * steps, which is how weight actually lands.
 */
const POP_SCALE = [1, 0.985, 0.997, 1];
const POP_TIMES = [0, 0.3, 0.62, 1];
const POP_DURATION = 0.34;
const POP_RESET_MS = 420;
const PINNED_ROTATION = 45;
/**
 * Rows never sit flush against the list's edge: 4px of padding keeps the
 * landing rebound, the launch spring's overshoot and the 4px focus ring
 * (2px ring + 2px offset) inside whatever clips this list.
 */
const ROW_HALO = "p-1";

export type PinnedListItem = {
  icon?: ReactNode;
  id: string;
  meta?: string;
  pinned?: boolean;
  title: string;
};

export type PinnedListProps = {
  className?: string;
  emptyPinnedMessage?: string;
  items: PinnedListItem[];
  /** Names the list for assistive technology. */
  label?: string;
  maxPinned?: number;
  onPinnedChange?: (ids: string[]) => void;
  pinnedIds?: string[];
  renderItem?: (item: PinnedListItem, isPinned: boolean) => ReactNode;
  showDivider?: boolean;
};

/* -------------------------------------------------------------------------- */
/* Row                                                                       */
/* -------------------------------------------------------------------------- */

type RowProps = {
  groupIndex: number;
  isFocused: boolean;
  isPinned: boolean;
  item: PinnedListItem;
  justPinned: boolean;
  onKeyDownRow: (event: KeyboardEvent<HTMLDivElement>, index: number) => void;
  onTogglePin: (id: string) => void;
  pinDisabled: boolean;
  registerRef: (id: string, el: HTMLDivElement | null) => void;
  renderItem?: (item: PinnedListItem, isPinned: boolean) => ReactNode;
  rowIndex: number;
  shouldReduceMotion: boolean;
};

const Row = ({
  groupIndex,
  isFocused,
  isPinned,
  item,
  justPinned,
  onKeyDownRow,
  onTogglePin,
  pinDisabled,
  registerRef,
  renderItem,
  rowIndex,
  shouldReduceMotion,
}: RowProps) => {
  // The row that was just acted on leads; the rows closing the gap trail it.
  const layoutDelay = isPinned
    ? 0
    : Math.min(groupIndex * STAGGER_STEP, MAX_STAGGER);

  return (
    <motion.li
      className="list-none"
      layout={shouldReduceMotion ? false : "position"}
      transition={
        shouldReduceMotion
          ? INSTANT
          : {
              default: ENTER_SPRING,
              layout: { ...LAUNCH_SPRING, delay: layoutDelay },
            }
      }
    >
      {/* The row itself is the control: it carries the roving tabindex, so
          Arrow/Home/End/P all reach a handler that is actually focused. */}
      <motion.div
        animate={
          justPinned && !shouldReduceMotion
            ? { scale: POP_SCALE }
            : { scale: 1 }
        }
        aria-disabled={pinDisabled || undefined}
        aria-label={`${isPinned ? "Unpin" : "Pin"} ${item.title}`}
        aria-pressed={isPinned}
        className={cn(
          "group relative flex items-center gap-3 rounded-xl border p-3 outline-none",
          "transition-[background-color,border-color,box-shadow] duration-200 ease-out",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          // Pinned rows are raised, not tinted: a solid surface lifted off the
          // list with a real shadow and a crisper edge, the way the rest of the
          // library marks a selected surface. Dark mode lifts with light
          // instead, because a shadow has nothing to fall on there.
          isPinned
            ? "border-foreground/15 bg-background shadow-black/[0.07] shadow-sm dark:border-foreground/20 dark:bg-foreground/[0.07] dark:shadow-none"
            : "border-foreground/[0.08] bg-transparent",
          pinDisabled
            ? "cursor-not-allowed opacity-60"
            : "cursor-pointer hover:border-foreground/20"
        )}
        initial={false}
        onClick={() => {
          if (!pinDisabled) {
            onTogglePin(item.id);
          }
        }}
        onKeyDown={(event) => onKeyDownRow(event, rowIndex)}
        ref={(el) => {
          registerRef(item.id, el);
        }}
        role="button"
        tabIndex={isFocused ? 0 : -1}
        transition={
          shouldReduceMotion
            ? INSTANT
            : { duration: POP_DURATION, ease: EASE_OUT, times: POP_TIMES }
        }
      >
        {/* The only piece of brand colour on the row: a short rail on the
            leading edge. It grows out of nothing on pin, so the state change
            is structural rather than a rectangle of fill appearing. */}
        <motion.span
          animate={{
            opacity: isPinned ? 1 : 0,
            scaleY: isPinned ? 1 : 0.2,
          }}
          aria-hidden="true"
          className="absolute top-1/2 left-0 h-5 w-[3px] rounded-r-full bg-brand"
          initial={false}
          style={{ y: "-50%" }}
          transition={shouldReduceMotion ? INSTANT : PIN_SPRING}
        />
        <div className="min-w-0 flex-1">
          {renderItem ? (
            renderItem(item, isPinned)
          ) : (
            <div className="flex items-center gap-2">
              {item.icon ? (
                <span
                  aria-hidden="true"
                  className={cn(
                    "shrink-0 transition-colors duration-200",
                    isPinned ? "text-foreground" : "text-foreground/45"
                  )}
                >
                  {item.icon}
                </span>
              ) : null}
              <div className="min-w-0">
                <p className="truncate font-medium text-foreground text-sm">
                  {item.title}
                </p>
                {item.meta ? (
                  <p className="truncate text-muted-foreground text-xs">
                    {item.meta}
                  </p>
                ) : null}
              </div>
            </div>
          )}
        </div>
        <span
          aria-hidden="true"
          className={cn(
            "flex size-8 shrink-0 items-center justify-center rounded-full transition-colors duration-200",
            isPinned
              ? "text-brand"
              : "text-foreground/40 group-hover:bg-foreground/5 group-hover:text-foreground"
          )}
        >
          <motion.span
            animate={{ rotate: isPinned ? PINNED_ROTATION : 0 }}
            className="flex items-center justify-center"
            initial={false}
            transition={shouldReduceMotion ? INSTANT : PIN_SPRING}
          >
            <Pin className={cn("size-4", isPinned && "fill-current")} />
          </motion.span>
        </span>
      </motion.div>
    </motion.li>
  );
};

/* -------------------------------------------------------------------------- */
/* Root                                                                      */
/* -------------------------------------------------------------------------- */

const PinnedList = ({
  className,
  emptyPinnedMessage = "Pin an item to keep it at the top.",
  items,
  label = "Pinnable items",
  maxPinned = DEFAULT_MAX_PINNED,
  onPinnedChange,
  pinnedIds,
  renderItem,
  showDivider = true,
}: PinnedListProps) => {
  const shouldReduceMotion = Boolean(useReducedMotion());
  const [internalPinned, setInternalPinned] = useState<string[]>(() =>
    items.filter((item) => item.pinned).map((item) => item.id)
  );
  const [focusedId, setFocusedId] = useState<string | null>(null);
  const [justPinnedId, setJustPinnedId] = useState<string | null>(null);
  const rowRefs = useRef(new Map<string, HTMLDivElement>());
  // A row that moves between the two groups is re-inserted in the DOM, which
  // can drop focus. Remember which row to hand focus back to after the move.
  const restoreFocusRef = useRef<string | null>(null);

  const isControlled = pinnedIds !== undefined;
  const pinned = isControlled ? pinnedIds : internalPinned;

  useEffect(() => {
    if (!justPinnedId) {
      return;
    }
    const timer = setTimeout(() => setJustPinnedId(null), POP_RESET_MS);
    return () => clearTimeout(timer);
  }, [justPinnedId]);

  const pinnedItems = useMemo(
    () => items.filter((item) => pinned.includes(item.id)),
    [items, pinned]
  );
  const unpinnedItems = useMemo(
    () => items.filter((item) => !pinned.includes(item.id)),
    [items, pinned]
  );
  const orderedItems = useMemo(
    () => [...pinnedItems, ...unpinnedItems],
    [pinnedItems, unpinnedItems]
  );

  // Exactly one row is tabbable at a time, and it is always a row that exists.
  const activeFocusId =
    focusedId && orderedItems.some((item) => item.id === focusedId)
      ? focusedId
      : (orderedItems[0]?.id ?? null);

  const registerRef = useCallback((id: string, el: HTMLDivElement | null) => {
    if (el) {
      rowRefs.current.set(id, el);
    } else {
      rowRefs.current.delete(id);
    }
  }, []);

  const setPinned = (next: string[]) => {
    if (!isControlled) {
      setInternalPinned(next);
    }
    onPinnedChange?.(next);
  };

  const togglePin = (id: string) => {
    // Keep focus on the row the user acted on, even though pinning moves it.
    if (rowRefs.current.get(id) === document.activeElement) {
      restoreFocusRef.current = id;
    }
    setFocusedId(id);

    if (pinned.includes(id)) {
      setJustPinnedId(null);
      setPinned(pinned.filter((pinnedId) => pinnedId !== id));
      return;
    }
    if (pinned.length >= maxPinned) {
      return;
    }
    setJustPinnedId(id);
    setPinned([...pinned, id]);
  };

  useEffect(() => {
    const id = restoreFocusRef.current;
    if (!id) {
      return;
    }
    restoreFocusRef.current = null;
    rowRefs.current.get(id)?.focus();
  });

  const focusRowAt = (index: number) => {
    const total = orderedItems.length;
    if (total === 0) {
      return;
    }
    const nextItem = orderedItems[((index % total) + total) % total];
    setFocusedId(nextItem.id);
    rowRefs.current.get(nextItem.id)?.focus();
  };

  const handleKeyDownRow = (
    event: KeyboardEvent<HTMLDivElement>,
    index: number
  ) => {
    if (event.key === "ArrowDown" || event.key === "ArrowRight") {
      event.preventDefault();
      focusRowAt(index + 1);
      return;
    }
    if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
      event.preventDefault();
      focusRowAt(index - 1);
      return;
    }
    if (event.key === "Home") {
      event.preventDefault();
      focusRowAt(0);
      return;
    }
    if (event.key === "End") {
      event.preventDefault();
      focusRowAt(orderedItems.length - 1);
      return;
    }
    if (
      event.key === "p" ||
      event.key === "P" ||
      event.key === "Enter" ||
      event.key === " "
    ) {
      event.preventDefault();
      const item = orderedItems[index];
      if (item) {
        togglePin(item.id);
      }
    }
  };

  const pinDisabled = pinned.length >= maxPinned;
  const showEmptyPinned = pinnedItems.length === 0;
  const showSeparator =
    showDivider && pinnedItems.length > 0 && unpinnedItems.length > 0;

  return (
    <div className={cn("flex flex-col", className)}>
      {/* One list, not two: a pinned row is reordered inside its own parent
          instead of being torn out of one list and rebuilt in another. */}
      <ul aria-label={label} className={cn("flex flex-col gap-2", ROW_HALO)}>
        {/* popLayout takes the leaving placeholder out of flow on the first
            frame, so the rows above it move as one — and, because nothing is
            left waiting on a layout animation, its exit actually completes. */}
        <AnimatePresence initial={false} mode="popLayout">
          {showEmptyPinned ? (
            <motion.li
              animate={{ opacity: 1 }}
              className="list-none rounded-xl border border-foreground/15 border-dashed p-3 text-muted-foreground text-sm"
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: INSTANT }
                  : { opacity: 0, transition: EXIT_TRANSITION }
              }
              initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }}
              key="empty-pinned"
              transition={shouldReduceMotion ? INSTANT : ENTER_SPRING}
            >
              {emptyPinnedMessage}
            </motion.li>
          ) : null}
        </AnimatePresence>

        {pinnedItems.map((item, groupIndex) => (
          <Row
            groupIndex={groupIndex}
            isFocused={activeFocusId === item.id}
            isPinned
            item={item}
            justPinned={justPinnedId === item.id}
            key={item.id}
            onKeyDownRow={handleKeyDownRow}
            onTogglePin={togglePin}
            pinDisabled={false}
            registerRef={registerRef}
            renderItem={renderItem}
            rowIndex={groupIndex}
            shouldReduceMotion={shouldReduceMotion}
          />
        ))}

        {/* A hairline is below the threshold worth animating; it also keeps
            the exiting-child machinery off the one element in the list that
            has no content of its own. */}
        {showSeparator ? (
          <li
            aria-hidden="true"
            className="my-1 list-none border-foreground/10 border-t"
          />
        ) : null}

        {unpinnedItems.map((item, groupIndex) => (
          <Row
            groupIndex={groupIndex}
            isFocused={activeFocusId === item.id}
            isPinned={false}
            item={item}
            justPinned={false}
            key={item.id}
            onKeyDownRow={handleKeyDownRow}
            onTogglePin={togglePin}
            pinDisabled={pinDisabled}
            registerRef={registerRef}
            renderItem={renderItem}
            rowIndex={pinnedItems.length + groupIndex}
            shouldReduceMotion={shouldReduceMotion}
          />
        ))}
      </ul>
    </div>
  );
};

export default PinnedList;

"use client";

import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import {
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type Ref,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

export type PixelBrushCanvasBrush =
  | "pencil"
  | "eraser"
  | "fill"
  | "line"
  | "rect";

export interface PixelBrushCanvasHandle {
  /** Erases every pixel back to the empty state. */
  clear: () => void;
  /** Returns a copy of the raw pixel buffer (palette indices, 0 = empty). */
  getPixels: () => Uint8Array;
  /** Exports the current drawing as a PNG data URL. */
  toDataURL: () => string;
  /** Reverts the last committed stroke, fill, line, rect or clear. */
  undo: () => void;
}

export interface PixelBrushCanvasProps {
  /** Currently active brush tool. Uncontrolled if omitted. */
  brush?: PixelBrushCanvasBrush;
  className?: string;
  /** Index into `palette` for the active paint color. Uncontrolled if omitted. */
  color?: number;
  /** Show gridlines between pixel cells. */
  grid?: boolean;
  /** Height of the art grid, in pixel cells (not CSS px). */
  height?: number;
  /** Optional initial artwork as a 2D array (rows of `height`, cols of `width`) of palette indices. Negative values mean empty. */
  initial?: number[][];
  onBrushChange?: (brush: PixelBrushCanvasBrush) => void;
  /** Fires with a snapshot of the pixel buffer on every mutation. */
  onChange?: (pixels: Uint8Array) => void;
  onColorChange?: (color: number) => void;
  /** Available paint colors, as CSS color strings. */
  palette?: string[];
  /** Size of a single pixel cell, in CSS px. */
  pixelSize?: number;
  ref?: Ref<PixelBrushCanvasHandle>;
  /** Render the built-in color/brush palette below the canvas. */
  showTools?: boolean;
  /** Width of the art grid, in pixel cells (not CSS px). */
  width?: number;
}

interface Cell {
  x: number;
  y: number;
}

interface BoundingBox {
  maxX: number;
  maxY: number;
  minX: number;
  minY: number;
}

interface BrushOption {
  label: string;
  shortcut?: string;
  value: PixelBrushCanvasBrush;
}

const DEFAULT_GRID_WIDTH = 16;
const DEFAULT_GRID_HEIGHT = 16;
const DEFAULT_PIXEL_SIZE = 20;
const MAX_DEVICE_PIXEL_RATIO = 2;
const MAX_UNDO_STEPS = 50;
const GRID_LINE_WIDTH = 1;
const EMPTY_CELL_VALUE = 0;
const GRID_LINE_COLOR = "rgba(120, 120, 120, 0.35)";

const DEFAULT_PALETTE: string[] = [
  "#1f2937",
  "#ef4444",
  "#f97316",
  "#facc15",
  "#22c55e",
  "#0ea5e9",
  "#6366f1",
  "#ec4899",
  "#ffffff",
];

const BRUSH_OPTIONS: BrushOption[] = [
  { label: "Pencil", shortcut: "B", value: "pencil" },
  { label: "Eraser", shortcut: "E", value: "eraser" },
  { label: "Fill", shortcut: "G", value: "fill" },
  { label: "Line", value: "line" },
  { label: "Rectangle", value: "rect" },
];

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const createInitialPixels = (
  gridWidth: number,
  gridHeight: number,
  initial?: number[][]
): Uint8Array => {
  const pixels = new Uint8Array(gridWidth * gridHeight);
  if (!initial) {
    return pixels;
  }
  for (let y = 0; y < gridHeight; y++) {
    const row = initial[y];
    if (!row) {
      continue;
    }
    for (let x = 0; x < gridWidth; x++) {
      const value = row[x];
      if (value === undefined || value < 0) {
        continue;
      }
      pixels[y * gridWidth + x] = value + 1;
    }
  }
  return pixels;
};

const drawCell = (
  ctx: CanvasRenderingContext2D,
  pixels: Uint8Array,
  gridWidth: number,
  x: number,
  y: number,
  cellSize: number,
  palette: string[],
  showGrid: boolean
) => {
  const value = pixels[y * gridWidth + x];
  const left = x * cellSize;
  const top = y * cellSize;
  ctx.clearRect(left, top, cellSize, cellSize);
  if (value !== EMPTY_CELL_VALUE) {
    ctx.fillStyle = palette[value - 1] ?? palette[0] ?? "#000000";
    ctx.fillRect(left, top, cellSize, cellSize);
  }
  if (showGrid) {
    ctx.strokeStyle = GRID_LINE_COLOR;
    ctx.lineWidth = GRID_LINE_WIDTH;
    ctx.strokeRect(left + 0.5, top + 0.5, cellSize - 1, cellSize - 1);
  }
};

const drawRegion = (
  ctx: CanvasRenderingContext2D,
  pixels: Uint8Array,
  gridWidth: number,
  gridHeight: number,
  cellSize: number,
  palette: string[],
  showGrid: boolean,
  box: BoundingBox
) => {
  const startX = Math.max(0, box.minX);
  const startY = Math.max(0, box.minY);
  const endX = Math.min(gridWidth - 1, box.maxX);
  const endY = Math.min(gridHeight - 1, box.maxY);
  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      drawCell(ctx, pixels, gridWidth, x, y, cellSize, palette, showGrid);
    }
  }
};

/** Iterative (stack-based) flood fill — never recursive, so it cannot blow the call stack. */
const floodFillIterative = (
  pixels: Uint8Array,
  gridWidth: number,
  gridHeight: number,
  startX: number,
  startY: number,
  newValue: number
): BoundingBox | null => {
  const targetValue = pixels[startY * gridWidth + startX];
  if (targetValue === newValue) {
    return null;
  }
  const stack: Cell[] = [{ x: startX, y: startY }];
  const box: BoundingBox = {
    maxX: startX,
    maxY: startY,
    minX: startX,
    minY: startY,
  };
  while (stack.length > 0) {
    const cell = stack.pop();
    if (!cell) {
      break;
    }
    const { x, y } = cell;
    if (x < 0 || x >= gridWidth || y < 0 || y >= gridHeight) {
      continue;
    }
    if (pixels[y * gridWidth + x] !== targetValue) {
      continue;
    }
    pixels[y * gridWidth + x] = newValue;
    box.minX = Math.min(box.minX, x);
    box.maxX = Math.max(box.maxX, x);
    box.minY = Math.min(box.minY, y);
    box.maxY = Math.max(box.maxY, y);
    stack.push(
      { x: x + 1, y },
      { x: x - 1, y },
      { x, y: y + 1 },
      { x, y: y - 1 }
    );
  }
  return box;
};

/** Bresenham line rasterization, bounded by the known max step count. */
const getLineCells = (start: Cell, end: Cell): Cell[] => {
  const cells: Cell[] = [];
  const dx = Math.abs(end.x - start.x);
  const dy = Math.abs(end.y - start.y);
  const stepX = end.x >= start.x ? 1 : -1;
  const stepY = end.y >= start.y ? 1 : -1;
  const maxSteps = Math.max(dx, dy) + 1;
  let { x, y } = start;
  let error = dx - dy;
  for (let step = 0; step < maxSteps; step++) {
    cells.push({ x, y });
    if (x === end.x && y === end.y) {
      break;
    }
    const doubledError = error * 2;
    if (doubledError > -dy) {
      error -= dy;
      x += stepX;
    }
    if (doubledError < dx) {
      error += dx;
      y += stepY;
    }
  }
  return cells;
};

const getRectOutlineCells = (start: Cell, end: Cell): Cell[] => {
  const minX = Math.min(start.x, end.x);
  const maxX = Math.max(start.x, end.x);
  const minY = Math.min(start.y, end.y);
  const maxY = Math.max(start.y, end.y);
  const cells: Cell[] = [];
  for (let x = minX; x <= maxX; x++) {
    cells.push({ x, y: minY });
    if (maxY !== minY) {
      cells.push({ x, y: maxY });
    }
  }
  for (let y = minY; y <= maxY; y++) {
    cells.push({ x: minX, y });
    if (maxX !== minX) {
      cells.push({ x: maxX, y });
    }
  }
  return cells;
};

const getCellFromPoint = (
  clientX: number,
  clientY: number,
  rect: DOMRect,
  gridWidth: number,
  gridHeight: number,
  cellSize: number
): Cell => {
  const scaleX = rect.width / (gridWidth * cellSize) || 1;
  const scaleY = rect.height / (gridHeight * cellSize) || 1;
  const rawX = (clientX - rect.left) / scaleX;
  const rawY = (clientY - rect.top) / scaleY;
  return {
    x: clamp(Math.floor(rawX / cellSize), 0, gridWidth - 1),
    y: clamp(Math.floor(rawY / cellSize), 0, gridHeight - 1),
  };
};

const describeValue = (value: number, palette: string[]): string =>
  value === EMPTY_CELL_VALUE
    ? "empty"
    : (palette[value - 1] ?? "unknown color");

interface ToolPaletteProps {
  brush: PixelBrushCanvasBrush;
  colorIndex: number;
  onSelectBrush: (brush: PixelBrushCanvasBrush) => void;
  onSelectColor: (index: number) => void;
  palette: string[];
}

const ToolPalette = ({
  brush,
  colorIndex,
  onSelectBrush,
  onSelectColor,
  palette,
}: ToolPaletteProps) => {
  const shouldReduceMotion = useReducedMotion();
  const brushIndicatorId = `pixel-brush-tool-${useId()}`;

  return (
    <div className="flex flex-wrap items-center gap-3">
      <fieldset
        aria-label="Color palette"
        className="m-0 flex items-center gap-1.5 border-0 p-0"
      >
        {palette.map((hex, index) => {
          const isSelected = index === colorIndex;
          return (
            <button
              aria-label={`Select color ${index + 1}: ${hex}`}
              aria-pressed={isSelected}
              className={cn(
                "relative flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-full",
                "shadow-[inset_0_0_0_1px_rgb(0_0_0/0.12)] outline-none dark:shadow-[inset_0_0_0_1px_rgb(255_255_255/0.16)]",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
              )}
              // biome-ignore lint/suspicious/noArrayIndexKey: palette is a flat color list with no stable id and colors may repeat
              key={`${hex}-${index}`}
              onClick={() => onSelectColor(index)}
              style={{ backgroundColor: hex }}
              type="button"
            >
              {isSelected && (
                // A brand ring around a swatch fights the colour the swatch is
                // showing. The selection halo is neutral chrome instead — the
                // gap-then-ring every colour picker uses — so it reads the same
                // against every hue in the palette.
                <motion.span
                  animate={{ opacity: 1, scale: 1 }}
                  aria-hidden="true"
                  className="absolute inset-0 rounded-full ring-2 ring-foreground ring-offset-2 ring-offset-background"
                  initial={
                    shouldReduceMotion
                      ? { opacity: 1, scale: 1 }
                      : { opacity: 0, scale: 0.6 }
                  }
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { bounce: 0.1, duration: 0.25, type: "spring" }
                  }
                />
              )}
            </button>
          );
        })}
      </fieldset>
      {/* Tool selection borrows the language of `animated-tabs`: the whole
          group is a recessed track and the active tool is a solid chip raised
          out of it, which reads instantly at this size without any fill. */}
      <fieldset
        aria-label="Brush tools"
        className="m-0 flex items-center gap-0.5 rounded-lg border-0 bg-foreground/[0.05] p-1 dark:bg-foreground/[0.09]"
      >
        {BRUSH_OPTIONS.map((option) => {
          const isActive = option.value === brush;
          return (
            <button
              aria-label={
                option.shortcut
                  ? `${option.label} tool (shortcut ${option.shortcut})`
                  : `${option.label} tool`
              }
              aria-pressed={isActive}
              className={cn(
                "relative cursor-pointer rounded-md px-2.5 py-1.5 font-medium text-xs outline-none",
                "transition-colors duration-150 ease-out",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background",
                isActive
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground"
              )}
              key={option.value}
              onClick={() => onSelectBrush(option.value)}
              type="button"
            >
              {isActive && (
                <motion.span
                  aria-hidden="true"
                  className="absolute inset-0 rounded-md bg-background shadow-[0_0_0_1px_rgb(0_0_0/0.07),0_1px_2px_rgb(0_0_0/0.08)] dark:bg-foreground/[0.14] dark:shadow-[0_0_0_1px_rgb(255_255_255/0.10)]"
                  layoutId={brushIndicatorId}
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { bounce: 0.1, duration: 0.25, type: "spring" }
                  }
                />
              )}
              <span className="relative">{option.label}</span>
            </button>
          );
        })}
      </fieldset>
    </div>
  );
};

const PixelBrushCanvas = ({
  brush,
  className,
  color,
  grid = false,
  height = DEFAULT_GRID_HEIGHT,
  initial,
  onBrushChange,
  onChange,
  onColorChange,
  palette = DEFAULT_PALETTE,
  pixelSize = DEFAULT_PIXEL_SIZE,
  ref,
  showTools = true,
  width = DEFAULT_GRID_WIDTH,
}: PixelBrushCanvasProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const pixelsRef = useRef<Uint8Array>(
    createInitialPixels(width, height, initial)
  );
  const undoStackRef = useRef<Uint8Array[]>([]);
  const isPaintingRef = useRef(false);
  const lastPaintedRef = useRef<Cell | null>(null);
  const dragStartRef = useRef<Cell | null>(null);
  const anchorRef = useRef<Cell | null>(null);

  const [internalColor, setInternalColor] = useState(color ?? 0);
  const [internalBrush, setInternalBrush] = useState<PixelBrushCanvasBrush>(
    brush ?? "pencil"
  );
  const [cursor, setCursor] = useState<Cell>({ x: 0, y: 0 });
  const [announcement, setAnnouncement] = useState("");

  useEffect(() => {
    if (color !== undefined) {
      setInternalColor(color);
    }
  }, [color]);

  useEffect(() => {
    if (brush !== undefined) {
      setInternalBrush(brush);
    }
  }, [brush]);

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    if (pixelsRef.current.length !== width * height) {
      pixelsRef.current = createInitialPixels(width, height, initial);
      undoStackRef.current = [];
    }
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DEVICE_PIXEL_RATIO);
    const cssWidth = width * pixelSize;
    const cssHeight = height * pixelSize;
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;
    canvas.width = Math.round(cssWidth * dpr);
    canvas.height = Math.round(cssHeight * dpr);
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawRegion(
      ctx,
      pixelsRef.current,
      width,
      height,
      pixelSize,
      palette,
      grid,
      {
        maxX: width - 1,
        maxY: height - 1,
        minX: 0,
        minY: 0,
      }
    );
  }, [width, height, pixelSize, palette, grid, initial]);

  const redrawRegion = useCallback(
    (box: BoundingBox) => {
      const ctx = canvasRef.current?.getContext("2d");
      if (!ctx) {
        return;
      }
      drawRegion(
        ctx,
        pixelsRef.current,
        width,
        height,
        pixelSize,
        palette,
        grid,
        box
      );
    },
    [width, height, pixelSize, palette, grid]
  );

  const notifyChange = useCallback(() => {
    onChange?.(pixelsRef.current.slice());
  }, [onChange]);

  const pushUndoSnapshot = useCallback(() => {
    const stack = undoStackRef.current;
    if (stack.length >= MAX_UNDO_STEPS) {
      stack.shift();
    }
    stack.push(pixelsRef.current.slice());
  }, []);

  const announceFocusedCell = (x: number, y: number) => {
    const value = pixelsRef.current[y * width + x];
    setAnnouncement(
      `Column ${x + 1}, row ${y + 1}. Color: ${describeValue(value, palette)}.`
    );
  };

  const setCellValue = (x: number, y: number, value: number): boolean => {
    if (pixelsRef.current[y * width + x] === value) {
      return false;
    }
    pixelsRef.current[y * width + x] = value;
    redrawRegion({ maxX: x, maxY: y, minX: x, minY: y });
    return true;
  };

  const commitCells = (cells: Cell[], value: number) => {
    pushUndoSnapshot();
    let changed = false;
    const box: BoundingBox = { maxX: -1, maxY: -1, minX: width, minY: height };
    for (const cell of cells) {
      if (cell.x < 0 || cell.x >= width || cell.y < 0 || cell.y >= height) {
        continue;
      }
      if (pixelsRef.current[cell.y * width + cell.x] === value) {
        continue;
      }
      pixelsRef.current[cell.y * width + cell.x] = value;
      changed = true;
      box.minX = Math.min(box.minX, cell.x);
      box.minY = Math.min(box.minY, cell.y);
      box.maxX = Math.max(box.maxX, cell.x);
      box.maxY = Math.max(box.maxY, cell.y);
    }
    if (changed) {
      redrawRegion(box);
      notifyChange();
    } else {
      undoStackRef.current.pop();
    }
  };

  const applyFillAt = (x: number, y: number) => {
    pushUndoSnapshot();
    const box = floodFillIterative(
      pixelsRef.current,
      width,
      height,
      x,
      y,
      internalColor + 1
    );
    if (box) {
      redrawRegion(box);
      notifyChange();
    } else {
      undoStackRef.current.pop();
    }
  };

  const clear = useCallback(() => {
    pushUndoSnapshot();
    pixelsRef.current.fill(EMPTY_CELL_VALUE);
    redrawRegion({ maxX: width - 1, maxY: height - 1, minX: 0, minY: 0 });
    notifyChange();
  }, [width, height, pushUndoSnapshot, redrawRegion, notifyChange]);

  const undo = useCallback(() => {
    const snapshot = undoStackRef.current.pop();
    if (!snapshot) {
      return;
    }
    pixelsRef.current = snapshot;
    redrawRegion({ maxX: width - 1, maxY: height - 1, minX: 0, minY: 0 });
    notifyChange();
  }, [width, height, redrawRegion, notifyChange]);

  useImperativeHandle(
    ref,
    () => ({
      clear,
      getPixels: () => pixelsRef.current.slice(),
      toDataURL: () => canvasRef.current?.toDataURL() ?? "",
      undo,
    }),
    [clear, undo]
  );

  const selectBrush = (next: PixelBrushCanvasBrush) => {
    setInternalBrush(next);
    anchorRef.current = null;
    onBrushChange?.(next);
  };

  const selectColor = (index: number) => {
    setInternalColor(index);
    onColorChange?.(index);
  };

  const handlePointerDown = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const cell = getCellFromPoint(
      event.clientX,
      event.clientY,
      rect,
      width,
      height,
      pixelSize
    );
    wrapperRef.current?.focus();
    setCursor(cell);

    if (internalBrush === "pencil" || internalBrush === "eraser") {
      event.currentTarget.setPointerCapture(event.pointerId);
      isPaintingRef.current = true;
      lastPaintedRef.current = null;
      pushUndoSnapshot();
      const value =
        internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
      if (setCellValue(cell.x, cell.y, value)) {
        notifyChange();
      } else {
        undoStackRef.current.pop();
      }
      lastPaintedRef.current = cell;
    } else if (internalBrush === "fill") {
      applyFillAt(cell.x, cell.y);
    } else {
      dragStartRef.current = cell;
    }
    announceFocusedCell(cell.x, cell.y);
  };

  const handlePointerMove = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (!isPaintingRef.current) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const cell = getCellFromPoint(
      event.clientX,
      event.clientY,
      rect,
      width,
      height,
      pixelSize
    );
    const last = lastPaintedRef.current;
    if (last && last.x === cell.x && last.y === cell.y) {
      return;
    }
    const value =
      internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
    if (setCellValue(cell.x, cell.y, value)) {
      notifyChange();
    }
    lastPaintedRef.current = cell;
    setCursor(cell);
  };

  const handlePointerUp = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (isPaintingRef.current) {
      isPaintingRef.current = false;
      lastPaintedRef.current = null;
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
      return;
    }
    const start = dragStartRef.current;
    if (start && (internalBrush === "line" || internalBrush === "rect")) {
      const rect = event.currentTarget.getBoundingClientRect();
      const end = getCellFromPoint(
        event.clientX,
        event.clientY,
        rect,
        width,
        height,
        pixelSize
      );
      const cells =
        internalBrush === "line"
          ? getLineCells(start, end)
          : getRectOutlineCells(start, end);
      commitCells(cells, internalColor + 1);
      announceFocusedCell(end.x, end.y);
    }
    dragStartRef.current = null;
  };

  const moveCursor = (dx: number, dy: number) => {
    const nextX = clamp(cursor.x + dx, 0, width - 1);
    const nextY = clamp(cursor.y + dy, 0, height - 1);
    setCursor({ x: nextX, y: nextY });
    announceFocusedCell(nextX, nextY);
  };

  const paintAtCursor = () => {
    if (internalBrush === "pencil" || internalBrush === "eraser") {
      pushUndoSnapshot();
      const value =
        internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
      if (setCellValue(cursor.x, cursor.y, value)) {
        notifyChange();
      } else {
        undoStackRef.current.pop();
      }
      announceFocusedCell(cursor.x, cursor.y);
    } else if (internalBrush === "fill") {
      applyFillAt(cursor.x, cursor.y);
      announceFocusedCell(cursor.x, cursor.y);
    } else {
      const anchor = anchorRef.current;
      if (!anchor) {
        anchorRef.current = { x: cursor.x, y: cursor.y };
        setAnnouncement(
          `Anchor set at column ${cursor.x + 1}, row ${cursor.y + 1}. Move and press space again to finish.`
        );
        return;
      }
      const cells =
        internalBrush === "line"
          ? getLineCells(anchor, cursor)
          : getRectOutlineCells(anchor, cursor);
      commitCells(cells, internalColor + 1);
      anchorRef.current = null;
      announceFocusedCell(cursor.x, cursor.y);
    }
  };

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    const isUndoShortcut =
      (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "z";
    if (isUndoShortcut) {
      event.preventDefault();
      undo();
      return;
    }
    switch (event.key) {
      case "ArrowUp": {
        event.preventDefault();
        moveCursor(0, -1);
        return;
      }
      case "ArrowDown": {
        event.preventDefault();
        moveCursor(0, 1);
        return;
      }
      case "ArrowLeft": {
        event.preventDefault();
        moveCursor(-1, 0);
        return;
      }
      case "ArrowRight": {
        event.preventDefault();
        moveCursor(1, 0);
        return;
      }
      case " ":
      case "Spacebar": {
        event.preventDefault();
        paintAtCursor();
        return;
      }
      default:
        break;
    }
    const lowerKey = event.key.toLowerCase();
    if (lowerKey === "e") {
      selectBrush("eraser");
    } else if (lowerKey === "b") {
      selectBrush("pencil");
    } else if (lowerKey === "g") {
      selectBrush("fill");
    }
  };

  return (
    <div className={cn("inline-flex flex-col gap-3", className)}>
      <div className="inline-block rounded-lg border border-border bg-muted/40 p-2">
        {/* biome-ignore lint/a11y/noNoninteractiveElementInteractions: role="application" is the keyboard-operable pixel grid; no semantic element models 2D arrow-key navigation */}
        <div
          aria-label="Pixel art drawing canvas"
          className="relative inline-block rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-brand"
          onKeyDown={handleKeyDown}
          ref={wrapperRef}
          role="application"
          // biome-ignore lint/a11y/noNoninteractiveTabindex: role="application" must be focusable to be keyboard-operable
          tabIndex={0}
        >
          <canvas
            className="block touch-none rounded-sm"
            onPointerDown={handlePointerDown}
            onPointerLeave={handlePointerUp}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            ref={canvasRef}
          />
          <div
            aria-hidden="true"
            className="pointer-events-none absolute border-2 border-brand"
            style={{
              height: pixelSize,
              left: cursor.x * pixelSize,
              top: cursor.y * pixelSize,
              width: pixelSize,
            }}
          />
          <span aria-live="polite" className="sr-only">
            {announcement}
          </span>
        </div>
      </div>
      {showTools ? (
        <ToolPalette
          brush={internalBrush}
          colorIndex={internalColor}
          onSelectBrush={selectBrush}
          onSelectColor={selectColor}
          palette={palette}
        />
      ) : null}
    </div>
  );
};

export default PixelBrushCanvas;

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

export type PixelFlowFieldShape = "square" | "circle" | "cross";

export interface PixelFlowFieldProps {
  /** Cell size in CSS pixels. Smaller cells read the source more sharply. */
  cellSize?: number;
  /** Foreground content, always painted above the decorative field. */
  children?: ReactNode;
  /** Extra classes for the positioned wrapper element. */
  className?: string;
  /**
   * Three ramp stops, dim to bright: `[field, accent, ink]`. Cells the source
   * does not cover sit on the first stop; fully covered cells sit on the last.
   * Accepts any CSS colour, a `var(--token)` expression, or a bare custom
   * property name such as `--color-brand`.
   */
  colors?: string[];
  /** Gap between cells in CSS pixels. */
  gap?: number;
  /** Freezes the field on its current frame. */
  paused?: boolean;
  /** Radius in CSS pixels within which the pointer disturbs cells. */
  pointerRadius?: number;
  /** How hard the pointer shoves cells, from 0 to 1. */
  pointerStrength?: number;
  /**
   * Increment this to blow the field apart and let it re-form. Any change to
   * the number re-scatters with a fresh deterministic seed; the value itself
   * carries no meaning.
   */
  scatter?: number;
  /** Shape drawn for every cell. */
  shape?: PixelFlowFieldShape;
  /** Flow speed multiplier. 1 is the calibrated default. */
  speed?: number;
  /**
   * Image URL sampled instead of `text`. Needs to be CORS-readable; if the
   * pixels cannot be read the component falls back to `text`.
   */
  src?: string;
  /** Word sampled into the grid. Short words read best. */
  text?: string;
  /** Font weight used when rasterising `text`. Heavy weights survive better. */
  weight?: number;
}

type Rgba = [number, number, number, number];

interface FieldSettings {
  cellSize: number;
  colors: Rgba[];
  fontFamily: string;
  gap: number;
  pointerRadius: number;
  pointerStrength: number;
  scatterSeed: number;
  shape: PixelFlowFieldShape;
  source: HTMLImageElement | null;
  speed: number;
  still: boolean;
  text: string;
  weight: number;
}

interface FieldController {
  destroy: () => void;
  render: () => void;
  resize: () => void;
  setPointer: (x: number, y: number, active: boolean) => void;
  setRunning: (running: boolean) => void;
  setSettings: (settings: FieldSettings) => void;
}

const MAX_DPR = 2;
const RGB_MAX = 255;
const MS_PER_SECOND = 1000;
const TAU = Math.PI * 2;

const DEFAULT_CELL_SIZE = 8;
const DEFAULT_GAP = 3;
const DEFAULT_SPEED = 1;
const DEFAULT_TEXT = "smooth";
const DEFAULT_WEIGHT = 800;
const DEFAULT_POINTER_RADIUS = 130;
const DEFAULT_POINTER_STRENGTH = 1;
const DEFAULT_FONT_FAMILY = "system-ui, sans-serif";

// Ramp stops as theme tokens. The hardcoded fallbacks are the same oklch
// values the tokens resolve to in light mode, converted to sRGB:
// neutral oklch(0.81 0 0), brand oklch(0.72 0.2 352.53), ink oklch(0.22 0 0).
const DEFAULT_COLORS = [
  "var(--color-smooth-500, oklch(0.81 0 0))",
  "var(--color-brand, oklch(0.72 0.2 352.53))",
  "var(--color-foreground, oklch(0.22 0 0))",
];
const FALLBACK_COLORS: Rgba[] = [
  [193, 193, 193, 1],
  [239, 92, 152, 1],
  [26, 26, 26, 1],
];

const MIN_STEP = 3;
const MIN_COLS = 44;
const MAX_CELLS = 14_000;
const MIN_DRAW = 0.35;

/** Brightness tiers. Each tier is one `fillStyle` + one `fill()` per frame. */
const TIER_COUNT = 7;
const RAMP_MID = 0.6;
const FIELD_ALPHA = 0.24;
const ACCENT_ALPHA = 0.92;
const INK_ALPHA = 1;

/** Coverage below/above these lands flat, so letter edges stay crisp. */
const MASK_LOW = 0.08;
const MASK_HIGH = 0.86;

const TEXT_HEIGHT_RATIO = 0.68;
const TEXT_WIDTH_RATIO = 0.86;
const LUMA_R = 0.2126;
const LUMA_G = 0.7152;
const LUMA_B = 0.0722;

/** One flow-field sample per 4x4 block of cells, bilinear-filtered per cell. */
const LATTICE = 4;
const NOISE_SCALE = 0.19;
const TIME_SCALE = 0.14;
const FLOW_TURNS = 1.35;
const MAG_FLOOR = 0.35;
const MAG_RANGE = 0.65;
const NOISE_OFFSET_X = 37.2;
const NOISE_OFFSET_Y = 11.5;
const NOISE_COUNTER_FLOW = 0.8;

const DRIFT_RATIO = 0.95;
const WORD_CALM = 0.84;
const SIZE_FLOOR = 0.3;
const SIZE_MASK = 0.64;
const SIZE_FLOW = 0.2;
const STILL_MAG = 0.55;
const CROSS_THICKNESS = 0.34;

const REFORM_MS = 1750;
const STAGGER = 0.45;
const WORD_LEAD = 0.16;
const DELAY_X = 0.55;
const DELAY_Y = 0.3;
const DELAY_JITTER = 0.15;
const SCATTER_SIZE = 0.5;
const SCATTER_SPREAD = 1.25;

const WAKE_TAU = 0.42;
const WAKE_GAIN = 3.4;
const WAKE_CEILING = 2.4;
const MAX_SUBSTEPS = 4;
const MAX_DT = 0.05;

const HASH_X = 127.1;
const HASH_Y = 311.7;
const HASH_SEED = 74.7;
const HASH_MULTIPLIER = 43_758.545_312_3;

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(max, value));

const smoothstep = (value: number) => value * value * (3 - 2 * value);

const toCssColor = (input: string) =>
  input.trim().startsWith("--") ? `var(${input.trim()})` : input.trim();

const hash2 = (x: number, y: number) => {
  const value = Math.sin(x * HASH_X + y * HASH_Y + HASH_SEED) * HASH_MULTIPLIER;
  return value - Math.floor(value);
};

const valueNoise = (x: number, y: number) => {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const fx = x - ix;
  const fy = y - iy;
  const ux = smoothstep(fx);
  const uy = smoothstep(fy);
  const a = hash2(ix, iy);
  const b = hash2(ix + 1, iy);
  const c = hash2(ix, iy + 1);
  const d = hash2(ix + 1, iy + 1);
  const top = a + (b - a) * ux;
  const bottom = c + (d - c) * ux;
  return top + (bottom - top) * uy;
};

const resolveCssColors = (inputs: string[], host: HTMLElement): Rgba[] => {
  const probe = document.createElement("span");
  probe.style.display = "none";
  host.append(probe);

  const canvas = document.createElement("canvas");
  canvas.width = 1;
  canvas.height = 1;
  const context = canvas.getContext("2d", { willReadFrequently: true });

  const resolved = inputs.map((input, index) => {
    const fallback = FALLBACK_COLORS[index % FALLBACK_COLORS.length];
    if (!context) {
      return fallback;
    }
    probe.style.color = "";
    probe.style.color = toCssColor(input);
    const computed = window.getComputedStyle(probe).color;
    if (!computed) {
      return fallback;
    }
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = "#000000";
    context.fillStyle = computed;
    context.fillRect(0, 0, 1, 1);
    const { data } = context.getImageData(0, 0, 1, 1);
    const alpha = data[3] / RGB_MAX;
    if (alpha === 0) {
      return [data[0], data[1], data[2], 1] as Rgba;
    }
    return [
      Math.round(data[0] / alpha),
      Math.round(data[1] / alpha),
      Math.round(data[2] / alpha),
      alpha,
    ] as Rgba;
  });

  probe.remove();
  return resolved;
};

const mixChannel = (from: number, to: number, t: number) =>
  Math.round(from + (to - from) * t);

/**
 * Coverage → colour. Brightness travels through the ramp's lightness, not
 * through opacity alone, which is what makes the sampled word actually read
 * instead of looking like a dimmer patch of the same grey.
 */
const rampCss = (coverage: number, colors: Rgba[]) => {
  const field = colors[0] ?? FALLBACK_COLORS[0];
  const accent = colors[1] ?? colors[0] ?? FALLBACK_COLORS[1];
  const ink = colors[2] ?? accent;
  const low = coverage <= RAMP_MID;
  const from = low ? field : accent;
  const to = low ? accent : ink;
  const t = low
    ? coverage / RAMP_MID
    : (coverage - RAMP_MID) / (1 - RAMP_MID || 1);
  const fromAlpha = low ? FIELD_ALPHA : ACCENT_ALPHA;
  const toAlpha = low ? ACCENT_ALPHA : INK_ALPHA;
  const r = mixChannel(from[0], to[0], t);
  const g = mixChannel(from[1], to[1], t);
  const b = mixChannel(from[2], to[2], t);
  const a = (fromAlpha + (toAlpha - fromAlpha) * t) * (to[3] ?? 1);
  return `rgba(${r}, ${g}, ${b}, ${a.toFixed(3)})`;
};

const createFieldController = (
  canvas: HTMLCanvasElement
): FieldController | null => {
  const context = canvas.getContext("2d");
  if (!context) {
    return null;
  }

  const sampler = document.createElement("canvas");
  const samplerContext = sampler.getContext("2d", { willReadFrequently: true });

  let settings: FieldSettings = {
    cellSize: DEFAULT_CELL_SIZE,
    colors: FALLBACK_COLORS,
    fontFamily: DEFAULT_FONT_FAMILY,
    gap: DEFAULT_GAP,
    pointerRadius: DEFAULT_POINTER_RADIUS,
    pointerStrength: DEFAULT_POINTER_STRENGTH,
    scatterSeed: 0,
    shape: "square",
    source: null,
    speed: DEFAULT_SPEED,
    still: false,
    text: DEFAULT_TEXT,
    weight: DEFAULT_WEIGHT,
  };

  let width = 1;
  let height = 1;
  let cols = 1;
  let rows = 1;
  let count = 1;
  let step = DEFAULT_CELL_SIZE + DEFAULT_GAP;
  let cellPx = DEFAULT_CELL_SIZE;

  let mask = new Float32Array(1);
  let ampFactor = new Float32Array(1);
  let sizeBase = new Float32Array(1);
  let homeX = new Float32Array(1);
  let homeY = new Float32Array(1);
  let scatterX = new Float32Array(1);
  let scatterY = new Float32Array(1);
  let wakeX = new Float32Array(1);
  let wakeY = new Float32Array(1);
  let delay = new Float32Array(1);
  let latticeIndex = new Int32Array(1);
  let latticeWx = new Float32Array(1);
  let latticeWy = new Float32Array(1);

  let latCols = 2;
  let latRows = 2;
  let fieldU = new Float32Array(4);
  let fieldV = new Float32Array(4);

  let tiers: Int32Array[] = [];
  let tierCss: string[] = [];
  let sampleKey = "";

  let pointerX = 0;
  let pointerY = 0;
  let previousPointerX = 0;
  let previousPointerY = 0;
  let pointerActive = false;

  const startedAt = performance.now();
  let lastFrameAt = startedAt;
  let scatterAt = startedAt;
  let hasStarted = false;
  let frame = 0;
  let running = false;
  let destroyed = false;

  const allocate = () => {
    mask = new Float32Array(count);
    ampFactor = new Float32Array(count);
    sizeBase = new Float32Array(count);
    homeX = new Float32Array(count);
    homeY = new Float32Array(count);
    scatterX = new Float32Array(count);
    scatterY = new Float32Array(count);
    wakeX = new Float32Array(count);
    wakeY = new Float32Array(count);
    delay = new Float32Array(count);
    latticeIndex = new Int32Array(count);
    latticeWx = new Float32Array(count);
    latticeWy = new Float32Array(count);
  };

  /**
   * Rasterises the source once into a cols x rows bitmap — one pixel per cell —
   * and reads it back. Called only when the grid or the source changes, never
   * from the frame loop.
   */
  const sampleSource = () => {
    if (!samplerContext) {
      mask.fill(0);
      return;
    }
    sampler.width = cols;
    sampler.height = rows;
    samplerContext.clearRect(0, 0, cols, rows);

    const { source, text } = settings;
    let drewSource = false;

    if (source && source.naturalWidth > 0) {
      const scale = Math.min(
        cols / source.naturalWidth,
        rows / source.naturalHeight
      );
      const drawWidth = source.naturalWidth * scale;
      const drawHeight = source.naturalHeight * scale;
      try {
        samplerContext.drawImage(
          source,
          (cols - drawWidth) / 2,
          (rows - drawHeight) / 2,
          drawWidth,
          drawHeight
        );
        drewSource = true;
      } catch {
        // A source the browser refuses to draw leaves the text path in charge.
        drewSource = false;
      }
    }

    if (!drewSource && text.length > 0) {
      let fontSize = Math.max(rows * TEXT_HEIGHT_RATIO, 1);
      samplerContext.font = `${settings.weight} ${fontSize}px ${settings.fontFamily}`;
      const measured = samplerContext.measureText(text).width;
      const maxWidth = cols * TEXT_WIDTH_RATIO;
      if (measured > maxWidth && measured > 0) {
        fontSize = Math.max((fontSize * maxWidth) / measured, 1);
        samplerContext.font = `${settings.weight} ${fontSize}px ${settings.fontFamily}`;
      }
      samplerContext.fillStyle = "#ffffff";
      samplerContext.textAlign = "center";
      samplerContext.textBaseline = "middle";
      samplerContext.fillText(text, cols / 2, rows / 2);
    }

    let pixels: Uint8ClampedArray | null = null;
    try {
      pixels = samplerContext.getImageData(0, 0, cols, rows).data;
    } catch {
      // Tainted canvas (cross-origin image without CORS headers).
      pixels = null;
    }
    if (!pixels) {
      mask.fill(0);
      return;
    }

    const span = MASK_HIGH - MASK_LOW || 1;
    for (let i = 0; i < count; i++) {
      const p = i * 4;
      const luma =
        (pixels[p] * LUMA_R + pixels[p + 1] * LUMA_G + pixels[p + 2] * LUMA_B) /
        RGB_MAX;
      const coverage = (luma * pixels[p + 3]) / RGB_MAX;
      mask[i] = smoothstep(clamp((coverage - MASK_LOW) / span, 0, 1));
    }
  };

  const buildDerived = () => {
    for (let row = 0; row < rows; row++) {
      const ny = rows > 1 ? row / (rows - 1) : 0;
      const latY = row / LATTICE;
      const iy = Math.floor(latY);
      const wy = latY - iy;
      for (let col = 0; col < cols; col++) {
        const i = row * cols + col;
        const nx = cols > 1 ? col / (cols - 1) : 0;
        const m = mask[i];
        homeX[i] = (col + 0.5) * step;
        homeY[i] = (row + 0.5) * step;
        ampFactor[i] = 1 - m * WORD_CALM;
        sizeBase[i] = SIZE_FLOOR + SIZE_MASK * m;
        delay[i] = clamp(
          nx * DELAY_X +
            ny * DELAY_Y +
            hash2(col, row) * DELAY_JITTER -
            m * WORD_LEAD,
          0,
          1
        );
        const latX = col / LATTICE;
        const ix = Math.floor(latX);
        latticeIndex[i] = iy * latCols + ix;
        latticeWx[i] = latX - ix;
        latticeWy[i] = wy;
      }
    }
  };

  const buildScatter = (seed: number) => {
    const offset = (SCATTER_SPREAD - 1) / 2;
    for (let i = 0; i < count; i++) {
      const a = hash2(i + 1, seed * 1.7 + 3.1);
      const b = hash2(seed * 2.3 + 7.7, i + 1);
      scatterX[i] = (a * SCATTER_SPREAD - offset) * width;
      scatterY[i] = (b * SCATTER_SPREAD - offset) * height;
    }
  };

  const buildTiers = () => {
    const buckets: number[][] = Array.from({ length: TIER_COUNT }, () => []);
    for (let i = 0; i < count; i++) {
      const tier = Math.min(TIER_COUNT - 1, Math.floor(mask[i] * TIER_COUNT));
      buckets[tier].push(i);
    }
    tiers = buckets.map((bucket) => Int32Array.from(bucket));
    tierCss = buckets.map((_, tier) =>
      rampCss((tier + 0.5) / TIER_COUNT, settings.colors)
    );
  };

  const buildGrid = () => {
    step = Math.max(settings.cellSize + settings.gap, MIN_STEP);
    cellPx = settings.cellSize;
    cols = Math.max(1, Math.ceil(width / step));
    rows = Math.max(1, Math.ceil(height / step));

    // The word is fitted to a fraction of the column count, so too few columns
    // means too few cells per glyph and the word stops reading. On a narrow
    // surface the grid densifies instead, keeping the type legible.
    const legibleStep = Math.max(width / MIN_COLS, MIN_STEP);
    if (width >= MIN_COLS && legibleStep < step) {
      cellPx *= legibleStep / step;
      step = legibleStep;
      cols = Math.max(1, Math.ceil(width / step));
      rows = Math.max(1, Math.ceil(height / step));
    }

    // A dense grid over a large surface would blow the frame budget, so the
    // grid is coarsened rather than truncated — coverage stays complete.
    if (cols * rows > MAX_CELLS) {
      const scale = Math.sqrt((cols * rows) / MAX_CELLS);
      step *= scale;
      cellPx *= scale;
      cols = Math.max(1, Math.ceil(width / step));
      rows = Math.max(1, Math.ceil(height / step));
    }

    const nextCount = cols * rows;
    const resized = nextCount !== count;
    count = nextCount;
    latCols = Math.ceil(cols / LATTICE) + 2;
    latRows = Math.ceil(rows / LATTICE) + 2;

    if (resized) {
      allocate();
      fieldU = new Float32Array(latCols * latRows);
      fieldV = new Float32Array(latCols * latRows);
    } else if (fieldU.length !== latCols * latRows) {
      fieldU = new Float32Array(latCols * latRows);
      fieldV = new Float32Array(latCols * latRows);
    }

    const key = [
      cols,
      rows,
      settings.text,
      settings.weight,
      settings.fontFamily,
      settings.source?.src ?? "",
    ].join("|");
    if (key !== sampleKey) {
      sampleKey = key;
      sampleSource();
    }

    buildDerived();
    buildScatter(settings.scatterSeed);
    buildTiers();
  };

  const resize = () => {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    width = Math.max(1, rect.width);
    height = Math.max(1, rect.height);
    const pixelWidth = Math.max(1, Math.round(width * dpr));
    const pixelHeight = Math.max(1, Math.round(height * dpr));
    if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
      canvas.width = pixelWidth;
      canvas.height = pixelHeight;
    }
    context.setTransform(dpr, 0, 0, dpr, 0, 0);
    buildGrid();
  };

  /** Adds one cell to the current path around its centre. Never fills. */
  const traceCell = (cx: number, cy: number, size: number) => {
    const half = size / 2;
    if (settings.shape === "circle") {
      context.moveTo(cx + half, cy);
      context.arc(cx, cy, half, 0, TAU);
      return;
    }
    if (settings.shape === "cross") {
      const arm = size * CROSS_THICKNESS;
      context.rect(cx - half, cy - arm / 2, size, arm);
      context.rect(cx - arm / 2, cy - half, arm, size);
      return;
    }
    context.rect(cx - half, cy - half, size, size);
  };

  /** Refreshes the coarse flow lattice. O(cols + rows), not O(cells). */
  const updateFlowField = (time: number) => {
    for (let ly = 0; ly < latRows; ly++) {
      const gy = ly * LATTICE * NOISE_SCALE;
      const base = ly * latCols;
      for (let lx = 0; lx < latCols; lx++) {
        const gx = lx * LATTICE * NOISE_SCALE;
        const swirl = valueNoise(gx, gy + time);
        const strength = valueNoise(
          gx + NOISE_OFFSET_X,
          gy - time * NOISE_COUNTER_FLOW + NOISE_OFFSET_Y
        );
        const angle = swirl * TAU * FLOW_TURNS;
        const magnitude = MAG_FLOOR + MAG_RANGE * strength;
        fieldU[base + lx] = Math.cos(angle) * magnitude;
        fieldV[base + lx] = Math.sin(angle) * magnitude;
      }
    }
  };

  /** Stamps a decaying impulse into every cell inside the pointer radius. */
  const stampWake = (px: number, py: number, dt: number) => {
    const radius = Math.max(settings.pointerRadius, 1);
    const limit = radius * radius;
    const ceiling = step * WAKE_CEILING;
    const firstCol = clamp(Math.floor((px - radius) / step), 0, cols - 1);
    const lastCol = clamp(Math.ceil((px + radius) / step), 0, cols - 1);
    const firstRow = clamp(Math.floor((py - radius) / step), 0, rows - 1);
    const lastRow = clamp(Math.ceil((py + radius) / step), 0, rows - 1);

    for (let row = firstRow; row <= lastRow; row++) {
      const base = row * cols;
      for (let col = firstCol; col <= lastCol; col++) {
        const i = base + col;
        const dx = homeX[i] - px;
        const dy = homeY[i] - py;
        const squared = dx * dx + dy * dy;
        if (squared >= limit || squared === 0) {
          continue;
        }
        const distance = Math.sqrt(squared);
        const falloff = 1 - distance / radius;
        const push =
          falloff *
          falloff *
          settings.pointerStrength *
          radius *
          WAKE_GAIN *
          dt;
        wakeX[i] = clamp(wakeX[i] + (dx / distance) * push, -ceiling, ceiling);
        wakeY[i] = clamp(wakeY[i] + (dy / distance) * push, -ceiling, ceiling);
      }
    }
  };

  /**
   * Walks the segment the pointer covered since the previous frame so a fast
   * flick leaves a continuous trail instead of a dotted line of impacts.
   */
  const advanceWake = (dt: number) => {
    if (!pointerActive) {
      previousPointerX = pointerX;
      previousPointerY = pointerY;
      return;
    }
    const dx = pointerX - previousPointerX;
    const dy = pointerY - previousPointerY;
    const travel = Math.hypot(dx, dy);
    const steps = clamp(Math.ceil(travel / step), 1, MAX_SUBSTEPS);
    const slice = dt / steps;
    for (let s = 1; s <= steps; s++) {
      const t = s / steps;
      stampWake(previousPointerX + dx * t, previousPointerY + dy * t, slice);
    }
    previousPointerX = pointerX;
    previousPointerY = pointerY;
  };

  /** The one frame drawn when motion is reduced: grid at rest, word legible. */
  const drawResolved = () => {
    for (let tier = 0; tier < tiers.length; tier++) {
      const bucket = tiers[tier];
      if (bucket.length === 0) {
        continue;
      }
      context.fillStyle = tierCss[tier];
      context.beginPath();
      for (const i of bucket) {
        const size = cellPx * (sizeBase[i] + SIZE_FLOW * STILL_MAG);
        if (size > MIN_DRAW) {
          traceCell(homeX[i], homeY[i], size);
        }
      }
      context.fill();
    }
  };

  const drawFlowing = (reform: number, decay: number) => {
    const settled = reform >= 1;
    const rest = 1 / (1 - STAGGER);
    const drift = step * DRIFT_RATIO;

    for (let tier = 0; tier < tiers.length; tier++) {
      const bucket = tiers[tier];
      if (bucket.length === 0) {
        continue;
      }
      context.fillStyle = tierCss[tier];
      context.beginPath();

      for (const i of bucket) {
        const wx = wakeX[i] * decay;
        const wy = wakeY[i] * decay;
        wakeX[i] = wx;
        wakeY[i] = wy;

        const corner = latticeIndex[i];
        const tx = latticeWx[i];
        const ty = latticeWy[i];
        const below = corner + latCols;
        const uTop =
          fieldU[corner] + (fieldU[corner + 1] - fieldU[corner]) * tx;
        const uBottom =
          fieldU[below] + (fieldU[below + 1] - fieldU[below]) * tx;
        const vTop =
          fieldV[corner] + (fieldV[corner + 1] - fieldV[corner]) * tx;
        const vBottom =
          fieldV[below] + (fieldV[below + 1] - fieldV[below]) * tx;
        const u = uTop + (uBottom - uTop) * ty;
        const v = vTop + (vBottom - vTop) * ty;
        const magnitude = Math.abs(u) + Math.abs(v);

        const amplitude = drift * ampFactor[i];
        const restX = homeX[i] + u * amplitude + wx;
        const restY = homeY[i] + v * amplitude + wy;

        let x = restX;
        let y = restY;
        let scale = 1;
        if (!settled) {
          const local = clamp((reform - delay[i] * STAGGER) * rest, 0, 1);
          const inverse = 1 - local;
          // Ease-out cubic: cells decelerate into place instead of arriving
          // at a constant speed.
          const eased = 1 - inverse * inverse * inverse;
          x = scatterX[i] + (restX - scatterX[i]) * eased;
          y = scatterY[i] + (restY - scatterY[i]) * eased;
          scale = SCATTER_SIZE + (1 - SCATTER_SIZE) * eased;
        }

        const size = cellPx * (sizeBase[i] + SIZE_FLOW * magnitude) * scale;
        if (size <= MIN_DRAW) {
          continue;
        }
        if (x < -size || x > width + size) {
          continue;
        }
        if (y < -size || y > height + size) {
          continue;
        }
        traceCell(x, y, size);
      }
      context.fill();
    }
  };

  const draw = () => {
    if (destroyed) {
      return;
    }
    context.clearRect(0, 0, width, height);

    if (settings.still) {
      drawResolved();
      return;
    }

    const now = performance.now();
    const dt = clamp((now - lastFrameAt) / MS_PER_SECOND, 0, MAX_DT);
    lastFrameAt = now;

    const elapsed = (now - startedAt) / MS_PER_SECOND;
    updateFlowField(elapsed * settings.speed * TIME_SCALE);
    advanceWake(dt);

    const reform = clamp((now - scatterAt) / REFORM_MS, 0, 1);
    // Exponential decay, so the wake settles like momentum bleeding off
    // rather than fading on a straight line.
    drawFlowing(reform, Math.exp(-dt / WAKE_TAU));
  };

  const tick = () => {
    if (destroyed || !running) {
      return;
    }
    draw();
    frame = requestAnimationFrame(tick);
  };

  resize();

  return {
    destroy: () => {
      destroyed = true;
      running = false;
      cancelAnimationFrame(frame);
      context.setTransform(1, 0, 0, 1, 0, 0);
      context.clearRect(0, 0, canvas.width, canvas.height);
      canvas.width = 0;
      canvas.height = 0;
      sampler.width = 0;
      sampler.height = 0;
    },
    render: () => {
      resize();
      draw();
    },
    resize: () => {
      resize();
      if (!running) {
        draw();
      }
    },
    setPointer: (x: number, y: number, active: boolean) => {
      if (!pointerActive) {
        previousPointerX = x;
        previousPointerY = y;
      }
      pointerX = x;
      pointerY = y;
      pointerActive = active;
    },
    setRunning: (next: boolean) => {
      if (destroyed || running === next) {
        return;
      }
      running = next;
      if (next) {
        lastFrameAt = performance.now();
        if (!hasStarted) {
          // The reveal plays when the field first becomes visible, not while
          // it is still parked below the fold.
          hasStarted = true;
          scatterAt = lastFrameAt;
        }
        frame = requestAnimationFrame(tick);
      } else {
        cancelAnimationFrame(frame);
      }
    },
    setSettings: (next: FieldSettings) => {
      const rescatter = next.scatterSeed !== settings.scatterSeed;
      settings = next;
      buildGrid();
      if (rescatter) {
        scatterAt = performance.now();
        wakeX.fill(0);
        wakeY.fill(0);
      }
    },
  };
};

const PixelFlowField = ({
  cellSize = DEFAULT_CELL_SIZE,
  children,
  className,
  colors = DEFAULT_COLORS,
  gap = DEFAULT_GAP,
  paused = false,
  pointerRadius = DEFAULT_POINTER_RADIUS,
  pointerStrength = DEFAULT_POINTER_STRENGTH,
  scatter = 0,
  shape = "square",
  speed = DEFAULT_SPEED,
  src,
  text = DEFAULT_TEXT,
  weight = DEFAULT_WEIGHT,
}: PixelFlowFieldProps) => {
  const shouldReduceMotion = useReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controllerRef = useRef<FieldController | null>(null);
  const [isSupported, setIsSupported] = useState(true);
  const [isActive, setIsActive] = useState(false);
  const [resolvedColors, setResolvedColors] = useState<Rgba[]>(FALLBACK_COLORS);
  const [fontFamily, setFontFamily] = useState(DEFAULT_FONT_FAMILY);
  const [source, setSource] = useState<HTMLImageElement | null>(null);

  const colorKey = colors.join("|");

  useEffect(() => {
    const host = hostRef.current;
    if (!host) {
      return;
    }
    setResolvedColors(resolveCssColors(colorKey.split("|"), host));
  }, [colorKey]);

  // The sampled word should be set in the same typeface as the surrounding
  // page, so the family is read off the host instead of being hardcoded.
  useEffect(() => {
    const host = hostRef.current;
    if (!host) {
      return;
    }
    let cancelled = false;
    const read = () => {
      if (!cancelled) {
        setFontFamily(window.getComputedStyle(host).fontFamily);
      }
    };
    read();
    document.fonts.ready.then(read).catch(() => {
      // A font that never resolves just leaves the fallback family in place.
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!src) {
      setSource(null);
      return;
    }
    let cancelled = false;
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.decoding = "async";
    image.onload = () => {
      if (!cancelled) {
        setSource(image);
      }
    };
    image.onerror = () => {
      if (!cancelled) {
        setSource(null);
      }
    };
    image.src = src;
    return () => {
      cancelled = true;
    };
  }, [src]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const controller = createFieldController(canvas);
    controllerRef.current = controller;
    setIsSupported(controller !== null);
    if (!controller) {
      return;
    }

    const observer = new ResizeObserver(() => controller.resize());
    observer.observe(canvas);

    return () => {
      observer.disconnect();
      controller.destroy();
      controllerRef.current = null;
    };
  }, []);

  useEffect(() => {
    const host = hostRef.current;
    if (!(host && isSupported)) {
      return;
    }

    let isOnScreen = true;
    const sync = () => {
      setIsActive(isOnScreen && document.visibilityState === "visible");
    };

    const observer = new IntersectionObserver((entries) => {
      isOnScreen = entries.some((entry) => entry.isIntersecting);
      sync();
    });
    observer.observe(host);
    document.addEventListener("visibilitychange", sync);
    sync();

    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", sync);
    };
  }, [isSupported]);

  useEffect(() => {
    const controller = controllerRef.current;
    if (!controller) {
      return;
    }
    controller.setSettings({
      cellSize: Math.max(cellSize, MIN_STEP),
      colors: resolvedColors,
      fontFamily,
      gap: Math.max(gap, 0),
      pointerRadius: Math.max(pointerRadius, 1),
      pointerStrength: clamp(pointerStrength, 0, 1),
      scatterSeed: scatter,
      shape,
      source,
      speed: Math.max(speed, 0),
      still: shouldReduceMotion === true,
      text,
      weight,
    });
    controller.render();
  }, [
    cellSize,
    fontFamily,
    gap,
    pointerRadius,
    pointerStrength,
    resolvedColors,
    scatter,
    shape,
    shouldReduceMotion,
    source,
    speed,
    text,
    weight,
  ]);

  useEffect(() => {
    const controller = controllerRef.current;
    if (!controller) {
      return;
    }
    const shouldRun = isActive && !paused && !shouldReduceMotion;
    controller.setRunning(shouldRun);
    if (!shouldRun) {
      controller.render();
    }
  }, [isActive, paused, shouldReduceMotion]);

  useEffect(() => {
    const host = hostRef.current;
    const canvas = canvasRef.current;
    if (!(host && canvas) || shouldReduceMotion) {
      return;
    }

    // Pointer events, not hover: a touch drag has to leave a wake too.
    const track = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      controllerRef.current?.setPointer(
        event.clientX - rect.left,
        event.clientY - rect.top,
        true
      );
    };
    const release = () => {
      controllerRef.current?.setPointer(0, 0, false);
    };

    host.addEventListener("pointermove", track, { passive: true });
    host.addEventListener("pointerdown", track, { passive: true });
    host.addEventListener("pointerleave", release);
    host.addEventListener("pointercancel", release);

    return () => {
      host.removeEventListener("pointermove", track);
      host.removeEventListener("pointerdown", track);
      host.removeEventListener("pointerleave", release);
      host.removeEventListener("pointercancel", release);
    };
  }, [shouldReduceMotion]);

  const fallbackColor = toCssColor(colors[1] ?? colors[0] ?? DEFAULT_COLORS[1]);
  const fallbackStep = Math.max(cellSize + gap, MIN_STEP);

  return (
    <div
      className={cn("relative isolate overflow-hidden", className)}
      ref={hostRef}
    >
      {isSupported ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        >
          <canvas className="h-full w-full" ref={canvasRef} />
        </div>
      ) : (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 opacity-40"
          style={{
            backgroundImage: `radial-gradient(${fallbackColor} 1px, transparent 1px)`,
            backgroundSize: `${fallbackStep}px ${fallbackStep}px`,
          }}
        />
      )}
      <div className="relative z-10 h-full">{children}</div>
    </div>
  );
};

