  actionHref,
  onActionClick,
  meta,
  className = "",
  side = "top",
  align = "center",
}: RichTooltipProps) {
  const shouldReduceMotion = useReducedMotion();
  const Title = (
    <div className="flex items-center gap-2 font-medium text-sm">
      {icon ?? <YouTubeIcon />}
      {href ? (
        <a
          className="inline-flex items-center gap-1 hover:underline"
          href={href}
          rel="noopener noreferrer"
          target="_blank"
        >
          <span>{title}</span>
          <ExternalLink className="h-3.5 w-3.5 opacity-70" />
        </a>
      ) : (
        <span>{title}</span>
      )}
    </div>
  );

  const renderAction = () => {
    if (!actionLabel) {
      return null;
    }

    const actionClassName =
      "inline-flex items-center gap-2 rounded-full bg-white px-3 py-2 font-medium text-black text-xs transition-colors hover:bg-white/90";

    if (actionHref) {
      return (
        <a
          className={actionClassName}
          href={actionHref}
          rel="noopener noreferrer"
          target="_blank"
        >
          <Play className="h-3.5 w-3.5" /> {actionLabel}
        </a>
      );
    }

    return (
      <button className={actionClassName} onClick={onActionClick} type="button">
        <Play className="h-3.5 w-3.5" /> {actionLabel}
      </button>
    );
  };

  const Action = renderAction();

  return (
    <PopoverRoot>
      <PopoverTrigger asChild>{trigger}</PopoverTrigger>
      <PopoverPortal>
        <PopoverContent
          align={align}
          asChild
          className={`z-50 ${className}`}
          side={side}
          sideOffset={8}
        >
          <motion.div
            animate={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(0px)", opacity: 1, scale: 1, y: 0 }
            }
            className="relative rounded-2xl border border-white/10 bg-black px-4 py-3 text-white shadow-xl"
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { filter: "blur(8px)", opacity: 0, scale: 0.95, y: 5 }
            }
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(8px)", opacity: 0, scale: 0.95, y: 5 }
            }
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : {
                    damping: 30,
                    duration: 0.2,
                    stiffness: 500,
                    type: "spring" as const,
                  }
            }
          >
            {Title}
            {description ? (
              <p className="mt-3 max-w-xs text-balance text-base text-white/90 leading-relaxed">
                {description}
              </p>
            ) : null}
            {meta || Action ? (
              <div className="mt-4 flex items-center justify-between gap-3">
                {meta ? (
                  <span className="inline-flex items-center gap-1 rounded-full bg-white/10 px-3 py-1 text-white text-xs">
                    <Clock className="h-3.5 w-3.5" /> {meta}
                  </span>
                ) : (
                  <span />
                )}
                {Action}
              </div>
            ) : null}

            {/* Tail */}
            <PopoverArrow className="fill-black" />
          </motion.div>
        </PopoverContent>
      </PopoverPortal>
    </PopoverRoot>
  );
}

"use client";

import { motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useMemo, useRef, useState } from "react";

export type RollingTextDirection = "up" | "down";
export type RollingTextTrigger = "mount" | "inView" | "hover" | "manual";

export interface RollingTextProps {
  className?: string;
  /** Direction the glyph column rolls in before landing. */
  direction?: RollingTextDirection;
  /** Roll duration per character, in milliseconds. */
  duration?: number;
  /**
   * Ramp alphabet cycled through before landing on the target character.
   * Defaults to the unique characters found in `text`.
   */
  glyphs?: string;
  /** Plays the roll when `trigger` is "manual" and this flips to `true`. */
  playing?: boolean;
  /** Number of intermediate glyphs shown before the target lands. */
  rampLength?: number;
  /** Per-character stagger, in milliseconds. */
  stagger?: number;
  text: string;
  trigger?: RollingTextTrigger;
}

interface RollingCharacter {
  isWhitespace: boolean;
  items: string[];
  key: string;
  targetIndex: number;
}

const DEFAULT_DURATION = 500;
const DEFAULT_STAGGER = 40;
const DEFAULT_RAMP_LENGTH = 4;
const MS = 1000;
const PERCENT = 100;
const DEFAULT_GLYPH_POOL =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
const MOVEMENT_EASE = [0.645, 0.045, 0.355, 1] as const;

const segmentGraphemes = (value: string): string[] => {
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const segmenter = new Intl.Segmenter(undefined, {
      granularity: "grapheme",
    });
    return Array.from(segmenter.segment(value), (entry) => entry.segment);
  }
  return [...value];
};

const buildGlyphPool = (text: string, glyphs?: string): string[] => {
  if (glyphs && glyphs.length > 0) {
    return segmentGraphemes(glyphs);
  }
  const unique = Array.from(
    new Set(segmentGraphemes(text).filter((char) => char.trim().length > 0))
  );
  return unique.length > 1 ? unique : segmentGraphemes(DEFAULT_GLYPH_POOL);
};

const buildRamp = (
  target: string,
  pool: string[],
  rampLength: number,
  direction: RollingTextDirection
): string[] => {
  const randomGlyphs = Array.from(
    { length: rampLength },
    () => pool[Math.floor(Math.random() * pool.length)] ?? target
  );
  const ramp = [...randomGlyphs, target];
  return direction === "down" ? ramp.reverse() : ramp;
};

const buildCharacters = (
  text: string,
  pool: string[],
  rampLength: number,
  direction: RollingTextDirection
): RollingCharacter[] => {
  const occurrences = new Map<string, number>();
  return segmentGraphemes(text).map((char) => {
    const count = occurrences.get(char) ?? 0;
    occurrences.set(char, count + 1);
    const isWhitespace = char.trim().length === 0;
    const items = isWhitespace
      ? [char]
      : buildRamp(char, pool, rampLength, direction);
    return {
      isWhitespace,
      items,
      key: `${char}-${count}`,
      targetIndex: direction === "down" ? 0 : items.length - 1,
    };
  });
};

/**
 * RollingText — odometer-style vertical roll. Each character cycles
 * through a short ramp of glyphs, like a split-flap display, before
 * landing on its target.
 */
export default function RollingText({
  text,
  className,
  direction = "up",
  duration = DEFAULT_DURATION,
  glyphs,
  playing = false,
  rampLength = DEFAULT_RAMP_LENGTH,
  stagger = DEFAULT_STAGGER,
  trigger = "mount",
}: RollingTextProps) {
  const containerRef = useRef<HTMLSpanElement>(null);
  const inView = useInView(containerRef, { once: true });
  const shouldReduceMotion = useReducedMotion();
  const [playCount, setPlayCount] = useState(() =>
    trigger === "mount" ? 1 : 0
  );
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const wasPlayingRef = useRef(playing);

  useEffect(() => {
    const hoverQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(hoverQuery.matches);
    const handleHoverChange = (event: MediaQueryListEvent) => {
      setIsHoverDevice(event.matches);
    };
    hoverQuery.addEventListener("change", handleHoverChange);
    return () => hoverQuery.removeEventListener("change", handleHoverChange);
  }, []);

  useEffect(() => {
    if (trigger === "inView" && inView && !shouldReduceMotion) {
      setPlayCount((count) => count + 1);
    }
  }, [trigger, inView, shouldReduceMotion]);

  useEffect(() => {
    if (
      trigger === "manual" &&
      playing &&
      !wasPlayingRef.current &&
      !shouldReduceMotion
    ) {
      setPlayCount((count) => count + 1);
    }
    wasPlayingRef.current = playing;
  }, [trigger, playing, shouldReduceMotion]);

  const pool = useMemo(() => buildGlyphPool(text, glyphs), [text, glyphs]);
  const characters = useMemo(
    () => buildCharacters(text, pool, rampLength, direction),
    [text, pool, rampLength, direction, playCount]
  );

  const handlePointerEnter = () => {
    if (trigger === "hover" && isHoverDevice && !shouldReduceMotion) {
      setPlayCount((count) => count + 1);
    }
  };

  if (shouldReduceMotion) {
    return <span className={className}>{text}</span>;
  }

  return (
    <span
      className={className}
      onPointerEnter={handlePointerEnter}
      ref={containerRef}
    >
      {/* Every glyph below is aria-hidden, so the readable copy lives here. An
          aria-label on this plain span would be dropped by assistive tech. */}
      <span className="sr-only">{text}</span>
      {characters.map((character, characterIndex) =>
        character.isWhitespace ? (
          <span
            aria-hidden="true"
            key={character.key}
            style={{ display: "inline-block", whiteSpace: "pre" }}
          >
            {character.items[0]}
          </span>
        ) : (
          <span
            aria-hidden="true"
            key={character.key}
            style={{
              display: "inline-block",
              height: "1em",
              lineHeight: "1em",
              overflow: "hidden",
              verticalAlign: "bottom",
            }}
          >
            <motion.span
              animate={{
                y: `${-(character.targetIndex / character.items.length) * PERCENT}%`,
              }}
              initial={{
                y:
                  direction === "down"
                    ? `${-((character.items.length - 1) / character.items.length) * PERCENT}%`
                    : "0%",
              }}
              key={playCount}
              style={{ display: "flex", flexDirection: "column" }}
              transition={{
                delay: (characterIndex * stagger) / MS,
                duration: duration / MS,
                ease: MOVEMENT_EASE,
              }}
            >
              {character.items.map((glyph, glyphIndex) => (
                <span
                  // biome-ignore lint/suspicious/noArrayIndexKey: ramp glyphs have no stable id
                  key={glyphIndex}
                  style={{
                    display: "block",
                    height: "1em",
                    lineHeight: "1em",
                  }}
                >
                  {glyph}
                </span>
              ))}
            </motion.span>
          </span>
        )
      )}
    </span>
  );
}

"use client";

import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";

export interface ScaleDownFadeProps {
  children: string;
  className?: string;
  /** Delay before the animation starts, in milliseconds. */
  delay?: number;
  /** Animate only once the text scrolls into view. */
  triggerOnView?: boolean;
}

const DURATION_S = 0.52;
const MS = 1000;
const EASE = [0.22, 1, 0.36, 1] as const;

/**
 * ScaleDownFade — subtle premium settle-in where the text enters slightly
 * scaled up and drifts down to its natural size. The whole text animates as
 * a single element. From the animate-text catalog (`scale-down-fade`).
 * Safe default for product UIs where copy should feel polished but not animated.
 */
export default function ScaleDownFade({
  children,
  className = "",
  delay = 0,
  triggerOnView = false,
}: ScaleDownFadeProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true });
  const shouldReduceMotion = useReducedMotion();
  const play = (!triggerOnView || inView) && !shouldReduceMotion;

  return (
    <motion.span
      animate={play ? { opacity: 1, scale: 1, y: 0 } : undefined}
      aria-label={children}
      className={className}
      initial={
        shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 1.04, y: 8 }
      }
      ref={ref}
      style={{ display: "inline-block" }}
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : {
              delay: delay / MS,
              duration: DURATION_S,
              ease: EASE,
            }
      }
    >
      {children}
    </motion.span>
  );
}

"use client";

import type React from "react";
import { useEffect, useRef, useState } from "react";

export interface ScrambleHoverProps {
  children: string;
  className?: string;
  duration?: number; // total animation duration in ms
  speed?: number; // interval between scrambles in ms
}

const CHARACTERS =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=<>?".split(
    ""
  );

function scrambleText(original: string) {
  return original
    .split("")
    .map((char) =>
      char === " "
        ? " "
        : CHARACTERS[Math.floor(Math.random() * CHARACTERS.length)]
    )
    .join("");
}

const ScrambleHover: React.FC<ScrambleHoverProps> = ({
  children,
  duration = 600,
  speed = 30,
  className = "",
}) => {
  const [display, setDisplay] = useState(children);
  const [shouldReduceMotion, setShouldReduceMotion] = useState(false);
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    const hoverQuery = window.matchMedia("(hover: hover) and (pointer: fine)");

    setShouldReduceMotion(motionQuery.matches);
    setIsHoverDevice(hoverQuery.matches);

    const handleMotionChange = (e: MediaQueryListEvent) => {
      setShouldReduceMotion(e.matches);
    };
    const handleHoverChange = (e: MediaQueryListEvent) => {
      setIsHoverDevice(e.matches);
    };

    motionQuery.addEventListener("change", handleMotionChange);
    hoverQuery.addEventListener("change", handleHoverChange);

    return () => {
      motionQuery.removeEventListener("change", handleMotionChange);
      hoverQuery.removeEventListener("change", handleHoverChange);
    };
  }, []);

  const handleMouseEnter = () => {
    if (shouldReduceMotion || !isHoverDevice) {
      return;
    }
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    intervalRef.current = setInterval(() => {
      setDisplay(() => scrambleText(children));
    }, speed);
    timeoutRef.current = setTimeout(() => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
      setDisplay(children);
    }, duration);
  };

  const handleMouseLeave = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setDisplay(children);
  };

  return (
    <button
      className={className}
      onBlur={handleMouseLeave}
      onFocus={isHoverDevice ? handleMouseEnter : undefined}
      onMouseEnter={isHoverDevice ? handleMouseEnter : undefined}
      onMouseLeave={handleMouseLeave}
      style={{
        background: "none",
        border: "none",
        color: "inherit",
        cursor: "pointer",
        display: "inline-block",
        font: "inherit",
        padding: 0,
        textAlign: "inherit",
      }}
      type="button"
    >
      {display}
    </button>
  );
};

export default ScrambleHover;

"use client";

import { cn } from "@/lib/utils";
import {
  motion,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import { type RefObject, useRef } from "react";

/** Motion scroll offset tuple, typed from `useScroll` itself. */
export type ScrollOffset = NonNullable<
  Parameters<typeof useScroll>[0]
>["offset"];

const DEFAULT_PARALLAX_PX = 60;
const CIRCLE_MAX_RADIUS_PERCENT = 90;
const BLIND_BAND_SIZE_PX = 40;
const SCALE_START = 1.12;
const FULL_SCALE = 1;
const FULL_OPACITY = 1;
const REVEAL_SPEED_MULTIPLIER = 2.5;
const SPRING_CONFIG = { damping: 32, mass: 0.4, stiffness: 260 } as const;
// The payoff has to land while the frame is still comfortably in view. Running
// the full enter-to-exit range finishes the reveal as the element leaves, so
// the moment it was built for happens off-screen.
const DEFAULT_OFFSET: ScrollOffset = ["start 0.9", "end 0.6"];
const DEFAULT_ROUNDED = "rounded-2xl";
const NO_CLIP = "inset(0% 0% 0% 0%)";

export type ScrollImageRevealMask =
  | "wipe"
  | "curtain"
  | "circle"
  | "blinds"
  | "scale";

export type ScrollImageRevealDirection = "left" | "right" | "up" | "down";

export interface ScrollImageRevealProps {
  /** Accessible description of the image. Required. */
  alt: string;
  className?: string;
  /** Ref to a scrollable ancestor that drives progress instead of the window. */
  container?: RefObject<HTMLElement | null>;
  /** Reveal direction. Only left/right apply to "wipe" and "blinds"; only up/down apply to "curtain". */
  direction?: ScrollImageRevealDirection;
  mask?: ScrollImageRevealMask;
  /** Motion `useScroll` offset tuple, e.g. ["start end", "end start"]. */
  offset?: ScrollOffset;
  /** Freeze the reveal once fully open instead of re-hiding on scroll-up. */
  once?: boolean;
  /** Counter-parallax travel of the image, in pixels. */
  parallax?: number;
  /** Tailwind rounded-* class applied to the frame. */
  rounded?: string;
  src: string;
}

const clampUnit = (value: number) => Math.min(1, Math.max(0, value));

const buildClipPath = (
  mask: ScrollImageRevealMask,
  direction: ScrollImageRevealDirection,
  progress: number
): string => {
  const hiddenPercent = clampUnit(1 - progress) * 100;

  if (mask === "wipe") {
    return direction === "right"
      ? `inset(0% 0% 0% ${hiddenPercent}%)`
      : `inset(0% ${hiddenPercent}% 0% 0%)`;
  }

  if (mask === "curtain") {
    return direction === "down"
      ? `inset(${hiddenPercent}% 0% 0% 0%)`
      : `inset(0% 0% ${hiddenPercent}% 0%)`;
  }

  if (mask === "circle") {
    const radius = clampUnit(progress) * CIRCLE_MAX_RADIUS_PERCENT;
    return `circle(${radius}% at 50% 50%)`;
  }

  return NO_CLIP;
};

const buildBlindsMask = (
  direction: ScrollImageRevealDirection,
  progress: number
): string => {
  const revealPx = clampUnit(progress) * BLIND_BAND_SIZE_PX;
  const axis =
    direction === "left" || direction === "right" ? "to right" : "to bottom";

  return `repeating-linear-gradient(${axis}, #000 0px, #000 ${revealPx}px, transparent ${revealPx}px, transparent ${BLIND_BAND_SIZE_PX}px)`;
};

export default function ScrollImageReveal({
  src,
  alt,
  mask = "wipe",
  direction = "left",
  parallax = DEFAULT_PARALLAX_PX,
  offset = DEFAULT_OFFSET,
  container,
  once = false,
  rounded = DEFAULT_ROUNDED,
  className,
}: ScrollImageRevealProps) {
  const ref = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const maxRevealRef = useRef(0);

  const { scrollYProgress } = useScroll({ container, offset, target: ref });
  const baseSpring = useSpring(scrollYProgress, SPRING_CONFIG);

  const revealProgress = useTransform(baseSpring, (latest) => {
    const scaled = clampUnit(latest * REVEAL_SPEED_MULTIPLIER);
    if (!once) {
      return scaled;
    }
    maxRevealRef.current = Math.max(maxRevealRef.current, scaled);
    return maxRevealRef.current;
  });

  // The mask lives on the frame, not the image: the image is deliberately
  // taller than the frame so the parallax has somewhere to travel, and a clip
  // measured against that oversized box would never line up with the edges.
  const clipPath = useTransform(revealProgress, (latest) =>
    shouldReduceMotion || mask === "blinds" || mask === "scale"
      ? NO_CLIP
      : buildClipPath(mask, direction, latest)
  );

  const maskImage = useTransform(revealProgress, (latest) =>
    shouldReduceMotion || mask !== "blinds"
      ? "none"
      : buildBlindsMask(direction, latest)
  );

  // Scales *down* into place from an overscan, never up from smaller than the
  // frame — scaling up from 0.85 would expose the background at the edges.
  const scale = useTransform(revealProgress, (latest) =>
    shouldReduceMotion || mask !== "scale"
      ? FULL_SCALE
      : SCALE_START + (FULL_SCALE - SCALE_START) * clampUnit(latest)
  );

  const revealOpacity = useTransform(revealProgress, (latest) =>
    shouldReduceMotion || mask !== "scale" ? FULL_OPACITY : clampUnit(latest)
  );

  const overscan = shouldReduceMotion ? 0 : Math.abs(parallax);

  const parallaxY = useTransform(baseSpring, (latest) =>
    shouldReduceMotion ? 0 : overscan - latest * overscan * 2
  );

  return (
    <motion.div
      className={cn("relative overflow-hidden", rounded, className)}
      ref={ref}
      style={{
        clipPath,
        maskImage,
        WebkitMaskImage: maskImage,
      }}
    >
      <motion.img
        alt={alt}
        className="absolute inset-x-0 w-full object-cover"
        decoding="async"
        src={src}
        style={{
          // Overscan on both edges so the counter-parallax never drags the
          // image off its own frame and leaves a strip of background behind.
          height: `calc(100% + ${overscan * 2}px)`,
          opacity: revealOpacity,
          scale,
          top: -overscan,
          y: parallaxY,
        }}
      />
    </motion.div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  type MotionValue,
  motion,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import { type CSSProperties, type RefObject, useState } from "react";

const SPRING_CONFIG = { damping: 30, mass: 0.4, stiffness: 220 } as const;
const SEGMENT_SPRING = { bounce: 0.1, duration: 0.25 } as const;
const DEFAULT_RING_SIZE_PX = 56;
const DEFAULT_SEGMENTS = 8;
const SEGMENT_WIDTH_PX = 18;
const PERCENT_MULTIPLIER = 100;
const MIN_PERCENT = 0;
const MAX_PERCENT = 100;
const DEFAULT_THICKNESS = 4;
const TRACK_MIN_THICKNESS = 2;
/** Width of the brightened leading edge baked into the bar's own gradient. */
const LEADING_EDGE_STOP = "2.25rem";
/** Ring label font size as a fraction of the ring diameter. */
const RING_LABEL_SIZE_RATIO = 0.28;
/**
 * Digits carry no descender, so a numeral block centred on its line box reads
 * a hair low against a geometric centre like a ring. Nudging it up by a
 * fraction of an em restores the optical centre. Kept in em so it tracks the
 * figure size at any ring diameter.
 */
const NUMERAL_OPTICAL_LIFT = "-0.028em";

export type ScrollProgressVariant = "bar" | "ring" | "number" | "segments";
export type ScrollProgressPosition =
  | "top"
  | "bottom"
  | "fixed-corner"
  | "inline";

export interface ScrollProgressProps {
  className?: string;
  color?: string;
  /** Ref to a scrollable ancestor whose own scroll is measured instead of the window. */
  container?: RefObject<HTMLElement | null>;
  /**
   * Uses `position: sticky` (not `fixed`) so the indicator stays contained
   * within its scrollable ancestor instead of escaping to the viewport.
   * `inline` opts out of stickiness entirely — use it when you place the
   * indicator in your own header or footer bar.
   */
  position?: ScrollProgressPosition;
  /** Number of segments for the "segments" variant. */
  segments?: number;
  showLabel?: boolean;
  /** Diameter (px) of the "ring" variant. */
  size?: number;
  /** Spring-smooth the value. Ignored (always direct) when reduced motion is preferred. */
  smooth?: boolean;
  /** Bar height, ring/segment stroke width, in pixels. */
  thickness?: number;
  variant?: ScrollProgressVariant;
}

const POSITION_CLASSES: Record<ScrollProgressPosition, string> = {
  bottom: "sticky inset-x-0 bottom-0 z-40",
  "fixed-corner": "sticky inset-x-0 bottom-4 z-40 flex justify-end pr-4",
  inline: "relative",
  top: "sticky inset-x-0 top-0 z-40",
};

const clampPercent = (value: number) =>
  Math.min(MAX_PERCENT, Math.max(MIN_PERCENT, value));

const clampUnit = (value: number) => Math.min(1, Math.max(0, value));

interface PercentFigureProps {
  className?: string;
  /** Applied to the digits only, so the unit can stay muted beside them. */
  digitColor?: string;
  percent: number;
  style?: CSSProperties;
}

/**
 * The digits and the `%` are one typographic unit, not two stacked spans:
 * shared baseline, tabular figures so the block never reflows as it counts,
 * and a unit sized as a deliberate fraction of the figures rather than an
 * arbitrary small size.
 */
const PercentFigure = ({
  percent,
  digitColor,
  className,
  style,
}: PercentFigureProps) => (
  <span
    className={cn(
      "inline-flex items-baseline font-semibold leading-none tracking-tight",
      className
    )}
    style={style}
  >
    <span
      className="tabular-nums"
      style={digitColor ? { color: digitColor } : undefined}
    >
      {percent}
    </span>
    <span className="ml-[0.06em] font-medium text-[0.56em] text-muted-foreground leading-none">
      %
    </span>
  </span>
);

interface SegmentDashProps {
  color: string;
  index: number;
  segments: number;
  thickness: number;
  value: MotionValue<number>;
}

const SegmentDash = ({
  value,
  index,
  segments,
  thickness,
  color,
}: SegmentDashProps) => {
  const shouldReduceMotion = useReducedMotion();
  // Each pill owns one 1/segments slice of the range, so they fill strictly
  // one after another instead of all easing together.
  const fill = useTransform(value, (progress) =>
    clampUnit(progress * segments - index)
  );
  const springFill = useSpring(fill, SEGMENT_SPRING);

  return (
    <span
      className="relative block shrink-0 overflow-hidden rounded-full bg-foreground/12"
      style={{ height: thickness, width: SEGMENT_WIDTH_PX }}
    >
      <motion.span
        className="absolute inset-0 origin-left rounded-full"
        style={{
          backgroundColor: color,
          scaleX: shouldReduceMotion ? fill : springFill,
        }}
      />
    </span>
  );
};

export default function ScrollProgress({
  variant = "bar",
  position = "top",
  container,
  thickness = DEFAULT_THICKNESS,
  color = "var(--color-brand)",
  showLabel = false,
  segments = DEFAULT_SEGMENTS,
  size = DEFAULT_RING_SIZE_PX,
  smooth = true,
  className,
}: ScrollProgressProps) {
  const shouldReduceMotion = useReducedMotion();
  const { scrollYProgress } = useScroll({ container });
  const springValue = useSpring(scrollYProgress, SPRING_CONFIG);
  const value = shouldReduceMotion || !smooth ? scrollYProgress : springValue;

  const [percent, setPercent] = useState(0);
  useMotionValueEvent(value, "change", (latest) => {
    setPercent(Math.round(clampPercent(latest * PERCENT_MULTIPLIER)));
  });

  // The fill is full-width and slides in from the left instead of being
  // scaled: a translate leaves the gradient and the rounded cap undistorted,
  // so the leading edge is literally the end of the bar and can never drift
  // away from it the way a separately positioned glow could.
  const fillX = useTransform(
    value,
    (latest) => `${-PERCENT_MULTIPLIER * (1 - clampUnit(latest))}%`
  );

  const ariaProps = {
    "aria-label": "Reading progress",
    "aria-valuemax": MAX_PERCENT,
    "aria-valuemin": MIN_PERCENT,
    "aria-valuenow": percent,
    role: "progressbar" as const,
  };

  if (variant === "bar") {
    return (
      <div
        {...ariaProps}
        className={cn(POSITION_CLASSES[position], "w-full", className)}
      >
        <div
          className="w-full overflow-hidden rounded-full bg-foreground/12"
          style={{ height: Math.max(thickness, TRACK_MIN_THICKNESS) }}
        >
          <motion.div
            className="h-full w-full rounded-full"
            style={{
              backgroundImage: `linear-gradient(90deg, ${color} 0%, ${color} calc(100% - ${LEADING_EDGE_STOP}), color-mix(in oklab, ${color} 40%, white) 100%)`,
              x: fillX,
            }}
          />
        </div>
        {showLabel ? (
          <span className="sr-only">{`${percent}% read`}</span>
        ) : null}
      </div>
    );
  }

  if (variant === "ring") {
    const ringRadius = (size - thickness) / 2;

    return (
      <div
        {...ariaProps}
        className={cn(
          POSITION_CLASSES[position],
          "inline-flex shrink-0 items-center justify-center",
          className
        )}
      >
        <svg
          aria-hidden="true"
          className="-rotate-90"
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          width={size}
        >
          <circle
            className="text-foreground/12"
            cx={size / 2}
            cy={size / 2}
            fill="none"
            r={ringRadius}
            stroke="currentColor"
            strokeWidth={thickness}
          />
          <motion.circle
            cx={size / 2}
            cy={size / 2}
            fill="none"
            pathLength={1}
            r={ringRadius}
            stroke={color}
            strokeLinecap="round"
            strokeWidth={thickness}
            style={{ pathLength: value }}
          />
        </svg>
        {showLabel ? (
          // The figure block is centred as one unit inside the ring, then
          // lifted by the optical correction — geometric centring alone leaves
          // a descender-less numeral sitting low.
          <span className="pointer-events-none absolute inset-0 flex items-center justify-center">
            <PercentFigure
              className="text-foreground"
              percent={percent}
              style={{
                // `em` here resolves against the figure's own size, so the
                // correction scales with the ring.
                fontSize: size * RING_LABEL_SIZE_RATIO,
                transform: `translateY(${NUMERAL_OPTICAL_LIFT})`,
              }}
            />
          </span>
        ) : null}
      </div>
    );
  }

  if (variant === "number") {
    return (
      <div
        {...ariaProps}
        className={cn(
          POSITION_CLASSES[position],
          // Size lives on the root so a consumer's `text-*` class wins over it
          // and scales the figures with it.
          "inline-flex shrink-0 items-baseline text-4xl leading-none",
          className
        )}
      >
        <PercentFigure digitColor={color} percent={percent} />
        {showLabel ? (
          // Sits further from the figure than the `%` does, so the unit reads
          // as part of the number and the word reads as a separate label.
          <span className="ml-[0.9em] font-medium text-[0.3em] text-muted-foreground uppercase leading-none tracking-[0.08em]">
            read
          </span>
        ) : null}
      </div>
    );
  }

  return (
    <div
      {...ariaProps}
      className={cn(
        POSITION_CLASSES[position],
        "flex items-center gap-1.5",
        className
      )}
    >
      {Array.from({ length: segments }, (_, index) => (
        <SegmentDash
          color={color}
          index={index}
          key={`scroll-progress-segment-${index}`}
          segments={segments}
          thickness={thickness}
          value={value}
        />
      ))}
      {showLabel ? (
        // Fixed measure + tabular figures: the row must not shuffle sideways
        // every time the count gains a digit.
        <span className="ml-2 w-[3.25ch] text-right font-medium text-muted-foreground text-xs tabular-nums">
          {percent}%
        </span>
      ) : null}
    </div>
  );
}

"use client";

import {
  type MotionValue,
  motion,
  useReducedMotion,
  useScroll,
  useTransform,
} from "motion/react";
import { useRef } from "react";

const KEY_PREFIX_LENGTH = 3;

export interface ScrollRevealParagraphProps {
  className?: string;
  paragraph: string;
}

export default function ScrollRevealParagraph({
  paragraph,
  className = "",
}: ScrollRevealParagraphProps) {
  const container = useRef<HTMLParagraphElement>(null);
  const { scrollYProgress } = useScroll({
    offset: ["start 0.9", "start 0.25"],
    target: container,
  });

  const words = paragraph.split(" ");

  return (
    <p className={`text-lg leading-relaxed ${className}`} ref={container}>
      {words.map((word, i) => {
        const start = i / words.length;
        const end = start + 1 / words.length;
        return (
          <Word
            key={`word-${i}-${word.slice(0, KEY_PREFIX_LENGTH)}`}
            progress={scrollYProgress}
            range={[start, end]}
          >
            {word}
          </Word>
        );
      })}
    </p>
  );
}

interface WordProps {
  children: string;
  progress: MotionValue<number>;
  range: [number, number];
}

const Word = ({ children, progress, range }: WordProps) => {
  const shouldReduceMotion = useReducedMotion();
  const opacity = useTransform(
    progress,
    range,
    shouldReduceMotion ? [1, 1] : [0, 1]
  );

  return (
    <span className="relative mr-2 inline-block">
      {shouldReduceMotion ? null : (
        <span className="text-foreground/10">{children}</span>
      )}
      <motion.span
        className="absolute inset-0 text-foreground"
        style={{ opacity }}
      >
        {children}
      </motion.span>
    </span>
  );
};

"use client";

import { cn } from "@/lib/utils";
import { motion, useMotionValue, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

const SCROLL_TIMEOUT_OFFSET = 100;
const MIN_SCROLL_INTERVAL = 300;
const SCROLL_THRESHOLD = 20;
const TOUCH_SCROLL_THRESHOLD = 100;
const SCALE_FACTOR = 0.08;
const MIN_SCALE = 0.08;
const MAX_SCALE = 2;
const HOVER_SCALE_MULTIPLIER = 1.02;
const CARD_PADDING = 100;

interface CardItem {
  avatar: string;
  handle: string;
  href: string;
  id: string;
  image: string;
  imageAlt?: string;
  name: string;
}

export interface ScrollableCardStackProps {
  cardHeight?: number;
  className?: string;
  items: CardItem[];
  perspective?: number;
  transitionDuration?: number;
}

const ScrollableCardStack: React.FC<ScrollableCardStackProps> = ({
  items,
  cardHeight = 384,
  perspective = 1000,
  transitionDuration = 180,
  className,
}) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [isScrolling, setIsScrolling] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollY = useMotionValue(0);
  const lastScrollTime = useRef(0);
  const shouldReduceMotion = useReducedMotion();

  // Calculate the total number of items
  const totalItems = items.length;
  const maxIndex = totalItems - 1;

  // Constants for visual effects - matching reference code exactly
  const FRAME_OFFSET = -30;
  const FRAMES_VISIBLE_LENGTH = 3;
  const SNAP_DISTANCE = 50;

  // Clamp function from reference code - memoized to prevent recreation
  const clamp = useCallback(
    (val: number, [min, max]: [number, number]): number =>
      Math.min(Math.max(val, min), max),
    []
  );

  // Controlled scroll function to move exactly one card
  const scrollToCard = useCallback(
    (direction: 1 | -1) => {
      if (isScrolling) {
        return;
      }

      const now = Date.now();
      const timeSinceLastScroll = now - lastScrollTime.current;

      if (timeSinceLastScroll < MIN_SCROLL_INTERVAL) {
        return;
      }

      const newIndex = clamp(currentIndex + direction, [0, maxIndex]);

      if (newIndex !== currentIndex) {
        lastScrollTime.current = now;
        setIsScrolling(true);
        setCurrentIndex(newIndex);
        scrollY.set(newIndex * SNAP_DISTANCE);

        setTimeout(() => {
          setIsScrolling(false);
        }, transitionDuration + SCROLL_TIMEOUT_OFFSET);
      }
    },
    [currentIndex, maxIndex, scrollY, isScrolling, transitionDuration, clamp]
  );

  // Handle scroll events with improved responsiveness
  const handleScroll = useCallback(
    (deltaY: number) => {
      if (isDragging || isScrolling) {
        return;
      }

      if (Math.abs(deltaY) < SCROLL_THRESHOLD) {
        return;
      }

      const scrollDirection = deltaY > 0 ? 1 : -1;
      scrollToCard(scrollDirection);
    },
    [isDragging, isScrolling, scrollToCard]
  );

  // Handle wheel events
  const handleWheel = useCallback(
    (e: WheelEvent) => {
      e.preventDefault();
      handleScroll(e.deltaY);
    },
    [handleScroll]
  );

  // Handle keyboard navigation - improved with reference code logic
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (isScrolling) {
        return;
      }

      switch (e.key) {
        case "ArrowUp":
        case "ArrowLeft": {
          e.preventDefault();
          scrollToCard(-1);
          break;
        }
        case "ArrowDown":
        case "ArrowRight": {
          e.preventDefault();
          scrollToCard(1);
          break;
        }
        case "Home": {
          e.preventDefault();
          if (currentIndex !== 0) {
            setIsScrolling(true);
            setCurrentIndex(0);
            scrollY.set(0);
            setTimeout(() => {
              setIsScrolling(false);
            }, transitionDuration + SCROLL_TIMEOUT_OFFSET);
          }
          break;
        }
        case "End": {
          e.preventDefault();
          if (currentIndex !== maxIndex) {
            setIsScrolling(true);
            setCurrentIndex(maxIndex);
            scrollY.set(maxIndex * SNAP_DISTANCE);
            setTimeout(() => {
              setIsScrolling(false);
            }, transitionDuration + SCROLL_TIMEOUT_OFFSET);
          }
          break;
        }
        default: {
          // No action for other keys
          break;
        }
      }
    },
    [
      currentIndex,
      maxIndex,
      scrollY,
      isScrolling,
      scrollToCard,
      transitionDuration,
    ]
  );

  // Handle touch events for mobile
  const touchStartY = useRef(0);
  const touchStartIndex = useRef(0);
  const touchStartTime = useRef(0);
  const touchMoved = useRef(false);

  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      touchStartY.current = e.touches[0].clientY;
      touchStartIndex.current = currentIndex;
      touchStartTime.current = Date.now();
      touchMoved.current = false;
      setIsDragging(true);
    },
    [currentIndex]
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!isDragging || isScrolling) {
        return;
      }

      const touchY = e.touches[0].clientY;
      const deltaY = touchStartY.current - touchY;

      if (Math.abs(deltaY) > TOUCH_SCROLL_THRESHOLD && !touchMoved.current) {
        const scrollDirection = deltaY > 0 ? 1 : -1;
        scrollToCard(scrollDirection);
        touchMoved.current = true;
      }
    },
    [isDragging, isScrolling, scrollToCard]
  );

  const handleTouchEnd = useCallback(() => {
    setIsDragging(false);
    touchMoved.current = false;
  }, []);

  // Set up event listeners
  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    container.addEventListener("wheel", handleWheel, { passive: false });

    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, [handleWheel]);

  // Snap to current index when not dragging
  useEffect(() => {
    if (!isDragging) {
      scrollY.set(currentIndex * SNAP_DISTANCE);
    }
  }, [currentIndex, isDragging, scrollY]);

  // Calculate transform for each card based on the reference code
  const getCardTransform = useCallback(
    (index: number) => {
      const offsetIndex = index - currentIndex;

      // Apply blur effect for cards behind the current one - matching reference exactly
      const isBehindCurrent = currentIndex > index;
      const blur = !shouldReduceMotion && isBehindCurrent ? 2 : 0;

      // Opacity based on distance - improved logic from reference
      const opacity = currentIndex > index ? 0 : 1;

      // Scale with improved calculation inspired by reference - using clamp function
      const scale = shouldReduceMotion
        ? 1
        : clamp(1 - offsetIndex * SCALE_FACTOR, [MIN_SCALE, MAX_SCALE]);

      // Vertical offset with improved calculation - matching reference exactly
      const y = shouldReduceMotion
        ? 0
        : clamp(offsetIndex * FRAME_OFFSET, [
            FRAME_OFFSET * FRAMES_VISIBLE_LENGTH,
            Number.POSITIVE_INFINITY,
          ]);

      // Z-index for proper layering - matching reference pattern
      const zIndex = items.length - index;

      return {
        blur,
        opacity,
        scale,
        y,
        zIndex,
      };
    },
    [currentIndex, items.length, clamp, shouldReduceMotion]
  );

  return (
    <section
      aria-atomic="true"
      aria-label="Scrollable card stack"
      aria-live="polite"
      className={cn("relative mx-auto h-fit w-fit min-w-[300px]", className)}
    >
      {/* biome-ignore lint/a11y/noNoninteractiveElementInteractions: Interactive scrollable widget requires event handlers */}
      <div
        aria-label="Scrollable card container"
        className="h-full w-full"
        onKeyDown={handleKeyDown}
        onTouchEnd={handleTouchEnd}
        onTouchMove={handleTouchMove}
        onTouchStart={handleTouchStart}
        ref={containerRef}
        role="application"
        style={{
          minHeight: `${cardHeight + CARD_PADDING}px`, // Add some padding for the card stack effect
          perspective: `${perspective}px`,
          perspectiveOrigin: "center 60%",
          touchAction: "none",
        }}
        // biome-ignore lint/a11y/noNoninteractiveTabindex: Required for keyboard navigation
        tabIndex={0}
      >
        {items.map((item, i) => {
          const transform = getCardTransform(i);
          const isActive = i === currentIndex;
          const isHovered = hoveredIndex === i;

          return (
            <motion.div
              animate={
                shouldReduceMotion
                  ? { x: "-50%", y: "-50%" }
                  : {
                      scale: transform.scale,
                      x: "-50%",
                      y: `calc(-50% + ${transform.y}px)`,
                    }
              }
              aria-hidden={!isActive}
              className="absolute top-1/2 left-1/2 w-max max-w-[100vw] overflow-hidden rounded-2xl border bg-background shadow-lg"
              data-active={isActive}
              initial={false}
              key={`scrollable-card-${item.id}`}
              onBlur={() => setHoveredIndex(null)}
              onFocus={() => isActive && setHoveredIndex(i)}
              onMouseEnter={() => isActive && setHoveredIndex(i)}
              onMouseLeave={() => setHoveredIndex(null)}
              style={{
                // Dynamic border width based on scale - from reference code
                borderWidth: `${2 / transform.scale}px`,
                filter: `blur(${transform.blur}px)`,
                height: `${cardHeight}px`,
                opacity: transform.opacity,
                pointerEvents: isActive ? "auto" : "none",
                transformOrigin: "center center",
                transitionDuration: shouldReduceMotion ? "0ms" : "200ms",
                transitionProperty: shouldReduceMotion
                  ? "none"
                  : "opacity, filter",
                transitionTimingFunction:
                  "cubic-bezier(0.645, 0.045, 0.355, 1)",
                willChange: shouldReduceMotion
                  ? undefined
                  : "opacity, filter, transform",
                zIndex: transform.zIndex,
              }}
              tabIndex={isActive ? 0 : -1}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      damping: 20,
                      duration: 0.25,
                      mass: 0.5,
                      stiffness: 250,
                      type: "spring" as const,
                    }
              }
              whileHover={
                shouldReduceMotion || !isActive
                  ? {}
                  : {
                      scale: transform.scale * HOVER_SCALE_MULTIPLIER,
                      transition: {
                        damping: 20,
                        duration: 0.25,
                        mass: 0.5,
                        stiffness: 250,
                        type: "spring" as const,
                      },
                    }
              }
            >
              {/* Card Content */}
              <div
                className={cn(
                  "flex aspect-16/10 w-full flex-col rounded-xl bg-background transition-all duration-200",
                  isHovered && "shadow-xl",
                  isScrolling && isActive && "ring-2 ring-brand ring-opacity-50"
                )}
                style={{ height: `${cardHeight}px` }}
              >
                {/* Scroll indicator */}
                {isScrolling && isActive ? (
                  <div className="absolute -top-1 left-1/2 h-1 w-8 -translate-x-1/2 rounded-full bg-brand opacity-75" />
                ) : null}

                {/* Image Container - takes remaining space */}
                <div className="relative w-full flex-1 overflow-hidden">
                  {/* Background blur image */}
                  <img
                    alt=""
                    aria-hidden="true"
                    className="absolute inset-0 h-full w-full object-cover text-transparent"
                    decoding="async"
                    draggable={false}
                    height={10}
                    src="data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTAiIGhlaWdodD0iMTAiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+PHJlY3Qgd2lkdGg9IjEwIiBoZWlnaHQ9IjEwIiBmaWxsPSIjZjNmNGY2Ii8+PC9zdmc+"
                    style={{
                      filter: "blur(32px)",
                      pointerEvents: "none",
                      scale: "1.2",
                      zIndex: 1,
                    }}
                    width={10}
                  />
                  {/* Image */}
                  <img
                    alt={item.imageAlt ?? `${item.name}'s card`}
                    className="absolute inset-0 h-full w-full object-cover"
                    decoding="async"
                    draggable={false}
                    height={cardHeight}
                    src={item.image}
                    style={{
                      pointerEvents: "none",
                      userSelect: "none",
                      zIndex: 2,
                    }}
                    width={400}
                  />
                </div>

                {/* User Info - always at bottom */}
                <a
                  aria-label={`View ${item.name}'s profile`}
                  className={cn(
                    "flex items-center justify-center gap-1 bg-background/95 p-3 text-decoration-none text-inherit backdrop-blur-sm transition-colors duration-200"
                  )}
                  href={item.href}
                  rel="noopener noreferrer"
                  target="_blank"
                >
                  <img
                    alt={`${item.name}'s avatar`}
                    className="mr-1 h-5 w-5 overflow-hidden rounded-full"
                    draggable={false}
                    height={20}
                    src={item.avatar}
                    style={{
                      boxShadow: "0 0 0 1px var(--border-secondary, #e0e0e0)",
                    }}
                    width={20}
                  />
                  <span className="font-medium text-foreground text-sm leading-none">
                    {item.name}
                  </span>
                  <span className="font-normal text-foreground/70 text-sm">
                    {item.handle}
                  </span>
                </a>
              </div>
            </motion.div>
          );
        })}

        {/* Navigation indicators */}
        <div
          aria-label="Card navigation"
          className="absolute bottom-4 left-1/2 flex -translate-x-1/2 transform space-x-2"
          style={{ zIndex: items.length + 1 }}
          role="tablist"
        >
          {Array.from({ length: items.length }, (_, i) => (
            <motion.button
              aria-label={`Go to card ${i + 1} of ${items.length}`}
              aria-selected={i === currentIndex}
              className={cn(
                "h-2 w-2 cursor-pointer rounded-full transition-all duration-200 focus:outline-none focus:ring-1 focus:ring-brand focus:ring-offset-1",
                i === currentIndex
                  ? "scale-125 bg-brand"
                  : "bg-gray-300 hover:bg-gray-400"
              )}
              key={`scrollable-indicator-${items[i]?.id || i}`}
              onClick={() => {
                if (i !== currentIndex && !isScrolling) {
                  setIsScrolling(true);
                  setCurrentIndex(i);
                  scrollY.set(i * SNAP_DISTANCE);
                  setTimeout(() => {
                    setIsScrolling(false);
                  }, transitionDuration + SCROLL_TIMEOUT_OFFSET);
                }
              }}
              role="tab"
              transition={{
                damping: 20,
                mass: 0.5,
                stiffness: 250,
                type: "spring" as const,
              }}
              type="button"
              whileHover={{ scale: 1.2 }}
              whileTap={{ scale: 0.9 }}
            />
          ))}
        </div>

        {/* Instructions for screen readers */}
        <div aria-live="polite" className="sr-only">
          {`Card ${currentIndex + 1} of ${items.length} selected. Use arrow keys to navigate one card at a time, or click the dots below.`}
        </div>
      </div>
    </section>
  );
};

export default ScrollableCardStack;

"use client";

import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

export interface ScrubberProps {
  /** Additional CSS classes */
  className?: string;
  /** Number of decimal places to display */
  decimals?: number;
  /** Default value for uncontrolled usage */
  defaultValue?: number;
  /** Label displayed on the left side of the track */
  label?: string;
  /** Maximum value */
  max?: number;
  /** Minimum value */
  min?: number;
  /** Called when value changes during interaction */
  onValueChange?: (value: number) => void;
  /** Step increment */
  step?: number;
  /** Number of tick marks (0 to hide) */
  ticks?: number;
  /** Controlled value */
  value?: number;
}

const clamp = (val: number, min: number, max: number) =>
  Math.min(Math.max(val, min), max);

const roundToStep = (val: number, step: number, min: number) =>
  Math.round((val - min) / step) * step + min;

const Scrubber = ({
  label = "Value",
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  min = 0,
  max = 1,
  step = 0.01,
  decimals = 2,
  ticks = 9,
  className,
}: ScrubberProps) => {
  const shouldReduceMotion = useReducedMotion();
  const trackRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [isDragging, setIsDragging] = useState(false);
  const [isHovering, setIsHovering] = useState(false);
  const [isHoverDevice, setIsHoverDevice] = useState(false);

  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : internalValue;
  const range = max - min;
  const percentage = range > 0 ? ((value - min) / range) * 100 : 0;
  const isActive = isDragging || (isHoverDevice && isHovering);

  useEffect(() => {
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setIsHoverDevice(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const setValue = useCallback(
    (newValue: number) => {
      const clamped = clamp(roundToStep(newValue, step, min), min, max);
      if (!isControlled) {
        setInternalValue(clamped);
      }
      onValueChange?.(clamped);
    },
    [step, min, max, isControlled, onValueChange]
  );

  const getValueFromPointer = useCallback(
    (clientX: number) => {
      const track = trackRef.current;
      if (!track) {
        return value;
      }
      const rect = track.getBoundingClientRect();
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      return min + ratio * range;
    },
    [min, range, value]
  );

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      trackRef.current?.setPointerCapture(e.pointerId);
      setIsDragging(true);
      setValue(getValueFromPointer(e.clientX));
    },
    [getValueFromPointer, setValue]
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging) {
        return;
      }
      setValue(getValueFromPointer(e.clientX));
    },
    [isDragging, getValueFromPointer, setValue]
  );

  const handlePointerUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      let next: number | undefined;
      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          next = value + step;
          break;
        case "ArrowLeft":
        case "ArrowDown":
          next = value - step;
          break;
        case "Home":
          next = min;
          break;
        case "End":
          next = max;
          break;
        default:
          return;
      }
      e.preventDefault();
      setValue(next);
    },
    [value, step, min, max, setValue]
  );

  const springConfig = shouldReduceMotion
    ? { duration: 0 }
    : { bounce: 0.1, duration: 0.25, type: "spring" as const };

  return (
    <div className={cn("relative w-full select-none", className)}>
      <div
        aria-label={label}
        aria-valuemax={max}
        aria-valuemin={min}
        aria-valuenow={Number(value.toFixed(decimals))}
        className="relative cursor-pointer overflow-hidden bg-muted outline-offset-2"
        onKeyDown={handleKeyDown}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={trackRef}
        role="slider"
        style={{
          borderRadius: 8,
          height: 36,
          touchAction: "none",
        }}
        tabIndex={0}
      >
        {/* Fill indicator */}
        <div
          className="pointer-events-none absolute inset-y-0 left-0 bg-foreground/14"
          style={{
            borderRadius: 8,
            transition: isDragging
              ? "none"
              : "width 150ms cubic-bezier(0.23, 1, 0.32, 1)",
            width: `${percentage}%`,
          }}
        />

        {/* Tick marks */}
        {ticks > 0 && (
          <div className="pointer-events-none absolute inset-0">
            {Array.from({ length: ticks }, (_, i) => {
              const pos = ((i + 1) / (ticks + 1)) * 100;
              return (
                <div
                  className="absolute top-1/2 bg-foreground/25"
                  key={pos}
                  style={{
                    borderRadius: 999,
                    height: 6,
                    left: `${pos}%`,
                    transform: "translateX(-50%) translateY(-50%)",
                    width: 1,
                  }}
                />
              );
            })}
          </div>
        )}

        {/* Scrub bar (capsule thumb) */}
        <div
          className="pointer-events-none absolute"
          style={{
            left: `${percentage}%`,
            marginLeft: -5,
            top: "50%",
            transform: "translateX(-50%) translateY(-50%)",
            transition: isDragging
              ? "none"
              : "left 150ms cubic-bezier(0.23, 1, 0.32, 1)",
            zIndex: 3,
          }}
        >
          <motion.div
            animate={{
              opacity: isActive ? 0.8 : 0.15,
              scaleX: isActive ? 1 : 0.7,
              scaleY: isActive ? 1 : 0.7,
            }}
            className="bg-foreground/90"
            style={{
              borderRadius: 999,
              height: 22,
              width: 4,
            }}
            transition={springConfig}
          />
        </div>

        {/* Label */}
        <div
          className="pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 whitespace-nowrap text-foreground"
          style={{
            fontSize: 13,
            fontWeight: 500,
            zIndex: 4,
          }}
        >
          {label}
        </div>

        {/* Value display */}
        <div
          className="pointer-events-none absolute top-1/2 right-2.5 -translate-y-1/2 text-foreground"
          style={{
            fontFamily: "ui-monospace, monospace",
            fontSize: 13,
            fontVariantNumeric: "tabular-nums",
            fontWeight: 500,
            zIndex: 4,
          }}
        >
          {value.toFixed(decimals)}
        </div>
      </div>
    </div>
  );
};

export default Scrubber;

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

export type SdfBlobVariant = "circle" | "warped" | "merge" | "radial" | "final";

export interface SdfBlobTransitionProps {
  children: ReactNode;
  className?: string;
  duration?: number;
  onRest?: () => void;
  transitionKey: string | number;
  variant?: SdfBlobVariant;
}

const DEFAULT_DURATION_MS = 1120;
const MIDPOINT = 0.5;
const MAX_DPR = 2;
const VERTEX_SHADER =
  "attribute vec2 a; void main(){ gl_Position = vec4(a, 0.0, 1.0); }";
const FRAGMENT_SHADER = `
precision mediump float;
uniform vec2 uRes;
uniform float uTime;
uniform float uProgress;
uniform float uAlpha;
uniform float uVariant;
#define PI 3.14159265359

float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float noise(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float circleSdf(vec2 p, vec2 c, float r){ return length(p - c) - r; }
float smin(float a, float b, float k){
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

void main(){
  vec2 uv = gl_FragCoord.xy / uRes;
  vec2 aspect = vec2(uRes.x / uRes.y, 1.0);
  vec2 p = (uv - 0.5) * aspect;
  float progress = smoothstep(0.0, 1.0, uProgress);
  float grow = smoothstep(0.0, 0.86, progress);
  float exitFade = smoothstep(1.0, 0.72, progress);

  float wobble = noise(uv * 7.0 + uTime * 0.18) * 0.035;
  float ringNoise = noise(vec2(atan(p.y, p.x) * 2.0, uTime * 0.18)) * 0.075;
  float dCircle = circleSdf(p, vec2(0.0), 0.04 + grow * 0.64);
  float dWarped = circleSdf(p, vec2(0.0), 0.04 + grow * 0.62 + ringNoise * smoothstep(0.08, 0.96, progress));

  float m0 = circleSdf(p, vec2(-0.26, -0.08), 0.06 + grow * 0.42 + wobble);
  float m1 = circleSdf(p, vec2(0.24, 0.12), 0.06 + grow * 0.40 - wobble * 0.5);
  float dMerge = smin(m0, m1, 0.18);

  float angle = atan(p.y, p.x);
  float sector3 = 2.0 * PI / 3.0;
  float sector5 = 2.0 * PI / 5.0;
  float a3 = floor((angle + PI) / sector3 + 0.5) * sector3 - PI;
  float a5 = floor((angle + PI) / sector5 + 0.5) * sector5 - PI;
  float r0 = 0.17 + grow * 0.24;
  float r1 = 0.30 + grow * 0.18;
  float dR0 = circleSdf(p, vec2(cos(a3), sin(a3)) * r0, 0.04 + grow * 0.22 + wobble * 0.4);
  float dR1 = circleSdf(p, vec2(cos(a5), sin(a5)) * r1, 0.035 + grow * 0.18);
  float dRadial = smin(dR0, dR1, 0.14);

  float f0 = circleSdf(p, vec2(-0.28, -0.10), 0.08 + grow * 0.46 + wobble);
  float f1 = circleSdf(p, vec2(0.00, 0.16), 0.06 + grow * 0.42 - wobble * 0.5);
  float f2 = circleSdf(p, vec2(0.30, -0.06), 0.05 + grow * 0.40 + wobble * 0.6);
  float f3 = circleSdf(p, vec2(-0.02, -0.30), 0.04 + grow * 0.34);
  float dFinal = smin(smin(f0, f1, 0.18), smin(f2, f3, 0.16), 0.20);
  dFinal = smin(dFinal, dRadial, 0.16);

  float d = dFinal;
  if (uVariant < 0.5) {
    d = dCircle;
  } else if (uVariant < 1.5) {
    d = dWarped;
  } else if (uVariant < 2.5) {
    d = dMerge;
  } else if (uVariant < 3.5) {
    d = dRadial;
  }

  float edge = exp(-d * d * 160.0) * exitFade;
  float fill = smoothstep(0.08, -0.10, d) * smoothstep(0.0, 0.18, progress) * exitFade;
  float cell = hash(floor((uv + noise(uv * 11.0) * 0.01) * uRes / 7.0) + floor(uTime * 10.0));
  float flecks = step(0.78, cell) * edge * 0.22 * smoothstep(1.5, 4.0, uVariant);

  vec3 rose = vec3(1.0, 0.23, 0.58);
  vec3 apricot = vec3(1.0, 0.70, 0.38);
  vec3 mint = vec3(0.42, 0.94, 0.78);
  vec3 color = mix(rose, apricot, smoothstep(-0.35, 0.35, p.x + noise(uv * 5.0) * 0.18));
  color = mix(color, mint, smoothstep(0.12, 0.7, p.y + grow * 0.16));

  float alpha = (fill * 0.24 + edge * 0.72 + flecks) * uAlpha;
  gl_FragColor = vec4(color * alpha + vec3(1.0) * edge * 0.18 * uAlpha, clamp(alpha, 0.0, 0.9));
}
`;
const STRIP = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

interface Playback {
  cancel: () => void;
}
interface Controller {
  destroy: () => void;
  setAlpha: (alpha: number) => void;
  setProgress: (progress: number) => void;
  setVariant: (variant: SdfBlobVariant) => void;
}

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const easeOutQuart = (value: number) => 1 - (1 - value) ** 4;
const easeInOutCubic = (value: number) =>
  value < 0.5 ? 4 * value ** 3 : 1 - (-2 * value + 2) ** 3 / 2;

const compile = (gl: WebGLRenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

const resize = (canvas: HTMLCanvasElement, gl: WebGLRenderingContext) => {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
  const width = Math.max(1, Math.round(rect.width * dpr));
  const height = Math.max(1, Math.round(rect.height * dpr));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
  gl.viewport(0, 0, width, height);
};

const variantToUniform = (variant: SdfBlobVariant) => {
  switch (variant) {
    case "circle":
      return 0;
    case "warped":
      return 1;
    case "merge":
      return 2;
    case "radial":
      return 3;
    default:
      return 4;
  }
};

const createController = (
  canvas: HTMLCanvasElement,
  initialVariant: SdfBlobVariant
): Controller | null => {
  const gl = canvas.getContext("webgl", {
    alpha: true,
    antialias: false,
    premultipliedAlpha: true,
  });
  if (!gl) {
    return null;
  }
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  const program = gl.createProgram();
  if (!(vertex && fragment && program)) {
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }

  // biome-ignore lint/correctness/useHookAtTopLevel: WebGLRenderingContext.useProgram is not a React hook.
  gl.useProgram(program);
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, STRIP, gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, "a");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

  const uRes = gl.getUniformLocation(program, "uRes");
  const uTime = gl.getUniformLocation(program, "uTime");
  const uProgress = gl.getUniformLocation(program, "uProgress");
  const uAlpha = gl.getUniformLocation(program, "uAlpha");
  const uVariant = gl.getUniformLocation(program, "uVariant");
  const startedAt = performance.now();
  let progress = 0;
  let alpha = 0;
  let variant = initialVariant;
  let frame = 0;
  let destroyed = false;

  const tick = () => {
    if (destroyed) {
      return;
    }
    resize(canvas, gl);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(uRes, canvas.width, canvas.height);
    gl.uniform1f(uTime, (performance.now() - startedAt) / 1000);
    gl.uniform1f(uProgress, progress);
    gl.uniform1f(uAlpha, alpha);
    gl.uniform1f(uVariant, variantToUniform(variant));
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    frame = requestAnimationFrame(tick);
  };
  frame = requestAnimationFrame(tick);

  return {
    destroy: () => {
      destroyed = true;
      cancelAnimationFrame(frame);
      gl.clear(gl.COLOR_BUFFER_BIT);
      if (buffer) {
        gl.deleteBuffer(buffer);
      }
      gl.deleteProgram(program);
    },
    setAlpha: (nextAlpha: number) => {
      alpha = clamp01(nextAlpha);
    },
    setProgress: (nextProgress: number) => {
      progress = clamp01(nextProgress);
    },
    setVariant: (nextVariant: SdfBlobVariant) => {
      variant = nextVariant;
    },
  };
};

const play = (
  controller: Controller,
  duration: number,
  onMidpoint: () => void,
  onComplete: () => void
): Playback => {
  let frame = 0;
  let cancelled = false;
  let didSwap = false;
  const startedAt = performance.now();
  controller.setAlpha(1);

  const advance = () => {
    if (cancelled) {
      return;
    }
    const raw = clamp01((performance.now() - startedAt) / duration);
    const progress = easeOutQuart(raw);
    controller.setProgress(progress);
    if (!(didSwap || progress < MIDPOINT)) {
      didSwap = true;
      onMidpoint();
    }
    if (raw < 1) {
      frame = requestAnimationFrame(advance);
      return;
    }
    if (!didSwap) {
      onMidpoint();
    }
    const fadeStartedAt = performance.now();
    const fade = () => {
      if (cancelled) {
        return;
      }
      const fadeRaw = clamp01((performance.now() - fadeStartedAt) / 90);
      controller.setAlpha(1 - easeInOutCubic(fadeRaw));
      if (fadeRaw < 1) {
        frame = requestAnimationFrame(fade);
        return;
      }
      controller.setAlpha(0);
      controller.setProgress(0);
      onComplete();
    };
    frame = requestAnimationFrame(fade);
  };
  frame = requestAnimationFrame(advance);

  return {
    cancel: () => {
      cancelled = true;
      cancelAnimationFrame(frame);
    },
  };
};

const SdfBlobTransition = ({
  children,
  className,
  duration = DEFAULT_DURATION_MS,
  onRest,
  transitionKey,
  variant = "final",
}: SdfBlobTransitionProps) => {
  const shouldReduceMotion = useReducedMotion();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controllerRef = useRef<Controller | null>(null);
  const playbackRef = useRef<Playback | null>(null);
  const previousKey = useRef(transitionKey);
  const [renderedChildren, setRenderedChildren] = useState(children);
  const [isActive, setIsActive] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const controller = createController(canvas, variant);
    controllerRef.current = controller;
    return () => {
      playbackRef.current?.cancel();
      controller?.destroy();
      controllerRef.current = null;
    };
  }, [variant]);

  useEffect(() => {
    if (previousKey.current === transitionKey) {
      setRenderedChildren(children);
      return;
    }
    previousKey.current = transitionKey;
    playbackRef.current?.cancel();

    if (shouldReduceMotion) {
      setRenderedChildren(children);
      setIsActive(false);
      onRest?.();
      return;
    }

    const controller = controllerRef.current;
    if (!controller) {
      setRenderedChildren(children);
      onRest?.();
      return;
    }
    controller.setVariant(variant);
    setIsActive(true);
    playbackRef.current = play(
      controller,
      duration,
      () => setRenderedChildren(children),
      () => {
        setIsActive(false);
        playbackRef.current = null;
        onRest?.();
      }
    );
  }, [children, duration, onRest, shouldReduceMotion, transitionKey, variant]);

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-2xl bg-background text-foreground",
        className
      )}
      data-transitioning={isActive ? "true" : "false"}
    >
      <div className="relative z-0">{renderedChildren}</div>
      <canvas
        className={cn(
          "pointer-events-none absolute inset-0 z-10 h-full w-full transition-opacity duration-75",
          isActive && !shouldReduceMotion ? "opacity-100" : "opacity-0"
        )}
        ref={canvasRef}
      />
    </div>
  );
};

export default SdfBlobTransition;

