export interface StaggerFromEdgesProps {
  children: string;
  className?: string;
  /** Delay before the animation starts, in milliseconds. */
  delay?: number;
  /** Per-step stagger between characters, in milliseconds. */
  stagger?: number;
  /** Animate only once the text scrolls into view. */
  triggerOnView?: boolean;
}

const DURATION_S = 0.62;
const MS = 1000;
// Apple-ish ease-out for edges-in reveal.
const EASE = [0.22, 1, 0.36, 1] as const;

/**
 * StaggerFromEdges — characters start from both edges and converge toward
 * the center. Delay is computed by distance from the nearest edge, not
 * linear index. From the animate-text catalog (`stagger-from-edges`).
 */
export default function StaggerFromEdges({
  children,
  className = "",
  delay = 0,
  stagger = 22,
  triggerOnView = false,
}: StaggerFromEdgesProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true });
  const shouldReduceMotion = useReducedMotion();
  const play = (!triggerOnView || inView) && !shouldReduceMotion;
  const characters = Array.from(children);
  const lastIndex = characters.length - 1;

  return (
    <span aria-label={children} className={className} ref={ref}>
      {characters.map((char, index) => {
        // Distance from the nearest edge (0 = edge character, increases toward center)
        const distanceFromEdge = Math.min(index, lastIndex - index);
        return (
          <motion.span
            animate={
              play ? { filter: "blur(0px)", opacity: 1, y: 0 } : undefined
            }
            aria-hidden="true"
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(3px)", opacity: 0, y: 12 }
            }
            // biome-ignore lint/suspicious/noArrayIndexKey: characters have no stable id
            key={index}
            style={{ display: "inline-block", whiteSpace: "pre" }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : {
                    delay: delay / MS + (distanceFromEdge * stagger) / MS,
                    duration: DURATION_S,
                    ease: EASE,
                  }
            }
          >
            {char === " " ? " " : String(char)}
          </motion.span>
        );
      })}
    </span>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  motion,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
} from "motion/react";
import {
  type ReactNode,
  type RefObject,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

/** Motion scroll offset tuple, typed from `useScroll` itself. */
export type ScrollOffset = NonNullable<
  Parameters<typeof useScroll>[0]
>["offset"];

const EASE_MOVE = [0.645, 0.045, 0.355, 1] as const;
const TRANSITION_DURATION = 0.3;
const DEFAULT_MORPH_DURATION = 4;
// The mask has to finish opening while the frame is still in view; the full
// enter-to-exit range parks the fully-revealed state off-screen.
const DEFAULT_SCROLL_OFFSET: ScrollOffset = ["start 0.9", "end 0.6"];

const PRESET_PATHS = {
  arch: "M0,1 L0,0.4 C0,0.18 0.18,0 0.5,0 C0.82,0 1,0.18 1,0.4 L1,1 Z",
  blob: "M0.5,0.02 C0.75,0.02 0.98,0.25 0.98,0.5 C0.98,0.75 0.75,0.98 0.5,0.98 C0.25,0.98 0.02,0.75 0.02,0.5 C0.02,0.25 0.25,0.02 0.5,0.02 Z",
  diamond: "M0.5,0 L1,0.5 L0.5,1 L0,0.5 Z",
  wave: "M0,0.3 C0.25,0.05 0.75,0.55 1,0.3 L1,1 L0,1 Z",
} as const;

export type SvgClipMaskShape = "blob" | "arch" | "diamond" | "wave" | "custom";
export type SvgClipMaskAnimate = "none" | "morph" | "scroll" | "hover";

export interface SvgClipMaskProps {
  /**
   * "morph" cycles through morphPaths forever, "scroll" steps through them as
   * the container scrolls, "hover" swaps to morphPaths[0] on hover.
   */
  animate?: SvgClipMaskAnimate;
  children: ReactNode;
  className?: string;
  /** Ref to a scrollable ancestor that drives "scroll" mode instead of the window. */
  container?: RefObject<HTMLElement | null>;
  /** Seconds for one full "morph" loop. */
  duration?: number;
  /**
   * Paths to cycle between for "morph"/"scroll"/"hover". They must all share
   * the same command structure (same sequence of M/L/C/Z and point counts) —
   * browsers interpolate matching parameters positionally, so mismatched
   * structures snap instead of morphing smoothly.
   */
  morphPaths?: string[];
  /** Custom path data, in objectBoundingBox (0..1) coordinates. Required when shape is "custom". */
  path?: string;
  shape?: SvgClipMaskShape;
}

const useHoverCapable = (enabled: boolean) => {
  const [isHoverCapable, setIsHoverCapable] = useState(false);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverCapable(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverCapable(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, [enabled]);

  return isHoverCapable;
};

export default function SvgClipMask({
  children,
  shape = "blob",
  path,
  animate = "none",
  morphPaths,
  duration = DEFAULT_MORPH_DURATION,
  container,
  className,
}: SvgClipMaskProps) {
  const clipId = useId();
  const shouldReduceMotion = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const isHoverCapable = useHoverCapable(animate === "hover");
  const [isHovered, setIsHovered] = useState(false);
  const [scrollIndex, setScrollIndex] = useState(0);

  const basePath =
    shape === "custom" ? (path ?? PRESET_PATHS.blob) : PRESET_PATHS[shape];
  const paths = morphPaths && morphPaths.length > 1 ? morphPaths : [basePath];

  const { scrollYProgress } = useScroll({
    container,
    offset: DEFAULT_SCROLL_OFFSET,
    target: ref,
  });

  useMotionValueEvent(scrollYProgress, "change", (value) => {
    if (shouldReduceMotion || animate !== "scroll" || paths.length < 2) {
      return;
    }
    const index = Math.min(paths.length - 1, Math.floor(value * paths.length));
    setScrollIndex(index);
  });

  const isMorphing =
    animate === "morph" && !shouldReduceMotion && paths.length > 1;

  const activeD = (() => {
    if (shouldReduceMotion || animate === "none" || isMorphing) {
      return paths[0];
    }
    if (animate === "scroll") {
      return paths[scrollIndex] ?? paths[0];
    }
    if (animate === "hover") {
      return isHoverCapable && isHovered ? (paths[1] ?? paths[0]) : paths[0];
    }
    return paths[0];
  })();

  return (
    <div
      className={cn("relative", className)}
      onPointerEnter={() => setIsHovered(true)}
      onPointerLeave={() => setIsHovered(false)}
      ref={ref}
    >
      <svg aria-hidden="true" className="absolute h-0 w-0">
        <defs>
          <clipPath clipPathUnits="objectBoundingBox" id={clipId}>
            <motion.path
              animate={isMorphing ? { d: paths } : { d: activeD }}
              initial={false}
              transition={
                isMorphing
                  ? {
                      duration,
                      ease: EASE_MOVE,
                      repeat: Number.POSITIVE_INFINITY,
                      repeatType: "loop",
                    }
                  : { duration: TRANSITION_DURATION, ease: EASE_MOVE }
              }
            />
          </clipPath>
        </defs>
      </svg>
      <div
        className="h-full w-full"
        style={{
          clipPath: `url(#${clipId})`,
          WebkitClipPath: `url(#${clipId})`,
        }}
      >
        {children}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import {
  type MotionValue,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import {
  type ReactNode,
  type RefObject,
  useCallback,
  useEffect,
  useMemo,
  useRef,
} from "react";

/** Motion scroll offset tuple, typed from `useScroll` itself. */
export type ScrollOffset = NonNullable<
  Parameters<typeof useScroll>[0]
>["offset"];

const SPRING_CONFIG = { damping: 28, mass: 0.4, stiffness: 240 } as const;
// Finishes drawing while the artwork is still mid-viewport rather than on its
// way out, so the completed stroke is something you actually get to look at.
const DEFAULT_OFFSET: ScrollOffset = ["start 0.9", "end 0.6"];
const DEFAULT_VIEW_BOX = "0 0 100 100";
const DEFAULT_STROKE_WIDTH = 2;
const DEFAULT_STROKE = "currentColor";
const MARKER_KEY_SLICE = 8;
const FULL_PROGRESS = 1;

export interface SvgDrawOnScrollProps {
  className?: string;
  /** Ref to a scrollable ancestor that drives progress instead of the window. */
  container?: RefObject<HTMLElement | null>;
  /** Rides the tip of the drawn stroke, positioned from the path's own geometry. */
  marker?: ReactNode;
  /** Motion `useScroll` offset tuple, e.g. ["start 0.9", "end 0.3"]. */
  offset?: ScrollOffset;
  /** Freeze fully drawn once complete instead of undrawing on scroll-up. */
  once?: boolean;
  /** Single path's `d`. Ignored if `paths` is also provided. */
  path?: string;
  /** Multiple paths, drawn one after another across the scroll range. */
  paths?: string[];
  stroke?: string;
  strokeWidth?: number;
  viewBox?: string;
}

interface DrawPathProps {
  d: string;
  progress: MotionValue<number>;
  range: [number, number];
  stroke: string;
  strokeWidth: number;
}

const clampUnit = (value: number) => Math.min(1, Math.max(0, value));

const DrawPath = ({
  d,
  progress,
  range,
  stroke,
  strokeWidth,
}: DrawPathProps) => {
  const shouldReduceMotion = useReducedMotion();
  const pathLength = useTransform(
    progress,
    range,
    shouldReduceMotion ? [1, 1] : [0, 1]
  );

  return (
    <motion.path
      d={d}
      fill="none"
      pathLength={1}
      stroke={stroke}
      strokeLinecap="round"
      strokeWidth={strokeWidth}
      style={{ pathLength }}
    />
  );
};

export default function SvgDrawOnScroll({
  path,
  paths,
  viewBox = DEFAULT_VIEW_BOX,
  strokeWidth = DEFAULT_STROKE_WIDTH,
  stroke = DEFAULT_STROKE,
  marker,
  offset = DEFAULT_OFFSET,
  container,
  once = false,
  className,
}: SvgDrawOnScrollProps) {
  const ref = useRef<HTMLDivElement>(null);
  const measureRef = useRef<SVGPathElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const maxProgressRef = useRef(0);

  const pathList = useMemo(
    () => (paths && paths.length > 0 ? paths : path ? [path] : []),
    [paths, path]
  );
  const combinedD = useMemo(() => pathList.join(" "), [pathList]);

  const { scrollYProgress } = useScroll({ container, offset, target: ref });

  const monotonicProgress = useTransform(scrollYProgress, (latest) => {
    if (!once) {
      return latest;
    }
    maxProgressRef.current = Math.max(maxProgressRef.current, latest);
    return maxProgressRef.current;
  });
  const spring = useSpring(monotonicProgress, SPRING_CONFIG);

  // The marker is positioned from the path's own geometry rather than CSS
  // `offset-path`. `offset-path: path()` measures in the element's CSS pixel
  // space, but the `d` is written in viewBox units — so any viewBox that is not
  // 1:1 with the rendered box (which is the normal case, since the SVG scales
  // with `preserveAspectRatio`) left the marker floating away from the stroke
  // it is supposed to ride. `getPointAtLength` + `getScreenCTM` resolve the
  // point through the exact same transform the browser used to paint the line.
  const markerX = useMotionValue(0);
  const markerY = useMotionValue(0);

  const syncMarker = useCallback(
    (latest: number) => {
      const pathElement = measureRef.current;
      const wrapper = ref.current;

      if (!(pathElement && wrapper)) {
        return;
      }

      const totalLength = pathElement.getTotalLength();
      const matrix = pathElement.getScreenCTM();

      if (!(totalLength && matrix)) {
        return;
      }

      const progress = shouldReduceMotion ? FULL_PROGRESS : clampUnit(latest);
      const point = pathElement.getPointAtLength(progress * totalLength);
      const screenPoint = new DOMPoint(point.x, point.y).matrixTransform(
        matrix
      );
      const rect = wrapper.getBoundingClientRect();

      markerX.set(screenPoint.x - rect.left);
      markerY.set(screenPoint.y - rect.top);
    },
    [markerX, markerY, shouldReduceMotion]
  );

  useMotionValueEvent(spring, "change", syncMarker);

  // Also sync on mount and on resize: the scroll value can sit still for the
  // whole life of the component (reduced motion, or simply an untouched page)
  // and the mapping changes whenever the SVG is laid out at a new size.
  useEffect(() => {
    const wrapper = ref.current;

    if (!(marker && combinedD && wrapper)) {
      return;
    }

    syncMarker(spring.get());

    const observer = new ResizeObserver(() => syncMarker(spring.get()));
    observer.observe(wrapper);

    return () => observer.disconnect();
  }, [marker, combinedD, spring, syncMarker]);

  return (
    <div className={cn("relative", className)} ref={ref}>
      <svg
        aria-hidden="true"
        className="h-full w-full"
        fill="none"
        preserveAspectRatio="xMidYMid meet"
        viewBox={viewBox}
        xmlns="http://www.w3.org/2000/svg"
      >
        {pathList.map((d, index) => (
          <DrawPath
            d={d}
            key={`svg-draw-on-scroll-path-${index}-${d.slice(0, MARKER_KEY_SLICE)}`}
            progress={spring}
            range={[index / pathList.length, (index + 1) / pathList.length]}
            stroke={stroke}
            strokeWidth={strokeWidth}
          />
        ))}
        {/* Never painted — it exists only so the marker has a single, stable
            geometry to measure against, including across multiple paths. */}
        {marker && combinedD ? (
          <path d={combinedD} fill="none" ref={measureRef} stroke="none" />
        ) : null}
      </svg>
      {marker && combinedD ? (
        <motion.div
          aria-hidden="true"
          className="pointer-events-none absolute top-0 left-0"
          style={{ x: markerX, y: markerY }}
        >
          <div className="-translate-x-1/2 -translate-y-1/2">{marker}</div>
        </motion.div>
      ) : null}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import SmoothButton from "@/components/smoothui/smooth-button";
import { ArrowLeftRight, ChevronDown } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { useEffect, useId, useRef, useState } from "react";

const SPRING_TRANSITION = {
  bounce: 0.1,
  duration: 0.25,
  type: "spring" as const,
};
const SHIMMER_DURATION = 1.4;
const SHIMMER_EASE = [0, 0, 1, 1] as const;
const RING_SIZE = 20;
const RING_RADIUS = 8;
const RING_STROKE = 2;
const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;
const RING_TICK_MS = 100;

const decimalFormatter = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 6,
});
const percentFormatter = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 2,
  style: "percent",
});

export interface SwapToken {
  balance?: number;
  icon?: ReactNode;
  name: string;
  symbol: string;
}

export interface SwapQuote {
  expiresAt?: number;
  fee?: number;
  output: number;
  priceImpact?: number;
  rate: number;
}

export type SwapStatus = "idle" | "quoting" | "ready" | "submitting" | "error";

export interface SwapPanelProps {
  amount: string;
  className?: string;
  error?: string;
  from: SwapToken;
  onAmountChange: (value: string) => void;
  onFlip: () => void;
  onSelectToken?: (side: "from" | "to") => void;
  onSubmit: () => void;
  quote?: SwapQuote;
  slippage?: number;
  status: SwapStatus;
  to: SwapToken;
}

const RollingFigure = ({
  shouldReduceMotion,
  value,
}: {
  shouldReduceMotion: boolean;
  value: string;
}) => (
  <span className="relative inline-flex overflow-hidden">
    <AnimatePresence initial={false} mode="popLayout">
      <motion.span
        animate={{ opacity: 1, y: 0 }}
        exit={
          shouldReduceMotion
            ? { opacity: 0, transition: { duration: 0 } }
            : { opacity: 0, y: -12 }
        }
        initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 12 }}
        key={value}
        transition={shouldReduceMotion ? { duration: 0 } : SPRING_TRANSITION}
      >
        {value}
      </motion.span>
    </AnimatePresence>
  </span>
);

const CountdownRing = ({
  expiresAt,
  shouldReduceMotion,
}: {
  expiresAt: number;
  shouldReduceMotion: boolean;
}) => {
  const startRef = useRef(Date.now());
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    startRef.current = Date.now();
    setNow(Date.now());
    const interval = setInterval(() => setNow(Date.now()), RING_TICK_MS);
    return () => clearInterval(interval);
  }, [expiresAt]);

  const totalMs = expiresAt - startRef.current;
  const remainingMs = Math.max(expiresAt - now, 0);
  const fraction = totalMs > 0 ? remainingMs / totalMs : 0;
  // Exception to the transform/opacity-only rule: a radial countdown needs to animate
  // `stroke-dashoffset`, a paint-only SVG property with no reasonable transform equivalent.
  // This is the standard low-cost technique for progress rings.
  const dashOffset = RING_CIRCUMFERENCE * (1 - fraction);

  return (
    <svg
      aria-hidden="true"
      className="shrink-0"
      height={RING_SIZE}
      viewBox={`0 0 ${RING_SIZE} ${RING_SIZE}`}
      width={RING_SIZE}
    >
      <circle
        className="text-muted-foreground/20"
        cx={RING_SIZE / 2}
        cy={RING_SIZE / 2}
        fill="none"
        r={RING_RADIUS}
        stroke="currentColor"
        strokeWidth={RING_STROKE}
      />
      <circle
        className="text-brand"
        cx={RING_SIZE / 2}
        cy={RING_SIZE / 2}
        fill="none"
        r={RING_RADIUS}
        stroke="currentColor"
        strokeDasharray={RING_CIRCUMFERENCE}
        strokeDashoffset={dashOffset}
        strokeLinecap="round"
        strokeWidth={RING_STROKE}
        style={{
          transform: "rotate(-90deg)",
          transformOrigin: "50% 50%",
          transition: shouldReduceMotion
            ? "none"
            : `stroke-dashoffset ${RING_TICK_MS}ms linear`,
        }}
      />
    </svg>
  );
};

const TokenChip = ({
  onSelect,
  side,
  token,
}: {
  onSelect?: () => void;
  side: "from" | "to";
  token: SwapToken;
}) => (
  <SmoothButton
    aria-label={`Change ${side === "from" ? "pay" : "receive"} token, currently ${token.symbol}`}
    className="shrink-0 text-foreground"
    onClick={onSelect}
    prefix={
      token.icon ?? (
        <span
          aria-hidden="true"
          className="flex h-5 w-5 items-center justify-center rounded-full bg-foreground/10 font-semibold text-[10px] text-foreground"
        >
          {token.symbol.charAt(0)}
        </span>
      )
    }
    shape="pill"
    size="sm"
    suffix={
      <ChevronDown aria-hidden="true" className="text-muted-foreground" />
    }
    variant="secondary"
  >
    {token.symbol}
  </SmoothButton>
);

export default function SwapPanel({
  amount,
  className = "",
  error,
  from,
  onAmountChange,
  onFlip,
  onSelectToken,
  onSubmit,
  quote,
  slippage,
  status,
  to,
}: SwapPanelProps) {
  const shouldReduceMotion = Boolean(useReducedMotion());
  const [flipped, setFlipped] = useState(false);
  const fromInputId = useId();
  const toLabelId = useId();

  const isBusy = status === "quoting" || status === "submitting";
  const outputFormatted = decimalFormatter.format(quote?.output ?? 0);

  const actionLabel =
    status === "submitting"
      ? "Swapping…"
      : status === "error"
        ? "Try again"
        : "Review swap";

  const handleFlip = () => {
    setFlipped((prev) => !prev);
    onFlip();
  };

  const rows: { side: "from" | "to"; token: SwapToken }[] = [
    { side: "from", token: from },
    { side: "to", token: to },
  ];

  return (
    <div
      className={cn(
        "w-full max-w-sm rounded-2xl border bg-background p-4",
        className
      )}
    >
      <div className="flex flex-col gap-2">
        {rows.map((row) => (
          <motion.div
            className="relative"
            key={row.token.symbol}
            layout={!shouldReduceMotion}
            transition={
              shouldReduceMotion ? { duration: 0 } : SPRING_TRANSITION
            }
          >
            {row.side === "from" ? (
              <div>
                <label
                  className="mb-1 block px-1 text-muted-foreground text-xs"
                  htmlFor={fromInputId}
                >
                  You pay
                </label>
                <div className="flex items-center justify-between gap-2 rounded-xl border bg-secondary/40 px-3 py-2">
                  <input
                    className="w-full min-w-0 bg-transparent font-semibold text-2xl outline-none placeholder:text-muted-foreground/40"
                    id={fromInputId}
                    inputMode="decimal"
                    onChange={(event) => onAmountChange(event.target.value)}
                    placeholder="0.0"
                    type="text"
                    value={amount}
                  />
                  <TokenChip
                    onSelect={() => onSelectToken?.("from")}
                    side="from"
                    token={from}
                  />
                </div>
                {typeof from.balance === "number" ? (
                  <div className="mt-1 flex items-center gap-2 px-1 text-muted-foreground text-xs">
                    <span>Balance {decimalFormatter.format(from.balance)}</span>
                    <button
                      className="rounded font-medium text-foreground underline decoration-foreground/30 underline-offset-2 transition-colors hover:decoration-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      onClick={() => onAmountChange(String(from.balance))}
                      type="button"
                    >
                      Max
                    </button>
                  </div>
                ) : null}
              </div>
            ) : (
              <div>
                <span
                  className="mb-1 block px-1 text-muted-foreground text-xs"
                  id={toLabelId}
                >
                  You receive
                </span>
                <div className="relative flex items-center justify-between gap-2 overflow-hidden rounded-xl border bg-secondary/40 px-3 py-2">
                  {status === "quoting" &&
                    (shouldReduceMotion ? (
                      <div
                        aria-hidden="true"
                        className="absolute inset-0 bg-muted-foreground/10"
                      />
                    ) : (
                      <div
                        aria-hidden="true"
                        className="pointer-events-none absolute inset-0 overflow-hidden"
                      >
                        <motion.div
                          animate={{ x: ["-100%", "220%"] }}
                          className="h-full w-1/3 bg-gradient-to-r from-transparent via-foreground/10 to-transparent"
                          transition={{
                            duration: SHIMMER_DURATION,
                            ease: SHIMMER_EASE,
                            repeat: Number.POSITIVE_INFINITY,
                          }}
                        />
                      </div>
                    ))}
                  <div
                    aria-labelledby={toLabelId}
                    aria-live="polite"
                    className="relative min-h-8 flex-1 font-semibold text-2xl"
                  >
                    <RollingFigure
                      shouldReduceMotion={shouldReduceMotion}
                      value={outputFormatted}
                    />
                  </div>
                  <TokenChip
                    onSelect={() => onSelectToken?.("to")}
                    side="to"
                    token={to}
                  />
                </div>
              </div>
            )}
          </motion.div>
        ))}

        <div className="flex justify-center">
          <SmoothButton
            aria-label="Flip pay and receive tokens"
            className="z-10 -my-4"
            onClick={handleFlip}
            shape="pill"
            size="icon-sm"
            variant="outline"
          >
            {/* The rotation rides the icon, not the button: the frame is a
                circle, so spinning it only ever moved its shadow. */}
            <motion.span
              animate={{ rotate: flipped ? 180 : 0 }}
              className="flex"
              transition={
                shouldReduceMotion ? { duration: 0 } : SPRING_TRANSITION
              }
            >
              <ArrowLeftRight aria-hidden="true" />
            </motion.span>
          </SmoothButton>
        </div>
      </div>

      {quote ? (
        <div className="mt-3 flex flex-wrap items-center gap-2 px-1 text-muted-foreground text-xs">
          {quote.expiresAt ? (
            <CountdownRing
              expiresAt={quote.expiresAt}
              shouldReduceMotion={shouldReduceMotion}
            />
          ) : null}
          <span>
            1 {from.symbol} = {decimalFormatter.format(quote.rate)} {to.symbol}
          </span>
          {typeof quote.fee === "number" ? (
            <span>
              Fee {decimalFormatter.format(quote.fee)} {to.symbol}
            </span>
          ) : null}
          {typeof quote.priceImpact === "number" ? (
            <span>Impact {percentFormatter.format(quote.priceImpact)}</span>
          ) : null}
          {typeof slippage === "number" ? (
            <span>Max slippage {percentFormatter.format(slippage)}</span>
          ) : null}
        </div>
      ) : null}

      {error ? (
        <p className="mt-2 px-1 text-destructive text-xs" role="alert">
          {error}
        </p>
      ) : null}

      <SmoothButton
        className="mt-3 w-full rounded-xl font-semibold"
        disabled={isBusy}
        loading={status === "submitting"}
        onClick={onSubmit}
        // `candy` is the house primary, matching the CTA and footer blocks.
        variant="candy"
      >
        {actionLabel}
      </SmoothButton>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { useEffect, useMemo, useState } from "react";

export type LightState = "off" | "medium" | "high";

export interface SwitchboardCardProps {
  className?: string;
  columns?: number;
  gridPattern?: number[] | number[][]; // Direct grid pattern: flat array (columns*rows) or 2D array [rows][columns] where 0=off, 1=high
  href?: string;
  onButtonClick?: () => void;
  randomLights?: boolean; // If true, randomly activate some lights
  rows?: number;
  showButton?: boolean;
  subtitle: string;
  title: string;
  transitionDuration?: number; // in milliseconds (default: 200ms for smooth light transitions)
  variant?: "default" | "next";
}

function generateRandomPattern(
  totalLights: number,
  activeRatio = 0.15
): number[] {
  const activeCount = Math.floor(totalLights * activeRatio);
  const pattern: number[] = [];
  const used = new Set<number>();

  while (pattern.length < activeCount) {
    const index = Math.floor(Math.random() * totalLights);
    if (!used.has(index)) {
      used.add(index);
      pattern.push(index);
    }
  }

  return pattern.sort((a, b) => a - b);
}

function parse2DGridPattern(
  grid2D: number[][],
  rows: number,
  columns: number,
  totalLights: number
): number[] {
  const pattern: number[] = [];
  for (let row = 0; row < Math.min(grid2D.length, rows); row++) {
    const rowData = grid2D[row];
    if (Array.isArray(rowData)) {
      for (let col = 0; col < Math.min(rowData.length, columns); col++) {
        if (rowData[col] === 1) {
          const index = col + row * columns;
          if (index >= 0 && index < totalLights) {
            pattern.push(index);
          }
        }
      }
    }
  }
  return pattern;
}

function parseFlatGridPattern(
  flatPattern: number[],
  totalLights: number
): number[] {
  const pattern: number[] = [];
  for (let i = 0; i < Math.min(flatPattern.length, totalLights); i++) {
    if (flatPattern[i] === 1) {
      pattern.push(i);
    }
  }
  return pattern;
}

export default function SwitchboardCard({
  title,
  subtitle,
  columns = 18,
  rows = 5,
  gridPattern,
  randomLights = false,
  transitionDuration = 200,
  className,
  variant = "default",
  showButton: _showButton = true,
  href,
  onButtonClick,
}: SwitchboardCardProps) {
  const totalLights = columns * rows;
  const isRandomLightsMode = randomLights && !gridPattern;

  // Convert gridPattern to light indices
  // Priority: gridPattern > randomLights
  const basePattern = useMemo<number[]>(() => {
    if (gridPattern) {
      // Handle 2D array [rows][columns]
      const is2DArray =
        Array.isArray(gridPattern[0]) && typeof gridPattern[0] !== "number";
      if (is2DArray) {
        return parse2DGridPattern(
          gridPattern as number[][],
          rows,
          columns,
          totalLights
        );
      }
      // Handle flat array [columns*rows]
      return parseFlatGridPattern(gridPattern as number[], totalLights);
    }
    if (randomLights) {
      return generateRandomPattern(totalLights);
    }
    return [];
  }, [gridPattern, randomLights, columns, rows, totalLights]);

  // Animated light states
  // For random lights: all start off, will animate randomly through medium → high → medium → off
  // For word/pattern: pattern lights start high (stay high), rest off
  const [lightStates, setLightStates] = useState<LightState[]>(() => {
    const states: LightState[] = new Array(totalLights).fill("off");
    if (!isRandomLightsMode) {
      // For word/pattern, set pattern lights to high
      for (const index of basePattern) {
        if (index >= 0 && index < totalLights) {
          states[index] = "high";
        }
      }
    }
    // For random lights, all start off (will animate)
    return states;
  });

  // Animate lights - only for random lights mode (word/pattern stays high)
  useEffect(() => {
    // Word/pattern mode: no animation, lights stay high
    if (!isRandomLightsMode) {
      return;
    }

    const interval = setInterval(() => {
      setLightStates((prev) => {
        const next = [...prev];
        // For random lights: animate all lights randomly through off → high (via medium transition)
        // Randomly select a subset of lights to animate each tick
        const lightsToAnimate = Math.floor(totalLights * 0.2); // Animate ~20% of all lights per tick
        const allIndices = Array.from({ length: totalLights }, (_, i) => i);
        const shuffled = allIndices.sort(() => Math.random() - 0.5);

        for (let i = 0; i < Math.min(lightsToAnimate, shuffled.length); i++) {
          const index = shuffled[i];
          if (index >= 0 && index < totalLights) {
            const current = prev[index];
            // State transition logic for random lights: off → high (with medium as intermediate transition state)
            // Medium state is only used as a transition, not a final state
            if (current === "off") {
              // Start transition to high by going to medium first
              next[index] = "medium";
            } else if (current === "medium") {
              // Continue transition: medium → high
              next[index] = "high";
            } else if (current === "high") {
              // Turn off directly (no medium transition when turning off)
              next[index] = "off";
            }
          }
        }
        return next;
      });
    }, 200); // 0.2s interval to match transition duration

    return () => clearInterval(interval);
  }, [isRandomLightsMode, totalLights]);

  const isNextVariant = variant === "next";

  const CardContent = (
    <div
      className={cn(
        "relative flex h-[380px] w-full flex-col overflow-hidden rounded-xl border p-6 transition-[border-color,background-color] duration-150",
        isNextVariant
          ? "border-0 dark:border-0 dark:shadow-[inset_0_0_6px_rgba(255,255,255,0.1)]"
          : "border-border bg-background hover:border-foreground/20",
        className
      )}
      data-variant={isNextVariant ? "next" : undefined}
      style={
        isNextVariant
          ? ({
              background:
                "linear-gradient(110deg, oklch(0.65 0 0) 0.06%, oklch(0.54 0 0) 100%)",
            } as React.CSSProperties)
          : undefined
      }
    >
      {/* Illustration/Switchboard */}
      <div
        className="flex h-full w-full items-center justify-center"
        data-illustration="true"
      >
        <div
          className="grid h-full w-full"
          style={{
            gap: `min(1px, calc(100% / ${columns} / 10))`,
            gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
            gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))`,
            maxHeight: "81px",
            transitionDuration: `${transitionDuration}ms`,
          }}
        >
          {lightStates.map((state, index) => (
            <LightBulb
              // biome-ignore lint/suspicious/noArrayIndexKey: Light grid position is stable and never reorders
              key={`light-${index}`}
              state={state}
              transitionDuration={transitionDuration}
            />
          ))}
        </div>
      </div>

      {/* Title */}
      <div className="mt-4 flex flex-row items-center justify-start gap-2 text-left">
        <h3
          className={cn(
            "text-left font-semibold leading-8 tracking-[-0.04em]",
            isNextVariant ? "mt-4 text-2xl" : "text-foreground text-xl"
          )}
          data-title="true"
          style={
            isNextVariant
              ? ({ color: "oklch(0.95 0 0)" } as React.CSSProperties)
              : undefined
          }
        >
          {title}
        </h3>
      </div>

      {/* Subtitle */}
      <p
        className={cn(
          "text-left text-sm leading-relaxed tracking-[-0.01em]",
          isNextVariant
            ? "mt-1 max-w-[80%] text-base"
            : "mt-1 text-foreground/70"
        )}
        data-subtitle="true"
        style={
          isNextVariant
            ? ({ color: "oklch(0.9 0 0)" } as React.CSSProperties)
            : undefined
        }
      >
        {subtitle}
      </p>
    </div>
  );

  if (href) {
    return (
      <a
        aria-label={title}
        className="focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        href={href}
      >
        {CardContent}
      </a>
    );
  }

  if (onButtonClick) {
    return (
      <button
        aria-label={title}
        className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        onClick={onButtonClick}
        type="button"
      >
        {CardContent}
      </button>
    );
  }

  return CardContent;
}

function LightBulb({
  state,
  transitionDuration,
}: {
  state: LightState;
  transitionDuration: number;
}) {
  const transitionStyle = {
    transition: `opacity ${transitionDuration}ms ease-out, transform ${transitionDuration}ms ease-out`,
  };

  return (
    <div
      className={cn(
        "relative rounded-full",
        state === "off" && "bg-foreground/50",
        state === "high" ? "h-[2px] w-[2px]" : "h-px w-px"
      )}
      data-state={state}
      style={{
        ...transitionStyle,
        transform: state === "off" ? "unset" : "scale(1)",
      }}
    >
      {/* Glow effect for medium state (::before equivalent) */}
      {state === "medium" && (
        <div
          className="absolute inset-0 rounded-full"
          style={{
            ...transitionStyle,
            backgroundColor: "var(--color-brand)",
            boxShadow:
              "0 0 2px 1px color-mix(in oklch, var(--color-brand), transparent 60%), 0 0 4px 1.5px color-mix(in oklch, var(--color-brand), transparent 75%)",
            opacity: 1,
          }}
        />
      )}

      {/* Glow effect for high state (::after equivalent) */}
      {state === "high" && (
        <div
          className="absolute inset-0 rounded-full"
          style={{
            ...transitionStyle,
            backgroundColor: "var(--color-brand)",
            boxShadow:
              "0 0 2px 1px color-mix(in oklch, var(--color-brand), transparent 40%), 0 0 4px 1.5px color-mix(in oklch, var(--color-brand), transparent 65%), 0 0 6px 2px color-mix(in oklch, var(--color-brand), transparent 80%)",
            opacity: 1,
          }}
        />
      )}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ElementType } from "react";
import { useMemo } from "react";

export type TextMorphMode = "characters" | "words";
export type TextMorphAlign = "start" | "center" | "end";
export type TextMorphTag = "span" | "div" | "p" | "h1" | "h2" | "h3" | "h4";

export interface TextMorphProps {
  /** Justifies the token row when the wrapper is wider than the text. */
  align?: TextMorphAlign;
  /** Element rendered for the wrapper. */
  as?: TextMorphTag;
  className?: string;
  /** Spring duration for each token, in milliseconds. */
  duration?: number;
  /** Splits the diff on graphemes or whole words. */
  mode?: TextMorphMode;
  /** Per-token stagger, in milliseconds. Capped so long strings stay snappy. */
  stagger?: number;
  /** The current string. Changing it triggers the morph. */
  text: string;
}

interface TextMorphToken {
  key: string;
  value: string;
}

const DEFAULT_DURATION = 250;
const DEFAULT_STAGGER = 16;
const MS = 1000;
const POP_SCALE = 0.72;
const POP_OFFSET = 6;
const MAX_STAGGER_MS = 260;
const EXIT_DURATION_S = 0.15;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;

const ALIGN_CLASS: Record<TextMorphAlign, string> = {
  center: "justify-center",
  end: "justify-end",
  start: "justify-start",
};

const segmentGraphemes = (value: string): string[] => {
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const segmenter = new Intl.Segmenter(undefined, {
      granularity: "grapheme",
    });
    return Array.from(segmenter.segment(value), (entry) => entry.segment);
  }
  return [...value];
};

const tokenizeText = (text: string, mode: TextMorphMode): string[] =>
  mode === "words"
    ? text.split(/(\s+)/).filter((token) => token.length > 0)
    : segmentGraphemes(text);

const buildTokens = (text: string, mode: TextMorphMode): TextMorphToken[] => {
  const occurrences = new Map<string, number>();
  return tokenizeText(text, mode).map((value) => {
    const count = occurrences.get(value) ?? 0;
    occurrences.set(value, count + 1);
    return {
      key: `${value}-${count}`,
      value,
    };
  });
};

/**
 * TextMorph — morphs one string into another by diffing tokens: shared
 * tokens keep their key and slide to their new position via layout
 * animation, removed tokens shrink out, added tokens pop in.
 *
 * The token row is `position: relative` on purpose: `AnimatePresence`
 * in `popLayout` mode pulls exiting tokens out of the flow with
 * `position: absolute`, so without a positioned parent they would resolve
 * against the page and fly off into a corner of the viewport.
 */
export default function TextMorph({
  text,
  align = "start",
  as = "span",
  className,
  duration = DEFAULT_DURATION,
  mode = "characters",
  stagger = DEFAULT_STAGGER,
}: TextMorphProps) {
  const shouldReduceMotion = useReducedMotion();
  const tokens = useMemo(() => buildTokens(text, mode), [text, mode]);
  const Tag = as as ElementType;

  if (shouldReduceMotion) {
    return <Tag className={className}>{text}</Tag>;
  }

  return (
    <Tag className={className}>
      {/*
       * The intact string is exposed as visually hidden text rather than an
       * `aria-label` on the wrapper: `aria-label` is prohibited on the generic
       * roles the default `as="span"` (and `as="div"`) produce, so screen
       * readers dropped it — and with every token marked `aria-hidden`, the
       * component announced nothing at all.
       */}
      <span className="sr-only">{text}</span>
      <motion.span
        className={cn("relative inline-flex flex-wrap", ALIGN_CLASS[align])}
        layout
        transition={{ bounce: 0.1, duration: duration / MS, type: "spring" }}
      >
        <AnimatePresence initial={false} mode="popLayout">
          {tokens.map((token, index) => (
            <motion.span
              animate={{ opacity: 1, scale: 1, y: 0 }}
              aria-hidden="true"
              exit={{
                opacity: 0,
                scale: POP_SCALE,
                transition: { duration: EXIT_DURATION_S, ease: EASE_OUT },
                y: -POP_OFFSET,
              }}
              initial={{ opacity: 0, scale: POP_SCALE, y: POP_OFFSET }}
              key={token.key}
              layout
              style={{ display: "inline-block", whiteSpace: "pre" }}
              transition={{
                bounce: 0.1,
                delay: Math.min(index * stagger, MAX_STAGGER_MS) / MS,
                duration: duration / MS,
                type: "spring",
              }}
            >
              {token.value}
            </motion.span>
          ))}
        </AnimatePresence>
      </motion.span>
    </Tag>
  );
}

"use client";

import { cn } from "@/lib/utils";
import type { LucideIcon } from "lucide-react";
import { Monitor, Moon, Sun } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type KeyboardEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";

export const THEME_TOGGLE_VARIANTS = [
  "sun-moon",
  "pill",
  "switch",
  "orb",
] as const;

export type ThemeToggleVariant = (typeof THEME_TOGGLE_VARIANTS)[number];
export type ThemeToggleValue = "light" | "dark" | "system";

export type ThemeToggleProps = {
  /** Additional CSS classes */
  className?: string;
  /** Default theme for uncontrolled usage */
  defaultTheme?: ThemeToggleValue;
  /** Accessible label describing the control */
  label?: string;
  /** Called whenever the chosen theme changes */
  onThemeChange?: (theme: ThemeToggleValue) => void;
  /** Whether to include a third "system" option */
  showSystem?: boolean;
  /** Size of the control */
  size?: "sm" | "md" | "lg";
  /** Controlled theme value */
  theme?: ThemeToggleValue;
  /** Visual treatment of the control */
  variant?: ThemeToggleVariant;
};

/* -------------------------------------------------------------------------- */
/* Motion tokens                                                              */
/* -------------------------------------------------------------------------- */

const SPRING = { bounce: 0.1, duration: 0.25, type: "spring" as const };
const MORPH_SPRING = { bounce: 0.1, duration: 0.35, type: "spring" as const };
const KNOB_SPRING = { bounce: 0.1, duration: 0.3, type: "spring" as const };
const INSTANT = { duration: 0 };
const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];
const FADE = { duration: 0.3, ease: EASE_OUT };
const TRAVEL = { duration: 0.4, ease: EASE_OUT };

/* -------------------------------------------------------------------------- */
/* Sizing                                                                     */
/* -------------------------------------------------------------------------- */

type SizeConfig = {
  glyph: number;
  icon: string;
  knob: number;
  orb: number;
  pad: number;
  segment: string;
  text: string;
};

const SIZES: Record<"sm" | "md" | "lg", SizeConfig> = {
  lg: {
    glyph: 74,
    icon: "size-5",
    knob: 44,
    orb: 104,
    pad: 5,
    segment: "h-11 px-5",
    text: "text-sm",
  },
  md: {
    glyph: 58,
    icon: "size-4",
    knob: 34,
    orb: 82,
    pad: 4,
    segment: "h-10 px-4",
    text: "text-sm",
  },
  sm: {
    glyph: 42,
    icon: "size-3.5",
    knob: 26,
    orb: 58,
    pad: 3,
    segment: "h-8 px-3",
    text: "text-xs",
  },
};

type OptionEntry = {
  icon: LucideIcon;
  label: string;
  value: ThemeToggleValue;
};

const THEME_OPTIONS: OptionEntry[] = [
  { icon: Sun, label: "Light", value: "light" },
  { icon: Moon, label: "Dark", value: "dark" },
  { icon: Monitor, label: "System", value: "system" },
];

/* -------------------------------------------------------------------------- */
/* Variant 1 — sun-moon: a single disc carved by a travelling mask circle      */
/* -------------------------------------------------------------------------- */

const VIEWBOX = 24;
const CENTER = 12;
const RAY_ANGLES = [0, 45, 90, 135, 180, 225, 270, 315];
const RAY_INNER = 7.3;
const RAY_OUTER = 10.3;
const RAY_STAGGER = 0.025;
const RAY_WIDTH = 1.7;
const GLOW_RADIUS = 9.6;
const RAY_RETRACTED_SCALE = 0.12;

/** Where the carving circle sits: off-canvas (sun), overlapping (crescent), or a
 *  huge disc whose left edge lands exactly on the centre line (half-lit system). */
const MASK_STATE: Record<
  ThemeToggleValue,
  { cx: number; cy: number; r: number }
> = {
  dark: { cx: 17.6, cy: 8, r: 8.6 },
  light: { cx: 38, cy: 4, r: 9 },
  system: { cx: 52, cy: 12, r: 40 },
};

const DISC_RADIUS: Record<ThemeToggleValue, number> = {
  dark: 8.2,
  light: 5,
  system: 7,
};

const RAY_ROTATION: Record<ThemeToggleValue, number> = {
  dark: 60,
  light: 0,
  system: 30,
};

const GLOW_OPACITY: Record<ThemeToggleValue, number> = {
  dark: 0.16,
  light: 0.5,
  system: 0.28,
};

const GLYPH_COLOR: Record<ThemeToggleValue, string> = {
  dark: "text-indigo-400",
  light: "text-amber-500",
  system: "text-foreground",
};

const rayTarget = (angle: number, value: ThemeToggleValue) => {
  if (value === "light") {
    return { opacity: 1, scale: 1 };
  }
  if (value === "dark") {
    return { opacity: 0, scale: RAY_RETRACTED_SCALE };
  }
  // "system" keeps only the rays on the lit half of the disc.
  const isLit = angle > 90 && angle < 270;
  return {
    opacity: isLit ? 1 : 0,
    scale: isLit ? 1 : RAY_RETRACTED_SCALE,
  };
};

type SunMoonGlyphProps = {
  canAnimate: boolean;
  maskId: string;
  size: number;
  value: ThemeToggleValue;
};

const SunMoonGlyph = ({
  canAnimate,
  maskId,
  size,
  value,
}: SunMoonGlyphProps) => {
  const mask = MASK_STATE[value];
  const morph = canAnimate ? MORPH_SPRING : INSTANT;

  return (
    <svg
      aria-hidden="true"
      className={cn("transition-colors duration-300", GLYPH_COLOR[value])}
      height={size}
      viewBox={`0 0 ${VIEWBOX} ${VIEWBOX}`}
      width={size}
    >
      <mask id={maskId}>
        <rect fill="white" height={VIEWBOX} width={VIEWBOX} x={0} y={0} />
        <motion.circle
          animate={mask}
          cx={mask.cx}
          cy={mask.cy}
          fill="black"
          initial={false}
          r={mask.r}
          transition={morph}
        />
      </mask>

      <motion.circle
        animate={{ opacity: GLOW_OPACITY[value] }}
        cx={CENTER}
        cy={CENTER}
        fill="currentColor"
        initial={false}
        r={GLOW_RADIUS}
        style={{ filter: "blur(4px)" }}
        transition={canAnimate ? FADE : INSTANT}
      />

      <motion.circle
        animate={{ r: DISC_RADIUS[value] }}
        cx={CENTER}
        cy={CENTER}
        fill="currentColor"
        initial={false}
        mask={`url(#${maskId})`}
        r={DISC_RADIUS[value]}
        transition={morph}
      />

      <motion.g
        animate={{ rotate: RAY_ROTATION[value] }}
        initial={false}
        style={{ transformOrigin: `${CENTER}px ${CENTER}px` }}
        transition={morph}
      >
        {RAY_ANGLES.map((angle, index) => {
          const radians = (angle * Math.PI) / 180;
          return (
            <motion.line
              animate={rayTarget(angle, value)}
              initial={false}
              key={angle}
              stroke="currentColor"
              strokeLinecap="round"
              strokeWidth={RAY_WIDTH}
              style={{ transformOrigin: `${CENTER}px ${CENTER}px` }}
              transition={
                canAnimate ? { ...SPRING, delay: index * RAY_STAGGER } : INSTANT
              }
              x1={CENTER + Math.cos(radians) * RAY_INNER}
              x2={CENTER + Math.cos(radians) * RAY_OUTER}
              y1={CENTER + Math.sin(radians) * RAY_INNER}
              y2={CENTER + Math.sin(radians) * RAY_OUTER}
            />
          );
        })}
      </motion.g>
    </svg>
  );
};

/* -------------------------------------------------------------------------- */
/* Variant 2 — pill: segmented control with a shared-layout thumb              */
/* -------------------------------------------------------------------------- */

const ACTIVE_ICON_COLOR: Record<ThemeToggleValue, string> = {
  dark: "text-indigo-400",
  light: "text-amber-500",
  system: "text-foreground",
};

type PillToggleProps = {
  canAnimate: boolean;
  groupLabel: string;
  iconClassName: string;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>, index: number) => void;
  onSelect: (value: ThemeToggleValue) => void;
  options: OptionEntry[];
  registerRef: (index: number, el: HTMLButtonElement | null) => void;
  segmentClassName: string;
  selectedIndex: number;
  textClassName: string;
  thumbId: string;
};

const PillToggle = ({
  canAnimate,
  groupLabel,
  iconClassName,
  onKeyDown,
  onSelect,
  options,
  registerRef,
  segmentClassName,
  selectedIndex,
  textClassName,
  thumbId,
}: PillToggleProps) => (
  <div
    aria-label={groupLabel}
    className="relative inline-flex items-center gap-1 rounded-full border border-border bg-muted p-1 shadow-[inset_0_1px_3px_rgba(0,0,0,0.08)]"
    role="radiogroup"
  >
    {options.map((option, index) => {
      const active = index === selectedIndex;
      const Icon = option.icon;
      return (
        <button
          aria-checked={active}
          className={cn(
            "relative flex cursor-pointer items-center justify-center gap-2 rounded-full font-medium transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            active
              ? "text-foreground"
              : "text-muted-foreground hover:text-foreground/70",
            segmentClassName,
            textClassName
          )}
          key={option.value}
          onClick={() => onSelect(option.value)}
          onKeyDown={(event) => onKeyDown(event, index)}
          ref={(el) => {
            registerRef(index, el);
          }}
          role="radio"
          tabIndex={active ? 0 : -1}
          type="button"
        >
          {active ? (
            <motion.span
              aria-hidden="true"
              className="absolute inset-0 rounded-full bg-background shadow-[0_1px_2px_rgba(0,0,0,0.16),0_8px_18px_-8px_rgba(0,0,0,0.45)] ring-1 ring-foreground/10"
              layoutId={thumbId}
              transition={canAnimate ? SPRING : INSTANT}
            />
          ) : null}
          <Icon
            className={cn(
              "relative z-10 transition-colors duration-200",
              iconClassName,
              active ? ACTIVE_ICON_COLOR[option.value] : ""
            )}
          />
          <span className="relative z-10">{option.label}</span>
        </button>
      );
    })}
  </div>
);

/* -------------------------------------------------------------------------- */
/* Variant 3 — switch: sky-to-night track with a lit knob                      */
/* -------------------------------------------------------------------------- */

const TRACK_LAYERS: Record<ThemeToggleValue, string> = {
  dark: "linear-gradient(180deg,#1e293b 0%,#0f172a 55%,#020617 100%)",
  light: "linear-gradient(180deg,#7dd3fc 0%,#38bdf8 55%,#0284c7 100%)",
  system:
    "linear-gradient(100deg,#38bdf8 0%,#38bdf8 34%,#1e293b 64%,#020617 100%)",
};

const TRACK_LAYER_ORDER: ThemeToggleValue[] = ["light", "dark", "system"];

const STAR_POSITIONS = [
  { left: 0.14, size: 2, top: 0.26 },
  { left: 0.29, size: 1.5, top: 0.64 },
  { left: 0.45, size: 2.5, top: 0.2 },
  { left: 0.58, size: 1.5, top: 0.72 },
  { left: 0.72, size: 2, top: 0.36 },
  { left: 0.86, size: 1.5, top: 0.58 },
];

const KNOB_ICON: Record<ThemeToggleValue, LucideIcon> = {
  dark: Moon,
  light: Sun,
  system: Monitor,
};

const KNOB_ICON_COLOR: Record<ThemeToggleValue, string> = {
  dark: "text-slate-700",
  light: "text-amber-500",
  system: "text-slate-600",
};

const starOpacityFor = (value: ThemeToggleValue) => {
  if (value === "dark") {
    return 1;
  }
  return value === "system" ? 0.55 : 0;
};

type SwitchVisualProps = {
  canAnimate: boolean;
  iconClassName: string;
  index: number;
  knob: number;
  pad: number;
  trackHeight: number;
  trackWidth: number;
  value: ThemeToggleValue;
};

const SwitchVisual = ({
  canAnimate,
  iconClassName,
  index,
  knob,
  pad,
  trackHeight,
  trackWidth,
  value,
}: SwitchVisualProps) => {
  const Icon = KNOB_ICON[value];
  const starOpacity = starOpacityFor(value);

  return (
    <span
      aria-hidden="true"
      className="relative block overflow-hidden rounded-full"
      style={{ height: trackHeight, width: trackWidth }}
    >
      {TRACK_LAYER_ORDER.map((layer) => (
        <motion.span
          animate={{ opacity: layer === value ? 1 : 0 }}
          className="absolute inset-0"
          initial={false}
          key={layer}
          style={{ background: TRACK_LAYERS[layer] }}
          transition={canAnimate ? FADE : INSTANT}
        />
      ))}

      {STAR_POSITIONS.map((star, starIndex) => (
        <motion.span
          animate={{ opacity: starOpacity, scale: starOpacity > 0 ? 1 : 0.4 }}
          className="absolute rounded-full bg-white"
          initial={false}
          key={`${star.left}-${star.top}`}
          style={{
            height: star.size,
            left: star.left * trackWidth,
            top: star.top * trackHeight,
            width: star.size,
          }}
          transition={
            canAnimate ? { ...SPRING, delay: starIndex * RAY_STAGGER } : INSTANT
          }
        />
      ))}

      <span className="pointer-events-none absolute inset-0 rounded-full shadow-[inset_0_2px_6px_rgba(0,0,0,0.5),inset_0_-1px_0_rgba(255,255,255,0.2)]" />

      <motion.span
        animate={{ x: index * knob }}
        className="absolute flex items-center justify-center rounded-full bg-gradient-to-b from-white to-slate-200 shadow-[0_3px_8px_rgba(0,0,0,0.4),inset_0_-2px_4px_rgba(0,0,0,0.12),inset_0_2px_3px_rgba(255,255,255,0.95)]"
        initial={false}
        style={{ height: knob, left: pad, top: pad, width: knob }}
        transition={canAnimate ? KNOB_SPRING : INSTANT}
      >
        <span className="pointer-events-none absolute top-[12%] left-[18%] h-1/4 w-1/3 rounded-full bg-white/95 blur-[2px]" />
        <AnimatePresence initial={false} mode="wait">
          <motion.span
            animate={{ opacity: 1, rotate: 0, scale: 1 }}
            className="relative"
            exit={
              canAnimate
                ? { opacity: 0, rotate: -120, scale: 0.4 }
                : { opacity: 0, transition: INSTANT }
            }
            initial={
              canAnimate ? { opacity: 0, rotate: 120, scale: 0.4 } : false
            }
            key={value}
            transition={canAnimate ? SPRING : INSTANT}
          >
            <Icon className={cn(iconClassName, KNOB_ICON_COLOR[value])} />
          </motion.span>
        </AnimatePresence>
      </motion.span>
    </span>
  );
};

/* -------------------------------------------------------------------------- */
/* Variant 4 — orb: a lit sphere with a travelling specular and a cast bloom    */
/* -------------------------------------------------------------------------- */

const ORB_BODY: Record<ThemeToggleValue, string> = {
  dark: "radial-gradient(circle at 32% 26%, #a8b6cd 0%, #64748b 20%, #334155 52%, #0f172a 82%, #020617 100%)",
  light:
    "radial-gradient(circle at 34% 28%, #fffbeb 0%, #fde68a 24%, #fbbf24 54%, #ea580c 86%, #9a3412 100%)",
  system:
    "radial-gradient(circle at 50% 24%, #fef3c7 0%, #fbbf24 30%, #64748b 56%, #1e293b 84%, #020617 100%)",
};

const ORB_LAYER_ORDER: ThemeToggleValue[] = ["light", "dark", "system"];

const ORB_BLOOM: Record<ThemeToggleValue, string> = {
  dark: "#4f46e5",
  light: "#f59e0b",
  system: "#7c8aa5",
};

const ORB_BLOOM_OPACITY: Record<ThemeToggleValue, number> = {
  dark: 0.5,
  light: 0.62,
  system: 0.36,
};

const SPECULAR: Record<
  ThemeToggleValue,
  { opacity: number; x: number; y: number }
> = {
  dark: { opacity: 0.3, x: 0.58, y: 0.2 },
  light: { opacity: 0.92, x: 0.17, y: 0.11 },
  system: { opacity: 0.62, x: 0.38, y: 0.09 },
};

const CRATERS = [
  { left: 0.5, size: 0.2, top: 0.3 },
  { left: 0.28, size: 0.13, top: 0.58 },
  { left: 0.6, size: 0.1, top: 0.66 },
];

type OrbVisualProps = {
  canAnimate: boolean;
  size: number;
  value: ThemeToggleValue;
};

const OrbVisual = ({ canAnimate, size, value }: OrbVisualProps) => {
  const specular = SPECULAR[value];
  const travel = canAnimate ? TRAVEL : INSTANT;

  return (
    <span
      aria-hidden="true"
      className="pointer-events-none relative block"
      style={{ height: size, width: size }}
    >
      <motion.span
        animate={{
          backgroundColor: ORB_BLOOM[value],
          opacity: ORB_BLOOM_OPACITY[value],
        }}
        className="absolute left-1/2 rounded-[50%]"
        initial={false}
        style={{
          bottom: -size * 0.12,
          filter: `blur(${Math.round(size * 0.13)}px)`,
          height: size * 0.3,
          marginLeft: -size * 0.42,
          width: size * 0.84,
        }}
        transition={canAnimate ? FADE : INSTANT}
      />

      <span className="absolute inset-0 overflow-hidden rounded-full">
        {ORB_LAYER_ORDER.map((layer) => (
          <motion.span
            animate={{ opacity: layer === value ? 1 : 0 }}
            className="absolute inset-0"
            initial={false}
            key={layer}
            style={{ background: ORB_BODY[layer] }}
            transition={canAnimate ? FADE : INSTANT}
          />
        ))}

        {CRATERS.map((crater) => (
          <motion.span
            animate={{ opacity: value === "dark" ? 0.32 : 0 }}
            className="absolute rounded-full bg-slate-950"
            initial={false}
            key={`${crater.left}-${crater.top}`}
            style={{
              filter: "blur(2px)",
              height: size * crater.size,
              left: size * crater.left,
              top: size * crater.top,
              width: size * crater.size,
            }}
            transition={canAnimate ? FADE : INSTANT}
          />
        ))}

        <motion.span
          animate={{
            opacity: specular.opacity,
            x: size * specular.x,
            y: size * specular.y,
          }}
          className="absolute top-0 left-0 rounded-[50%] bg-white"
          initial={false}
          style={{
            filter: `blur(${Math.round(size * 0.06)}px)`,
            height: size * 0.24,
            width: size * 0.32,
          }}
          transition={travel}
