    if (status === "shipped") {
      return "bg-amber-500";
    }
    return "bg-emerald-500";
  };

  const renderLastOrders = () => (
    <div className="flex flex-col gap-3 p-4">
      {orders.map((order) => (
        <div
          className="flex flex-col gap-3 rounded-lg border border-border bg-muted/30 p-3 transition-colors hover:bg-muted/50"
