                {activeSection === "profile" && (
                  <motion.div
                    animate={
                      shouldReduceMotion
                        ? { height: "auto", opacity: 1 }
                        : {
                            filter: "blur(0px)",
                            height: "auto",
                            opacity: 1,
                          }
                    }
                    exit={
                      shouldReduceMotion
                        ? { height: 0, opacity: 0, transition: { duration: 0 } }
                        : { filter: "blur(10px)", height: 0, opacity: 0 }
                    }
                    initial={
                      shouldReduceMotion
                        ? { height: 0, opacity: 0 }
                        : { filter: "blur(10px)", height: 0, opacity: 0 }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : { bounce: 0, duration: 0.25, type: "spring" as const }
                    }
                  >
                    {renderEditProfile()}
                  </motion.div>
                )}
              </AnimatePresence>
              <button
                className={`flex w-full cursor-pointer items-center gap-2 rounded-lg px-3 py-2.5 font-medium text-sm transition-colors ${
                  activeSection === "orders"
                    ? "bg-primary text-primary-foreground"
