              <AnimatePresence initial={false}>
                {activeSection === "orders" && (
                  <motion.div
                    animate={
                      shouldReduceMotion
                        ? { height: "auto", opacity: 1 }
                        : {
                            filter: "blur(0px)",
                            height: "auto",
                            opacity: 1,
                          }
                    }
                    exit={
                      shouldReduceMotion
                        ? { height: 0, opacity: 0, transition: { duration: 0 } }
                        : { filter: "blur(10px)", height: 0, opacity: 0 }
                    }
                    initial={
                      shouldReduceMotion
                        ? { height: 0, opacity: 0 }
                        : { filter: "blur(10px)", height: 0, opacity: 0 }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : { bounce: 0, duration: 0.25, type: "spring" as const }
                    }
                  >
                    {renderLastOrders()}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        </PopoverContent>
      </Portal>
    </PopoverRoot>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type ComponentType,
  type KeyboardEvent as ReactKeyboardEvent,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

const LONG_PRESS_MS = 450;

/** Moving on screen: spring, no overshoot worth noticing on a 36px hop. */
const PILL_SPRING = { bounce: 0.1, duration: 0.25, type: "spring" as const };
/** Entering: strong ease-out. Exits are shorter, the decision is already made. */
const ENTER_TRANSITION = {
  duration: 0.22,
  ease: [0.23, 1, 0.32, 1] as [number, number, number, number],
};
const EXIT_TRANSITION = {
  duration: 0.14,
  ease: [0.23, 1, 0.32, 1] as [number, number, number, number],
};
const INSTANT = { duration: 0 };

const PANEL_SURFACE =
  "rounded-2xl border border-foreground/10 bg-background/80 shadow-[0px_0px_0.5px_0px_rgba(0,0,0,0.18),0px_8px_24px_-8px_rgba(0,0,0,0.28),0px_2px_6px_-2px_rgba(0,0,0,0.12)] backdrop-blur-xl";

const EDITABLE_TAGS = new Set(["INPUT", "TEXTAREA", "SELECT"]);

const isEditableTarget = (target: EventTarget | null): boolean => {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  if (EDITABLE_TAGS.has(target.tagName)) {
    return true;
  }
  return target.isContentEditable;
};

const findOwnerTool = (
  tools: VectorTool[],
  id: string | undefined
): VectorTool | undefined => {
  if (!id) {
    return;
  }
  for (const tool of tools) {
    if (tool.id === id || tool.items?.some((item) => item.id === id)) {
      return tool;
    }
  }
};

export interface VectorToolItem {
  icon: ComponentType<{ className?: string }>;
  id: string;
  label: string;
  shortcut?: string;
}

export interface VectorTool extends VectorToolItem {
  items?: VectorToolItem[];
}

export interface VectorEditorToolbarProps {
  /** Controlled active tool id (matches a top-level tool id or a nested item id). */
  activeTool?: string;
  className?: string;
  /**
   * Renders the toolbar as a draggable panel pinned near the top of its nearest
   * positioned ancestor. The overlay itself is click-through, so only the panel
   * intercepts pointer events and whatever sits underneath stays interactive.
   */
  floating?: boolean;
  onToolChange?: (toolId: string) => void;
  orientation?: "horizontal" | "vertical";
  /**
   * Content for the contextual properties panel. It floats beside the toolbar
   * rather than sitting in its flow, so revealing it never moves the tools.
   */
  properties?: ReactNode;
  /** Enables single-key shortcuts bound on `document`. Defaults to true. */
  shortcutsEnabled?: boolean;
  tools: VectorTool[];
}

/** Bottom-right corner triangle marking a tool that hides more tools. */
const CornerTriangle = () => (
  <svg
    aria-hidden="true"
    className="size-1.5 fill-current"
    focusable="false"
    viewBox="0 0 6 6"
  >
    <path d="M6 0v6H0z" />
  </svg>
);

export default function VectorEditorToolbar({
  activeTool,
  className,
  floating = false,
  onToolChange,
  orientation = "horizontal",
  properties,
  shortcutsEnabled = true,
  tools,
}: VectorEditorToolbarProps) {
  const shouldReduceMotion = Boolean(useReducedMotion());
  const pillId = useId();
  const isHorizontal = orientation === "horizontal";

  const [internalActiveTool, setInternalActiveTool] = useState<
    string | undefined
  >(activeTool ?? tools[0]?.id);
  const resolvedActiveTool = activeTool ?? internalActiveTool;
  const activeOwner = findOwnerTool(tools, resolvedActiveTool) ?? tools[0];
  const activeOwnerId = activeOwner?.id;

  const [focusedToolId, setFocusedToolId] = useState(activeOwnerId ?? "");
  const [openFlyoutId, setOpenFlyoutId] = useState<string | null>(null);
  const [flyoutFocusedIndex, setFlyoutFocusedIndex] = useState(0);

  const boundsRef = useRef<HTMLDivElement>(null);
  const flyoutPanelRef = useRef<HTMLDivElement | null>(null);
  const toolButtonRefs = useRef(new Map<string, HTMLButtonElement>());
  const flyoutItemRefs = useRef(new Map<string, HTMLButtonElement>());
  const longPressTimerRef = useRef<number | null>(null);
  const longPressTriggeredRef = useRef(false);

  const selectTool = useCallback(
    (id: string) => {
      if (activeTool === undefined) {
        setInternalActiveTool(id);
      }
      onToolChange?.(id);
      setOpenFlyoutId(null);
    },
    [activeTool, onToolChange]
  );

  // Keep roving tabindex in sync with the resolved active tool.
  useEffect(() => {
    setFocusedToolId(activeOwnerId ?? "");
  }, [activeOwnerId]);

  // Close the open flyout when clicking outside its panel and trigger.
  useEffect(() => {
    if (!openFlyoutId) {
      return;
    }
    const handlePointerDown = (event: PointerEvent) => {
      const panel = flyoutPanelRef.current;
      const trigger = toolButtonRefs.current.get(openFlyoutId);
      const target = event.target as Node;
      if (panel?.contains(target) || trigger?.contains(target)) {
        return;
      }
      setOpenFlyoutId(null);
    };
    document.addEventListener("pointerdown", handlePointerDown);
    return () => document.removeEventListener("pointerdown", handlePointerDown);
  }, [openFlyoutId]);

  // Move focus onto the highlighted flyout item as the user navigates it.
  useEffect(() => {
    if (!openFlyoutId) {
      return;
    }
    const tool = tools.find((candidate) => candidate.id === openFlyoutId);
    const item = tool?.items?.[flyoutFocusedIndex];
    if (item) {
      flyoutItemRefs.current.get(item.id)?.focus();
    }
  }, [openFlyoutId, flyoutFocusedIndex, tools]);

  // Single-key shortcuts, ignored while typing in an editable field.
  useEffect(() => {
    if (!shortcutsEnabled) {
      return;
    }
    const handleKeyDown = (event: KeyboardEvent) => {
      if (isEditableTarget(event.target)) {
        return;
      }
      if (event.metaKey || event.ctrlKey || event.altKey) {
        return;
      }
      const key = event.key.toLowerCase();
      for (const tool of tools) {
        if (tool.shortcut?.toLowerCase() === key) {
          selectTool(tool.id);
          return;
        }
        for (const item of tool.items ?? []) {
          if (item.shortcut?.toLowerCase() === key) {
            selectTool(item.id);
            return;
          }
        }
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [shortcutsEnabled, tools, selectTool]);

  useEffect(
    () => () => {
      if (longPressTimerRef.current !== null) {
        window.clearTimeout(longPressTimerRef.current);
      }
    },
    []
  );

  const clearLongPressTimer = () => {
    if (longPressTimerRef.current !== null) {
      window.clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  };

  const openFlyout = (toolId: string) => {
    setOpenFlyoutId(toolId);
    setFlyoutFocusedIndex(0);
  };

  const handleToolPointerDown = (tool: VectorTool) => {
    longPressTriggeredRef.current = false;
    if (!tool.items?.length) {
      return;
    }
    longPressTimerRef.current = window.setTimeout(() => {
      longPressTriggeredRef.current = true;
      openFlyout(tool.id);
    }, LONG_PRESS_MS);
  };

  const handleToolClick = (tool: VectorTool) => {
    if (longPressTriggeredRef.current) {
      longPressTriggeredRef.current = false;
      return;
    }
    // Clicking the tool that is already active reveals its variants, so the
    // flyout is reachable without knowing about long-press.
    if (tool.items?.length && tool.id === activeOwnerId) {
      openFlyout(tool.id);
      return;
    }
    selectTool(tool.id);
  };

  const handleCornerClick = (
    tool: VectorTool,
    event: ReactMouseEvent<HTMLButtonElement>
  ) => {
    event.stopPropagation();
    clearLongPressTimer();
    setOpenFlyoutId((previous) => (previous === tool.id ? null : tool.id));
    setFlyoutFocusedIndex(0);
  };

  const handleToolbarKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (openFlyoutId) {
      return;
    }
    const nextKey = isHorizontal ? "ArrowRight" : "ArrowDown";
    const prevKey = isHorizontal ? "ArrowLeft" : "ArrowUp";
    const openKey = isHorizontal ? "ArrowDown" : "ArrowRight";

    if (event.key === openKey) {
      const tool = tools.find((candidate) => candidate.id === focusedToolId);
      if (tool?.items?.length) {
        event.preventDefault();
        openFlyout(tool.id);
      }
      return;
    }

    if (event.key !== nextKey && event.key !== prevKey) {
      return;
    }
    event.preventDefault();
    const currentIndex = tools.findIndex(
      (candidate) => candidate.id === focusedToolId
    );
    const delta = event.key === nextKey ? 1 : -1;
    const nextIndex = (currentIndex + delta + tools.length) % tools.length;
    const nextTool = tools[nextIndex];
    if (!nextTool) {
      return;
    }
    setFocusedToolId(nextTool.id);
    toolButtonRefs.current.get(nextTool.id)?.focus();
  };

  const handleFlyoutKeyDown = (
    event: ReactKeyboardEvent<HTMLDivElement>,
    tool: VectorTool
  ) => {
    const items = tool.items ?? [];
    if (event.key === "Escape") {
      event.preventDefault();
      setOpenFlyoutId(null);
      toolButtonRefs.current.get(tool.id)?.focus();
      return;
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const delta = event.key === "ArrowDown" ? 1 : -1;
      setFlyoutFocusedIndex(
        (previous) => (previous + delta + items.length) % items.length
      );
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      const item = items[flyoutFocusedIndex];
      if (item) {
        selectTool(item.id);
        toolButtonRefs.current.get(tool.id)?.focus();
      }
    }
  };

  const renderFlyout = (tool: VectorTool) => (
    <div
      className={cn(
        "absolute z-30",
        isHorizontal
          ? "top-full left-1/2 mt-2 -translate-x-1/2"
          : "top-0 left-full ml-2"
      )}
    >
      <AnimatePresence>
        {openFlyoutId === tool.id ? (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            aria-label={`${tool.label} options`}
            className={cn(
              "relative flex min-w-44 flex-col gap-0.5 p-1.5",
              PANEL_SURFACE
            )}
            exit={
              shouldReduceMotion
                ? { opacity: 0, transition: INSTANT }
                : { opacity: 0, scale: 0.98, transition: EXIT_TRANSITION }
            }
            initial={
              shouldReduceMotion ? { opacity: 1 } : { opacity: 0, scale: 0.96 }
            }
            onKeyDown={(event) => handleFlyoutKeyDown(event, tool)}
            ref={flyoutPanelRef}
            role="group"
            style={{
              transformOrigin: isHorizontal ? "top center" : "left center",
            }}
            transition={shouldReduceMotion ? INSTANT : ENTER_TRANSITION}
          >
            <span
              aria-hidden="true"
              className={cn(
                "absolute size-2 rotate-45 border-foreground/10 bg-background",
                isHorizontal
                  ? "-top-1 left-1/2 -translate-x-1/2 border-t border-l"
                  : "top-4 -left-1 border-b border-l"
              )}
            />
            {tool.items?.map((item, index) => {
              const ItemIcon = item.icon;
              const isItemActive = resolvedActiveTool === item.id;
              return (
                <button
                  aria-label={item.label}
                  aria-pressed={isItemActive}
                  className={cn(
                    "flex cursor-pointer items-center gap-2.5 rounded-lg px-2 py-1.5 text-left text-foreground/70 text-sm transition-colors ease-out hover:bg-foreground/5 hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand focus-visible:outline-offset-1",
                    isItemActive && "bg-foreground/10 text-foreground",
                    flyoutFocusedIndex === index && "bg-foreground/5"
                  )}
                  key={item.id}
                  onClick={() => {
                    selectTool(item.id);
                    toolButtonRefs.current.get(tool.id)?.focus();
                  }}
                  ref={(el) => {
                    if (el) {
                      flyoutItemRefs.current.set(item.id, el);
                    } else {
                      flyoutItemRefs.current.delete(item.id);
                    }
                  }}
                  tabIndex={-1}
                  type="button"
                >
                  <ItemIcon className="size-4 shrink-0" />
                  <span className="flex-1">{item.label}</span>
                  {item.shortcut ? (
                    <span className="font-medium text-[10px] text-foreground/40 uppercase tabular-nums">
                      {item.shortcut}
                    </span>
                  ) : null}
                </button>
              );
            })}
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );

  const toolbarPanel = (
    <div className="relative">
      <div
        aria-label="Vector editor tools"
        aria-orientation={orientation}
        className={cn(
          "flex items-center gap-1 p-1.5",
          PANEL_SURFACE,
          isHorizontal ? "flex-row" : "flex-col"
        )}
        onKeyDown={handleToolbarKeyDown}
        role="toolbar"
      >
        {tools.map((tool) => {
          const isActive = tool.id === activeOwnerId;
          const activeItem = tool.items?.find(
            (item) => item.id === resolvedActiveTool
          );
          // Figma-style: the cell adopts the icon of the variant last used.
          const Icon = (isActive && activeItem?.icon) || tool.icon;
          const isFocusable = tool.id === focusedToolId;
          const hasItems = Boolean(tool.items?.length);
          const isFlyoutOpen = openFlyoutId === tool.id;
          const label = (isActive && activeItem?.label) || tool.label;

          return (
            <div className="relative size-9 shrink-0" key={tool.id}>
              {isActive ? (
                <motion.span
                  className="absolute inset-0 rounded-xl bg-foreground/10"
                  layoutId={`vector-editor-toolbar-pill-${pillId}`}
                  transition={shouldReduceMotion ? INSTANT : PILL_SPRING}
                />
              ) : null}
              <button
                aria-expanded={hasItems ? isFlyoutOpen : undefined}
                aria-haspopup={hasItems ? "menu" : undefined}
                aria-label={label}
                aria-pressed={isActive}
                className={cn(
                  "absolute inset-0 flex cursor-pointer items-center justify-center rounded-xl text-foreground/60",
                  "transition-[color,transform] duration-150 ease-out active:scale-[0.92]",
                  "hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-brand focus-visible:outline-offset-2",
                  "motion-reduce:transition-none motion-reduce:active:scale-100",
                  isActive && "text-foreground"
                )}
                onClick={() => handleToolClick(tool)}
                onPointerCancel={clearLongPressTimer}
                onPointerDown={() => handleToolPointerDown(tool)}
                onPointerLeave={clearLongPressTimer}
                onPointerUp={clearLongPressTimer}
                ref={(el) => {
                  if (el) {
                    toolButtonRefs.current.set(tool.id, el);
                  } else {
                    toolButtonRefs.current.delete(tool.id);
                  }
                }}
                tabIndex={isFocusable ? 0 : -1}
                title={
                  tool.shortcut
                    ? `${label} (${tool.shortcut.toUpperCase()})`
                    : label
                }
                type="button"
              >
                <Icon className="size-4" />
              </button>
              {hasItems ? (
                <button
                  aria-label={`${tool.label} options`}
                  className={cn(
                    "absolute right-0 bottom-0 flex size-3.5 cursor-pointer items-end justify-end rounded-br-xl pr-[3px] pb-[3px]",
                    "text-foreground/25 transition-colors ease-out hover:text-foreground/70",
                    isActive && "text-foreground/45"
                  )}
                  onClick={(event) => handleCornerClick(tool, event)}
                  tabIndex={-1}
                  type="button"
                >
                  <CornerTriangle />
                </button>
              ) : null}
              {hasItems ? renderFlyout(tool) : null}
            </div>
          );
        })}
      </div>

      <div
        className={cn(
          "absolute z-20",
          // Vertical flyouts already own the right-hand side, so the properties
          // panel goes below the toolbar in both orientations.
          isHorizontal
            ? "top-full left-1/2 mt-1.5 -translate-x-1/2"
            : "top-full left-0 mt-1.5"
        )}
      >
        <AnimatePresence>
          {properties ? (
            <motion.div
              animate={{ opacity: 1, scale: 1, y: 0 }}
              className={cn("w-max p-2", PANEL_SURFACE)}
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: INSTANT }
                  : {
                      opacity: 0,
                      scale: 0.98,
                      transition: EXIT_TRANSITION,
                      y: -4,
                    }
              }
              initial={
                shouldReduceMotion
                  ? { opacity: 1, scale: 1, y: 0 }
                  : { opacity: 0, scale: 0.98, y: -4 }
              }
              style={{
                transformOrigin: isHorizontal ? "top center" : "top left",
              }}
              transition={shouldReduceMotion ? INSTANT : ENTER_TRANSITION}
            >
              {properties}
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  );

  if (!floating) {
    return (
      <div className={cn("relative", className)} ref={boundsRef}>
        {toolbarPanel}
      </div>
    );
  }

  return (
    <div
      className={cn("pointer-events-none absolute inset-0", className)}
      ref={boundsRef}
    >
      <div className="absolute inset-x-0 top-4 flex justify-center">
        <motion.div
          className="pointer-events-auto"
          drag
          dragConstraints={boundsRef}
          dragElastic={0}
          dragMomentum={false}
          style={{ touchAction: "none" }}
        >
          {toolbarPanel}
        </motion.div>
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const DEFAULT_INTENSITY = 0.9;
const DEFAULT_BLUR_PX = 34;
const DEFAULT_SAMPLE_RATE_FPS = 12;
const DEFAULT_SCALE = 1.3;
const DEFAULT_SATURATION = 1.9;
const DEFAULT_GAIN = 1.7;
const GLOW_BRIGHTNESS = 1.12;
const BLOOM_BRIGHTNESS = 1.2;
const DEFAULT_ROUNDED_PX = 20;

/**
 * The sampled canvas is deliberately tiny. The glow is a colour field, not a
 * picture — a low-resolution grab left to the browser's own bilinear upscaling
 * is already a soft gradient, so the CSS blur only has to finish the job.
 */
const SAMPLE_WIDTH = 24;
const SAMPLE_HEIGHT = 14;

/** The outer pass is bigger, softer and more saturated than the inner one. */
const BLOOM_SCALE_FACTOR = 1.55;
const BLOOM_BLUR_FACTOR = 1.9;
const BLOOM_SATURATION_FACTOR = 1.2;
const BLOOM_OPACITY_FACTOR = 0.6;

const MS_PER_SECOND = 1000;
const MIN_SAMPLE_RATE = 1;
const MAX_SAMPLE_RATE = 60;
const GLOW_FADE_MS = 400;
const STATIC_GRADIENT_OPACITY_FACTOR = 0.55;
const HAVE_CURRENT_DATA = 2;

/* -------------------------------------------------------------------------- */
/* Public types                                                               */
/* -------------------------------------------------------------------------- */

export type VideoAmbientProps = {
  /** Describes the video content for assistive technology. */
  alt: string;
  autoPlay?: boolean;
  /** Blur radius in pixels on the inner glow. The outer bloom doubles it. */
  blur?: number;
  className?: string;
  controls?: boolean;
  /**
   * Extra light pushed into the glow. The sampled frame is composited onto
   * itself with `lighter`, so 1 is the video's own brightness and anything
   * above it reads as emitted light rather than a colour wash. Values past
   * ~2.2 clip the highlights to white.
   */
  gain?: number;
  /** Turn the ambient glow off entirely — useful for an A/B toggle. */
  glow?: boolean;
  /** Glow opacity, 0–1. */
  intensity?: number;
  loop?: boolean;
  muted?: boolean;
  poster?: string;
  /** Border radius in pixels applied to the video itself. */
  rounded?: number;
  /** How many times per second the glow re-samples the current frame. */
  sampleRate?: number;
  /** Colour boost on the glow, 1 = the video's own saturation. */
  saturation?: number;
  /** How far past the video's edges the inner glow bleeds, 1 = no bleed. */
  scale?: number;
  src: string;
};

/* -------------------------------------------------------------------------- */
/* Component                                                                  */
/* -------------------------------------------------------------------------- */

/**
 * A video with an ambient glow sampled from its own frames.
 *
 * Two passes make the effect read: an inner glow scaled just past the player's
 * edges, and a much larger, softer, more saturated bloom behind it. Both are
 * drawn from the same 24×14 grab, so the bleed costs two `drawImage` calls per
 * sample regardless of the video's real resolution.
 *
 * No pixel data is ever read back, so the effect survives a cross-origin source
 * with no CORS headers. The one thing that can still fail is `drawImage` itself,
 * which a handful of strict configurations throw on for a tainted source; that
 * failure is caught and the glow falls back to a blurred poster or a
 * theme-coloured gradient.
 */
const VideoAmbient = ({
  alt,
  autoPlay = true,
  blur = DEFAULT_BLUR_PX,
  className,
  controls = false,
  gain = DEFAULT_GAIN,
  glow = true,
  intensity = DEFAULT_INTENSITY,
  loop = true,
  muted = true,
  poster,
  rounded = DEFAULT_ROUNDED_PX,
  sampleRate = DEFAULT_SAMPLE_RATE_FPS,
  saturation = DEFAULT_SATURATION,
  scale = DEFAULT_SCALE,
  src,
}: VideoAmbientProps) => {
  const shouldReduceMotion = Boolean(useReducedMotion());

  const containerRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const innerCanvasRef = useRef<HTMLCanvasElement>(null);
  const bloomCanvasRef = useRef<HTMLCanvasElement>(null);
  /** Mirrors `hasFrame` so the sample loop never sets state per frame. */
  const hasFrameRef = useRef(false);

  const [isPlaying, setIsPlaying] = useState(false);
  const [isOnScreen, setIsOnScreen] = useState(true);
  const [isTabVisible, setIsTabVisible] = useState(true);
  const [isBlocked, setIsBlocked] = useState(false);
  const [hasFrame, setHasFrame] = useState(false);

  // Autoplay never fights reduced motion — a moving glow behind a page that
  // asked to stay still is the exact thing the preference exists to prevent.
  const effectiveAutoPlay = autoPlay && !shouldReduceMotion;
  const showSampledGlow = glow && hasFrame && !isBlocked;
  const showFallbackGlow = glow && !showSampledGlow;

  const sampleFrame = useCallback(() => {
    const video = videoRef.current;
    if (!video || video.readyState < HAVE_CURRENT_DATA) {
      return;
    }
    const extraGain = Math.max(0, gain - 1);
    const canvases = [innerCanvasRef.current, bloomCanvasRef.current];
    for (const canvas of canvases) {
      const ctx = canvas?.getContext("2d");
      if (!(canvas && ctx)) {
        continue;
      }
      try {
        ctx.globalCompositeOperation = "source-over";
        ctx.globalAlpha = 1;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        if (extraGain > 0) {
          // Composited onto itself with `lighter`, the frame gains light rather
          // than paint. Without this the glow reads as a tint over whatever it
          // sits on — the difference between a lamp and a coloured filter.
          ctx.globalCompositeOperation = "lighter";
          ctx.globalAlpha = extraGain;
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          ctx.globalCompositeOperation = "source-over";
          ctx.globalAlpha = 1;
        }
      } catch {
        // A few strict configurations throw on drawImage for a tainted
        // cross-origin source — the static fallback below takes over.
        setIsBlocked(true);
        return;
      }
    }
    if (!hasFrameRef.current) {
      hasFrameRef.current = true;
      setHasFrame(true);
    }
  }, [gain]);

  // Playback state is read from the element rather than assumed, so a video
  // that was already playing before this effect ran still drives the loop.
  useEffect(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    const sync = () => setIsPlaying(!(video.paused || video.ended));
    sync();
    const events = ["play", "playing", "pause", "ended", "loadeddata"];
    for (const event of events) {
      video.addEventListener(event, sync);
    }
    return () => {
      for (const event of events) {
        video.removeEventListener(event, sync);
      }
    };
  }, []);

  // Some browsers reject a programmatic-looking autoplay even when muted; a
  // rejected promise here just means the user presses play themselves.
  useEffect(() => {
    const video = videoRef.current;
    if (!(video && effectiveAutoPlay)) {
      return;
    }
    const attempt = () => {
      video.play().catch(() => {
        /* Autoplay refused — controls remain available. */
      });
    };
    if (video.readyState >= HAVE_CURRENT_DATA) {
      attempt();
      return;
    }
    video.addEventListener("loadeddata", attempt, { once: true });
    return () => video.removeEventListener("loadeddata", attempt);
  }, [effectiveAutoPlay]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setIsOnScreen(entry.isIntersecting)
    );
    observer.observe(container);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const handleVisibility = () => setIsTabVisible(!document.hidden);
    document.addEventListener("visibilitychange", handleVisibility);
    return () =>
      document.removeEventListener("visibilitychange", handleVisibility);
  }, []);

  // Reduced motion draws exactly one frame and stops there: the glow stays
  // present, it just never moves again.
  useEffect(() => {
    if (!(glow && shouldReduceMotion)) {
      return;
    }
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (video.readyState >= HAVE_CURRENT_DATA) {
      sampleFrame();
      return;
    }
    video.addEventListener("loadeddata", sampleFrame, { once: true });
    return () => video.removeEventListener("loadeddata", sampleFrame);
  }, [glow, sampleFrame, shouldReduceMotion]);

  // Sampling only runs while there is something worth sampling: playing, on
  // screen, and the tab actually visible. The loop is rAF-driven and throttled
  // rather than interval-driven so it never fires on a frame the browser is
  // already dropping.
  useEffect(() => {
    const isWorthSampling =
      glow &&
      !(isBlocked || shouldReduceMotion) &&
      isPlaying &&
      isOnScreen &&
      isTabVisible;
    if (!isWorthSampling) {
      return;
    }
    const minDelta =
      MS_PER_SECOND /
      Math.min(MAX_SAMPLE_RATE, Math.max(MIN_SAMPLE_RATE, sampleRate));
    let frameId = 0;
    let lastSampleAt = 0;
    const tick = (now: number) => {
      frameId = requestAnimationFrame(tick);
      if (now - lastSampleAt < minDelta) {
        return;
      }
      lastSampleAt = now;
      sampleFrame();
    };
    frameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameId);
  }, [
    glow,
    isBlocked,
    isOnScreen,
    isPlaying,
    isTabVisible,
    sampleFrame,
    sampleRate,
    shouldReduceMotion,
  ]);

  const glowTransition = `opacity ${GLOW_FADE_MS}ms cubic-bezier(0.23, 1, 0.32, 1)`;

  return (
    <div className={cn("relative isolate", className)} ref={containerRef}>
      {glow ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 z-0"
        >
          {/* Outer bloom: bigger, softer, more saturated. */}
          <canvas
            className="absolute inset-0 size-full"
            height={SAMPLE_HEIGHT}
            ref={bloomCanvasRef}
            style={{
              filter: `blur(${blur * BLOOM_BLUR_FACTOR}px) saturate(${saturation * BLOOM_SATURATION_FACTOR}) brightness(${BLOOM_BRIGHTNESS})`,
              opacity: showSampledGlow ? intensity * BLOOM_OPACITY_FACTOR : 0,
              transform: `scale(${scale * BLOOM_SCALE_FACTOR})`,
              transition: glowTransition,
            }}
            width={SAMPLE_WIDTH}
          />
          {/* Inner glow: hugs the player, carries the colour. */}
          <canvas
            className="absolute inset-0 size-full"
            height={SAMPLE_HEIGHT}
            ref={innerCanvasRef}
            style={{
              filter: `blur(${blur}px) saturate(${saturation}) brightness(${GLOW_BRIGHTNESS})`,
              opacity: showSampledGlow ? intensity : 0,
              transform: `scale(${scale})`,
              transition: glowTransition,
            }}
            width={SAMPLE_WIDTH}
          />
        </div>
      ) : null}

      {/* Stays mounted so the first sampled frame crossfades in rather than cutting. */}
      {glow ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 z-0"
          style={{
            opacity: showFallbackGlow ? 1 : 0,
            transition: glowTransition,
          }}
        >
          {poster ? (
            <img
              alt=""
              className="absolute inset-0 size-full object-cover"
              src={poster}
              style={{
                filter: `blur(${blur}px) saturate(${saturation})`,
                opacity: intensity * STATIC_GRADIENT_OPACITY_FACTOR,
                transform: `scale(${scale})`,
              }}
            />
          ) : (
            <div
              className="absolute inset-0 rounded-full"
              style={{
                background:
                  "radial-gradient(circle, var(--color-brand, currentColor) 0%, transparent 70%)",
                filter: `blur(${blur}px)`,
                opacity: intensity * STATIC_GRADIENT_OPACITY_FACTOR,
                transform: `scale(${scale})`,
              }}
            />
          )}
        </div>
      ) : null}

      <video
        aria-label={alt}
        autoPlay={effectiveAutoPlay}
        className="relative z-10 block size-full object-cover"
        controls={controls}
        loop={loop}
        muted={muted}
        playsInline
        poster={poster}
        ref={videoRef}
        src={src}
        style={{ borderRadius: rounded }}
      />
    </div>
  );
};

export default VideoAmbient;

"use client";

import { cn } from "@/lib/utils";
import SmoothButton from "@/components/smoothui/smooth-button";
import {
  Maximize,
  Minimize,
  Pause,
  Play,
  Volume2,
  VolumeX,
  X,
} from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import {
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const SPRING_PANEL = { bounce: 0.1, duration: 0.25, type: "spring" as const };
const BACKDROP_DURATION = 0.2;
const SEEK_STEP_SECONDS = 5;
const SECONDS_PER_MINUTE = 60;
const TIME_PAD_LENGTH = 2;
const THUMBNAIL_PLAY_ICON_SIZE = 22;

/** Control-bar buttons sit on video, so the ghost variant is tinted white via
 *  the `color` axis' own custom property rather than a text/hover override. */
const CONTROL_BUTTON_CLASS = "shrink-0 [--btn:#fff]";

const FOCUSABLE_SELECTOR =
  'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';

/* -------------------------------------------------------------------------- */
/* Public types                                                               */
/* -------------------------------------------------------------------------- */

export type VideoModalCaption = {
  /** Human-readable track name, e.g. "English". */
  label: string;
  src: string;
  /** BCP 47 language tag, e.g. "en". */
  srcLang: string;
};

export type VideoModalProps = {
  /** Starts playback once the modal finishes opening. Ignored under reduced motion. */
  autoPlayOnOpen?: boolean;
  captions?: VideoModalCaption[];
  className?: string;
  onOpenChange?: (open: boolean) => void;
  /** Controlled open state. Omit to let the component own it. */
  open?: boolean;
  poster?: string;
  /** Renders the built-in control bar instead of the browser's native one. */
  showCustomControls?: boolean;
  src: string;
  /** CSS `aspect-ratio` value for the closed thumbnail, e.g. "16/9". */
  thumbnailAspect?: string;
  title: string;
};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

const formatTime = (seconds: number): string => {
  if (!Number.isFinite(seconds) || seconds < 0) {
    return "0:00";
  }
  const minutes = Math.floor(seconds / SECONDS_PER_MINUTE);
  const remainder = Math.floor(seconds % SECONDS_PER_MINUTE);
  return `${minutes}:${remainder.toString().padStart(TIME_PAD_LENGTH, "0")}`;
};

/* -------------------------------------------------------------------------- */
/* Custom control bar                                                         */
/* -------------------------------------------------------------------------- */

type VideoModalControlsProps = {
  currentTime: number;
  duration: number;
  isFullscreen: boolean;
  isMuted: boolean;
  isPlaying: boolean;
  onScrubKeyDown: (event: ReactKeyboardEvent<HTMLDivElement>) => void;
  onScrubPointerDown: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onToggleFullscreen: () => void;
  onToggleMute: () => void;
  onTogglePlay: () => void;
  progress: number;
};

const VideoModalControls = ({
  currentTime,
  duration,
  isFullscreen,
  isMuted,
  isPlaying,
  onScrubKeyDown,
  onScrubPointerDown,
  onToggleFullscreen,
  onToggleMute,
  onTogglePlay,
  progress,
}: VideoModalControlsProps) => (
  <div className="absolute inset-x-0 bottom-0 flex items-center gap-3 bg-gradient-to-t from-black/85 to-transparent px-4 py-3 text-white">
    <SmoothButton
      aria-label={isPlaying ? "Pause" : "Play"}
      className={cn(CONTROL_BUTTON_CLASS, "[&_svg]:size-[18px]")}
      onClick={onTogglePlay}
      shape="pill"
      size="icon-sm"
      variant="ghost"
    >
      {isPlaying ? (
        <Pause aria-hidden="true" fill="currentColor" />
      ) : (
        <Play aria-hidden="true" fill="currentColor" />
      )}
    </SmoothButton>

    <div
      aria-label="Seek"
      aria-valuemax={Math.round(duration)}
      aria-valuemin={0}
      aria-valuenow={Math.round(currentTime)}
      aria-valuetext={`${formatTime(currentTime)} of ${formatTime(duration)}`}
      className="relative h-1.5 flex-1 cursor-pointer touch-none rounded-full bg-white/25"
      onKeyDown={onScrubKeyDown}
      onPointerDown={onScrubPointerDown}
      role="slider"
      tabIndex={0}
    >
      <div
        className="pointer-events-none absolute inset-y-0 left-0 rounded-full bg-white"
        style={{ width: `${progress}%` }}
      />
    </div>

    <span className="shrink-0 whitespace-nowrap text-xs tabular-nums">
      {formatTime(currentTime)} / {formatTime(duration)}
    </span>

    <SmoothButton
      aria-label={isMuted ? "Unmute" : "Mute"}
      className={CONTROL_BUTTON_CLASS}
      onClick={onToggleMute}
      shape="pill"
      size="icon-sm"
      variant="ghost"
    >
      {isMuted ? (
        <VolumeX aria-hidden="true" />
      ) : (
        <Volume2 aria-hidden="true" />
      )}
    </SmoothButton>

    <SmoothButton
      aria-label={isFullscreen ? "Exit fullscreen" : "Enter fullscreen"}
      className={CONTROL_BUTTON_CLASS}
      onClick={onToggleFullscreen}
      shape="pill"
      size="icon-sm"
      variant="ghost"
    >
      {isFullscreen ? (
        <Minimize aria-hidden="true" />
      ) : (
        <Maximize aria-hidden="true" />
      )}
    </SmoothButton>
  </div>
);

/* -------------------------------------------------------------------------- */
/* Component                                                                  */
/* -------------------------------------------------------------------------- */

/**
 * A thumbnail that morphs into a full player.
 *
 * The thumbnail and the modal frame share one `layoutId`, so opening reads as
 * the same rectangle growing into place rather than a new one appearing on
 * top of it. The thumbnail stays mounted — invisible — for exactly as long as
 * the modal is open, because Motion needs a live node with that id to measure
 * the box it is morphing from and back into.
 */
const VideoModal = ({
  autoPlayOnOpen = true,
  captions = [],
  className,
  onOpenChange,
  open,
  poster,
  showCustomControls = true,
  src,
  thumbnailAspect = "16/9",
  title,
}: VideoModalProps) => {
  const shouldReduceMotion = Boolean(useReducedMotion());
  const frameLayoutId = `${useId()}-frame`;

  const [mounted, setMounted] = useState(false);
  const [internalOpen, setInternalOpen] = useState(false);
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const previousOverflowRef = useRef<string | null>(null);

  useEffect(() => setMounted(true), []);

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) {
        setInternalOpen(next);
      }
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange]
  );

  const close = useCallback(() => setOpen(false), [setOpen]);

  // Body scroll locks while the modal is open, and only while it is open.
  useEffect(() => {
    if (!isOpen) {
      return;
    }
    previousOverflowRef.current = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previousOverflowRef.current ?? "";
    };
  }, [isOpen]);

  // Focus enters the panel on open and returns to the trigger on close.
  useEffect(() => {
    if (isOpen) {
      panelRef.current?.focus();
    } else {
      triggerRef.current?.focus();
    }
  }, [isOpen]);

  // Escape closes the modal; Tab is trapped inside the panel.
  useEffect(() => {
    if (!isOpen) {
      return;
    }
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        close();
        return;
      }
      if (event.key !== "Tab" || !panelRef.current) {
        return;
      }
      const focusable = Array.from(
        panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)
      );
      const [first] = focusable;
      const last = focusable.at(-1);
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, close]);

  // The video pauses whenever the modal closes or the tab goes hidden — an
  // autoplaying video nobody can see is just a battery drain.
  useEffect(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (!isOpen) {
      video.pause();
      return;
    }
    if (autoPlayOnOpen && !shouldReduceMotion) {
      video.play().catch(() => {
        // Autoplay can be blocked by the browser; the play button still works.
      });
    }
    const handleVisibility = () => {
      if (document.hidden) {
        video.pause();
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () =>
      document.removeEventListener("visibilitychange", handleVisibility);
  }, [isOpen, autoPlayOnOpen, shouldReduceMotion]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);
    const handleTimeUpdate = () => setCurrentTime(video.currentTime);
    const handleLoadedMetadata = () => setDuration(video.duration || 0);
    const handleVolumeChange = () => setIsMuted(video.muted);
    video.addEventListener("play", handlePlay);
    video.addEventListener("pause", handlePause);
    video.addEventListener("timeupdate", handleTimeUpdate);
    video.addEventListener("loadedmetadata", handleLoadedMetadata);
    video.addEventListener("volumechange", handleVolumeChange);
    return () => {
      video.removeEventListener("play", handlePlay);
      video.removeEventListener("pause", handlePause);
      video.removeEventListener("timeupdate", handleTimeUpdate);
      video.removeEventListener("loadedmetadata", handleLoadedMetadata);
      video.removeEventListener("volumechange", handleVolumeChange);
    };
    // The <video> only exists once the portal has mounted and the modal is
    // open, both of which land a render after this effect first runs. With an
    // empty dependency array it found a null ref and never re-ran, so the
    // control bar's play state, mute state and scrub position never tracked
    // actual playback.
  }, [mounted, isOpen]);

  useEffect(() => {
    const handleFullscreenChange = () =>
      setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", handleFullscreenChange);
    return () =>
      document.removeEventListener("fullscreenchange", handleFullscreenChange);
  }, []);

  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    if (video.paused) {
      video.play().catch(() => {
        // Ignore — nothing useful to surface for a blocked play() here.
      });
    } else {
      video.pause();
    }
  };

  const toggleMute = () => {
    const video = videoRef.current;
    if (video) {
      video.muted = !video.muted;
    }
  };

  const toggleFullscreen = () => {
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(() => {});
    } else {
      panelRef.current?.requestFullscreen().catch(() => {});
    }
  };

  const seekTo = (time: number) => {
    const video = videoRef.current;
    if (!video || duration <= 0) {
      return;
    }
    video.currentTime = Math.min(Math.max(time, 0), duration);
  };

  const handleScrubPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    const track = event.currentTarget;
    track.setPointerCapture(event.pointerId);
    const scrub = (clientX: number) => {
      const rect = track.getBoundingClientRect();
      const ratio = Math.min(
        Math.max((clientX - rect.left) / rect.width, 0),
        1
      );
      seekTo(ratio * duration);
    };
    scrub(event.clientX);
    const handleMove = (moveEvent: PointerEvent) => scrub(moveEvent.clientX);
    const handleUp = () => {
      track.removeEventListener("pointermove", handleMove);
      track.removeEventListener("pointerup", handleUp);
    };
    track.addEventListener("pointermove", handleMove);
    track.addEventListener("pointerup", handleUp);
  };

  const handleScrubKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    switch (event.key) {
      case "ArrowRight":
        event.preventDefault();
        seekTo(currentTime + SEEK_STEP_SECONDS);
        break;
      case "ArrowLeft":
        event.preventDefault();
        seekTo(currentTime - SEEK_STEP_SECONDS);
        break;
      case "Home":
        event.preventDefault();
        seekTo(0);
        break;
      case "End":
        event.preventDefault();
        seekTo(duration);
        break;
      default:
        break;
    }
  };

  const progress = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <>
      <button
        aria-hidden={isOpen}
        aria-label={`Play ${title}`}
        className={cn(
          "group relative block w-full cursor-pointer overflow-hidden rounded-xl border border-border bg-muted text-left",
          className
        )}
        onClick={() => setOpen(true)}
        ref={triggerRef}
        tabIndex={isOpen ? -1 : 0}
        type="button"
      >
        <motion.div
          animate={isOpen ? { opacity: 0 } : { opacity: 1 }}
          className="relative w-full"
          layoutId={shouldReduceMotion ? undefined : frameLayoutId}
          style={{ aspectRatio: thumbnailAspect }}
          transition={shouldReduceMotion ? { duration: 0 } : SPRING_PANEL}
        >
          {poster ? (
            <img
              alt=""
              className="size-full object-cover"
              height={720}
              src={poster}
              width={1280}
            />
          ) : (
            <div className="size-full bg-foreground/10" />
          )}
          <span className="absolute inset-0 flex items-center justify-center bg-black/20 transition-colors group-hover:bg-black/30">
            <span className="flex size-14 items-center justify-center rounded-full bg-white/90 text-black shadow-lg transition-transform group-hover:scale-105">
              <Play
                aria-hidden="true"
                fill="currentColor"
                size={THUMBNAIL_PLAY_ICON_SIZE}
              />
            </span>
          </span>
        </motion.div>
        <span className="sr-only">{title}</span>
      </button>

      {mounted
        ? createPortal(
            <AnimatePresence>
              {isOpen ? (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                  <motion.div
                    animate={{ opacity: 1 }}
                    className="absolute inset-0 bg-black/60 backdrop-blur-sm"
                    exit={{ opacity: 0 }}
                    initial={
                      shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }
                    }
                    onClick={close}
                    transition={{
                      duration: shouldReduceMotion ? 0 : BACKDROP_DURATION,
                    }}
                  />

                  <motion.div
                    animate={{ opacity: 1 }}
                    aria-label={title}
                    aria-modal="true"
                    className="relative z-10 w-full max-w-3xl overflow-hidden rounded-xl bg-black outline-none"
                    exit={
                      shouldReduceMotion
                        ? { opacity: 0, transition: { duration: 0 } }
                        : { opacity: 0 }
                    }
                    initial={
                      shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }
                    }
                    layoutId={shouldReduceMotion ? undefined : frameLayoutId}
                    ref={panelRef}
                    role="dialog"
                    tabIndex={-1}
                    transition={
                      shouldReduceMotion ? { duration: 0 } : SPRING_PANEL
                    }
                  >
                    {/* biome-ignore lint/a11y/useMediaCaption: the rule only recognises an unconditional <track> literal, so it cannot see the mapped tracks below. Satisfying it with an extra always-present <track> shipped one bogus empty caption track per video, which is worse than this suppression. */}
                    <video
                      className="block max-h-[80vh] w-full"
                      controls={!showCustomControls}
                      playsInline
                      poster={poster}
                      ref={videoRef}
                      src={src}
                    >
                      {captions.length > 0 ? (
                        captions.map((caption) => (
                          <track
                            key={caption.srcLang}
                            kind="captions"
                            label={caption.label}
                            src={caption.src}
                            srcLang={caption.srcLang}
                          />
                        ))
                      ) : (
                        <track kind="captions" />
                      )}
                    </video>

                    {showCustomControls ? (
                      <VideoModalControls
                        currentTime={currentTime}
                        duration={duration}
                        isFullscreen={isFullscreen}
                        isMuted={isMuted}
                        isPlaying={isPlaying}
                        onScrubKeyDown={handleScrubKeyDown}
                        onScrubPointerDown={handleScrubPointerDown}
                        onToggleFullscreen={toggleFullscreen}
                        onToggleMute={toggleMute}
                        onTogglePlay={togglePlay}
                        progress={progress}
                      />
                    ) : null}

                    <SmoothButton
                      aria-label="Close video"
                      className="absolute top-3 right-3 [--btn-fg:#fff] [--btn-hover:rgb(0_0_0/0.7)] [--btn:rgb(0_0_0/0.5)]"
                      onClick={close}
                      shape="pill"
                      size="icon-sm"
                      variant="solid"
                    >
                      <X aria-hidden="true" />
                    </SmoothButton>
                  </motion.div>
                </div>
              ) : null}
            </AnimatePresence>,
            document.body
          )
        : null}
    </>
  );
};

export default VideoModal;

"use client";

import { cn } from "@/lib/utils";
import SmoothButton from "@/components/smoothui/smooth-button";
import { Eye, EyeOff } from "lucide-react";
import {
  AnimatePresence,
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
  useSpring,
} from "motion/react";
import type { KeyboardEvent, PointerEvent, ReactNode } from "react";
import { useEffect, useId, useRef, useState } from "react";

const STACK_OFFSET_DEFAULT = 13;
const STACK_SCALE_STEP = 0.05;
const MAX_STACK_DEPTH = 3;
/** Cards held in a hand tip away from you — this is that tilt. */
const RECEDE_ROTATE_X = 7;
/** Selected card comes toward the viewer instead of just growing. */
const ACTIVE_LIFT_Z = 36;
const PERSPECTIVE = 1400;
const AVATAR_OVERFLOW_THRESHOLD = 4;
const AVATAR_OVERLAP = 12;
const BLUR_AMOUNT = 6;
const CHAR_STAGGER = 0.018;
const INITIALS_MAX = 2;
const MASK_LENGTH = 6;
const SHEEN_HOME_X = 28;
const SHEEN_HOME_Y = 18;
const PERCENT = 100;

const SPRING_TRANSITION = {
  bounce: 0.1,
  duration: 0.25,
  type: "spring" as const,
};
const LIFT_TRANSITION = {
  bounce: 0.1,
  duration: 0.3,
  type: "spring" as const,
};
const SHEEN_SPRING = { damping: 26, mass: 0.4, stiffness: 140 };

/**
 * Fine grain over the whole card. Real cards are printed, not painted —
 * a flat gradient is the single biggest tell that a card is a CSS box.
